-- ============================================================
-- ISO 27001 v6 (318) + NIS2 (268) — TAM DEĞİŞİM, veri koruyarak
-- Kaynak: Unified_Control_Catalogue.json + Applicability_Model.json
-- Bu sürüm ek olarak: yedekleme, cevap taşıma, risk üretimi,
--   UI'nın beklediği meta alanları (ref/annex/topic/description).
-- İdempotent. Tek transaction. Hata olursa hiçbir şey değişmez.
-- ============================================================
BEGIN;

-- 0) YEDEKLER — eigenes Schema, vollständige Felder, kein Zugriff für die App.
--
--    Codex-Prüfung 2026-09-12 (Y1–Y4) hat drei echte Fehler gefunden:
--      Y1  answers hat seit Migration 20260703133854 einen VIERspaltigen
--          Unique-Key (tenant_id, framework, control_id, asset_id) mit
--          NULLS NOT DISTINCT. Ein dreispaltiges ON CONFLICT lässt die
--          gesamte Transaktion scheitern — die Migration liefe NIE durch.
--      Y2  asset_id und reifegrad fehlten im Backup: Antworten je Asset
--          wären auf eine Organisationsantwort zusammengefallen, Reifegrade
--          verloren. answer_evidence hängt per FK ON DELETE CASCADE an
--          controls — die Datei↔Kontroll-Verknüpfungen wären still gelöscht.
--      Y3  Die v6_pre_*-Tabellen lagen in `public` ohne RLS: unter den
--          Default-Privilegien dieses Repos wären sie über den Daten-Gateway
--          mandantenübergreifend lesbar.
--
--    Antwort darauf: Backups in ein eigenes Schema `mig`, das der Gateway
--    nicht erreicht (er erlaubt ausschließlich `public`), ohne Grants für
--    anon/authenticated. Vollständige Spalten. Historie statt TRUNCATE.
CREATE SCHEMA IF NOT EXISTS mig;
REVOKE ALL ON SCHEMA mig FROM PUBLIC;
DO $mig$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON SCHEMA mig FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON SCHEMA mig FROM authenticated';
  END IF;
END $mig$;

CREATE TABLE IF NOT EXISTS mig.v6_pre_answers (
  run_at      timestamptz NOT NULL DEFAULT now(),
  id          uuid,
  tenant_id   uuid,
  framework   text,
  control_id  text,
  asset_id    uuid,
  antwort     text,
  reifegrad   smallint,
  evidence    text,
  note        text,
  updated_at  timestamptz,
  updated_by  uuid
);
CREATE TABLE IF NOT EXISTS mig.v6_pre_answer_evidence (
  run_at      timestamptz NOT NULL DEFAULT now(),
  evidence_id uuid,
  tenant_id   uuid,
  framework   text,
  control_id  text
);
CREATE TABLE IF NOT EXISTS mig.v6_pre_control_effect (
  run_at      timestamptz NOT NULL DEFAULT now(),
  framework text, control_id text, dimension text, kind text, base_eff numeric
);
CREATE TABLE IF NOT EXISTS mig.v6_pre_control_risk (
  run_at      timestamptz NOT NULL DEFAULT now(),
  framework text, control_id text, risk_id text, link_typ text
);
CREATE TABLE IF NOT EXISTS mig.v6_pre_node_member (
  run_at      timestamptz NOT NULL DEFAULT now(),
  node_id text, framework text, control_id text
);

-- Historie: NICHT truncaten. Wiederhergestellt wird nur der neueste Lauf.
SELECT id,tenant_id,framework,control_id,asset_id,antwort,reifegrad,evidence,note,updated_at,updated_by
  FROM public.answers WHERE framework IN ('NIS2','ISO27001');
SELECT evidence_id,tenant_id,framework,control_id
  FROM public.answer_evidence WHERE framework IN ('NIS2','ISO27001');
SELECT framework,control_id,dimension,kind,base_eff
  FROM public.control_effect WHERE framework IN ('NIS2','ISO27001');
SELECT framework,control_id,risk_id,link_typ
  FROM public.control_risk WHERE framework IN ('NIS2','ISO27001');
SELECT node_id,framework,control_id
  FROM public.control_node_member WHERE framework IN ('NIS2','ISO27001');

-- Review-Warteschlange für die 417→v6-Abbildung (Y4): eine Abbildung ist
-- KEINE Bewertungsgleichheit. Alte Antworten landen hier zur Prüfung, nicht
-- als fertiges Ergebnis in `answers`.
CREATE TABLE IF NOT EXISTS mig.v6_answer_review (
  run_at        timestamptz NOT NULL DEFAULT now(),
  tenant_id     uuid,
  framework     text,
  source_id     text,      -- alte Prüffragen-ID (a5-04)
  target_id     text,      -- v6-Kontroll-ID (C29.4)
  asset_id      uuid,
  antwort       text,
  reifegrad     smallint,
  evidence      text,
  note          text,
  updated_at    timestamptz,
  status        text NOT NULL DEFAULT 'offen'   -- offen | uebernommen | verworfen
);

-- 1) 417 soru ID -> v6 kontrol ID haritası (kalıcı; cevap taşıma ve diğer
--    framework'lerin meta.iso_ids çevirisi için gerekli).
CREATE TABLE IF NOT EXISTS public.iso_qid_map_v6 (
  q text NOT NULL, t text NOT NULL, ord int NOT NULL DEFAULT 1,
  PRIMARY KEY (q,t));
TRUNCATE public.iso_qid_map_v6;

-- 2) Eski NIS2/ISO27001 kontrolleri (yedekler alındı)
DELETE FROM public.controls WHERE framework IN ('NIS2','ISO27001');

ON CONFLICT (code) DO UPDATE SET name_de=EXCLUDED.name_de,name_en=EXCLUDED.name_en,role=EXCLUDED.role;

-- 3) NIS2: 268 kontrol
ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, req_en=EXCLUDED.req_en, muss=EXCLUDED.muss, source=EXCLUDED.source, meta=EXCLUDED.meta;

-- 4) ISO 27001: 318 kontrol
ON CONFLICT (framework,id) DO UPDATE SET req_de=EXCLUDED.req_de, req_en=EXCLUDED.req_en, muss=EXCLUDED.muss, source=EXCLUDED.source, meta=EXCLUDED.meta;

-- 5) same-as düğümleri: 224 ortak kontrol tek kayıt gibi davranır
ON CONFLICT (node_id) DO UPDATE SET label=EXCLUDED.label, meta=EXCLUDED.meta;

ON CONFLICT (framework,control_id) DO UPDATE SET node_id=EXCLUDED.node_id;

-- 6) RİSKLER: her kontrolün katalogdaki risk metni bir risks satırı olur,
--    control_risk ile ilgili görünüm(ler)e bağlanır. Motor buradan okur.
DELETE FROM public.risks WHERE quelle='Unified Catalogue v6';
ON CONFLICT (risk_id) DO UPDATE SET quelle=EXCLUDED.quelle, iso_anchor=EXCLUDED.iso_anchor, text_de=EXCLUDED.text_de, text_en=EXCLUDED.text_en, status=EXCLUDED.status, primary_control_framework=EXCLUDED.primary_control_framework, primary_control_id=EXCLUDED.primary_control_id, meta=EXCLUDED.meta;

ON CONFLICT (framework,control_id,risk_id) DO UPDATE SET link_typ=EXCLUDED.link_typ;

-- 6b) Verwaiste Risiken stilllegen (nicht löschen): Risikotexte, die nur an den
--     alten NIS2-70- bzw. ISO-417-Kontrollen hingen, haben nach dem Austausch
--     keine einzige Verknüpfung mehr. Sie würden sonst ohne Bezug in der
--     Risikoliste stehen. status='retired_v6' lässt sie jederzeit zurückholen.
UPDATE public.risks r
   SET status = 'retired_v6'
 WHERE r.status = 'active'
   AND r.quelle <> 'Unified Catalogue v6'
   AND NOT EXISTS (SELECT 1 FROM public.control_risk cr WHERE cr.risk_id = r.risk_id);

-- 7) CEVAP GERİ YÜKLEME — nur IDENTITÄT ist eine Bewertung.
--
--    (a) IDENTITÄT: control_id existiert im neuen Katalog unverändert →
--        1:1 zurück, MIT asset_id und reifegrad. Das ist derselbe Datensatz,
--        keine Übersetzung. Der Unique-Key ist VIERspaltig
--        (tenant_id, framework, control_id, asset_id) mit NULLS NOT DISTINCT —
--        ein dreispaltiges ON CONFLICT würde hier abbrechen (Codex Y1).
--    (b) ABBILDUNG 417→v6: landet NICHT in `answers`. Eine Abbildung sagt
--        nur „diese alte Prüffrage betraf diese Kontrolle", nicht „die neue,
--        breitere Kontrolle ist damit bewertet". Deshalb Review-Warteschlange
--        `mig.v6_answer_review`; Übernahme entscheidet ein Mensch (Codex Y4).
WITH snap AS (
  SELECT * FROM mig.v6_pre_answers
   WHERE run_at = (SELECT max(run_at) FROM mig.v6_pre_answers)
)
SELECT a.tenant_id, a.framework, a.control_id, a.asset_id, a.antwort, a.reifegrad,
       a.evidence, a.note, a.updated_at, a.updated_by
  FROM snap a
 WHERE EXISTS (SELECT 1 FROM public.controls c
                WHERE c.framework = a.framework AND c.id = a.control_id)
ON CONFLICT (tenant_id, framework, control_id, asset_id) DO NOTHING;

-- Datei-/Nachweis-Verknüpfungen zurückholen (hingen per CASCADE an controls).
WITH snap AS (
  SELECT * FROM mig.v6_pre_answer_evidence
   WHERE run_at = (SELECT max(run_at) FROM mig.v6_pre_answer_evidence)
)
SELECT e.evidence_id, e.tenant_id, e.framework, e.control_id
  FROM snap e
 WHERE EXISTS (SELECT 1 FROM public.controls c
                WHERE c.framework = e.framework AND c.id = e.control_id)
   AND EXISTS (SELECT 1 FROM public.evidence ev WHERE ev.id = e.evidence_id)
ON CONFLICT (evidence_id, framework, control_id) DO NOTHING;

-- Abbildungsvorschläge zur menschlichen Prüfung (keine Bewertung!).
WITH snap AS (
  SELECT * FROM mig.v6_pre_answers
   WHERE run_at = (SELECT max(run_at) FROM mig.v6_pre_answers)
)
SELECT a.tenant_id, 'ISO27001', a.control_id, m.t, a.asset_id, a.antwort, a.reifegrad,
       a.evidence, a.note, a.updated_at
  FROM snap a
  JOIN public.iso_qid_map_v6 m ON m.q = lower(a.control_id)
 WHERE a.framework = 'ISO27001'
   AND EXISTS (SELECT 1 FROM public.controls c WHERE c.framework='ISO27001' AND c.id = m.t)
   AND NOT EXISTS (SELECT 1 FROM public.answers x
                    WHERE x.tenant_id = a.tenant_id AND x.framework='ISO27001'
                      AND x.control_id = m.t
                      AND (x.asset_id = a.asset_id OR (x.asset_id IS NULL AND a.asset_id IS NULL)));

-- 8) control_effect geri yükleme (katalog verisi, tenant'a bağlı değil).
--    Kimlik yolu + harita yolu; birleşmede en yüksek base_eff alınır
--    (birleşmiş kontrol daha geniş kapsıyor). En son anlık görüntüden.
WITH snap AS (
  SELECT * FROM mig.v6_pre_control_effect
   WHERE run_at = (SELECT max(run_at) FROM mig.v6_pre_control_effect)
), src AS (
  SELECT e.framework, e.control_id AS tgt, e.dimension, e.kind, e.base_eff
    FROM snap e
   WHERE EXISTS (SELECT 1 FROM public.controls c
                  WHERE c.framework = e.framework AND c.id = e.control_id)
  UNION ALL
  SELECT 'ISO27001', m.t, e.dimension, e.kind, e.base_eff
    FROM snap e
    JOIN public.iso_qid_map_v6 m ON m.q = lower(e.control_id)
   WHERE e.framework = 'ISO27001'
     AND EXISTS (SELECT 1 FROM public.controls c
                  WHERE c.framework = 'ISO27001' AND c.id = m.t)
), best AS (
  SELECT DISTINCT ON (framework, tgt) framework, tgt, dimension, kind, base_eff
    FROM src ORDER BY framework, tgt, base_eff DESC NULLS LAST
)
SELECT b.framework, b.tgt, b.dimension, b.kind, b.base_eff
  FROM best b
ON CONFLICT (framework,control_id) DO NOTHING;

-- 9) Diğer framework'lerin meta.iso_ids alanı: 417 soru ID -> v6 kontrol ID
WITH src AS (
  SELECT c.framework, c.id, lower(x.q) AS q
    FROM public.controls c
    CROSS JOIN LATERAL jsonb_array_elements_text(c.meta->'iso_ids') AS x(q)
   WHERE c.framework NOT IN ('NIS2','ISO27001')
     AND jsonb_typeof(c.meta->'iso_ids')='array'
), agg AS (
  SELECT s.framework, s.id, to_jsonb(array_agg(DISTINCT m.t ORDER BY m.t)) AS ids
    FROM src s JOIN public.iso_qid_map_v6 m ON m.q=s.q GROUP BY 1,2
)
UPDATE public.controls c
   SET meta = jsonb_set(jsonb_set(c.meta,'{iso_ids}',a.ids,true),
                        '{iso_ids_space}','"iso27001_control_id_v6"'::jsonb,true)
  FROM agg a
 WHERE c.framework=a.framework AND c.id=a.id;

-- NIS2'de iso_ids'e gerek yok: 224 ortak kontrol aynı ID ile iki görünümde.
UPDATE public.controls SET meta = meta - 'iso_ids' WHERE framework='NIS2';

-- 10) DOĞRULAMA — tutmazsa tüm işlem geri alınır
DO $$
DECLARE n2 int; n_iso int; n_node int; n_mem int; n_cond int;
        n_risk int; n_crisk int; n_ans int; n_ans_pre int; n_eff int;
        n_bak_node int; n_bak_crisk int; n_retired int;
        n_restorable int; n_ans_all int;
        n_reif_pre int; n_reif_now int; n_asset_pre int; n_asset_now int;
        n_ev_pre int; n_ev_now int; n_review int;
BEGIN
  SELECT count(*) INTO n2      FROM public.controls WHERE framework='NIS2';
  SELECT count(*) INTO n_iso   FROM public.controls WHERE framework='ISO27001';
  SELECT count(*) INTO n_node  FROM public.control_node WHERE node_id LIKE 'N-%';
  SELECT count(*) INTO n_mem   FROM public.control_node_member WHERE node_id LIKE 'N-%';
  SELECT count(*) INTO n_cond  FROM public.controls WHERE framework IN ('NIS2','ISO27001') AND meta ? 'applicability';
  SELECT count(*) INTO n_risk  FROM public.risks WHERE quelle='Unified Catalogue v6';
  SELECT count(*) INTO n_crisk FROM public.control_risk WHERE framework IN ('NIS2','ISO27001');
  SELECT count(*) INTO n_ans   FROM public.answers WHERE framework='ISO27001';
  SELECT count(*) INTO n_ans_pre FROM mig.v6_pre_answers WHERE framework='ISO27001';
  SELECT count(*) INTO n_eff   FROM public.control_effect WHERE framework='ISO27001';
  SELECT count(*) INTO n_bak_node  FROM mig.v6_pre_node_member;
  SELECT count(*) INTO n_bak_crisk FROM mig.v6_pre_control_risk;
  SELECT count(*) INTO n_retired   FROM public.risks WHERE status='retired_v6';

  IF n2<>268       THEN RAISE EXCEPTION 'NIS2 kontrol sayisi %, beklenen 268', n2; END IF;
  IF n_iso<>318  THEN RAISE EXCEPTION 'ISO kontrol sayisi %, beklenen 318', n_iso; END IF;
  IF n_node<>224 THEN RAISE EXCEPTION 'dugum sayisi %, beklenen 224', n_node; END IF;
  IF n_mem<>448  THEN RAISE EXCEPTION 'dugum uyeligi %, beklenen 448', n_mem; END IF;
  IF n_cond<>102 THEN RAISE EXCEPTION 'kosullu kontrol %, beklenen 102', n_cond; END IF;
  IF n_risk<>362 THEN RAISE EXCEPTION 'v6 risk sayisi %, beklenen 362', n_risk; END IF;
  IF n_crisk<>586 THEN RAISE EXCEPTION 'control_risk bagi %, beklenen 586', n_crisk; END IF;
  -- Jede IDENTISCH wiederherstellbare Antwort MUSS wieder da sein — Feld für
  -- Feld, inklusive asset_id und reifegrad. Abbildungsvorschläge zählen hier
  -- NICHT mit; die stehen in mig.v6_answer_review und sind keine Bewertung.
  SELECT count(*) INTO n_restorable
    FROM mig.v6_pre_answers a
   WHERE a.run_at = (SELECT max(run_at) FROM mig.v6_pre_answers)
     AND EXISTS (SELECT 1 FROM public.controls c
                  WHERE c.framework=a.framework AND c.id=a.control_id);
  SELECT count(*) INTO n_ans_all FROM public.answers WHERE framework IN ('NIS2','ISO27001');
  IF n_ans_all < n_restorable THEN
    RAISE EXCEPTION 'Antwort-Wiederherstellung unvollstaendig: % wiederherstellbar, nur % vorhanden', n_restorable, n_ans_all;
  END IF;

  -- Reifegrade und Asset-Antworten dürfen nicht verloren gehen (Codex Y2).
  SELECT count(*) INTO n_reif_pre FROM mig.v6_pre_answers
   WHERE run_at=(SELECT max(run_at) FROM mig.v6_pre_answers) AND reifegrad IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.controls c WHERE c.framework=mig.v6_pre_answers.framework AND c.id=mig.v6_pre_answers.control_id);
  SELECT count(*) INTO n_reif_now FROM public.answers
   WHERE framework IN ('NIS2','ISO27001') AND reifegrad IS NOT NULL;
  IF n_reif_now < n_reif_pre THEN
    RAISE EXCEPTION 'Reifegrade verloren: vorher % , jetzt %', n_reif_pre, n_reif_now;
  END IF;

  SELECT count(*) INTO n_asset_pre FROM mig.v6_pre_answers
   WHERE run_at=(SELECT max(run_at) FROM mig.v6_pre_answers) AND asset_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.controls c WHERE c.framework=mig.v6_pre_answers.framework AND c.id=mig.v6_pre_answers.control_id);
  SELECT count(*) INTO n_asset_now FROM public.answers
   WHERE framework IN ('NIS2','ISO27001') AND asset_id IS NOT NULL;
  IF n_asset_now < n_asset_pre THEN
    RAISE EXCEPTION 'Asset-Antworten verloren: vorher % , jetzt %', n_asset_pre, n_asset_now;
  END IF;

  -- Nachweis-Verknüpfungen (Datei ↔ Kontrolle) dürfen nicht verloren gehen.
  SELECT count(*) INTO n_ev_pre FROM mig.v6_pre_answer_evidence
   WHERE run_at=(SELECT max(run_at) FROM mig.v6_pre_answer_evidence)
     AND EXISTS (SELECT 1 FROM public.controls c WHERE c.framework=mig.v6_pre_answer_evidence.framework AND c.id=mig.v6_pre_answer_evidence.control_id);
  SELECT count(*) INTO n_ev_now FROM public.answer_evidence WHERE framework IN ('NIS2','ISO27001');
  IF n_ev_now < n_ev_pre THEN
    RAISE EXCEPTION 'Nachweis-Verknuepfungen verloren: vorher % , jetzt %', n_ev_pre, n_ev_now;
  END IF;

  SELECT count(*) INTO n_review FROM mig.v6_answer_review
   WHERE run_at=(SELECT max(run_at) FROM mig.v6_answer_review);

  RAISE NOTICE 'OK  NIS2=% ISO=% dugum=% uyelik=% kosullu=%', n2,n_iso,n_node,n_mem,n_cond;
  RAISE NOTICE 'RISK  risks=% control_risk=% (eski baglar yedekte: %)', n_risk,n_crisk,n_bak_crisk;
  RAISE NOTICE 'ANTWORTEN identisch wiederhergestellt: % von % moeglich (ISO=%), control_effect=%', n_ans_all, n_restorable, n_ans, n_eff;
  RAISE NOTICE 'ERHALTEN  Reifegrade=% Asset-Antworten=% Nachweis-Links=%', n_reif_now, n_asset_now, n_ev_now;
  RAISE NOTICE 'REVIEW  % Abbildungsvorschlaege in mig.v6_answer_review (KEINE Bewertung, manuell zu pruefen)', n_review;
  RAISE NOTICE 'RISK  baglantisiz kalan eski risk (status=retired_v6): %', n_retired;
  RAISE NOTICE 'YEDEK dugum bacagi=% (KN- dugumleri ISO/NIS2 bacagini kaybetti; capraz iliski meta.iso_ids uzerinden korunur)', n_bak_node;
END $$;

COMMIT;