INSERT INTO public.frameworks (code,name_de,name_en,role,uses_maturity,color,sort_order) VALUES
  ('ISO27001','ISO/IEC 27001:2022','ISO/IEC 27001:2022','hub',true,'#003399',10),
  ('NIS2','NIS2','NIS2','spoke',false,'#0055CC',20)
INSERT INTO public.controls (framework,id,req_de,req_en,muss,source,meta) VALUES
  ('NIS2','C12.1','NIS2 Applicability Is Reassessed After Relevant Changes','NIS2 Applicability Is Reassessed After Relevant Changes','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-SCP · Scope and EU representation", "topic_label": "S-SCP · Scope and EU representation", "description": "The entity reassesses whether and how NIS2 applies to it after changes in its activities, size, ownership or jurisdiction that could affect its scope status.", "evidence": "Examples: relevant activity, size, ownership or jurisdiction change records linked to dated reassessments and resulting scope decisions. Where no relevant change occurred, existing change information and an explanation of the reassessment trigger can establish that position.", "risk_text": "A change in scope, classification or jurisdiction goes unnoticed, causing missed obligations or reliance on the wrong competent authority.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H", "nis2_basis": "NIS2 Articles 2-3", "ref": "Art. 2"}'::jsonb),
  ('NIS2','C11.1','A Qualifying EU Representative Is Validly Appointed (Applies only to Article 26(1)(b) providers with no EU establishment that offer services in the EU.)','A Qualifying EU Representative Is Validly Appointed (Applies only to Article 26(1)(b) providers with no EU establishment that offer services in the EU.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-SCP · Scope and EU representation", "topic_label": "S-SCP · Scope and EU representation", "description": "For the non-EU providers specified in this control, the appointed representative is established in an EU Member State where the provider offers services and has a mandate to act for it; merely naming an EU contact does not demonstrate a valid appointment.", "evidence": "Where applicable, evidence may include an accepted appointment or equivalent mandate identifying the EU representative, its qualifying EU establishment and authority to act for the provider.", "risk_text": "Authority communications or required follow-up are delayed because no authorised EU representative can act for the provider.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 26(3)", "ref": "Art. 26(3)", "applicability": {"condition": "only to Article 26(1)(b) providers with no EU establishment that offer services in the EU", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C14.1','Required Registration Information Is Complete and Accurate','Required Registration Information Is Complete and Accurate','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-REG · Registration and changes", "topic_label": "S-REG · Registration and changes", "description": "The applicable registration information is complete and accurate: name, address, email addresses, telephone numbers, IP ranges and, where applicable, sector, subsector and Member States served. For providers subject to Article 27, this also covers entity type, main and other EU establishments and required EU representative details.", "evidence": "Examples: current registration details reconciled with authoritative organisational and service records, covering the required identity, contact and IP-range fields and applicable sector, subsector and Member States served. Include entity type, EU establishments and representative details where Article 27 applies.", "risk_text": "Incomplete or inaccurate data prevent correct identification, scope tracking or contact by the competent authority.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Articles 3(4), 27(2)", "ref": "Art. 3(4)"}'::jsonb),
  ('NIS2','C14.2','Required Registration Information Is Submitted on Time','Required Registration Information Is Submitted on Time','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-REG · Registration and changes", "topic_label": "S-REG · Registration and changes", "description": "The entity has submitted its name, address, email addresses, telephone numbers, IP ranges and applicable sector, subsector and Member States served to the competent authority on time. Where Article 27 applies, the submission also includes entity type, main and other EU establishment details and required EU representative details.", "evidence": "Examples: the submitted registration information and portal history, receipt or equivalent transmission record identifying the competent authority and submission date, compared with the applicable deadline. Check that the submission includes all fields applicable to the entity, including Article 27 details where relevant.", "risk_text": "The competent authority cannot reliably include or contact the entity through the required registration process, triggering corrective follow-up for an omitted or late submission.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Articles 3(4), 27(2)", "ref": "Art. 3(4)"}'::jsonb),
  ('NIS2','C15.2','Registration Changes Are Identified and Notified Within Applicable Deadlines','Registration Changes Are Identified and Notified Within Applicable Deadlines','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-REG · Registration and changes", "topic_label": "S-REG · Registration and changes", "description": "The entity identifies changes to its NIS2 registration information and notifies the competent national NIS2 authority responsible for its registration of the updated information without delay and within the applicable legal deadline, using the designated notification channel.", "evidence": "Examples: arrangements for detecting registration changes and dated change records linked to updated details, the applicable deadline and transmission through the designated channel to the responsible national authority. Assess elapsed time for undue delay as well as the deadline; where no change occurred, examine the detection arrangements and change history.", "risk_text": "Authority records remain outdated, regulatory contact is impaired and the change-notification duty is not met.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Articles 3(4), 27(3)", "ref": "Art. 3(4)"}'::jsonb),
  ('NIS2','C19.3','Domain Data Policies and Verification Procedures Are Publicly Available (Applies only to TLD name registries and domain name registration service providers.)','Domain Data Policies and Verification Procedures Are Publicly Available (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "The applicable registry or registration provider publishes the policies and procedures it uses to keep registration data accurate and complete, including verification; the public version reflects the process actually in use.", "evidence": "For an applicable registry or registration provider, examples include publicly accessible domain-data policies and verification procedures, with a dated check that the published material is accessible and corresponds to the procedures in use.", "risk_text": "Registrants and other users cannot understand or challenge how registration data are verified, leading to inconsistent submissions and avoidable disputes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(3)", "ref": "Art. 28(3)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.1','Required Domain Registration Data Are Accurate and Complete (Applies only to TLD name registries and domain name registration service providers.)','Required Domain Registration Data Are Accurate and Complete (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "Check that the required domain-registration fields are populated and that their values agree with relevant registration and verification information. The existence of a database record alone does not establish accuracy or completeness. (Applies only to TLD name registries and domain name registration service providers.)", "evidence": "For an applicable registry or registration provider, examples include the required-field definition and privacy-protected samples or supervised database checks demonstrating completeness and accuracy against relevant registration and verification information.", "risk_text": "Incorrect domain-holder records delay identification and contact during abuse investigations or incident response.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(1)-(2)", "ref": "Art. 28(1)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.2','Domain Data Verification Procedures Operate (Applies only to TLD name registries and domain name registration service providers.)','Domain Data Verification Procedures Operate (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "The applicable registry or registration provider carries out its defined registration-data checks and handles failed or inconsistent results; a published procedure without evidence of its operation is not enough.", "evidence": "For an applicable registry or registration provider, examples include verification procedures and privacy-protected transaction records showing checks actually performed, their results and handling of failed or inconsistent data.", "risk_text": "False or unreachable registrant details are accepted as genuine, allowing abusive registrations to evade reliable attribution and follow-up.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(3)", "ref": "Art. 28(3)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.4','Non-Personal Domain Registration Data Are Published Without Undue Delay (Applies only to TLD name registries and domain name registration service providers.)','Non-Personal Domain Registration Data Are Published Without Undue Delay (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "Make the non-personal registration fields publicly retrievable without undue delay after registration. Check actual registration and publication times and the selected fields; a publication schedule alone does not demonstrate timely availability, and personal fields must not be indiscriminately exposed. (Applies only to TLD name registries and domain name registration service providers.)", "evidence": "For an applicable registry or registration provider, examples include public lookup results and registration/publication timestamps demonstrating availability of non-personal registration data without undue delay. Check the publication field selection without copying unnecessary personal data.", "risk_text": "R1: Investigators and other users cannot obtain required non-personal domain information promptly, delaying abuse identification and follow-up.<br>R2: Publication that fails to distinguish personal from non-personal fields discloses registrants'' personal information to the public.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(4)", "ref": "Art. 28(4)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.8','Domain Data Access Policies and Procedures Are Published (Applies only to TLD name registries and domain name registration service providers.)','Domain Data Access Policies and Procedures Are Published (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "The applicable registry or registration provider publishes how legitimate access seekers can request registration data that are not public, including the request route and the information needed to assess the request.", "evidence": "For an applicable registry or registration provider, examples include the published access policy and request procedure, with a dated accessibility check showing that requesters can find the application route and requirements.", "risk_text": "Legitimate requesters cannot identify the application route or requirements, and requests are misdirected or delayed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(5)", "ref": "Art. 28(5)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.5','Domain Data Access Is Limited to Lawful, Substantiated Requests (Applies only to TLD name registries and domain name registration service providers.)','Domain Data Access Is Limited to Lawful, Substantiated Requests (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "For the applicable registry or registration provider, access to non-public registration data is granted to legitimate access seekers on lawful, duly substantiated requests; assess the grounds and permitted disclosure rather than treating every request as automatically valid.", "evidence": "For an applicable registry or registration provider, examples include access criteria and redacted request decisions showing the lawful basis, substantiation, approved disclosure scope and reasons for rejection where relevant. Compare actual access or disclosures with those decisions; absent requests, examine the configured process rather than inventing cases.", "risk_text": "R1: Unsubstantiated or excessive disclosures expose non-public registration data to unauthorised requesters.<br>R2: Lawful, substantiated requests are wrongly rejected, obstructing legitimate abuse investigations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(5)", "ref": "Art. 28(5)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.6','Domain Data Access Requests Receive Replies Without Undue Delay and Within 72 Hours (Applies only to TLD name registries and domain name registration service providers.)','Domain Data Access Requests Receive Replies Without Undue Delay and Within 72 Hours (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "Track access requests from receipt to reply and respond without undue delay and within 72 hours of receipt. Internal reassignment does not restart the clock, and a receipt log alone does not demonstrate that a reply was sent. If no requests occurred, assess readiness rather than claim demonstrated performance. (Applies only to TLD name registries and domain name registration service providers.)", "evidence": "For an applicable registry or registration provider, examples include privacy-protected request and reply records showing receipt time, reply time and any delays. Check both reply without undue delay and the 72-hour limit; if no requests occurred, inspect readiness without claiming demonstrated response performance.", "risk_text": "Responses are delayed, investigations are hindered and the access-request response deadline is missed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(5)", "ref": "Art. 28(5)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C19.9','Cooperation Prevents Duplicate Collection of Domain Registration Data (Applies only to TLD name registries and domain name registration service providers.)','Cooperation Prevents Duplicate Collection of Domain Registration Data (Applies only to TLD name registries and domain name registration service providers.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "topic_label": "S-DOM · TLD registries and domain registration", "description": "The parties cooperate so that domain name registration data are not collected twice. (Applies only to TLD name registries and domain name registration service providers.)", "evidence": "For an applicable registry or registration provider, examples include cooperation arrangements, registration-data flows and representative collection records showing how the parties avoid collecting the same registration data twice.", "risk_text": "Repeated collection creates conflicting registrant records and unnecessary copies of personal data, delaying correction and increasing disclosure exposure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 28(6)", "ref": "Art. 28(6)", "applicability": {"condition": "only to TLD name registries and domain name registration service providers", "condition_source": "control_name", "scope_group": "APP-DOM", "presentation": "scope_gate", "gate_id": "APP-DOM"}}'::jsonb),
  ('NIS2','C27.1','Responsible Persons Have Authority to Ensure NIS2 Compliance','Responsible Persons Have Authority to Ensure NIS2 Compliance','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Persons responsible for or legally representing the entity, with powers to represent it, decide on its behalf or control it, have the authority needed to ensure NIS2 compliance.", "evidence": "Examples: current representation and decision mandates, delegated powers or equivalent governance records identifying the responsible persons and their authority to secure compliance action, corroborated by relevant decisions where available.", "risk_text": "A legally responsible person cannot obtain necessary action, leaving compliance failures unresolved because of gaps in authority.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 20(1); 32(6); 33(5) CIR-specific requirement within CIR scope: CIR Annex 1.2.1; CIR Annex 10.1.2(c).", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C22.1','Management Approves Current Cybersecurity Risk-Management Measures','Management Approves Current Cybersecurity Risk-Management Measures','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "The management body''s approval identifies the cybersecurity risk-management measures currently in force, so an auditor can distinguish an authorised version or scope from a draft or an operational team''s unapproved proposal.", "evidence": "Examples: the current cybersecurity risk-management measures linked to a dated management approval identifying the approved version or scope, whether recorded in a decision, workflow or equivalent record.", "risk_text": "Security measures are contested or bypassed because management has not endorsed their priorities and authority, delaying implementation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "5.2", "A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 20(1) CIR-specific requirement within CIR scope: CIR Annex 1.1.1(k); CIR Annex 2.1.1.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C22.2','Security Responsibilities Have Sufficient Staff, Funding and Tools','Security Responsibilities Have Sufficient Staff, Funding and Tools','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Compare assigned security work with the staff time, funding and usable tools available to perform it; an approved responsibility is not adequately resourced if essential tasks cannot be carried out.", "evidence": "Examples: assigned security work compared with available staff time, funding and usable tools, supported by allocations and operating records. Include identified resource shortfalls and their handling where relevant.", "risk_text": "Approved measures do not operate because people, time, funding or tools are missing, leaving risks untreated.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "7.1", "A.5.4"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 20(1); 21(1) CIR-specific requirement within CIR scope: CIR Annex 1.1.1(e); CIR Annex 1.2.4; CIR Annex 10.1.3.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C27.3','Conflicting Duties Are Segregated Where Applicable','Conflicting Duties Are Segregated Where Applicable','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Identify conflicting duties and compare their assigned responsibilities with actual permissions and operations to verify applicable segregation. A written separation rule is insufficient if one person can still initiate, approve and conceal the same action. Any alternative arrangement must be justified against the applicable requirement; independent oversight is not an automatic waiver of required segregation.", "evidence": "Examples: identified conflicting duties compared with actual responsibilities, permissions and sampled transactions showing applicable separation. Where an alternative arrangement is relied on, examine its justification and effective independent scrutiny against the applicable requirement.", "risk_text": "A person can initiate, approve and conceal an improper action without effective independent scrutiny.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a), (i) CIR-specific requirement within CIR scope: CIR Annex 1.2.5.", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C27.2','Security Reporting Reaches the Management Body Effectively (For CIR-covered entities, at least one person reports directly to the management body.)','Security Reporting Reaches the Management Body Effectively (For CIR-covered entities, at least one person reports directly to the management body.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Security findings, resource needs and decisions requiring oversight reach the management body through an operating reporting route; for CIR-covered entities, at least one person reports directly to that body.", "evidence": "Examples: reporting responsibilities and recent communications demonstrating that security reporting reaches the management body. For CIR-covered entities, identify at least one person with a direct reporting route and evidence that the route operates.", "risk_text": "Material security issues are filtered or delayed before reaching management, so decisions and corrective action occur too late.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 20(1) CIR-specific requirement within CIR scope: CIR Annex 1.2.3.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C23.1','Management Receives Sufficient Implementation and Risk Information for Oversight','Management Receives Sufficient Implementation and Risk Information for Oversight','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Provide the management body with current implementation status and material-risk information, including significant deficiencies and delays, so it can exercise oversight. Compare the information actually received with known material issues; preparing a report that never reaches management, or omits those issues, is not sufficient.", "evidence": "Examples: implementation-status and material-risk information provided to the management body, with evidence of receipt and comparison against known material issues and current implementation status.", "risk_text": "Management relies on incomplete or outdated information and overlooks serious deficiencies or delayed measures.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 20(1)", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C23.2','Management Oversees Implementation of Cybersecurity Measures','Management Oversees Implementation of Cybersecurity Measures','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Management actually exercises oversight of implementation.", "evidence": "Examples: management review discussions, decisions, interventions or follow-up records linked to implementation status, material issues and the progress of actions it requested.", "risk_text": "Known deficiencies persist because management does not decide, intervene or follow up; oversight becomes a reporting formality.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "A.5.4"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 20(1)", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C27.4','Security Roles and Personnel Assignments Are Reviewed','Security Roles and Personnel Assignments Are Reviewed','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Security Roles and Personnel Assignments Are Reviewed. Check that assigned responsibilities, decision authority and available personnel still meet current security needs. Record decisions and update assignments when necessary. For CIR-covered entities, review roles at planned intervals and after significant incidents or changes, and review personnel assignments and staffing at least annually.", "evidence": "Examples: dated reviews of responsibilities, decision authority and staffing, with changed assignments or justified no-change decisions. For CIR-covered entities, compare role reviews with planned intervals and significant incident/change triggers, and personnel-assignment and staffing reviews with the at-least-annual requirement.", "risk_text": "Security tasks are missed or delayed after organisational changes because responsibilities and available personnel no longer match operational needs.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.3", "A.5.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Articles 20(1), 21(2)(i); CIR Annex 1.2.6 and 10.1.3.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C25.2','Management Training Develops Required Risk-Management Knowledge and Skills','Management Training Develops Required Risk-Management Knowledge and Skills','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "G-MGT · Management training", "topic_label": "G-MGT · Management training", "description": "The training content equips management members to identify cybersecurity risks and assess risk-management practices and their effect on the services provided; general attendance alone does not establish that these learning needs are covered.", "evidence": "Examples: management training objectives and content mapped to the required risk-management knowledge and skills, with relevant exercises, assessments or discussion records where available to demonstrate that alignment.", "risk_text": "Management misjudges treatment priorities or accepts exposure it does not understand because training has not developed the necessary risk-management skills.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 20(2)", "ref": "Art. 20(2)"}'::jsonb),
  ('NIS2','C25.1','All Applicable Management Members Complete Required Training','All Applicable Management Members Complete Required Training','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "G-MGT · Management training", "topic_label": "G-MGT · Management training", "description": "Compare the applicable management membership with completed training records to identify anyone still untrained; planned attendance or completion by only the security lead does not demonstrate coverage of all required members.", "evidence": "Examples: the population of applicable management members reconciled with individual training-completion records and any outstanding requirements. Attendance records, provider confirmations or equivalent records may demonstrate completion where appropriate.", "risk_text": "Untrained management members make approval or oversight decisions without recognising material cybersecurity and service-dependency implications.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 20(2)", "ref": "Art. 20(2)"}'::jsonb),
  ('NIS2','C29.2','Information Security Policy Defines the Security Approach and Responsibilities','Information Security Policy Defines the Security Approach and Responsibilities','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "The Information Security Policy Defines the Security Approach and Responsibilities. Set security objectives, accountable roles, implementation resources and monitoring arrangements, and identify the supporting topic-specific policies. Management approval and operational implementation must be evidenced; separate documents are not required for every topic if the requirements remain identifiable.", "evidence": "Examples: the current information-security policy identifying objectives, responsibilities, resources, monitoring arrangements and supporting topic requirements, linked to management approval and samples of operational application. These elements may be held in one document or an identifiable set of existing records.", "risk_text": "Teams make incompatible security decisions or routinely bypass agreed safeguards, leaving information and services exposed at organisational boundaries.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.2", "A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Articles 20(1), 21(2)(a); CIR Annex 1.1.1 and 1.2.1.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C29.5','Security Documents and Records Are Current, Assigned and Retrievable','Security Documents and Records Are Current, Assigned and Retrievable','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Required security documents and records have identifiable current versions, assigned responsible persons and defined retention periods, and can be retrieved when needed.", "evidence": "Examples: document metadata or equivalent records identifying current versions, responsible persons and retention periods, with retrieval of sampled current instructions and retained security records.", "risk_text": "R1: Obsolete instructions are used in operations, causing incorrect security actions.<br>R2: Lost or untraceable records prevent reconstruction and substantiation of security decisions or implementation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.5.1", "7.5.2", "7.5.3", "A.5.33"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a); 32(2)(e)–(g); 33(2)(d)–(f) CIR-specific requirement within CIR scope: CIR Annex 1.1.1(h); CIR Annex 1.2.1.", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C29.3','Relevant Personnel and External Parties Receive and Follow Security Instructions','Relevant Personnel and External Parties Receive and Follow Security Instructions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Relevant employees and external parties receive the security policies or instructions applicable to their work and follow them. Receipt and acknowledgement are evidenced where required.", "evidence": "Examples: distribution or access records for relevant employees and external parties, receipt and acknowledgement where required, and work samples or observation demonstrating compliance with the applicable instructions.", "risk_text": "Personnel or external parties mishandle information or bypass required safeguards because the instructions relevant to their work are not understood or followed.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.2", "7.3", "A.5.1", "A.5.4", "A.5.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a) CIR-specific requirement within CIR scope: CIR Annex 1.1.1(f); CIR Annex 1.2.2.", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C29.4','Security Policies and Procedures Follow Their Applicable Review Schedules','Security Policies and Procedures Follow Their Applicable Review Schedules','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Security Policies and Procedures Are Reviewed on Their Applicable Schedules. Maintain an identifiable review schedule for the overarching policy and the relevant topic-specific policies and procedures, with owners and applicable incident/change triggers. Record the review and resulting updates or justified no-change decision. For CIR-covered entities, management reviews the overarching policy at least annually; apply each topic''s own review provision rather than inventing one annual interval for everything.", "evidence": "Examples: an identifiable schedule linking each relevant policy or procedure to its owner, interval and incident/change triggers, with dated reviews and updates or justified no-change decisions. For CIR-covered entities, include at least annual management review of the overarching policy while retaining each topic''s applicable schedule.", "risk_text": "Staff follow obsolete rules that no longer protect changed systems or working practices, allowing previously addressed exposures to recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Articles 20(1), 21(2)(a); CIR Annex 1.1.2. Topic-dependent review requirements include 3.2.7, 5.1.6, 6.1.3, 6.2.4, 6.3.3, 6.4.4, 6.5.3, 7.3, 8.2.5, 9.3, 10.2.3, 10.4.2, 11.1.3, 12.2.3 and 12.3.3.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C29.1','Risk-Analysis Policy Guides Actual Cybersecurity Risk Assessments','Risk-Analysis Policy Guides Actual Cybersecurity Risk Assessments','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Define how cybersecurity risks are identified, analysed and assessed, and use that approach in completed assessments. Compare the policy with the methods and assumptions actually applied; a policy document alone is insufficient where operational assessments follow an unexplained, inconsistent approach.", "evidence": "Examples: the risk-analysis policy or equivalent identifiable policy content defining identification, analysis and assessment, with completed assessments showing that the stated approach is applied.", "risk_text": "Assessments omit relevant threats or apply incompatible assumptions, so treatment decisions leave material exposures unaddressed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(a)", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C30.4','Risk-Assessment Methods and Acceptance Criteria Are Applied Consistently','Risk-Assessment Methods and Acceptance Criteria Are Applied Consistently','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "A defined risk-assessment method and risk-acceptance criteria are applied consistently when rating risks and deciding whether they can be accepted.", "evidence": "Examples: the defined assessment method and acceptance criteria compared with sampled risk ratings and acceptance decisions, including explanations for materially different treatment of comparable risks.", "risk_text": "Risk ratings depend on individual judgement without a common basis, distorting priorities and acceptance decisions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(1), (2)(a) CIR-specific requirement within CIR scope: CIR Annex 2.1.2(a); CIR Annex 2.1.2(b); CIR Annex 2.1.2(c); CIR Annex 2.1.2(f); CIR Annex 2.1.2(j).", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C30.1','Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies','Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies. Use current information on threats, vulnerabilities, likelihood and impact, including third-party dependencies and single points of failure. Address confidentiality, integrity, authenticity and availability through an all-hazards approach, including relevant physical events. Consider effects on service recipients and other services, not only the entity''s own financial loss.", "evidence": "Examples: current assessments linking services, systems and third-party dependencies to threats, vulnerabilities, likelihood and impact, including single points of failure and relevant physical hazards. Check confidentiality, integrity, authenticity and availability impacts and consequences for recipients and other services.", "risk_text": "Significant risks are missed or rated incorrectly, leading to unsuitable priorities and measures.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.2", "8.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(1), 21(2) opening sentence and 21(2)(a); CIR Annex 2.1.1-2.1.2.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C30.2','Risk-Treatment Decisions Are Justified and Linked to Assessed Risks','Risk-Treatment Decisions Are Justified and Linked to Assessed Risks','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risk-Treatment Decisions Are Justified and Linked to the Assessed Risks. Record selected safeguards and reasons, considering exposure, entity size, likelihood and severity, societal and economic consequences, the state of the art and implementation cost. Use relevant effectiveness findings, asset protection needs and continuity requirements. Risk acceptance does not waive an applicable legal duty.", "evidence": "Examples: treatment decisions linked to assessed risks and chosen safeguards, explaining proportionality using exposure, size, likelihood, severity, societal/economic effects, state of the art and cost. Relevant effectiveness results, asset protection needs, continuity requirements and applicable duties should be traceable in the decision basis.", "risk_text": "Treatment choices cannot be traced to the risks and assumptions they address, leading to unsuitable safeguards or untreated exposure when decisions are revisited.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3", "8.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(1), 21(2)(a); CIR Annex 2.1.2(g), (j) and 2.1.3.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C30.5','Risk-Treatment Measures Have Owners, Target Dates and Tracked Progress','Risk-Treatment Measures Have Owners, Target Dates and Tracked Progress','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Each risk-treatment measure has an assigned responsible person and a planned implementation date. Progress, delays and completion are tracked.", "evidence": "Examples: treatment actions in existing plans or work-tracking records identifying the responsible person, planned date, progress, delays and evidence of implemented completion.", "risk_text": "Treatment stalls, actions become ownerless or unresolved risks persist behind nominal completion claims.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3", "8.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a); 21(4) CIR-specific requirement within CIR scope: CIR Annex 2.1.2(h); CIR Annex 2.1.2(i).", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C30.3','Residual Risks Are Evaluated and Accepted by Accountable Decision-Makers','Residual Risks Are Evaluated and Accepted by Accountable Decision-Makers','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risks remaining after treatment are evaluated and accepted by the management body or, where applicable, an authorised, accountable risk owner, with adequate reporting to the management body.", "evidence": "Examples: post-treatment residual-risk evaluations linked to acceptance by the management body or an authorised accountable risk owner, with evidence of adequate reporting to the management body where acceptance is delegated.", "risk_text": "Unresolved exposure is accepted without authority or understanding, or acceptance is wrongly used to excuse non-compliance.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a), (f) CIR-specific requirement within CIR scope: CIR Annex 2.1.1; CIR Annex 2.1.2(j).", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C30.6','Risk Assessments and Treatment Plans Are Reviewed and Updated','Risk Assessments and Treatment Plans Are Reviewed and Updated','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risk Assessments and Treatment Plans Are Reviewed and Updated. Review at planned intervals and after significant incidents or significant operational or risk changes. For CIR-covered entities, the periodic review is at least annual. Record the outcome and update assessment results, treatment priorities and plans where needed.", "evidence": "Examples: dated reviews and resulting updates or confirmed assessments and treatment plans, compared with planned intervals and significant incident, operational-change and risk-change triggers. For CIR-covered entities, check that periodic review is at least annual.", "risk_text": "Changes in systems, threats or incidents invalidate treatment assumptions, leaving new or increased exposures untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["8.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a), (f); CIR Annex 2.1.4.", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C42.1','Asset Inventory Identifies Services and Their Supporting Assets','Asset Inventory Identifies Services and Their Supporting Assets','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "The Asset Inventory Identifies Services and Their Supporting Assets. Maintain a complete, accurate and consistent inventory for the assessed scope, covering operations and services, their descriptions, supporting network and information systems and associated assets. Include relevant cloud, operational-technology and outsourced dependencies rather than limiting the inventory to owned hardware. Record changes traceably; C42.4 assesses periodic reconciliation and review.", "evidence": "Examples: the current inventory identifying in-scope operations, services, descriptions and supporting systems/assets, including relevant cloud, OT and outsourced dependencies, with traceable changes. Compare representative entries with actual operations to assess completeness and accuracy.", "risk_text": "Unrecorded assets escape patching, access control or incident scoping, allowing compromise to persist outside operational oversight.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.9", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 12.4.1-12.4.3.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.3','In-Scope Assets Have Accountable Owners','In-Scope Assets Have Accountable Owners','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Each asset within scope has an identifiable person or role accountable for its management and protection decisions; technical custody alone does not establish that accountability.", "evidence": "Examples: asset or service records, responsibility assignments or equivalent information identifying an accountable owner for each in-scope asset, corroborated by the relevant owners.", "risk_text": "Asset protection or maintenance actions are left undone because teams assume another owner will act, prolonging known exposure or service faults.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.9"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(i)", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.2','Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability','Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability Needs. Assign systems and supporting assets protection levels based on sensitivity, criticality, risks and service dependencies. Align availability needs with continuity and recovery objectives. INFO-CLASS separately assesses information confidentiality labels; it does not replace the other protection dimensions.", "evidence": "Examples: assigned asset and system protection levels linked to sensitivity, criticality, risk and service dependencies across confidentiality, integrity, authenticity and availability. Compare availability levels with continuity and recovery objectives.", "risk_text": "R1: Protection effort is misallocated because the service impact and dependencies of assets are underestimated, leaving priority operations vulnerable to disruption.<br>R2: Underestimated integrity requirements allow critical data or system configurations to be altered without adequate safeguards, causing incorrect business decisions or unsafe operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 12.1.1-12.1.2.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.4','Asset Reviews and Material-Change Updates Are Performed','Asset Reviews and Material-Change Updates Are Performed','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Carry out the planned asset reviews and update inventory records for material changes. Retain review results and traceable updates or a justified conclusion that no update was needed; an unchanged inventory by itself does not demonstrate that a review occurred.", "evidence": "Examples: completed asset reviews, comparisons identifying missing or obsolete entries and traceable inventory updates after material changes, or review outcomes confirming that no update was needed.", "risk_text": "Outdated asset details cause new or changed systems to be omitted from security operations and misdirect incident or recovery work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.9"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 12.4.1; CIR Annex 12.4.3.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','INFO-CLASS','Data and Information Are Classified by Confidentiality Level','Data and Information Are Classified by Confidentiality Level','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Assign data and information a confidentiality level using the organisation''s classification scheme and the consequences of unauthorised disclosure; a device inventory alone does not show that its information has been classified.", "evidence": "Examples: the confidentiality classification scheme and representative information classified under it, with explanations supporting the assigned levels. Redacted samples or supervised inspection can demonstrate classification without disclosing sensitive contents.", "risk_text": "Sensitive information is treated as public or internal, allowing unauthorised access or disclosure.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 12.1.1–12.1.2 (information/confidentiality)", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','INFO-LABEL','Information Labels Reflect the Assigned Confidentiality Class','Information Labels Reflect the Assigned Confidentiality Class','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Apply the organisation''s labelling rules so that users can recognise the confidentiality class assigned to relevant information or media; a visible marking or associated metadata may be used without prescribing one universal format.", "evidence": "Examples: representative documents, files or media showing labels consistent with their assigned confidentiality classes and applicable labelling rules. Use redacted samples or observation; no particular label format is required.", "risk_text": "R1: Users or automated handling rules disclose confidential information because the visible label indicates a lower protection class.<br>R2: Labels or asset markings themselves reveal sensitive personnel, location or network information to unauthorised people, supporting reconnaissance or targeted deception.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "H implementation of NIS2 Article 21(2)(i). CIR Annex 12.1 supplies classification context, not a universal labelling format. ISO comparison: A.5.13, Part 2 p.4, Q1–2.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','INFO-CLASS-REV','Information Confidentiality Classifications Are Reviewed and Updated','Information Confidentiality Classifications Are Reviewed and Updated','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Reassess assigned confidentiality levels periodically and following relevant changes, retaining or correcting each level according to current sensitivity; CIR expressly requires periodic review, while the change trigger is a supporting practice in this catalogue.", "evidence": "Examples: dated reviews of information confidentiality classifications and resulting corrections or confirmed classifications, including reassessment following relevant changes.", "risk_text": "Outdated confidentiality levels leave sensitive information exposed or impose unnecessary restrictions after its sensitivity has changed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 12.1.3 (periodic information classification review); change-triggered review is H", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C45.2','NIS2-Purpose Personal-Data Processing Has an Appropriate Lawful Basis','NIS2-Purpose Personal-Data Processing Has an Appropriate Lawful Basis','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-DATA · Personal data used for NIS2 purposes", "topic_label": "I-DATA · Personal data used for NIS2 purposes", "description": "For personal data used in NIS2-related activities, such as incident investigation or access monitoring, identify the purpose and the appropriate legal basis for that processing; citing NIS2 in general is not by itself a justification for every use of personal data.", "evidence": "Examples: existing processing descriptions and decisions linking each NIS2-purpose personal-data activity to its purpose and appropriate lawful basis, with enough context to substantiate that basis. Review descriptions or redacted records rather than unnecessary personal-data copies.", "risk_text": "Security activities process personal data unlawfully, exposing the organisation to complaints, enforcement and restrictions on processing.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 2(14); GDPR Articles 5 and 6", "ref": "Art. 2(14)"}'::jsonb),
  ('NIS2','C45.1','Personal-Data Use for NIS2 Purposes Is Limited to What Is Necessary','Personal-Data Use for NIS2 Purposes Is Limited to What Is Necessary','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-DATA · Personal data used for NIS2 purposes", "topic_label": "I-DATA · Personal data used for NIS2 purposes", "description": "In NIS2-related activities, limit the personal data collected, accessed, used and retained to what the stated security purpose needs; avoid collecting additional personal information merely because the system makes it available.", "evidence": "Examples: purpose-and-necessity decisions compared with actual personal-data fields, collection settings, access/use and retention in NIS2-related activities. Redacted samples or supervised inspection may show that unnecessary data are excluded or removed.", "risk_text": "Excessive monitoring or retention unnecessarily exposes individuals and increases the consequences of a data breach.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 2(14); GDPR Articles 5 and 6", "ref": "Art. 2(14)"}'::jsonb),
  ('NIS2','C42.5','Asset Handling Rules Are Established and Applied','Asset Handling Rules Are Established and Applied','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Define and communicate how the relevant asset and information types may be used, stored and otherwise handled, and check that operating practice follows those rules; practical employee instruction is assessed separately under TRN-DATA.", "evidence": "Examples: applicable handling rules by asset or information type, evidence that relevant users receive them, and observed handling or operational samples showing that they are applied.", "risk_text": "R1: Improper handling damages or loses equipment and media, interrupting work or making needed information unavailable.<br>R2: Handling that ignores sensitivity exposes information to unauthorised people.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 12.2. Handling rules, communication and application; practical employee instruction is assessed separately under TRN-DATA.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.6','Asset and Information Transfers Are Protected According to Type and Classification','Asset and Information Transfers Are Protected According to Type and Classification','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Match safeguards for electronic, physical and, where relevant, verbal transfers to the information''s classification and the asset type, so the chosen transfer method protects the material throughout the exchange.", "evidence": "Examples: transfer arrangements and representative transfers showing safeguards matched to asset/information type and classification, covering electronic, physical or verbal exchange where relevant. Existing channel settings, observed practices or transfer records may demonstrate protection.", "risk_text": "R1: Information is intercepted or delivered to an unintended recipient during transfer.<br>R2: Transferred data are altered or become incomplete, causing the recipient to act on incorrect information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.14"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (h) CIR-specific requirement within CIR scope: CIR Annex 12.2.1; CIR Annex 12.2.2(c); CIR Annex 12.1.2(b).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','DATA-OUTFLOW','Unauthorised Transfers of Sensitive Data Are Prevented or Detected','Unauthorised Transfers of Sensitive Data Are Prevented or Detected','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Identify sensitive-data transfer paths and apply risk-based safeguards that prevent or detect unauthorised disclosure; assess the protection achieved rather than the purchase of a particular data loss prevention product.", "evidence": "Examples: risk-based selection of safeguards for relevant sensitive-data transfer paths, operating configurations or procedures, and detection/prevention records or safe checks showing unauthorised transfers are prevented or detected.", "risk_text": "Sensitive information is exfiltrated through an authorised account or unapproved transfer channel, and delayed detection allows further disclosure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.8.12"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "H implementation of NIS2 Article 21(1), 21(2)(i) and, for detection and response, 21(2)(b). Neither a particular DLP product nor identical controls on every channel are prescribed. ISO comparison: A.8.12, Part 4 p.5; A.5.14, Part 2 p.4, Q3.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','DATA-MASK','Sensitive Data Is Masked Where Full Visibility Is Unnecessary (Applies where access needs can be met with a limited view of sensitive data.)','Sensitive Data Is Masked Where Full Visibility Is Unnecessary (Applies where access needs can be met with a limited view of sensitive data.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where a limited view meets the access need, conceal sensitive values from users who do not need the full content and check that the assessed access paths do not expose the unmasked values; this is not a requirement to mask every field.", "evidence": "Where limited views can meet access needs, examples include visibility decisions, masking settings and safe tests using synthetic or redacted data showing that restricted users cannot obtain the full sensitive values through the assessed access paths.", "risk_text": "People who need only limited information obtain full sensitive values through displays, exports or unrestricted reidentification.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "H implementation of NIS2 Article 21(1) and 21(2)(i), reducing unnecessary information exposure. Not a universal requirement to mask every field and not a separate GDPR audit module. ISO comparison: A.8.11, Part 4 pp.4–5. Pseudonymisation does not itself make data anonymous.", "ref": "Art. 21(1)", "applicability": {"condition": "where access needs can be met with a limited view of sensitive data", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','MEDIA-UNATTENDED','Sensitive Papers and Media Are Secured When Unattended (Applies where sensitive physical information or removable media is handled.)','Sensitive Papers and Media Are Secured When Unattended (Applies where sensitive physical information or removable media is handled.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where sensitive papers or removable media are handled, place them in protected storage or apply equivalent safeguards when left unattended, so people without permission cannot read or remove them.", "evidence": "Where sensitive papers or removable media are handled, examples include applicable storage arrangements and observation that unattended materials are secured, supported by relevant checks or corrected exposures where available.", "risk_text": "Visitors or unauthorised personnel read, photograph or take sensitive material left unattended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.7"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "H implementation of NIS2 Article 21(2)(i) and its physical-environment approach. CIR Annex 12.2.2(b) provides safe-use and storage context. ISO comparison: A.7.7, Part 3 pp.6–7, Q6–8. CIR-specific requirement within CIR scope: CIR Annex 12.2.1; CIR Annex 12.2.2(b).", "ref": "Art. 21(2)(i)", "applicability": {"condition": "where sensitive physical information or removable media is handled", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','ASSET-OFFSITE','Assets Used Outside the Organisation Are Protected (Applies only where work assets are used outside organisational premises.)','Assets Used Outside the Organisation Are Protected (Applies only where work assets are used outside organisational premises.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where work assets leave organisational premises, apply handling and protection measures suited to their information, location and exposure to loss, theft or unauthorised use; location tracking and remote erasure are possible safeguards, not universal requirements.", "evidence": "Where work assets are used off-site, examples include applicable handling arrangements and representative assets or operating records showing protections suited to the location and exposure. Examine selected safeguards and relevant loss-handling records where available; tracking and remote erasure are not universally required.", "risk_text": "R1: Loss, theft or observation of an off-site asset exposes organisational information.<br>R2: Damage or loss of an off-site asset interrupts work or makes locally held data unavailable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.9", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "H implementation of NIS2 Article 21(1), 21(2)(i) and the physical-environment approach in NIS2 Article 21(2). CIR Annex 12.2 provides handling context; location tracking or remote erasure is not universally required. ISO comparison: A.7.9, Part 3 p.7; A.6.7, Part 3 p.4. CIR-specific requirement within CIR scope: CIR Annex 12.2.1; CIR Annex 12.2.2(a); CIR Annex 12.2.2(b); CIR Annex 12.3.1.", "ref": "Art. 21(1)", "applicability": {"condition": "only where work assets are used outside organisational premises", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C42.7','Removable Media Connections Are Blocked Unless Organisationally Authorised','Removable Media Connections Are Blocked Unless Organisationally Authorised','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Connection of removable media is technically prohibited unless an organisational reason authorises it.", "evidence": "Examples: enforced removable-media connection restrictions, organisational reasons and authorisation for exceptions, and safe allowed/blocked connection checks on representative systems.", "risk_text": "R1: Unauthorised removable media introduce malicious code into connected systems.<br>R2: Users copy sensitive information to unapproved media and remove it from organisational control.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 12.3.1; CIR Annex 12.3.2(a).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.8','Removable Media Are Scanned Before Use and Do Not Auto-Execute','Removable Media Are Scanned Before Use and Do Not Auto-Execute','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Removable media do not auto-execute and are scanned for malicious code before use.", "evidence": "Examples: representative configuration checks and safe demonstrations showing that removable media cannot auto-execute and are scanned for malicious code before use. Existing scan records may corroborate operation.", "risk_text": "R1: Malicious code executes from removable media, stealing information or credentials.<br>R2: Media-borne malware corrupts data, disrupts systems or spreads to connected services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.10", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (g) CIR-specific requirement within CIR scope: CIR Annex 12.3.1; CIR Annex 12.3.2(b).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C42.9','Portable Storage Is Protected in Transit and Storage','Portable Storage Is Protected in Transit and Storage','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Apply appropriate handling and storage protections to portable media containing organisational data while stored and transported, using cryptography where appropriate. Check the actual protections, not only issue or custody records; recording who holds a device does not establish that its data or the medium are protected.", "evidence": "Examples: observed portable-storage handling and storage/transport protections, with cryptographic settings and safe checks where encryption is appropriate. Custody information or transfer records may support the assessment where relevant.", "risk_text": "R1: Lost or stolen portable media disclose readable sensitive information.<br>R2: Loss or damage to portable media makes required information unavailable where no usable copy exists.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (h) CIR-specific requirement within CIR scope: CIR Annex 12.3.2(c); CIR Annex 12.3.2(d).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','TRN-DATA','Employees Are Trained in Secure Data and Removable Media Handling','Employees Are Trained in Secure Data and Removable Media Handling','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-DATA-TRN · Data and removable media training", "topic_label": "I-DATA-TRN · Data and removable media training", "description": "Employees handling data or removable media receive practical instruction in the applicable classification, transfer, storage and disposal rules, so they can carry out those tasks securely; existing training can cover this without a separate course.", "evidence": "Examples: relevant data and removable-media handling instruction and participation records, supported by staff explanation or practical checks of the applicable handling rules. Existing onboarding or other training may supply this evidence without a separate course or certificate.", "risk_text": "R1: Employees mishandle or disclose sensitive work information or fail to escalate its loss promptly.<br>R2: Employees introduce malicious code by using removable media unsafely.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(g) and (i). CIR Annex 8.1.2(b)–(c), 12.2.1 and 12.3.1 link awareness to asset-handling and removable-media rules within CIR scope. A separate course or certificate is not mandated.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','DATA-DELETE','Data No Longer Required Is Securely Deleted','Data No Longer Required Is Securely Deleted','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Apply the relevant retention and deletion criteria to securely remove information that is no longer needed, taking account of valid retention requirements and relevant copies; this concerns the data lifecycle, not only disposal of equipment.", "evidence": "Examples: applicable retention/deletion criteria and representative deletion outcomes showing that data no longer required are securely removed, with checks of relevant copies under the applicable disposal arrangements. Use metadata or controlled demonstrations rather than copying the deleted sensitive content.", "risk_text": "R1: Obsolete sensitive data are exposed during later access, disclosure or restoration, extending the population and period affected by a breach.<br>R2: Deletion is applied before required retention or preservation needs end, destroying records needed for operations, investigations or substantiating decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.33", "A.8.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "H implementation of NIS2 Article 21(1) and 21(2)(i), limiting unnecessary data exposure. CIR Annex 12.2.2(b) addresses deletion rules within its scope; no universal retention duration is imposed here. ISO comparison: A.8.10, Part 4 p.4, Q1–3 (misprinted as 8.1). CIR-specific requirement within CIR scope: CIR Annex 12.2.1; CIR Annex 12.2.2(a); CIR Annex 12.2.2(b).", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C40.12','Personnel Assets Are Returned, Deposited or Deleted and Residual Access Removed on Termination','Personnel Assets Are Returned, Deposited or Deleted and Residual Access Removed on Termination','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Reconcile termination actions with the assets held by the person and verify their return, deposit or appropriate deletion, together with removal of residual access. Collecting a laptop alone is insufficient if organisational information or usable accounts, tokens or remote-access paths remain outside authorised control; remote erasure is not required in every case.", "evidence": "Examples: termination records reconciled with assets held by the person, showing return, deposit or appropriate deletion and removal of residual access. Receipts, system records or supervised checks may demonstrate the outcome without requiring remote erasure in every case.", "risk_text": "R1: Former personnel retain and disclose organisational information after their authority ends.<br>R2: Unreturned equipment or retained access enables unauthorised use of organisational resources.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 12.5; CIR Annex 11.2.2(b).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.4','Information Is Securely Erased on Reuse and Disposal','Information Is Securely Erased on Reuse and Disposal','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Before equipment or media are reused or disposed of, remove the information they hold using erasure or destruction appropriate to the medium and sensitivity, and verify the outcome; merely deleting a file reference is not evidence of secure removal.", "evidence": "Examples: reuse or disposal records linked to the relevant equipment/media, identifying the erasure or destruction method and checks showing that information was securely removed before reuse or release.", "risk_text": "A recipient of reused, sold or discarded equipment recovers residual sensitive information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.10", "A.7.14", "A.8.10"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) (asset management) CIR-specific requirement within CIR scope: CIR Annex 12.2.1; CIR Annex 12.2.2(a); CIR Annex 12.2.2(b).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.7','Necessary Background Checks Precede Assignment to Sensitive Roles','Necessary Background Checks Precede Assignment to Sensitive Roles','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Before assigning sensitive duties, complete the background checks justified by the role and permitted by applicable law, using only the personal information necessary to establish the result.", "evidence": "Examples: necessary, lawful screening criteria for sensitive roles and protected outcome/date records showing completion before assignment. Inspect only the information needed to substantiate the check, not unrestricted background reports.", "risk_text": "A person with relevant, lawfully discoverable trust concerns gains sensitive access and misuses it to obtain information or manipulate systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 10.2.1; CIR Annex 10.2.2(a); CIR Annex 10.2.2(b).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.6','Security-Relevant Personnel Are Qualified for Their Roles','Security-Relevant Personnel Are Qualified for Their Roles','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Match the security skills and expertise needed for assigned duties with the person''s qualifications, experience or demonstrated capability, and address relevant gaps; a particular certificate is not automatically required.", "evidence": "Examples: role-specific competence needs compared with relevant qualifications, experience or demonstrated capability of assigned personnel, including how any identified capability gaps are addressed.", "risk_text": "Personnel make security-relevant configuration or response errors because their assigned tasks exceed their skills, exposing information or prolonging service faults.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["7.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 10.1.2(d); CIR Annex 8.2.1.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.1','Personnel Accept Security and Confidentiality Duties Before Access','Personnel Accept Security and Confidentiality Duties Before Access','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Before relevant access is granted, personnel understand and accept the security and confidentiality responsibilities attached to their work; accepted contractual terms or an equivalent recorded commitment can suffice without a duplicate agreement.", "evidence": "Examples: accepted employment terms or equivalent recorded commitments covering security and confidentiality duties, with acceptance dates compared with the granting of relevant access.", "risk_text": "Personnel disclose or misuse information after receiving access without understanding and accepting their security and confidentiality responsibilities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.2", "A.6.6"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(i). CIR Annex 10.1.1 requires understanding and commitment to security responsibilities within its scope; the before-access timing and evidence format are H implementation choices. An accepted contract or equivalent recorded commitment may suffice without a duplicate confidentiality agreement.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.9','A Lawful, Communicated Disciplinary Process Addresses Security-Policy Violations','A Lawful, Communicated Disciplinary Process Addresses Security-Policy Violations','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Personnel are informed how security-policy violations are handled through a lawful disciplinary process, and actual cases follow that process; an organisation does not need to invent a disciplinary case to demonstrate readiness.", "evidence": "Examples: the lawful disciplinary process and evidence of communication to relevant personnel, with anonymised handling records if security-policy violations have occurred. Absence of a disciplinary case does not itself indicate failure.", "risk_text": "Violations are ignored or handled inconsistently, allowing repeated unsafe behaviour or unfair treatment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.4"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 10.4.1.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.8','Continuing Security Duties Are Defined and Enforced After Employment Changes or Termination','Continuing Security Duties Are Defined and Enforced After Employment Changes or Termination','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Specify the security duties that continue after a role change or termination in the applicable employment terms or agreements, communicate them to the person concerned and enforce them where applicable. A generic contract template alone does not demonstrate that the relevant continuing duties were agreed, communicated and enforced.", "evidence": "Examples: defined continuing security duties in employment terms or equivalent arrangements, their communication at role change or termination, and relevant records showing enforcement where those duties apply.", "risk_text": "Former or reassigned personnel disclose or misuse information because continuing duties are unclear.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i) CIR-specific requirement within CIR scope: CIR Annex 10.3.1; CIR Annex 10.3.2.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','TRN-07','Security Training Needs Are Defined by Role','Security Training Needs Are Defined by Role','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Security training needs are defined by role, based on security responsibilities, systems used and exposure. Roles with the same training needs may be grouped; a separate training plan for every job title is not required.", "evidence": "Examples: training-needs records linking roles or justified role groups to security responsibilities, systems used, exposure and required learning.", "risk_text": "Role-specific security tasks are performed incorrectly because generic training does not address the actual tools, privileges or exposure of the role.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g) CIR-specific requirement within CIR scope: CIR Annex 8.2.1; CIR Annex 8.2.2; CIR Annex 8.2.3.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','TRN-04','Cybersecurity Awareness Guidance Is Clear and Accessible to Employees','Cybersecurity Awareness Guidance Is Clear and Accessible to Employees','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Clear cybersecurity awareness guidance is prepared and accessible to employees. It covers the organisation''s security policies and procedures, relevant threats, safeguards in use, safe working practices, and contact points for advice and reporting concerns. Any accessible format may be used, including intranet content, training materials, videos or short instructions; a separate booklet is not required.", "evidence": "Examples: accessible awareness guidance covering current policies, procedures, relevant threats, safeguards, safe practices and advice/reporting contacts, with checks that employees can reach it.", "risk_text": "Employees improvise unsafe information handling or delay reporting concerns because usable guidance and contact information cannot be found.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.3", "A.6.3", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g) CIR-specific requirement within CIR scope: CIR Annex 8.1.1; CIR Annex 8.1.2(b); CIR Annex 8.1.2(c).", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','TRN-02','New Employees Receive Cybersecurity Awareness Within a Risk-Appropriate Onboarding Timeframe','New Employees Receive Cybersecurity Awareness Within a Risk-Appropriate Onboarding Timeframe','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Deliver onboarding cybersecurity awareness within the organisation''s defined, risk-appropriate timeframe. Compare starter dates with completion records and follow up late or missed participation; assigning a course without its completion does not demonstrate that a new employee received the required awareness in time.", "evidence": "Examples: the organisation''s risk-appropriate onboarding timeframe, starter dates and awareness-completion records, with handling of missed or late completion.", "risk_text": "New starters expose information or follow fraudulent instructions before they have learned the essential security practices for their work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.3", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g) CIR-specific requirement within CIR scope: CIR Annex 8.1.2(a).", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','TRN-03','Planned Awareness and Role-Based Security Training Are Delivered Regularly','Planned Awareness and Role-Based Security Training Are Delivered Regularly','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Planned Awareness and Role-Based Security Training Are Delivered Regularly. Repeat awareness activities and deliver the security training identified through TRN-07 at planned intervals. Check delivery and participation records, address missed training, and reuse evidence from the relevant operational topics rather than requiring duplicate courses.", "evidence": "Examples: planned awareness and role-based training intervals compared with actual delivery, participation and missed-training follow-up, linked to the needs identified under TRN-07. Reuse relevant operational-topic training records without requiring duplicate courses.", "risk_text": "Personnel repeat unsafe practices or cannot perform assigned security tasks because planned awareness and role-based training are not delivered or refreshed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "7.3", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g); CIR Annex 8.1.2(a), 8.2.1 and 8.2.5.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','TRN-09','Transferred Employees Receive Training for New Security Skill Requirements (Applies to transfers into roles requiring security-relevant skills and expertise.)','Transferred Employees Receive Training for New Security Skill Requirements (Applies to transfers into roles requiring security-relevant skills and expertise.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Identify the new security-relevant skill requirements introduced by a role transfer and provide training that addresses them. Compare the changed duties with training content and completion; prior general awareness or training for the previous role is not sufficient evidence of coverage of the new needs. (Applies to transfers into roles requiring security-relevant skills and expertise.)", "evidence": "Where a transfer introduces new security-relevant skill needs, examples include transfer/role information, the changed needs and completion of training addressing them.", "risk_text": "Transferred personnel make security-relevant mistakes while performing unfamiliar duties, exposing information or interrupting the affected operation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g) CIR-specific requirement within CIR scope: CIR Annex 8.2.4.", "ref": "Art. 21(2)(g)", "applicability": {"condition": "to transfers into roles requiring security-relevant skills and expertise", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','TRN-05','Training Effectiveness Is Assessed Beyond Attendance','Training Effectiveness Is Assessed Beyond Attendance','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Training Effectiveness Is Assessed, Not Inferred from Attendance. Check whether participants can apply the security knowledge and skills required for their work. For CIR-covered entities, assess the effectiveness of training for roles requiring security expertise; testing of the general awareness programme is required where appropriate. Use proportionate practical checks, exercises or other suitable assessments and address ineffective learning.", "evidence": "Examples: proportionate practical checks, exercises or other assessments showing whether participants can apply required security skills, evaluated results and responses to ineffective learning. For CIR-covered entities, include effectiveness assessment for security-expertise roles; assess general awareness where appropriate.", "risk_text": "Personnel remain unable to recognise threats or perform assigned security tasks because attendance is mistaken for effective learning and deficiencies are not corrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(f), (g); CIR Annex 8.1.3 and 8.2.3. The appropriateness qualifier in 8.1.3 must not be used to waive the assessment in 8.2.3.", "ref": "Art. 21(2)(f)"}'::jsonb),
  ('NIS2','TRN-06','Awareness and Security Training Programmes Are Kept Current','Awareness and Security Training Programmes Are Kept Current','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Awareness and Security Training Programmes Are Kept Current. Review their content and delivery arrangements at planned intervals against current policies, responsibilities, technologies and relevant threats. Update the programme and associated role-based needs where these change. Topic-specific courses stay in their operational topics; this control assesses programme maintenance.", "evidence": "Examples: dated reviews of programme content and delivery at planned intervals against current policies, responsibilities, technologies and threats, with resulting updates to materials and role-based needs where necessary.", "risk_text": "Employees follow outdated cyber-hygiene advice and mishandle current threats or changed working practices.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(g); CIR Annex 8.1.3 and 8.2.5.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','C40.2','Access Rules Define Who May Use Which Resources','Access Rules Define Who May Use Which Resources','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Set access rules linking users or roles to the resources and permitted actions they need, taking business and protection needs into account; these rules provide the basis for individual access decisions.", "evidence": "Examples: access-control rules identifying which users or roles may use which resources, compared with representative permissions and the business/protection needs supporting them.", "risk_text": "Users are granted access beyond legitimate business need, allowing unauthorised disclosure, modification or deletion of information and disruption of the affected service.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["7.5.3", "A.5.15", "A.8.1", "A.8.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 11.1.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.10','User and System Identities Are Managed Throughout Their Lifecycle','User and System Identities Are Managed Throughout Their Lifecycle','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Create, maintain and retire identities for people and systems so their assignment and ownership remain clear and unnecessary identities are deactivated; the identity record is distinct from the permissions attached to it.", "evidence": "Examples: user and system identity records showing identifiable ownership and correct assignment through creation, change and retirement, compared with representative active and retired accounts.", "risk_text": "R1: Orphaned user or system accounts are used for unauthorised access, and unclear ownership delays containment.<br>R2: An account is assigned to the wrong person or technical identity, giving the wrong party access and misattributing subsequent actions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 11.5.1–11.5.2, 11.5.4.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.3','Access Rights Are Approved, Updated and Removed','Access Rights Are Approved, Updated and Removed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Implement authorised access grants, changes and removals when responsibilities or access needs change, and verify the resulting permissions; planned reviews of existing rights are assessed separately under ACCESS-RECERT.", "evidence": "Examples: access decisions and their authorisation linked to implemented grants, updates and removals, compared with actual rights and current need on representative resources.", "risk_text": "R1: Unapproved or obsolete permissions are used to view or alter information after the business need has ended.<br>R2: Incorrect access updates or premature revocation prevent authorised personnel or service accounts from performing necessary tasks, interrupting legitimate operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.3", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 11.2.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','ACCESS-RECERT','Existing Access Rights Are Reviewed Against Current Need','Existing Access Rights Are Reviewed Against Current Need','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Review the access rights of users and service accounts at planned intervals against their current business need. Modify rights following relevant organisational changes. Record the review results and required corrections, then verify that rejected or excessive rights were removed or changed. Account existence alone does not justify every assigned permission. Reuse the privileged-account review under C43.1 where it covers the same rights; do not record the same deficiency twice.", "evidence": "Dated rights listings for the reviewed users and service accounts; planned review intervals and responsible reviewers; recorded decisions on continued need; resulting changes or revocations and verification that they took effect.", "risk_text": "R1: Permissions accumulated through earlier roles or projects remain active and enable unauthorised access to or modification of information.<br>R2: A review is marked complete while permissions it rejected remain usable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), supporting implementation; CIR Annex 11.2.3 within CIR scope.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.11','Shared Accounts Are Justified and Approved Exceptions','Shared Accounts Are Justified and Approved Exceptions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Where an account must be shared, retain its specific justification and approval and apply safeguards for accountable use; convenience alone does not demonstrate that shared access is a justified exception.", "evidence": "Examples: identified shared accounts with specific justifications and approvals, compared with actual shared-account use and applicable accountability safeguards. Existing account metadata or decisions may suffice without a separate exception register.", "risk_text": "R1: Shared access conceals who performed an action and makes misuse harder to investigate.<br>R2: A former or reassigned user retains a shared credential and continues to access resources after their individual authorisation has ended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i); CIR Annex 11.5.3.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C43.2','Administration Uses Separate, Individually Assigned Accounts','Administration Uses Separate, Individually Assigned Accounts','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Give administrators individually assigned administrative accounts separate from their ordinary-use accounts, and use those identities for administrative work so elevated actions can be attributed to the responsible person.", "evidence": "Examples: individually assigned administrative accounts linked to their users and separate ordinary-use accounts, with safe account/usage checks demonstrating that administration uses the separate identities.", "risk_text": "R1: Compromise of a routine-use account enables privileged changes or access to protected data.<br>R2: Administrative actions cannot be reliably attributed to an individual, impairing investigation and accountability.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.3.2.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C43.3','Administration Systems Are Separated and Protected','Administration Systems Are Separated and Protected','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Separate and protect the systems used for administration so ordinary user activity or unauthorised connections do not provide a route into the management environment; separate account names alone do not establish system separation.", "evidence": "Examples: administration-system design and operating configurations showing separation and protection, corroborated by representative access, isolation and hardening checks.", "risk_text": "Malware on an administration workstation captures privileged sessions or credentials and uses them to compromise managed systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.4.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C43.1','Privileged Access Is Regularly Checked Against Current Need','Privileged Access Is Regularly Checked Against Current Need','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "At planned intervals and following organisational changes, check whether administrators still need their privileged permissions and implement the resulting changes; reuse this evidence in ACCESS-RECERT rather than duplicating the same finding.", "evidence": "Examples: dated reviews of the privileged-account and permission population against current responsibilities, with retained decisions and implemented removal or adjustment of unnecessary rights.", "risk_text": "Obsolete or excessive administrator rights are misused to access sensitive information or alter systems beyond the holder''s current responsibilities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.3.3.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C40.5','Remote Access Uses Approved, Encrypted Connections','Remote Access Uses Approved, Encrypted Connections','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Use organisation-approved remote-access methods that protect connections with encryption and restrict them to authorised access; assess actual connection settings, not simply whether a remote-access product is installed.", "evidence": "Examples: approved remote-access methods compared with deployed encryption, access scope and representative connection checks showing that actual remote access follows those methods.", "risk_text": "R1: Remote-access traffic or credentials are intercepted, or commands and data are altered in transit, compromising confidentiality or the integrity of remote operations.<br>R2: Unapproved or overbroad remote connections give an attacker access to internal systems.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (i), (j); CIR Annex 6.7, 11.1 and 11.7.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','SUP-ACCESS-WINDOW','Service-Provider Connections Are Approved and Time-Limited (Applies where service providers connect to the entity''s network and information systems.)','Service-Provider Connections Are Approved and Time-Limited (Applies where service providers connect to the entity''s network and information systems.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-SUP-ACCESS · Time-limited service-provider connections", "topic_label": "I-SUP-ACCESS · Time-limited service-provider connections", "description": "Require an authorisation request before enabling a service-provider connection. Record the approved purpose, systems or resources and permitted time period. Close or disable the connection when that period ends, and approve any justified extension. Verify that access duration is controlled in operation; encrypted transport alone does not demonstrate this. C40.5 assesses the secure remote-access method and C51.3 assesses supplier-access visibility; reuse their records without duplicating findings. The express CIR requirement applies only within CIR scope.", "evidence": "Provider connection requests and approvals identifying resources and permitted duration; connection settings and redacted session records; expiry/closure records or safe tests; justified extension approvals. A named remote-access product is not required.", "risk_text": "R1: A supplier connection remains usable after the approved support period and provides an unnecessary path for an attacker.<br>R2: Provider access extends to systems or activities outside the approved scope and enables unauthorised disclosure or changes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (e), (i), supporting implementation; CIR Annex 6.7.2(h) and 11.2.2(d) within CIR scope.", "ref": "Art. 21(2)(d)", "applicability": {"condition": "where service providers connect to the entity''s network and information systems", "condition_source": "control_name", "scope_group": "APP-SUP-ACCESS", "presentation": "inline"}}'::jsonb),
  ('NIS2','C43.4','Privileged Utility Programs Are Restricted and Monitored','Privileged Utility Programs Are Restricted and Monitored','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-UTIL · Privileged utility programs", "topic_label": "I-UTIL · Privileged utility programs", "description": "Limit tools capable of bypassing normal application or system controls to authorised uses and monitor their execution, so powerful maintenance or diagnostic utilities do not become an uncontrolled route to data or settings.", "evidence": "Examples: identified privileged utilities, their access/execution restrictions and representative usage or monitoring records showing that use is limited to authorised purposes and monitored.", "risk_text": "R1: Privileged utilities bypass application safeguards to expose or modify protected data.<br>R2: Misuse of privileged utilities cannot be reconstructed, delaying attribution and containment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2", "A.8.18"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Supporting implementation control (H) for NIS2 Article 21(1), 21(2)(i). The Directive does not expressly name privileged utility programs.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C41.1','Authentication Uses Risk-Appropriate Strength','Authentication Uses Risk-Appropriate Strength','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Authentication Uses Risk-Appropriate Strength, Including Multi-Factor or Continuous Authentication. Select and enforce authentication according to the resource''s classification and access risk. Use multi-factor authentication (MFA) or continuous authentication where appropriate, explicitly assessing privileged and remote access. Where passwords are used, enforce suitable strength and reject commonly used or known-compromised passwords. A policy statement alone is not proof that the login paths enforce the selected protections.", "evidence": "Examples: authentication choices tied to resource classification and access risk, explicitly addressing privileged and remote access, with enforced settings and safe tests across relevant login paths. Where applicable, verify MFA or continuous authentication and rejection of weak, common or known-compromised passwords using non-production test credentials, not live secrets.", "risk_text": "Weak authentication allows attackers to access sensitive systems using stolen credentials.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(j); CIR Annex 11.6.1-11.6.3, 11.7 and 11.3.2(a). Rejection of weak or compromised passwords is implementation guidance in ENISA Technical Implementation Guidance, section 11.6, p.142, not a separately named Directive duty.", "ref": "Art. 21(2)(j)"}'::jsonb),
  ('NIS2','C41.11','Account Setup and Recovery Do Not Bypass Authentication Security','Account Setup and Recovery Do Not Bypass Authentication Security','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Account enrolment, initial credential delivery and recovery verify the user''s entitlement and preserve the required authentication protection, so an attacker cannot gain access through a weaker setup or reset route.", "evidence": "Examples: account-enrolment, initial-delivery and recovery arrangements with redacted case records or controlled test-account demonstrations showing that identity checks and recovery paths do not bypass the required authentication protection.", "risk_text": "An attacker obtains account access through weak enrolment, initial credential delivery or recovery checks, bypassing otherwise strong login protection.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Supporting implementation control for NIS2 Article 21(2)(j); the Directive does not expressly prescribe a separate recovery control.", "ref": "Art. 21(2)(j)"}'::jsonb),
  ('NIS2','C41.6','Passwords and Other Authentication Secrets Are Protected','Passwords and Other Authentication Secrets Are Protected','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Protect authentication secrets during allocation, storage and transmission, and conceal password entry by default with any reveal requiring deliberate user action; display masking alone does not protect stored or transmitted secrets.", "evidence": "Examples: redacted storage, transmission and access settings demonstrating protection of authentication secrets, together with synthetic-input checks showing password-entry concealment by default and reveal only through deliberate user action. Do not collect live passwords, tokens or other authentication secrets.", "risk_text": "Exposed authentication secrets, including passwords observed during entry, allow unauthorised access.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.6.2(a)–(b). Password-entry concealment by default is an H implementation detail; any reveal requires deliberate user action. Display masking does not replace secure transmission or storage.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C41.8','Repeated Failed Logins Trigger Blocking and Credential Reset','Repeated Failed Logins Trigger Blocking and Credential Reset','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Define the unsuccessful-login threshold and ensure that reaching it triggers user blocking and authentication-credential reset; this assesses the configured response without imposing a universal number of attempts.", "evidence": "Examples: configured failed-login thresholds and blocking/reset arrangements, with safe test-account results or redacted events showing that repeated failures trigger blocking and credential reset. Use the applicable chosen threshold without inventing a universal attempt count or exposing live credentials.", "risk_text": "R1: Repeated guessing or automated login attempts discover usable credentials and lead to account takeover.<br>R2: An attacker deliberately triggers account-wide lockouts or repeated resets, preventing legitimate users from accessing services or overloading the recovery process.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.6.2(d). The provision does not prescribe a fixed numerical threshold.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','DEVICE-LOCK','Unattended Devices Lock and Require Reauthentication','Unattended Devices Lock and Require Reauthentication','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "An unattended device prevents continued use until the user authenticates again, using the applicable locking arrangements; a device lock is distinct from terminating the application''s underlying session.", "evidence": "Examples: applicable device-lock settings and safe observation on representative devices showing locking when unattended and reauthentication before access resumes.", "risk_text": "An unauthorised person uses an unattended, unlocked device to view information or perform actions in the legitimate user''s account.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.7", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "H implementation of NIS2 Article 21(2)(i) and (j). The Directive does not prescribe a particular lock timeout. CIR Annex 11.6.2(e) concerns session termination and is not presented as an express device-lock requirement.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C41.9','Inactive Sessions End Automatically','Inactive Sessions End Automatically','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Configure a predefined inactivity period after which the authenticated session terminates and no longer authorises access; hiding the screen without ending the session does not satisfy this control.", "evidence": "Examples: inactivity termination settings and safe session tests on relevant applications showing that expired sessions no longer grant authenticated access.", "risk_text": "Another person reuses an inactive authenticated session to read information or perform actions as the legitimate user.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.7", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.6.2(e).", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C41.7','Credentials Are Replaced or Revoked on Suspected or Confirmed Compromise','Credentials Are Replaced or Revoked on Suspected or Confirmed Compromise','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Compromised Authentication Credentials Are Replaced or Revoked. Act on suspected or confirmed compromise by changing affected passwords and replacing or revoking other affected credentials, such as tokens or authentication certificates. Ensure the exposed credential no longer grants access and assess affected sessions through incident response.", "evidence": "Examples: redacted suspected/confirmed compromise cases or controlled exercises showing replacement or revocation of affected credentials, invalidation of their access and assessment of affected sessions through incident response. Use test credentials or metadata and do not collect exposed live secrets.", "risk_text": "An attacker continues to authenticate with an exposed password, token or other credential after the organisation becomes aware of the compromise.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b), (i), (j); CIR Annex 11.6.2(c), compromise trigger. Initial changes and predefined-interval changes are separate tests.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C41.10','Authentication Methods Are Reviewed Regularly','Authentication Methods Are Reviewed Regularly','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "At planned intervals, assess whether the authentication procedures and technologies remain appropriate for current risks and access needs, then update them or substantiate continued use; this is not a periodic credential-change check.", "evidence": "Examples: dated reviews of authentication methods against current threats, resource/access needs and relevant changes, with conclusions and implemented updates or justified continued use. Review timing and coverage should demonstrate that the methods are reviewed regularly.", "risk_text": "Authentication weaknesses become exploitable as threats or access needs change, while the organisation continues to trust outdated methods.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.6.4.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C41.12','Confidential Information Is Hidden Until Authentication Succeeds','Confidential Information Is Hidden Until Authentication Succeeds','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Prevent unauthenticated access to confidential content through the application''s relevant access paths, including direct requests where applicable; displaying a login page is insufficient if protected information remains accessible behind it.", "evidence": "Examples: unauthenticated tests using synthetic protected content across relevant pages, direct URLs, APIs and other access paths, showing that confidential information is unavailable until authentication succeeds. Corroborate with access-enforcement settings; a login screen alone is insufficient.", "risk_text": "An unauthenticated person reads protected information by bypassing the normal login screen.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.3", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Supporting implementation control (H) for NIS2 Article 21(1), 21(2)(i). Tests effective information-access restriction, not a separately named Directive obligation.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C41.13','Initial, Default and Temporary Credentials Are Changed Before Normal Use','Initial, Default and Temporary Credentials Are Changed Before Normal Use','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Initial, Default and Temporary Credentials Are Changed Before Normal Use. Replace or change initial and temporary passwords and supplier-provided default authentication secrets through a controlled setup process. Verify that defaults no longer permit access. For credential types that are individually generated rather than shared defaults, document the applicable secure provisioning method.", "evidence": "Examples: secure setup/provisioning arrangements and redacted activation records or test-account checks showing initial, temporary and supplier-default secrets are changed before normal use and defaults no longer permit access. For individually generated credential types, inspect the documented secure provisioning method; do not collect live secrets.", "risk_text": "A person who knows an initial, temporary or supplier-default secret accesses the account or system after deployment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(i), (j); CIR Annex 11.6.2(c), initial credential change; ENISA Technical Implementation Guidance section 11.6, p.142, supplier defaults.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','C41.14','An Approved Password Manager Is Used for Work Passwords','An Approved Password Manager Is Used for Work Passwords','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Use an organisation-approved password manager for work passwords and protect access to its vault and recovery process; the control assesses safe, actual use without prescribing a vendor or requiring disclosure of stored passwords.", "evidence": "Examples: the approved password-manager choice, evidence of actual use for work passwords and safe checks of vault access protections and authorised recovery arrangements. Use non-secret configuration or demonstrations, never vault exports, recovery secrets or work passwords.", "risk_text": "R1: Exposed or reused work passwords enable account compromise.<br>R2: Weak protection or recovery of a password vault exposes credentials for multiple work accounts at once.<br>R3: Loss of access to the password vault, without a usable authorised recovery route, prevents staff from retrieving credentials needed for critical work or recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Supporting implementation control (H) for NIS2 Article 21(2)(i), (j). NCSC recommends appropriate password-manager use; NIST supports password managers and autofill. Neither NIS2 nor these references creates a universal requirement to purchase a particular product.", "ref": "Art. 21(2)(i)"}'::jsonb),
  ('NIS2','AUTH-INTERVAL','Authentication Credentials Are Changed at Predefined Intervals. (Applies only to entities within the scope of Commission Implementing Regulation (EU) 2024/2690.)','Authentication Credentials Are Changed at Predefined Intervals. (Applies only to entities within the scope of Commission Implementing Regulation (EU) 2024/2690.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-CIR-INTERVAL · Credential change intervals within CIR scope", "topic_label": "J-CIR-INTERVAL · Credential change intervals within CIR scope", "description": "Define the change intervals for the relevant authentication credentials and implement changes when due. Retain the interval decisions and evidence that they operate. The Regulation does not set a universal number of days. This control assesses the interval requirement only; reuse C41.13 for initial/default changes and C41.7 for suspected-compromise changes without duplicating their assessment. Do not apply this CIR-specific requirement automatically to entities outside CIR scope.", "evidence": "Confirmed CIR applicability; documented credential-change intervals and responsible owners; enforced settings or controlled change procedures; dated, redacted records showing changes when due and follow-up of missed changes. Do not collect passwords or other live authentication secrets as evidence.", "risk_text": "A credential exposed without detection remains usable beyond its defined change interval, allowing continued unauthorised access.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "CIR D", "nis2_basis": "Commission Implementing Regulation (EU) 2024/2690, Annex 11.6.2(c), predefined-interval requirement. Related NIS2 Article 21(2)(i), (j); the specific interval wording is in the Regulation, not expressly in the Directive. Implementation references, not exceptions to CIR: [ENISA Technical Implementation Guidance, June 2025, section 11.6, p.142](https://www.enisa.europa.eu/sites/default/files/2025-06/ENISA_Technical_implementation_guidance_on_cybersecurity_risk_management_measures_version_1.0.pdf#page=143) gives event-triggered password-change examples; [NIST SP 800-63B-4, section 3.1.1.2](https://pages.nist.gov/800-63-4/sp800-63b/authenticators/) rejects routine periodic password changes and requires a change on evidence of compromise; BSI IT-Grundschutz Compendium, Edition 2023, ORP.4.A23 advises against purely time-driven password changes and consideration of periodic changes when compromise detection is not possible. These sources inform implementation decisions but do not waive the CIR predefined-interval requirement or establish a universal 30-, 60- or 90-day period.", "ref": "Art. 21(2)(i)", "applicability": {"condition": "only to entities within the scope of Commission Implementing Regulation (EU) 2024/2690", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','TRN-AUTH','Employees Are Trained in Password and Sign-In Security','Employees Are Trained in Password and Sign-In Security','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH-TRN · Password and remote-access training", "topic_label": "J-AUTH-TRN · Password and remote-access training", "description": "Employees receive practical instruction in protecting authentication secrets, recognising suspicious sign-in activity and following the organisation''s response rules, using examples relevant to the authentication methods they use.", "evidence": "Examples: password and sign-in instruction, relevant participation records and staff explanations or safe exercises addressing secret handling, sign-in checks and response to suspicious authentication activity.", "risk_text": "An employee discloses credentials or approves an attacker''s sign-in, defeating otherwise effective technical protection.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(g), linked to access control and authentication under (i) and (j). CIR Annex 8.1.2 and 11.6.2(b) support relevant awareness and advice on authentication information within CIR scope.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','TRN-REMOTE','Employees Are Trained in Secure Remote Access','Employees Are Trained in Secure Remote Access','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH-TRN · Password and remote-access training", "topic_label": "J-AUTH-TRN · Password and remote-access training", "description": "Employees who use remote access are instructed in the organisation''s approved connection methods and the precautions needed when working away from its premises; the instruction follows the actual remote-access arrangements rather than prescribing a particular technology.", "evidence": "Examples: instruction in the organisation''s approved remote-access methods and precautions, relevant participation records and staff explanations or practical checks of secure connection use.", "risk_text": "Employees bypass the protected connection, trust a false connection or expose internal resources through an unauthorised access route.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.6.7", "A.7.9"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(g), linked to access control and authentication under (i) and (j). CIR Annex 8.1.2(b)–(c) links awareness to applicable policies and safeguards within CIR scope. No universal requirement for a particular remote-access technology.", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','C38.5','Network Architecture Documentation Is Accurate and Current','Network Architecture Documentation Is Accurate and Current','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Maintain architecture records showing the relevant systems, zones, connections and dependencies actually deployed. Compare them with current configurations or controlled observation and trace relevant changes; a dated diagram does not establish accuracy if the running network has changed without corresponding documentation updates.", "evidence": "Examples: current network diagrams or equivalent architecture records showing relevant systems, zones, connections and dependencies, compared with deployed configurations or controlled observation. Dated revisions or change links should substantiate accuracy and currency.", "risk_text": "Responders or administrators act on an incorrect network map, overlooking an attack path or disrupting a dependency during containment or change.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(a).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.3','Secure Configurations Are Applied and Deviations Are Managed','Secure Configurations Are Applied and Deviations Are Managed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Secure configurations are applied and deviations are managed. Compare actual settings with approved security configurations throughout operation, identify deviations, and correct them or record a justified, authorised exception with appropriate safeguards.", "evidence": "Examples: approved secure configuration baselines compared with actual settings during operation, and records of deviations showing correction or justified authorised exceptions with operating safeguards.", "risk_text": "R1: Configuration drift exposes unnecessary services or weak permissions that attackers use to access systems.<br>R2: Uncontrolled configuration deviations cause service malfunction or incompatible operation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.1", "A.8.9", "A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(g); Recital 89 (device configuration) CIR-specific requirement within CIR scope: CIR Annex 6.3.1; CIR Annex 6.3.2(a); CIR Annex 6.3.2(b).", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','C38.4','Networks Are Segmented by Risk and Protection Needs','Networks Are Segmented by Risk and Protection Needs','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Networks Are Segmented by Risk and Protection Needs. Place systems and services in defined security zones according to their function, criticality and trust level, separating critical and third-party environments where required. This control assesses the overall segmentation design and implementation; dedicated controls assess wireless separation and inbound/outbound filtering.", "evidence": "Examples: defined security zones and placement decisions based on function, criticality and trust, with configurations and safe cross-zone checks showing the intended segmentation, including critical and third-party environments where required.", "risk_text": "R1: An attacker moves from a lower-trust or third-party zone into sensitive systems and discloses or alters information.<br>R2: An infection or disruptive event propagates across insufficiently separated zones and affects otherwise unrelated services.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(g); Recital 89 (network segmentation) CIR-specific requirement within CIR scope: CIR Annex 6.8.1; CIR Annex 6.8.2(a); CIR Annex 6.8.2(b); CIR Annex 6.8.2(c); CIR Annex 6.8.2(e).", "ref": "Art. 21(2)(g)"}'::jsonb),
  ('NIS2','C38.12','A Demilitarised Zone Protects Incoming and Outgoing Network Communication','A Demilitarised Zone Protects Incoming and Outgoing Network Communication','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "A demilitarised zone protects communication originating from or destined to the entity''s networks.", "evidence": "Examples: DMZ architecture and deployed boundary/service configurations, corroborated by safe connection checks showing how traffic to or from the entity''s networks is protected through the intended separation.", "risk_text": "Compromise of an externally reachable service provides a direct path into internal systems, extending the breach beyond the exposed service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g) CIR-specific requirement within CIR scope: CIR Annex 6.8.2(d).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.10','Administration Networks and Channels Are Separated from Other Traffic','Administration Networks and Channels Are Separated from Other Traffic','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Separate administration networks and channels from operational and other traffic and verify that the intended separation is enforced by actual access and routing configurations. A separately named management VLAN alone is insufficient if ordinary traffic can bypass the intended boundary and reach administrative interfaces; assess any controlled access paths against the separation design.", "evidence": "Examples: administration-network/channel design and actual access/routing configurations, with safe checks showing separation of management traffic from operational and other traffic.", "risk_text": "An attacker on an operational or lower-trust network reaches management interfaces and makes unauthorised administrative changes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (i) CIR-specific requirement within CIR scope: CIR Annex 6.8.2(f); CIR Annex 6.8.2(g).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.11','Production Systems and Backups Are Separated from Development and Testing','Production Systems and Backups Are Separated from Development and Testing','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Use environment and access separation to prevent development or testing activity from compromising production systems or their backups; different environment names alone do not demonstrate an effective boundary.", "evidence": "Examples: environment and connectivity records with access/configuration checks showing that production systems and their backups are separated from development and test systems.", "risk_text": "R1: Compromise or unsafe activity in development or testing reaches production systems or recovery copies and exposes production information.<br>R2: Test activity damages production data or backups, interrupting live services or impairing recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.8.2(h).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.6','Network Access Is Restricted to Authorised Devices Where Appropriate','Network Access Is Restricted to Authorised Devices Where Appropriate','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Determine where restricting network admission to authorised devices is appropriate and enforce that restriction within the selected scope. Check that permitted devices can connect and unauthorised devices are rejected; a device list or an admission rule that is not enforced does not demonstrate restricted access.", "evidence": "Examples: the decision on where device-admission restriction is appropriate, and, for that scope, authorised-device information and safe checks showing that admission controls accept permitted devices and reject others.", "risk_text": "An unauthorised or compromised device joins the network and accesses internal resources or introduces malicious traffic.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g), (i) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(g).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.9','DNS and Internet Routing Follow Applicable Security Practices','DNS and Internet Routing Follow Applicable Security Practices','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Apply the DNS and Internet-routing security practices relevant to the entity''s network role and services, and check their operational configuration; do not assume that every entity operates its own DNS or routing infrastructure.", "evidence": "Examples: identification of applicable DNS and Internet-routing security practices, corresponding service/router configurations and operational checks showing those practices are applied to the entity''s role.", "risk_text": "R1: Manipulated name resolution or routing sends users and systems to an attacker-controlled destination, exposing credentials or exchanged data.<br>R2: Routing or DNS failures make legitimate services unreachable or divert their traffic.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(l).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C38.7','Latest-Generation Network-Layer Protocols Have a Transition Plan and Implementation Actions','Latest-Generation Network-Layer Protocols Have a Transition Plan and Implementation Actions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "An implementation plan addresses the transition to latest-generation network-layer protocols. For CIR-covered entities, the transition must be secure, appropriate and gradual, with measures to accelerate its implementation. A plan alone does not demonstrate those implementation measures; the provision sets no universal protocol version or transition deadline.", "evidence": "Examples: an implementation plan or equivalent planning records identifying the relevant latest-generation network-layer protocol transition, affected scope, dependencies and planned actions. Within CIR scope, include implemented measures to accelerate the secure, appropriate and gradual transition and records showing progress rather than only an approved plan.", "risk_text": "An unmanaged protocol transition introduces unfiltered traffic paths or incompatible connectivity, exposing systems or disrupting network-dependent services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(j).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C28.1','Protection Against Malicious and Unauthorised Software Operates','Protection Against Malicious and Unauthorised Software Operates','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Protection against malicious and unauthorised software operates. Prevent or detect unapproved software installation and execution on relevant systems, keep protective measures current, and investigate detections through the established security process.", "evidence": "Examples: operating controls against malicious and unapproved software, current protection status and representative installation/execution detections or safe tests. Include handling of actual detections through the established security process where they occurred.", "risk_text": "R1: Malicious or unauthorised software steals information, captures credentials or enables remote control.<br>R2: Malicious software corrupts or encrypts data and interrupts affected services.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.1", "A.8.7", "A.8.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(1) (measures appropriate to the risks); 21(2)(g) CIR-specific requirement within CIR scope: CIR Annex 6.9.1; CIR Annex 6.9.2; CIR Annex 3.2.1.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','NET-FILTER','Inbound and Outbound Network Traffic Is Restricted','Inbound and Outbound Network Traffic Is Restricted','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-FLT · Network boundary filtering", "topic_label": "G-FLT · Network boundary filtering", "description": "Inbound and Outbound Network Traffic Is Restricted. Permit only justified incoming and outgoing connections through enforced rules for relevant sources, destinations, services and protocols. Block unneeded communication and verify allowed and denied paths in both directions. A named firewall product alone is not evidence that restrictions work.", "evidence": "Examples: justified rules for relevant sources, destinations, services and protocols compared with enforced configurations, plus safe allowed/denied path tests in both incoming and outgoing directions.", "risk_text": "R1: Unnecessary inbound connections expose internal services to unauthorised access.<br>R2: Unrestricted outbound paths enable data exfiltration or attacker command-and-control traffic.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(e), (g), (i). CIR Annex 6.7.2(b), (c), (f) and 6.8.2(e) address unauthorised access and unnecessary communication within CIR scope. ISO comparison: A.8.20 and A.8.21. No particular next-generation firewall product is mandated.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','WIFI-SEG','Wi-Fi Networks Are Segregated According to Their Trust Level (Applies only where the entity operates or provides wireless networks, including managed networks.)','Wi-Fi Networks Are Segregated According to Their Trust Level (Applies only where the entity operates or provides wireless networks, including managed networks.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-WLAN · Wireless network protection", "topic_label": "G-WLAN · Wireless network protection", "description": "Wi-Fi Networks Are Segregated According to Their Trust Level. Isolate guest and other untrusted wireless access from internal organisational systems. Restrict corporate wireless access to the zones and resources justified by its security requirements. Verify the separation through connection tests; different network names alone do not demonstrate isolation. (Applies only where the entity operates or provides wireless networks, including managed networks.)", "evidence": "For operated or provided wireless networks, examples include guest/untrusted and corporate zone configurations and connection tests showing guest isolation and only justified corporate access to internal resources.", "risk_text": "A guest or compromised low-trust wireless device reaches corporate resources and accesses data or spreads an attack.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(g), (i). CIR Annex 6.8.1 and 6.8.2(b), (c), (e) provide the risk-based segmentation context within CIR scope; they do not prescribe universal isolation of all Wi-Fi from wired networks. ISO comparison: A.8.22. CIR-specific requirement within CIR scope: CIR Annex 6.8.1; CIR Annex 6.8.2(b); CIR Annex 6.8.2(c); CIR Annex 6.8.2(e).", "ref": "Art. 21(2)(g)", "applicability": {"condition": "only where the entity operates or provides wireless networks, including managed networks", "condition_source": "control_name", "scope_group": "APP-WIFI", "presentation": "inline"}}'::jsonb),
  ('NIS2','WIFI-AUTH','Wireless Access Uses Secure Authentication and Encryption (Applies only where the entity operates or provides wireless networks, including managed networks.)','Wireless Access Uses Secure Authentication and Encryption (Applies only where the entity operates or provides wireless networks, including managed networks.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-WLAN · Wireless network protection", "topic_label": "G-WLAN · Wireless network protection", "description": "Wireless Access Uses Secure Authentication and Encryption. Protect wireless connections with authentication and encryption appropriate to their purpose and risk. Require authorised user or device authentication for corporate wireless access, disable insecure connection modes, and verify that unauthorised access is rejected. Keep guest access outside corporate access privileges. (Applies only where the entity operates or provides wireless networks, including managed networks.)", "evidence": "For operated or provided wireless networks, examples include risk-appropriate authentication/encryption settings and safe checks of corporate user/device authorisation, rejection of unauthorised access and disabled insecure modes. Check that guest access does not receive corporate privileges, without collecting wireless passwords or keys.", "risk_text": "R1: An unauthorised user or device obtains corporate wireless access through weak authentication.<br>R2: An attacker intercepts or manipulates inadequately protected wireless traffic, obtaining sensitive information or causing systems to accept altered data.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of NIS2 Article 21(2)(g), (h), (i), (j). Wireless-specific implementation, not a separately named Directive requirement. ISO comparison: A.8.20, A.8.21, with A.8.5 and A.8.24. C38.6 assesses device admission generally; this control assesses wireless authentication and over-the-air protection.", "ref": "Art. 21(2)(g)", "applicability": {"condition": "only where the entity operates or provides wireless networks, including managed networks", "condition_source": "control_name", "scope_group": "APP-WIFI", "presentation": "inline"}}'::jsonb),
  ('NIS2','SYS-CAP','System and Network Capacity Meets Service Needs','System and Network Capacity Meets Service Needs','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-CAP · System and network capacity", "topic_label": "G-CAP · System and network capacity", "description": "System and network capacity meets service needs. Assess current and expected processing, memory, storage and network demand against available capacity. Define thresholds, identify impending shortfalls and implement timely adjustments to avoid service disruption.", "evidence": "Examples: current and forecast processing, memory, storage and network demand compared with available capacity and defined thresholds, with records of identified shortfalls and timely implemented adjustments where needed.", "risk_text": "Demand exceeds processing, storage or network capacity, degrading or stopping services and potentially dropping queued work or records.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.6"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of the appropriate and proportionate risk-management measures in NIS2 Article 21(1), read with Article 6(2) solely for its definition of network and information system security, including availability; related ISO control A.8.6 (Part 4, p.3). Capacity management is an implementation measure, not an individually named Directive requirement; Article 6(2) does not independently impose a capacity-management duty.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C38.13','Network Protections and Segmentation Are Reviewed at Planned Intervals and After Relevant Events','Network Protections and Segmentation Are Reviewed at Planned Intervals and After Relevant Events','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-REVIEW · Network protection review", "topic_label": "G-REVIEW · Network protection review", "description": "Review the deployed network safeguards and segmentation at planned intervals and after significant incidents or relevant changes to operations or risks, recording necessary corrections or a supported decision that the protections remain appropriate.", "evidence": "Examples: planned review intervals and relevant-event triggers, completed reviews of network protections and segmentation, and resulting corrections or justified no-change decisions supported by relevant technical checks.", "risk_text": "R1: Changes leave obsolete network rules or ineffective zone boundaries in place, allowing unauthorised paths to persist unnoticed.<br>R2: Network changes leave legitimate service dependencies blocked by outdated filtering or segmentation rules, interrupting operations until the rules are corrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g) CIR-specific requirement within CIR scope: CIR Annex 6.7.3; CIR Annex 6.8.3.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C39.1','An Applied Cryptography Policy Defines Appropriate Use','An Applied Cryptography Policy Defines Appropriate Use','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY · Cryptography policy", "topic_label": "H-CRY · Cryptography policy", "description": "The cryptography policy specifies when and how cryptographic protection is to be used and guides actual implementation choices; a policy that is published but not followed does not demonstrate this outcome.", "evidence": "Examples: the operative cryptography policy defining appropriate use in the assessed scope, compared with relevant implementation decisions and practice demonstrating its application.", "risk_text": "Inconsistent cryptographic choices leave sensitive information unprotected or falsely assumed to be protected across systems and exchanges.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(h) CIR-specific requirement within CIR scope: CIR Annex 9.1; CIR Annex 9.2(a); CIR Annex 9.2(b); CIR Annex 9.2(c).", "ref": "Art. 21(2)(h)"}'::jsonb),
  ('NIS2','CRYPTO-INV','Cryptographic Keys and Certificates Are Inventoried','Cryptographic Keys and Certificates Are Inventoried','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-INV · Cryptographic inventory", "topic_label": "H-INV · Cryptographic inventory", "description": "Cryptographic Keys and Certificates Are Inventoried. Maintain identifiable records of relevant keys and digital certificates, their systems, purpose, responsible owners, approved storage locations, validity or usage periods and renewal responsibility. Reconcile records with actual use. Record references to securely held keys, not secret key material in the inventory. This control establishes what must be managed; C39.3 assesses the lifecycle actions.", "evidence": "Inventory or equivalent system records; owner and service mappings; expiry or usage-period tracking; reconciliation against deployed certificates and key-management systems. Do not extract private keys or other secret key material as audit evidence.", "risk_text": "R1: Unrecorded certificates expire without an identified renewal owner, interrupting dependent services.<br>R2: Compromised or obsolete keys remain in use because their locations and dependent systems cannot be identified for replacement or revocation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of NIS2 Article 21(2)(h); CIR Annex 9.2(c) supplies key-management context within CIR scope, not an express separate inventory duty. ISO comparison: A.8.24, Part 4 p.7, Q3 and Q5.", "ref": "Art. 21(2)(h)"}'::jsonb),
  ('NIS2','C39.2','Required Cryptographic Protections Are Implemented','Required Cryptographic Protections Are Implemented','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Check that the cryptographic safeguards selected for relevant information and communications are enabled and operate as intended; listing a requirement or deploying a product without the required configuration is insufficient.", "evidence": "Examples: the required cryptographic protections compared with deployed settings and safe checks demonstrating their operation on relevant data and communications. Use non-secret metadata or test data, not keys or sensitive plaintext.", "risk_text": "R1: An unauthorised party reads sensitive stored or transmitted information where required encryption is absent or ineffective.<br>R2: Altered communications or data are accepted as genuine where required integrity and authenticity protections do not operate.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(h)", "ref": "Art. 21(2)(h)"}'::jsonb),
  ('NIS2','C39.3','Cryptographic Keys Are Managed Throughout Their Lifecycle','Cryptographic Keys Are Managed Throughout Their Lifecycle','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Cryptographic Keys Are Managed Throughout Their Lifecycle. Protect key generation, distribution, storage and access. Set and enforce appropriate usage periods, change keys when due, and revoke or replace compromised keys. Provide secure backup and recovery where needed, renew or revoke certificates as appropriate, and securely retire and destroy keys. Verify that the lifecycle actions actually occur; identifying keys and certificates is assessed separately under CRYPTO-INV. Log significant key-management actions and audit those records as appropriate to the key-management policy.", "evidence": "Examples: redacted records and configurations covering key generation, distribution, storage/access, usage periods and due changes, compromise revocation/replacement, certificate renewal/revocation, needed backup/recovery and secure retirement/destruction. Include significant key-management action logs and their audit as appropriate to the policy; do not extract private keys or other secret key material.", "risk_text": "R1: Exposed, weak or unrevoked keys allow an attacker to decrypt information or impersonate a trusted party.<br>R2: Lost or prematurely destroyed keys, expired certificates or erroneous revocation make protected data or dependent services unavailable.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.23", "A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(h); CIR Annex 9.2(c), including key-management logging and auditing under point (xi).", "ref": "Art. 21(2)(h)"}'::jsonb),
  ('NIS2','C39.4','Cryptographic Policies and Procedures Track the State of the Art','Cryptographic Policies and Procedures Track the State of the Art','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Review cryptographic policies and procedures against relevant technical developments and current guidance, updating obsolete choices or substantiating why existing arrangements remain appropriate.", "evidence": "Examples: dated cryptographic policy/procedure reviews considering relevant current technical guidance and developments, with resulting updates or substantiated decisions that existing arrangements remain appropriate.", "risk_text": "Obsolete cryptographic algorithms or practices permit protected information to be decrypted or trusted communications to be forged.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(h) CIR-specific requirement within CIR scope: CIR Annex 9.3.", "ref": "Art. 21(2)(h)"}'::jsonb),
  ('NIS2','C41.2','Required Routine Voice, Video and Text Communications Are Secured','Required Routine Voice, Video and Text Communications Are Secured','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "Where appropriate, use secured voice, video and text services for routine communications, with safeguards matched to their assessed protection needs; the control does not prescribe the same solution for every communication channel.", "evidence": "Examples: identified protection needs for routine voice, video and text services, compared with actual service settings and safe demonstrations showing that the required communications are secured.", "risk_text": "R1: Unauthorised parties overhear or read routine voice, video or text communications containing sensitive information.<br>R2: A forged or manipulated communication is trusted and causes an incorrect business or security action.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(j)", "ref": "Art. 21(2)(j)"}'::jsonb),
  ('NIS2','C41.5','System-to-System Channels Authenticate Endpoints and Protect Data','System-to-System Channels Authenticate Endpoints and Protect Data','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "System-to-system communication uses trusted channels with authenticated endpoints and protected data. Within CIR scope, verify that the trusted channels are isolated from other communication channels using logical, cryptographic or physical separation. This isolation requirement is additional to endpoint identification and protection against data modification or disclosure.", "evidence": "Examples: system-to-system endpoint-authentication and trusted-channel settings, with safe connection/message checks demonstrating peer authentication and required data protection, including rejection of untrusted peers where relevant. Within CIR scope, include configurations or safe checks demonstrating logical, cryptographic or physical separation of the trusted channels from other communication channels.", "risk_text": "R1: A system connects to an impersonated endpoint and discloses data or credentials.<br>R2: Messages between systems are altered or replayed, causing unauthorised transactions or incorrect processing.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (h) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(i).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C41.3','Secure Emergency Communications Remain Usable When Needed','Secure Emergency Communications Remain Usable When Needed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "Where appropriate, provide secure emergency communications that remain usable during the relevant disruption scenarios, including loss of normal channels; having contact details alone does not establish an available communication route.", "evidence": "Examples: secured emergency communication arrangements and controlled exercises or actual-use records demonstrating availability when needed, including relevant disruption of normal channels.", "risk_text": "R1: Failure of emergency communication channels delays coordination and protective decisions during an incident.<br>R2: Responders fall back to untrusted channels and expose sensitive incident information or act on impersonated instructions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(j)", "ref": "Art. 21(2)(j)"}'::jsonb),
  ('NIS2','C38.8','Modern Interoperable Email Security Standards Have Deployment Plans and Actions','Modern Interoperable Email Security Standards Have Deployment Plans and Actions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "G-EMAIL · E-mail security standards", "topic_label": "G-EMAIL · E-mail security standards", "description": "Plan the deployment of applicable, interoperable modern email-security standards and carry out traceable implementation actions; a future plan without progress does not demonstrate deployment.", "evidence": "Examples: an e-mail security deployment plan identifying applicable modern interoperable standards, with traceable implementation actions and relevant configuration or interoperability checks.", "risk_text": "R1: Inconsistent email-security deployment allows forged messages to be trusted or sensitive mail to travel without its intended protection.<br>R2: An incompatible email-security rollout rejects or delays legitimate messages.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (g) CIR-specific requirement within CIR scope: CIR Annex 6.7.2(k).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-01','Required Security Features Are Defined Before Acquisition or Development','Required Security Features Are Defined Before Acquisition or Development','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Required Security Features Are Defined Before Buying or Developing a System. State what the system must protect and which security functions it must provide, based on its intended use, data, interfaces and risks. Put these requirements into the purchasing or development specifications and applicable supplier requirements. For example, specify who may access patient records and which access events must be logged.", "evidence": "Examples: dated purchasing/development specifications or equivalent requirement records defining protection needs and security functions from intended use, data, interfaces and risks, with applicable requirements communicated to suppliers before acquisition or development.", "risk_text": "An acquired system cannot provide the protections required for its intended data and service context, exposing information or forcing costly changes before safe use.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.8", "A.8.26"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.1; CIR Annex 6.1.2(a); CIR Annex 6.2.2(a).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-02','Proposed System Designs Are Checked Against Security Requirements','Proposed System Designs Are Checked Against Security Requirements','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "The Proposed System Design Is Checked Against the Security Requirements. Before accepting the proposed design, check whether its architecture, integrations and planned configuration can meet the requirements defined under D04-01. For example, check that the proposed access model restricts patient records to authorised users and that the design provides the required logging. Resolve material gaps or document justified treatment decisions. For a ready-made product, assess the available solution and deployment design; this does not require unrestricted access to the supplier''s internal design.", "evidence": "Examples: a design-stage comparison against D04-01 requirements covering architecture, integrations and planned configuration, with decisions resolving material gaps or justifying treatment before design acceptance. For ready-made products, available solution and deployment-design information may suffice.", "risk_text": "A design with unsafe trust boundaries or incompatible integrations is accepted, embedding an access or resilience weakness that is expensive to correct after delivery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.26", "A.8.27"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(a); CIR Annex 6.1.2(e).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-10','Component Information Identifies Products and Dependencies in Security-Relevant Acquisitions','Component Information Identifies Products and Dependencies in Security-Relevant Acquisitions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "For security-relevant acquisitions, the entity obtains and maintains sufficient information about the hardware and software components to identify affected products and dependencies when security issues arise.", "evidence": "For security-relevant acquisitions, examples include maintained component/version and dependency information sufficient to identify affected products when security issues arise, compared with representative deployed acquisitions.", "risk_text": "A vulnerable component or dependency cannot be matched to the acquired product, delaying identification and treatment of affected systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.1; CIR Annex 6.1.2(c).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-11','Security-Relevant Acquisitions Include Usable Security and Configuration Information','Security-Relevant Acquisitions Include Usable Security and Configuration Information','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "For security-relevant acquisitions, the entity obtains usable information about security functions and the configuration required to operate the product or service securely.", "evidence": "For security-relevant acquisitions, examples include usable supplier documentation or equivalent information describing security functions and the configuration needed for secure operation, matched to the acquired product/service.", "risk_text": "Operators deploy or run a product with insecure settings because its security functions and configuration needs are not understood.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.37"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.1; CIR Annex 6.1.2(d).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-12','Security-Update Support Commitments and End Dates Are Tracked','Security-Update Support Commitments and End Dates Are Tracked','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Security-update support commitments and support end dates are known and tracked for relevant products and services, so that gaps in supported operation are identified in time.", "evidence": "Examples: relevant supplier security-update commitments and support end dates in agreements, service records or equivalent tracking information, with checks identifying approaching or existing support gaps.", "risk_text": "Security support ends unnoticed, leaving deployed products exposed to vulnerabilities for which updates are no longer available.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.1; CIR Annex 6.1.2(b).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-03','Security Acceptance Confirms Delivered Systems Meet Requirements','Security Acceptance Confirms Delivered Systems Meet Requirements','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Security Acceptance Confirms That the Delivered System Meets the Requirements. Before the system or release goes live, review test results and other suitable evidence showing that the required protections actually work. For example, verify that an unauthorised test account cannot open a patient record and that the required log is produced. Record the acceptance decision, treatment of material findings and any unresolved conditions. This is the decision to accept the delivered system, not the earlier review of its proposed design.", "evidence": "Examples: the pre-go-live acceptance decision linked to the delivered system/release, defined requirements and tests or other evidence that the required protections work, including material-finding treatment and unresolved conditions.", "risk_text": "A delivered system goes live with ineffective required safeguards because acceptance relies on promises rather than working evidence, exposing live data or services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.8", "A.8.26", "A.8.29"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.2(e); CIR Annex 6.1.2(f); CIR Annex 6.2.2(d).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-13','Products Near or Beyond Support End Have Implemented Lifecycle Decisions','Products Near or Beyond Support End Have Implemented Lifecycle Decisions','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Products approaching or reaching the end of security support have an implemented lifecycle decision, with a responsible owner, a replacement or migration schedule and justified interim safeguards where needed.", "evidence": "Examples: identified products approaching or beyond security-support end, with implemented lifecycle decisions, responsible owners, replacement/migration schedules and evidence of justified interim safeguards where needed.", "risk_text": "R1: Unsupported systems remain in use without effective interim protection or a feasible migration path, extending exposure to exploitable vulnerabilities.<br>R2: A rushed replacement of unsupported technology disrupts dependent services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.1.1; CIR Annex 6.1.2(b); CIR Annex 2.1.2(i).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-04','Relevant Secure-Development Rules Are Established Before Development and Applied (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Relevant Secure-Development Rules Are Established Before Development and Applied (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Secure-development rules are established before development starts, cover the relevant lifecycle stages and responsible roles, and are used in both internal and outsourced development projects.", "evidence": "Where development is in scope, examples include secure-development rules established before work starts, covering relevant lifecycle stages and roles, with project records showing application to internal and outsourced development as applicable.", "risk_text": "Development teams omit security activities or apply inconsistent practices, allowing recurring design or implementation weaknesses into releases.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.25"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.1; CIR Annex 1.2.1.", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-23','Outsourced Development Follows Acquisition and Supply-Chain Security Processes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Outsourced Development Follows Acquisition and Supply-Chain Security Processes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Outsourced development is included in the entity''s acquisition and supply-chain security processes, with applicable requirements and responsibilities communicated to and agreed with the development provider.", "evidence": "Where development is outsourced, examples include agreed security requirements and responsibilities in contracts or equivalent arrangements, with evidence of their communication and inclusion in acquisition and supply-chain processes.", "risk_text": "An external developer omits required safeguards or leaves responsibilities unresolved, delivering software with unaddressed weaknesses or exposing entrusted information.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.3; CIR Annex 5.1.1; CIR Annex 5.1.4(a).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-14','System Architecture Prevents Unauthorised Access and Limits Attacks (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','System Architecture Prevents Unauthorised Access and Limits Attacks (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "System Architecture Is Designed to Prevent Unauthorised Access and Limit Attacks. Apply secure-engineering principles when deciding how components connect, where sensitive data are held and how access crosses system boundaries. For example, a patient-record database is reachable only through authorised application paths, not directly from the Internet. Record design decisions and assess and address material departures from the principles. This control assesses the security of the architecture, not the way individual code functions are written.", "evidence": "Where development is in scope, examples include architecture decisions showing secure component connections, sensitive-data placement and controlled trust-boundary access, with assessment and treatment of material departures from secure-engineering principles.", "risk_text": "An unsafe system architecture exposes sensitive components or permits an attacker to cross trust boundaries and compromise additional functions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.27"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(b).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-16','Development Repository Changes Are Authorised, Traceable and Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Development Repository Changes Are Authorised, Traceable and Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Access and change permissions to development repositories restrict code modification to authorised persons and processes, with traceable changes and appropriate protection of release-relevant branches.", "evidence": "Where development is in scope, examples include repository permissions, change histories and protection of release-relevant branches, with checks that only authorised persons/processes can modify code.", "risk_text": "Unauthorised changes to source code or release branches enter a trusted release, introducing malicious behaviour or disabling safeguards.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.4", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(c); CIR Annex 11.2.1; CIR Annex 11.2.2(a); CIR Annex 11.2.2(c); CIR Annex 6.4.2.", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-18','Development, Build and Deployment Secrets Are Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Development, Build and Deployment Secrets Are Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Credentials, tokens and signing secrets used for development, build or deployment are stored and exposed only to authorised users and processes, with appropriate handling when they are no longer valid or are suspected to be compromised.", "evidence": "Where development is in scope, examples include redacted secret-storage, access and exposure settings for development/build/deployment, plus metadata showing appropriate handling of invalid or suspected-compromised secrets. Use synthetic demonstrations where useful; never collect live credentials, tokens or signing secrets.", "risk_text": "Exposed development, deployment or signing secrets let an attacker impersonate trusted automation, access systems or distribute apparently authentic malicious releases.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.4", "A.8.28"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 11.6.2(b); CIR Annex 11.6.2(c); CIR Annex 9.2(c)(iv); CIR Annex 9.2(c)(vi); CIR Annex 9.2(c)(vii).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-15','Software Is Written Using Secure Coding Practices (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Software Is Written Using Secure Coding Practices (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Software Is Written Using Secure Coding Practices. Apply coding rules that prevent relevant vulnerabilities, such as checking access rights for each requested patient record and using parameterised database queries to prevent SQL injection. Use code review or analysis to identify violations and correct material weaknesses before release, with any unresolved findings subject to a justified treatment and release decision. This control assesses how software functions are implemented, not the overall system architecture.", "evidence": "Where development is in scope, examples include applicable coding rules, representative code-review or analysis results and corrected material weaknesses before release, with justified treatment/release decisions for unresolved findings.", "risk_text": "R1: An attacker exploits coding flaws to read or modify data without authorisation.<br>R2: Software defects cause incorrect processing or service failure even without an attack.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.28"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(b); CIR Annex 6.2.2(d); CIR Annex 6.5.2(d).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-17','Build and Deployment Processes Prevent Unauthorised Changes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Build and Deployment Processes Prevent Unauthorised Changes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Build and deployment processes prevent unauthorised changes to pipeline configuration, build inputs and release actions, with permissions and execution records appropriate to the development risks.", "evidence": "Where development is in scope, examples include pipeline and build-input permissions, change protections and execution records showing that configuration changes and release actions are authorised, proportionate to development risks.", "risk_text": "An attacker alters build inputs, pipeline configuration or deployment actions to distribute a compromised release or change production without authorisation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.25"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(c); CIR Annex 6.3.1; CIR Annex 6.4.1; CIR Annex 11.2.2(a); CIR Annex 11.2.2(c); CIR Annex 3.2.3(e).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-20','Test Data Selection Reflects Purpose, Sensitivity and Necessity (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Test Data Selection Reflects Purpose, Sensitivity and Necessity (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test datasets are selected for the testing purpose and assessed for sensitivity and necessity before use, avoiding unnecessary use of live sensitive information.", "evidence": "Where development is in scope, examples include test-dataset selection decisions made before use, linking purpose to sensitivity and necessity and showing why any live sensitive information is needed. Inspect descriptions or protected samples rather than exporting live datasets.", "risk_text": "R1: Unnecessary live sensitive data are copied into testing, exposing more people and records if the test environment is accessed or shared improperly.<br>R2: Unrepresentative test data omit relevant formats, relationships or boundary conditions, allowing defects that affect real operations to pass testing.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(e); CIR Annex 6.2.2(f).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-22','Risk-Justified Test Data Sanitisation and Anonymisation Are Verified Before Use (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Risk-Justified Test Data Sanitisation and Anonymisation Are Verified Before Use (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test data undergo the sanitisation and anonymisation justified by the risk assessment, and the resulting data are checked to confirm the claimed protection before use.", "evidence": "Where development is in scope, examples include the risk-based sanitisation/anonymisation choice and pre-use validation results demonstrating the claimed protection of the resulting test data. Use controlled samples and do not infer anonymity from pseudonymisation alone.", "risk_text": "Data claimed to be sanitised or anonymised still contain identifiable or recoverable sensitive values, leading to disclosure when treated as safe test data.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.11", "A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(f); CIR Annex 7.1.", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-21','Test Data Are Protected Throughout Their Lifecycle (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Test Data Are Protected Throughout Their Lifecycle (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test data are protected throughout storage, access, transfer and disposal, with access limited to the relevant test participants and retention appropriate to the testing need.", "evidence": "Where development is in scope, examples include test-data access, storage, transfer and disposal safeguards compared with actual participant permissions and the testing need, with representative records or checks of retention and disposal.", "risk_text": "Unauthorised test participants or later recipients obtain sensitive test data during storage, transfer or after the testing need ends.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(e); CIR Annex 12.2.2(a); CIR Annex 12.2.2(b); CIR Annex 11.2.2(a).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-19','Risk-Appropriate Security Tests Are Performed During Development and Before Release Acceptance (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Risk-Appropriate Security Tests Are Performed During Development and Before Release Acceptance (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Relevant security tests are performed during development and before release acceptance using a scope and method appropriate to the system''s risks, and their results identify the tested version and findings.", "evidence": "Where development is in scope, examples include risk-appropriate security test scope/methods and retained results from development and before release acceptance, identifying the tested version and findings.", "risk_text": "Security defects remain undetected until after release because tests do not cover relevant attack paths or the findings refer to a different version.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.29", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.2.2(d); CIR Annex 6.5.2(a); CIR Annex 6.5.2(b); CIR Annex 6.5.2(c); CIR Annex 6.1.2(f).", "ref": "Art. 21(2)(e)", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('NIS2','D04-06','Planned Changes Undergo Security and Service Impact Assessment Before Implementation','Planned Changes Undergo Security and Service Impact Assessment Before Implementation','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Before a planned change is implemented, its potential security and service impacts are assessed using the relevant dependencies and risks, and the required safeguards are identified.", "evidence": "Examples: assessments completed before planned changes, identifying affected dependencies, potential security/service impacts, relevant risks and required safeguards, linked to the proposed change.", "risk_text": "A change unexpectedly weakens a security boundary or breaks a dependent service because its effects were not assessed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.4.2.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','CHG-ROLLBACK','Failed Changes Have a Defined Rollback or Recovery Method','Failed Changes Have a Defined Rollback or Recovery Method','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Failed Changes Have a Defined Rollback or Recovery Method. Before implementing a change, determine how safe operation will be restored if it fails. Identify the required previous configurations, backups or other recovery resources, responsible people and conditions for starting recovery. Confirm that the necessary resources are usable and that the method is appropriate to the change''s risk. Where reversal is impossible, define an alternative recovery method rather than assuming that every change can be undone.", "evidence": "Change-specific rollback or alternative recovery instructions; responsibility and activation criteria; usable configuration copies or backups; relevant validation or test results proportionate to the risk.", "risk_text": "A failed change cannot be reversed or otherwise recovered safely, extending service interruption or leaving damaged data and configuration in use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of NIS2 Article 21(2)(e), with continuity context under Article 21(2)(c). CIR Annex 6.4 supplies change-management context, not a universal express requirement to reverse every change. ISO comparison: A.8.32, Part 4 p.9, Q3.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-07','Planned Operational Changes Undergo Risk-Appropriate Testing Before Implementation','Planned Operational Changes Undergo Risk-Appropriate Testing Before Implementation','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Planned operational changes are tested before implementation to an extent justified by their risks, and the recorded results support the decision to proceed or revise the change.", "evidence": "Examples: pre-implementation test scope justified by the planned change''s risks, recorded results and the resulting decision to proceed or revise the change.", "risk_text": "A defective or incompatible operational change reaches production and disrupts services or disables a required safeguard.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.4.2.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','CHG-AUTH','Changes Are Authorised Before Implementation','Changes Are Authorised Before Implementation','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Changes Are Authorised Before Implementation. Obtain approval from an authorised person before implementing a planned operational change. The approval identifies the change, its permitted scope and the decision-maker, taking account of the impact assessment and relevant test results. Where an emergency prevents the normal route, use the defined emergency authorisation process and record any exceptional departure and subsequent review.", "evidence": "Change request; named approval authority; approval time preceding planned implementation; approved scope matched to execution records; emergency authorisation or exception and review records where applicable.", "risk_text": "An unauthorised change bypasses accountable risk decisions and introduces an unsafe or disruptive production state.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.19", "A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of NIS2 Article 21(2)(e). CIR Annex 6.4.1–6.4.3 provides change-management context, not a separately worded approval requirement. ISO comparison: A.8.32, Part 4 p.9, Q4.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-05','Security-Relevant Changes and Their Outcomes Are Recorded','Security-Relevant Changes and Their Outcomes Are Recorded','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Security-relevant software, hardware and configuration changes are recorded with their scope, responsible person, timing and implementation outcome so that the changed state can be reconstructed.", "evidence": "Examples: software, hardware and configuration change histories identifying scope, responsible person, timing and implementation outcome, sufficient to reconstruct the changed state.", "risk_text": "Investigators or operators cannot reconstruct a changed system state, delaying fault diagnosis, incident scoping or recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.19", "A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.4.1; CIR Annex 6.4.2.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-24','Emergency Change Records Explain Actions, Outcomes and Procedural Departures','Emergency Change Records Explain Actions, Outcomes and Procedural Departures','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "When an emergency prevents the normal change procedure from being followed, the change record documents what was done, its result and why the normal steps could not be followed.", "evidence": "Where an emergency prevents normal change steps, examples include the change record showing what was done, its result and why the normal steps could not be followed.", "risk_text": "An emergency change leaves an undocumented unsafe state that later operators cannot assess or reverse reliably.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.4.3.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-08','Vulnerability Reports and Advisories Are Tracked and Disclosure Coordinated Where Needed','Vulnerability Reports and Advisories Are Tracked and Disclosure Coordinated Where Needed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability Reports and Advisories Are Tracked and Disclosure Is Coordinated Where Needed. Provide a usable contact for reports about vulnerabilities in the organisation''s systems or products. Actively follow relevant supplier, authority and Computer Security Incident Response Team (CSIRT) information channels, and review whether those sources remain relevant. Record received reports and actionable threat or vulnerability advisories, and route them to a responsible assessment or response handler. Where coordinated disclosure is relevant, coordinate handling and the timing and content of disclosure with affected suppliers, reporters and other appropriate parties through a defined procedure consistent with applicable coordinated-disclosure policies. Receiving reports alone does not satisfy active advisory monitoring; not every vulnerability requires public disclosure.", "evidence": "Working reporting contact; received reports and handler assignments; relevant advisory sources and their periodic relevance checks; evidence of active monitoring and actionable advisories routed to assessment or response; correspondence and decisions on coordinated handling and disclosure where relevant. A lack of public disclosure alone is not a failure where disclosure is not relevant.", "risk_text": "R1: Actionable reports or advisories fail to reach assessment, allowing a known vulnerability to be exploited before treatment.<br>R2: Poorly coordinated disclosure exposes affected users before protective action is ready or delays information they need to protect themselves.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.7", "A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(e). The Directive-level vulnerability handling and disclosure requirement is implemented here through report intake, active advisory monitoring and coordination where relevant; the R label does not make every implementation detail an individually named Directive duty. CIR-specific requirement within CIR scope: CIR Annex 6.10.1; CIR Annex 6.10.2(a); CIR Annex 6.10.2(e); CIR Annex 6.10.4.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-25','Vulnerability Scans and Reviews Are Risk-Appropriate and Operationally Safe','Vulnerability Scans and Reviews Are Risk-Appropriate and Operationally Safe','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability identification uses risk-appropriate scans or reviews over the required system scope, with planned intervals where applicable and retained results; methods are safe for operational, OT and clinical systems.", "evidence": "Examples: risk-appropriate vulnerability scan/review scope, planned intervals where applicable and retained results demonstrating required system coverage, with methods and precautions suitable for operational, OT or clinical systems where present.", "risk_text": "R1: Undetected vulnerabilities remain exploitable on systems omitted from or inadequately covered by scanning and review.<br>R2: An unsafe vulnerability-identification activity disrupts a sensitive operational, clinical or OT system.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.10.1; CIR Annex 6.10.2(b).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-26','Vulnerabilities Are Matched to Actual Products, Configurations and Exposure','Vulnerabilities Are Matched to Actual Products, Configurations and Exposure','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Identified or reported vulnerabilities are matched to the entity''s actual products, versions, configurations and exposure so that affected and unaffected systems are distinguished with reasons.", "evidence": "Examples: vulnerability assessments linked to actual products, versions, configurations and exposure, with affected/unaffected decisions and supporting reasons for representative systems.", "risk_text": "R1: An affected system is incorrectly considered unaffected, leaving an exploitable vulnerability untreated.<br>R2: An unaffected system receives unnecessary disruptive remediation because product, version or exposure information is misinterpreted.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.10.1.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-27','Vulnerability Treatment Priorities Reflect Operational Impact, Exposure and Existing Protections','Vulnerability Treatment Priorities Reflect Operational Impact, Exposure and Existing Protections','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability treatment priorities reflect the entity''s operational impact, exposure and existing protections, and identify vulnerabilities critical to operations for action without undue delay where CIR applies.", "evidence": "Examples: treatment priorities linked to operational impact, exposure and existing protections, identifying operationally critical vulnerabilities and their routing for action without undue delay where CIR applies.", "risk_text": "Resources are directed to less consequential vulnerabilities while exposed, operationally important weaknesses remain available to attackers.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.10.1; CIR Annex 6.10.2(c); CIR Annex 6.10.3.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-28','Vulnerabilities Are Remediated Within Appropriate Timeframes','Vulnerabilities Are Remediated Within Appropriate Timeframes','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerabilities Are Remediated Within Appropriate Timeframes. Assign a responsible person and a risk-based target date for each required remediation. Apply patches or other treatments through the defined change process, and record the affected systems and implementation outcome. Implement treatment according to the justified priority and timing, including impact-justified mitigation plans and applicable CIR requirements for prompt critical treatment and timely patching. An internal target date does not override an applicable legal timing requirement.", "evidence": "Examples: required remediation actions with responsible persons and justified risk-based target dates, linked to change records, affected systems and actual implementation outcomes. Compare priority and elapsed time with applicable prompt-treatment/patching requirements, including impact-justified mitigation plans where relevant and handling of delays.", "risk_text": "Attackers exploit a known vulnerability while required remediation is delayed, abandoned or only recorded as complete without being implemented.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.10.2(c); CIR Annex 6.10.2(d); CIR Annex 6.10.3; CIR Annex 6.6.1(a); CIR Annex 2.1.2(i).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-31','Compensating Controls Protect Systems with Unpatched Vulnerabilities','Compensating Controls Protect Systems with Unpatched Vulnerabilities','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Compensating Controls Protect Systems with Unpatched Vulnerabilities. When a patch is unavailable or not applied, implement and maintain alternative safeguards appropriate to the vulnerability, such as restricting access, isolating the affected system or disabling the vulnerable function. Base residual-risk decisions on the safeguards actually operating, not merely on planned actions; these controls do not waive applicable remediation obligations.", "evidence": "For unpatched vulnerabilities, examples include implemented alternative safeguards mapped to the affected attack paths, with current configuration/operational checks and residual-risk decisions based on those operating protections.", "risk_text": "An attacker reaches and exploits an unpatched vulnerable function because assumed compensating safeguards do not actually restrict the attack path.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.6.1(d); CIR Annex 6.10.3.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-30','Decisions Not to Remediate Vulnerabilities Are Justified and Assigned to Accountable Owners','Decisions Not to Remediate Vulnerabilities Are Justified and Assigned to Accountable Owners','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Decisions not to remediate or patch a vulnerability are substantively justified, assigned to an accountable owner and supported by authorised residual-risk acceptance where required; acceptance does not override a binding duty.", "evidence": "Examples: substantive decisions not to patch or otherwise remediate, identifying affected vulnerabilities, reasons and accountable owners, with authorised residual-risk acceptance where required and consideration of applicable binding duties.", "risk_text": "A vulnerability is left exposed on the basis of an uninformed or unauthorised exception, and treatment is deferred beyond what accountable owners intended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.6.2; CIR Annex 6.6.1(d); CIR Annex 6.10.3; CIR Annex 2.1.1.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-32','Vulnerability Exceptions Are Reassessed When Due or Conditions Change','Vulnerability Exceptions Are Reassessed When Due or Conditions Change','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability exceptions have a justified expiry or review date and are reassessed when due or when relevant conditions change, including patch availability, exposure or the effectiveness of interim safeguards.", "evidence": "Examples: vulnerability exceptions with justified expiry or review dates and completed reassessments when due or when relevant conditions change, covering patch availability, exposure and interim-safeguard effectiveness.", "risk_text": "An exception outlives its justification after exposure, patch availability or safeguards change, leaving an increasingly exploitable system untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 2.1.4; CIR Annex 6.10.1; CIR Annex 6.6.1(d).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-35','Security Patches Come from Verified or Trusted Sources','Security Patches Come from Verified or Trusted Sources','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patches are obtained through verified supplier or otherwise trusted distribution channels, with the package''s origin traceable before installation.", "evidence": "Examples: verified supplier or other trusted distribution-channel information and patch retrieval/provenance records showing the package''s origin was traceable before installation.", "risk_text": "A counterfeit update obtained from an untrusted source installs malicious code with the privileges of the update process.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.6.1(c).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-36','Security Patch Integrity Is Verified Before Installation','Security Patch Integrity Is Verified Before Installation','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patch integrity is verified before installation using a trusted verification mechanism, and failed or unverifiable packages are not accepted as validated updates.", "evidence": "Examples: trusted signature, hash or equivalent integrity-verification results before installation, together with records or safe tests showing failed/unverifiable packages are not accepted as validated updates.", "risk_text": "A modified or corrupted update package is installed as legitimate, introducing malicious changes or breaking the target system.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.6.1(c).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','D04-34','Security Patches Are Tested Before Production Deployment','Security Patches Are Tested Before Production Deployment','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patches are tested before production application using a method appropriate to the affected system, and the recorded results support the deployment decision.", "evidence": "Examples: pre-production patch-test methods appropriate to the affected systems, retained results and their linkage to the deployment decision.", "risk_text": "An incompatible or faulty security patch interrupts production or breaks a required security function.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e) CIR-specific requirement within CIR scope: CIR Annex 6.6.1(b); CIR Annex 6.6.1.", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','MON-RISK','Monitoring Needs Are Determined Through Risk Assessment','Monitoring Needs Are Determined Through Risk Assessment','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Monitoring Needs Are Determined Through Risk Assessment. Assess the systems, services, relevant threats, exposure and potential service impact to determine what security monitoring is needed. Record which systems and events require monitoring, the necessary detection coverage, monitoring frequency and degree of automation, and the capabilities needed from tools or services. Existing risk-assessment records may be used if they explicitly support these monitoring decisions; a separate risk report is not required. This control assesses the justified monitoring requirements, not their implementation.", "evidence": "Risk assessment identifying relevant threats and service impact; a traceable mapping to monitored systems/events, detection needs, monitoring frequency and automation/tool capability decisions. Existing risk records are acceptable if this link is explicit.", "risk_text": "Monitoring requirements overlook a relevant system or attack path, allowing compromise to persist in an unobserved area.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(1), 21(2)(a), (b). CIR Annex 2.1 and 3.2.1–3.2.3 provide risk-assessment and monitoring/logging context within CIR scope; no separately titled monitoring-risk report is prescribed.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','MON-BASE','Normal System Behaviour and Alert Thresholds Are Defined','Normal System Behaviour and Alert Thresholds Are Defined','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Normal System Behaviour and Alert Thresholds Are Defined. Establish relevant normal operating patterns and justified alert criteria for monitored systems, based on their purpose and assessed risks. Configure suitable thresholds or other detection conditions, allowing for legitimate variations and changes. Record why a deviation warrants investigation; a statistical baseline or numerical threshold is not necessary for every detection rule. This control assesses the reference patterns and alarm criteria, not the risk assessment or testing of detection effectiveness.", "evidence": "Documented normal operating patterns and justified alarm conditions; configured thresholds or rules, legitimate exceptions and relevant change records.", "risk_text": "R1: Detection criteria treat malicious deviations as normal, delaying investigation.<br>R2: Excessive or misleading alerts consume analyst attention and obscure significant events.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(1), 21(2)(b); CIR Annex 3.2.4 requires appropriate alarm thresholds where appropriate within CIR scope. A formal behavioural baseline is an implementation method, not a universally prescribed separate legal document. ISO comparison: supplied checklist A.8.16, question 2.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','D02-01','Monitoring Is Implemented According to the Risk Assessment','Monitoring Is Implemented According to the Risk Assessment','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Monitoring Is Implemented According to the Risk Assessment. Configure and operate monitoring to meet the requirements established under MON-RISK, covering the selected systems, events, detection needs and frequency. Demonstrate that the chosen tools or services produce usable information for detecting and investigating suspected incidents. Record and address gaps between assessed needs and actual coverage. No particular SIEM or other named product is universally required; applicable CIR duties, including automation to the extent feasible, still apply. This control assesses actual operation, not the existence of a risk assessment alone.", "evidence": "Operational configurations, coverage records and monitoring outputs demonstrating that the assessed requirements are implemented; recorded coverage gaps and actions. A purchased licence or approved plan alone does not demonstrate operation.", "risk_text": "An attack remains undetected because the required monitoring coverage is not operating or does not produce usable information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(1), 21(2)(b); CIR Annex 3.2.1–3.2.3 within its scope.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C44.6','System Clocks Are Synchronised to Approved Time Sources','System Clocks Are Synchronised to Approved Time Sources','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "System Clocks Are Synchronised to Approved Time Sources. Use suitable approved time sources for relevant systems, check for clock drift and correct deviations that could impair event correlation. Restrict changes to time settings and monitor relevant time-source configuration changes. Demonstrate consistent event timestamps across systems; no particular time protocol or in-house server is universally required.", "evidence": "Approved time sources, synchronisation settings, clock-drift checks, protected configuration and change records, and correlated timestamps from relevant systems.", "risk_text": "R1: Inconsistent or manipulated timestamps produce an incorrect incident sequence, weakening correlation, attribution and the reliability of evidence.<br>R2: Clock drift causes time-dependent authentication or certificate checks to reject valid access, interrupting services that depend on those checks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.17"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.6.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','LOG-RET-DEF','Security Log Retention Periods Are Defined and Justified','Security Log Retention Periods Are Defined and Justified','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Security Log Retention Periods Are Defined and Justified. Determine and document how long each relevant category of security logs must be retained, based on investigation needs, assessed risks and applicable requirements. Identify any different periods for readily searchable and archived records, where used, and the responsible owner. Explain the chosen periods rather than adopting an arbitrary universal duration. This control assesses the retention decision, not storage configuration or actual retained records.", "evidence": "Documented retention periods by relevant log category; rationale linked to investigation needs, risks and applicable requirements; responsible owner and any searchable/archive distinctions.", "risk_text": "R1: A retention decision is too short for investigation needs, causing relevant evidence to disappear before an incident is discovered.<br>R2: Excessive retention exposes unnecessary personal or sensitive records and creates unjustified data-processing exposure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(1), 21(2)(b); CIR Annex 3.2.5 expressly refers to a predefined retention period within CIR scope, without prescribing a universal number of days or months.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','C44.1','Required Security Log Sources Deliver Usable Records','Required Security Log Sources Deliver Usable Records','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Required security-log sources actually deliver usable records. Verify coverage and record quality for the required sources; privileged-activity coverage and its review are assessed separately under LOG-PRIV.", "evidence": "Required source list, actual incoming log samples, completeness and usability checks, and collection-gap follow-up.", "risk_text": "Missing or unusable event records conceal relevant activity and prevent reconstruction of an incident on the affected source systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.1; CIR Annex 3.2.3.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.2','Security Logs Are Protected Against Unauthorised Access and Alteration','Security Logs Are Protected Against Unauthorised Access and Alteration','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Restrict who can read or change security logs and protect them against unauthorised alteration during storage and transfer, so investigators can rely on the retained records.", "evidence": "Log access permissions, protected storage and transfer settings, alteration safeguards and access or integrity checks.", "risk_text": "R1: An attacker alters or deletes logs to conceal activity and mislead investigators.<br>R2: Unauthorised access to logs exposes personal data, internal infrastructure details or other sensitive operational information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.5.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.3','Security Logs Are Retained for the Defined Periods','Security Logs Are Retained for the Defined Periods','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Security Logs Are Retained for the Defined Periods. Configure log storage, rotation, archiving, backup and deletion to implement the periods established under LOG-RET-DEF. Back up logs and verify that backup records can be retrieved; redundant logging alone does not demonstrate a recoverable backup. Check actual retained records and retrieval, and address premature loss or retention inconsistent with the defined periods and applicable requirements. A documented period alone does not demonstrate implementation.", "evidence": "Effective storage, rotation, archive, backup and deletion settings; dated records demonstrating the defined periods; retrieval checks including backed-up logs and records of retention failures or corrections.", "risk_text": "R1: Rotation, deletion or storage failures remove required logs before the approved retention period ends, preventing investigation or recovery of evidence.<br>R2: Logs remain accessible beyond their justified retention period, unnecessarily exposing personal or sensitive information.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b); CIR Annex 3.2.5 within its scope.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.4','Logs Can Be Retrieved and Correlated for Investigations','Logs Can Be Retrieved and Correlated for Investigations','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Retrieve records from the relevant systems and periods and combine them into a usable event timeline; storing logs is not enough if they cannot be located, interpreted or correlated during an investigation.", "evidence": "Retrieval and correlation checks using records from relevant systems and periods; case timelines demonstrating usable correlation.", "risk_text": "Investigators cannot retrieve or connect relevant records across systems, delaying incident scoping and leaving affected assets or actions unidentified.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.4.2(c); CIR Annex 3.4.2(d); CIR Annex 3.2.5; CIR Annex 3.2.6.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','LOG-PRIV','Privileged Activities Are Logged and Reviewed','Privileged Activities Are Logged and Reviewed','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Privileged Activities Are Logged and Reviewed. Record privileged access and relevant administrative actions with enough information to identify the account, time, affected system and action. Review these records for misuse or suspicious activity and document investigation and follow-up. Cover administrative activity beyond the use of privileged utility programs; automated review may support the process but alerts must receive an appropriate response.", "evidence": "Administrative access and action logs showing account, time, target and action; review records, investigated exceptions and documented follow-up. Check privileged coverage separately from generic log collection.", "risk_text": "Misuse of administrative privileges remains unnoticed and cannot be reliably attributed, allowing unauthorised changes or data access to continue.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15", "A.8.18"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(b), (i); CIR Annex 3.2.3(e) and 3.2.4 within CIR scope. ISO comparison: supplied checklist A.8.15, question 4.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.5','Logs Are Reviewed Regularly and Alarms Receive Timely, Qualified Responses','Logs Are Reviewed Regularly and Alarms Receive Timely, Qualified Responses','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Logs are regularly reviewed for unusual trends and alarms receive a timely, qualified response. Assess the general review and response process here; assess privileged-activity review under LOG-PRIV and avoid duplicating the same finding.", "evidence": "Review schedules, analysed trends, alert tickets, qualified response assignments and response timestamps; avoid duplicating LOG-PRIV review findings.", "risk_text": "Significant alerts or unusual patterns are not investigated promptly, allowing unauthorised activity or service damage to continue.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.15", "A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.4.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.7','Monitoring and Logging Systems Are Redundant','Monitoring and Logging Systems Are Redundant','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Provide redundant monitoring and logging components or arrangements so that failure of a relevant component does not remove the required monitoring and recording capability; a single untested backup copy does not demonstrate operational redundancy.", "evidence": "Redundant monitoring and logging architecture, configuration and failover test results covering relevant failure scenarios.", "risk_text": "A monitoring or logging component failure creates a visibility gap and loses event records while the monitored services remain in use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.6.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C44.8','Monitoring and Logging Availability Is Monitored Independently','Monitoring and Logging Availability Is Monitored Independently','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Check the availability of monitoring and logging services independently of the systems whose activities they monitor. Examine dependencies and test outage detection; normal log arrival alone does not establish that failure of the monitoring or logging service will be detected and notified reliably.", "evidence": "Independent availability checks, dependency review, outage notifications and tests showing detection when the monitored service fails.", "risk_text": "Failure of the monitoring or logging service goes unnoticed, allowing an extended period without detection or reliable event evidence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.6.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-02','Detection Checks Identify Missed Events and Misleading Alerts','Detection Checks Identify Missed Events and Misleading Alerts','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET-TEST · Detection effectiveness testing", "topic_label": "B-DET-TEST · Detection effectiveness testing", "description": "Detection arrangements are checked against relevant known-event scenarios and benign activity. Missed detections and misleading alerts are investigated, and necessary adjustments are verified by a repeat check.", "evidence": "Known-event and benign-activity test cases, detection outputs, missed or misleading alerts and repeat-test results after correction.", "risk_text": "Unrecognised detection blind spots or misleading rules persist because known-event checks do not reveal and verify corrections, creating false confidence in monitoring.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.2.2; CIR Annex 3.1.3; CIR Annex 7.1; CIR Annex 7.2(b).", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-12','Incident Handling Is Defined and Approved','Incident Handling Is Defined and Approved','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "An approved incident-handling policy defines the response lifecycle, accountable roles, classification and escalation arrangements, communications, and the records and working documents to be used. It is consistent with the entity''s business continuity and recovery arrangements.", "evidence": "Approved incident-handling policy, responsibilities, escalation and communication arrangements, working templates and consistency with continuity plans.", "risk_text": "Responders make conflicting or delayed decisions under pressure, allowing the incident to worsen or causing unnecessary operational disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.1.1; CIR Annex 3.1.2.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','IR-TIME','Incident Response Time Targets Are Defined','Incident Response Time Targets Are Defined','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Define and document risk-appropriate time targets for initial assessment, starting a response and escalation where needed, according to incident priority and potential impact. Specify what starts each target period and the responsible response function. These are internal action targets, not authority-notification deadlines or guaranteed incident-resolution times; they do not permit delaying urgent action or overriding applicable legal duties.", "evidence": "Documented targets by priority and response stage, risk-based rationale, defined start points and responsible functions, and evidence that targets are available to responders.", "risk_text": "Urgent incident work waits too long for assessment, escalation or containment, increasing avoidable exposure or disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "Implementation of NIS2 Article 21(1), 21(2)(b). CIR Annex 3.5.1 requires timely response within its scope but does not prescribe fixed internal time targets. ISO comparison: supplied checklist A.5.26, question 2; not a claim that ISO expressly mandates a particular duration.", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','D02-05','Incident Communication Channels Are Established','Incident Communication Channels Are Established','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Establish usable communication channels for incident escalation and coordination with the responsible responders and relevant internal and external stakeholders. Identify current contacts and a fallback route when the normal channel or primary contact is unavailable.", "evidence": "Defined communication channels, current contact and alternate-contact details, and a test or incident record showing that the appropriate responders and stakeholders can be reached.", "risk_text": "Incident information does not reach those who must act, delaying or misdirecting the response.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b); CIR Annex 3.1.2(b)-(c) within CIR scope. Operational communication, not the separate statutory notification duties in T14.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-13','Suspicious Events Can Be Reported Easily','Suspicious Events Can Be Reported Easily','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Employees, suppliers and customers have a simple, usable way to report suspicious events. A submitted report reaches the responsible handling function and can be traced into the assessment process.", "evidence": "Accessible reporting channels for employees, suppliers and customers; submitted test or real reports traceable to the handling function.", "risk_text": "Observed suspicious activity does not reach the response team, delaying recognition and containment of a real incident.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.3.1; CIR Annex 3.4.1.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-14','Personnel Are Trained in Incident Reporting and Response','Personnel Are Trained in Incident Reporting and Response','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Train employees to recognise and report suspicious events through the available channel and to follow safe initial actions without exceeding their authority. Train designated responders in the incident-handling tasks assigned to them. Keep instruction current through regular, role-appropriate training; inform suppliers and customers of the reporting mechanism where appropriate. General programme methodology is assessed in T06, and operational response exercises are assessed under D02-18.", "evidence": "Role-matched incident training content and completion records; reporting and safe-action knowledge checks; responder instruction records and accessible reporting information for relevant suppliers and customers.", "risk_text": "R1: Personnel fail to report or escalate a real incident promptly.<br>R2: Unprepared responders take unsafe actions that worsen disruption or destroy evidence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.6.3", "A.6.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "Implementation of NIS2 Article 21(2)(b), (g); CIR Annex 3.3 and 8.2.1-8.2.3 within CIR scope. Role-specific response training extends the former reporting-only control.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-03','Suspicious Events Are Assessed','Suspicious Events Are Assessed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Suspicious events are assessed using the relevant facts, logs and correlated information to determine whether an incident has occurred. The decision, including a decision to dismiss an event, is recorded with its supporting reasons.", "evidence": "Assessment records with supporting logs, event facts, decision, rationale and reviewer; include dismissed events.", "risk_text": "R1: Real incidents are dismissed or remain unrecognised, delaying response.<br>R2: Benign activity is wrongly confirmed as an incident, triggering unnecessary isolation or account suspension that disrupts legitimate operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.4.1; CIR Annex 3.4.2(c); CIR Annex 3.4.2(d); CIR Annex 3.1.1.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-04','Incidents Are Classified and Prioritised','Incidents Are Classified and Prioritised','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Confirmed incidents are classified by their nature and severity using predefined criteria and the observed or credible service impact. The resulting priority guides how urgently containment and threat removal are undertaken.", "evidence": "Severity criteria and incident records showing type, assessed impact, priority and response urgency.", "risk_text": "A high-impact incident is treated as low priority, delaying containment while response resources are used on less urgent events.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.4.1; CIR Annex 3.4.2(a); CIR Annex 3.1.2(a).", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-15','Incident Assessments Are Updated When Facts Change','Incident Assessments Are Updated When Facts Change','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "When new information becomes available or existing information is reanalysed, the event assessment and classification are revisited and changed where warranted. The revised decision is recorded and passed to the response and reporting functions that need to act on it.", "evidence": "Versioned assessment and classification decisions, reasons for changes and evidence that response and reporting functions received updates.", "risk_text": "Outdated assessments cause inappropriate response or missed reporting obligations.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.4.2(e); CIR Annex 3.1.2(b).", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-16','Incident Actions and Decisions Are Recorded','Incident Actions and Decisions Are Recorded','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Incident records show who performed each material response action, when it occurred, what was done and the outcome. The records are maintained during handling so that the sequence of decisions and actions can be reconstructed reliably.", "evidence": "Incident timeline or case record showing who acted, when, what was done and the outcome; contemporaneous entries.", "risk_text": "Actions cannot be reconstructed and responders repeat or contradict earlier decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.4; CIR Annex 3.2.1.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-17','Incident Evidence Is Traceable and Protected','Incident Evidence Is Traceable and Protected','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Evidence collected for an incident retains an identifiable source and collection context, and is protected against unauthorised access or alteration. Relevant transfers and transformations are recorded so that the material used for decisions can be traced back to what was collected.", "evidence": "Collection records identifying source, time and context; access restrictions, integrity checks where appropriate and transfer or transformation history.", "risk_text": "R1: Evidence is altered, lost or cannot be traced to its source, undermining investigation and defensibility.<br>R2: Unauthorised disclosure of incident evidence exposes personal information, credentials or sensitive details of the affected environment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.28"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.4; CIR Annex 3.2.5; CIR Annex 12.2.1; CIR Annex 12.2.2(c).", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-07','Incidents Are Contained','Incidents Are Contained','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Documented containment procedures are used to limit an incident''s spread and impact through authorised, timely actions. The selected actions take account of critical service dependencies and safety constraints.", "evidence": "Containment procedures, authorisation and action records; evidence of isolation or access restriction and consideration of safety and service dependencies.", "risk_text": "R1: An incident spreads to additional systems or continues to expose information before it is contained.<br>R2: Poorly chosen containment actions interrupt necessary services or destroy volatile evidence.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.1; CIR Annex 3.5.2(a).", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-08','Incident Threats Are Removed','Incident Threats Are Removed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Documented eradication procedures guide the removal or neutralisation of the mechanisms that allow the incident to continue or recur. The results are checked rather than treating containment alone as removal of the threat.", "evidence": "Eradication procedures, records of removed persistence or compromised access, and checks demonstrating that the identified threat mechanisms were neutralised.", "risk_text": "Attackers retain access or the incident recurs despite apparent containment.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.1; CIR Annex 3.5.2(b); CIR Annex 7.1.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-09','Services Return to Operation Securely','Services Return to Operation Securely','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Where recovery is needed, documented procedures define and verify the incident-specific security conditions for returning affected services to operation. An authorised decision records why recovery or reconnection can proceed and any remaining safeguards.", "evidence": "Incident-specific recovery criteria, security validation results, authorised restoration or reconnection decision and remaining safeguards.", "risk_text": "Services are restored with unresolved compromise and immediately become affected again.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.1; CIR Annex 3.5.2(c); CIR Annex 4.1.2.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-10','Incidents Are Reviewed for Lessons Learned','Incidents Are Reviewed for Lessons Learned','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "After recovery, incidents are reviewed where appropriate to establish what happened, identify root causes where possible and record practical lessons. Periodic checks confirm that incidents warranting review have not been overlooked.", "evidence": "Review criteria and completed post-incident reviews covering timeline, root causes where possible and lessons; checks for omitted reviews.", "risk_text": "Unrecognised root causes or response weaknesses recur in later incidents, causing avoidable repeat disruption or compromise.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.6.1; CIR Annex 3.6.3.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-11','Incident Improvements Are Implemented','Incident Improvements Are Implemented','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Agreed improvements from incident reviews and exercises have responsible owners and target dates, and are implemented in the affected risk treatment, detection or response arrangements. Closure is supported by evidence that the intended correction works.", "evidence": "Action register linked to reviews or exercises, owners, target dates, implemented changes and evidence-based closure checks.", "risk_text": "Identified weaknesses remain unresolved and the same failures recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.6.2; CIR Annex 2.1.2(h); CIR Annex 2.1.2(i); CIR Annex 3.1.3; CIR Annex 7.1.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-18','Incident Response Is Tested Through Exercises','Incident Response Is Tested Through Exercises','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Incident-response procedures and the relevant roles are tested through planned exercises covering credible scenarios and the necessary hand-offs. Further tests address significant incidents or significant operational or risk changes where the applicable requirements call for them; observed results and failures are recorded.", "evidence": "Exercise plan, credible scenarios, participant and hand-off records, observed outcomes and identified failures; applicable change-triggered tests.", "risk_text": "Untested response procedures fail during a real incident and hand-offs break down.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b) CIR-specific requirement within CIR scope: CIR Annex 3.5.5; CIR Annex 3.1.3.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','D02-19','Incident Response Procedures Are Kept Current','Incident Response Procedures Are Kept Current','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Review operational incident-response procedures, playbooks and contact or escalation arrangements at planned intervals and after significant incidents or significant changes to operations or risks. Update and distribute them where needed, recording a justified no-change outcome where appropriate. This control assesses current operational instructions, not policy approval or general role assignments. It remains relevant even when no incident has occurred.", "evidence": "Dated scheduled and event-triggered reviews of operational procedures, playbooks and contact arrangements; version changes or justified no-change decisions; evidence that current instructions reach users. Do not duplicate policy or general role-assignment findings.", "risk_text": "Responders follow obsolete instructions or contact the wrong people, delaying or misdirecting incident handling.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(b); CIR Annex 3.1.3 within CIR scope. General policy reviews are assessed under C29.4 and personnel-role assignments under C27.4; incident lessons under D02-10 and corrective-action closure under D02-11.", "ref": "Art. 21(2)(b)"}'::jsonb),
  ('NIS2','C54.1','The Entity Identifies Incidents That Require Notification to the CSIRT or Competent Authority','The Entity Identifies Incidents That Require Notification to the CSIRT or Competent Authority','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-READY · Official-channel readiness and reporting decisions", "topic_label": "B-REP-READY · Official-channel readiness and reporting decisions", "description": "Assess whether an incident caused or can cause severe service disruption or financial loss for the entity, or considerable material or non-material damage to others. Apply any relevant CIR general and service-specific significance criteria only within their scope. Record whether the incident requires notification to the CSIRT or competent authority; do not equate internal priority labels with legal significance.", "evidence": "Applicable significance criteria, impact assessment and documented reportable/non-reportable decisions with rationale.", "risk_text": "A significant incident is incorrectly treated as non-reportable, delaying authority awareness and coordination and leaving the applicable reporting duty unmet.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 23(3); CIR Articles 3-14 where applicable. CIR-specific requirement within CIR scope: CIR Article 3(1); CIR Article 3(2); CIR Article 3(3); CIR Article 4; CIR Article 5; CIR Article 6; CIR Article 7; CIR Article 8; CIR Article 9; CIR Article 10; CIR Article 11; CIR Article 12; CIR Article 13; CIR Article 14.", "ref": "Art. 23(3)"}'::jsonb),
  ('NIS2','C54.2','The Entity Makes and Escalates Incident Notification Decisions Without Delay','The Entity Makes and Escalates Incident Notification Decisions Without Delay','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-READY · Official-channel readiness and reporting decisions", "topic_label": "B-REP-READY · Official-channel readiness and reporting decisions", "description": "Assign who determines whether an incident must be reported to the CSIRT or competent authority and who submits the reports. Ensure those people can act on current information, including outside working hours, and that escalation or internal approval does not delay a legally required notification. This assesses decision-making, not portal access or the criteria themselves.", "evidence": "Decision authority, deputies, escalation arrangements and decision timelines from incidents or exercises.", "risk_text": "Internal uncertainty or approval bottlenecks prevent timely statutory reporting.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(1), (3)-(4); operational implementation of the notification duty.", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C67.1','Significant Incidents Can Be Reported to the CSIRT or Competent Authority at Any Time','Significant Incidents Can Be Reported to the CSIRT or Competent Authority at Any Time','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-READY · Official-channel readiness and reporting decisions", "topic_label": "B-REP-READY · Official-channel readiness and reporting decisions", "description": "Authorised staff and their designated substitutes can submit significant-incident reports through the official channel to the responsible Computer Security Incident Response Team (CSIRT) or, where applicable, the competent NIS2 authority. Keep access credentials, permissions and contact details usable and test the reporting route during and outside working hours, using an agreed test method rather than sending a false incident report. This assesses readiness, not proof that a particular required report was submitted.", "evidence": "Named reporters and substitutes, channel and recipient details, access checks and end-to-end test records including out-of-hours availability.", "risk_text": "A significant incident cannot be notified through the official channel when required, delaying authority coordination and exposing the entity to reporting non-compliance.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H", "nis2_basis": "NIS2 Article 23(1), (4); supporting implementation, not a separate statutory portal-testing duty.", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C57.1','The Entity Assesses Recurring Incidents for Combined Reporting Significance (Applies only to entities within CIR scope.)','The Entity Assesses Recurring Incidents for Combined Reporting Significance (Applies only to entities within CIR scope.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-CIR · Recurring incidents within CIR scope", "topic_label": "B-REP-CIR · Recurring incidents within CIR scope", "description": "Check quarterly whether individually non-significant incidents occurred at least twice within six months, share the same apparent root cause and collectively meet the CIR financial-loss criterion: actual or potential direct financial loss exceeding EUR 500,000 or 5% of the entity''s preceding financial-year turnover, whichever is lower. When all conditions hold, treat them as one significant incident for CSIRT or competent-authority notification. The quarterly check does not permit delaying notification once significance is known. (Applies only to entities within CIR scope.)", "evidence": "Quarterly reviews, related incident records, root-cause links, loss calculations and resulting notification decisions.", "risk_text": "Recurring incidents are assessed only in isolation, so their combined impact is not notified when the applicable reporting threshold is met.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "CIR D", "nis2_basis": "CIR Article 4 with Article 3(1)(a); quarterly assessment: CIR Annex 3.4.2(b). Applies only within CIR scope.", "ref": "Art. 4", "applicability": {"condition": "only to entities within CIR scope", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C58.1','The Entity Sends an Early Warning to the CSIRT or Competent Authority Within 24 Hours','The Entity Sends an Early Warning to the CSIRT or Competent Authority Within 24 Hours','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "Submit the early warning through the designated official channel without undue delay and no later than 24 hours after becoming aware of the significant incident. Do not restart the clock at management approval or wait for a completed investigation. Where applicable, indicate suspected unlawful or malicious acts and possible cross-border effects; distinguish known facts from uncertainty.", "evidence": "Early-warning copy, correct recipient and official channel, awareness and submission timestamps, elapsed-time calculation, reasons for any delay, and supporting information on suspected cause and cross-border effects.", "risk_text": "An omitted, delayed or materially incomplete early warning prevents timely authority assessment and coordination.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(1), (4)(a).", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C60.1','The Entity Sends an Incident Notification to the CSIRT or Competent Authority Within 72 Hours','The Entity Sends an Incident Notification to the CSIRT or Competent Authority Within 72 Hours','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "Submit the follow-up incident notification without undue delay and within 72 hours of awareness of the significant incident, not of the early-warning submission. For a trust service provider, use 24 hours instead when the significant incident affects provision of its trust services. Send through the official channel and link the notification to the early warning. The initial assessment and other required content are assessed under C60.4.", "evidence": "Incident-notification copy and official transmission evidence; awareness and submission times; elapsed-time calculation; applicable provider/service classification; reasons for any delay.", "risk_text": "The follow-up notification is omitted or delayed, or the wrong deadline is applied, preventing timely coordination.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(1), (4)(b), including the final subparagraph of NIS2 Article 23(4) for trust services.", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C60.4','The Entity Includes the Required Assessment in Its Incident Notification','The Entity Includes the Required Assessment in Its Incident Notification','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "In the incident notification to the CSIRT or competent authority, update the early-warning information where applicable and provide an initial assessment of severity and impact. Include available indicators of compromise, such as malicious addresses or file hashes, and information that enables assessment of cross-border effects. Mark provisional or unavailable information clearly.", "evidence": "Notification copy, initial severity and impact assessment, applicable updates and available technical indicators.", "risk_text": "Incomplete or unreliable notification content misleads the authority about incident severity, spread or technical context, delaying or misdirecting coordinated follow-up.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(1), (4)(b).", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C61.1','The Entity Sends Intermediate Incident Reports When Requested by the CSIRT or Competent Authority (Applies when such a request is made.)','The Entity Sends Intermediate Incident Reports When Requested by the CSIRT or Competent Authority (Applies when such a request is made.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "When the CSIRT or competent authority requests an intermediate report, send the relevant incident status updates to that requester and address the requested information and applicable response instructions. No routine intermediate-report schedule is invented where no request exists. (Applies when such a request is made.)", "evidence": "Actual request, assigned response owner, submitted status update and transmission evidence.", "risk_text": "A requested status update is not provided, leaving the authority to coordinate follow-up using outdated information about the incident.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(4)(c).", "ref": "Art. 23(4)(c)", "applicability": {"condition": "when such a request is made", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C62.1','The Entity Sends the Final Incident Report to the CSIRT or Competent Authority Within One Month','The Entity Sends the Final Incident Report to the CSIRT or Competent Authority Within One Month','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "Send the final report to the CSIRT or competent authority no later than one month after submitting the incident notification. If the incident remains ongoing at that reporting point, use the progress-report route and submit the final report within one month of handling the incident. Record which route applies; one month is not automatically 30 days.", "evidence": "Incident-notification date, incident status, handling date where relevant, deadline calculation and final-report submission. Retain evidence of the distinct starting points; one month is not automatically 30 days.", "risk_text": "Late or omitted final reporting prevents timely authority review of the incident outcome and leaves the required reporting cycle incomplete.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(4)(d)-(e).", "ref": "Art. 23(4)(d)"}'::jsonb),
  ('NIS2','C62.2','The Entity Includes Incident Findings and Mitigation Measures in the Final Report','The Entity Includes Incident Findings and Mitigation Measures in the Final Report','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "In the final report to the CSIRT or competent authority, describe the incident and its severity and impact, the likely threat type or root cause, measures already taken and still underway, and cross-border effects where applicable. Separate established conclusions from remaining uncertainty.", "evidence": "Final report and supporting investigation findings, mitigation records and applicable cross-border assessment.", "risk_text": "An incomplete or unsupported final account misleads the authority about causes, effects or mitigation, impairing follow-up and shared learning.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(4)(d)(i)-(iv).", "ref": "Art. 23(4)(d)"}'::jsonb),
  ('NIS2','C63.1','The Entity Sends a Progress Report if the Incident Is Still Ongoing When the Final Report Is Due (Applies to incidents ongoing at that reporting point.)','The Entity Sends a Progress Report if the Incident Is Still Ongoing When the Final Report Is Due (Applies to incidents ongoing at that reporting point.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "topic_label": "B-REP-STAGES · Early warning, incident notification and follow-up reports", "description": "If the incident is still ongoing when the final report would otherwise be due, provide a progress report at that time to the CSIRT or competent authority. Explain the current status and retain responsibility for the later final report; do not falsely declare the incident complete. (Applies to incidents ongoing at that reporting point.)", "evidence": "Evidence of ongoing status, progress report, submission date and tracked obligation for the later final report.", "risk_text": "An ongoing incident is presented as closed or receives no progress update, leaving the authority with an inaccurate picture and preventing appropriate follow-up.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(4)(e).", "ref": "Art. 23(4)(e)", "applicability": {"condition": "to incidents ongoing at that reporting point", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C64.1','The Entity Sends Incident Information and Protective Threat Advice to Relevant Service Recipients','The Entity Sends Incident Information and Protective Threat Advice to Relevant Service Recipients','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-RECIP · Service-recipient and public communications", "topic_label": "B-REP-RECIP · Service-recipient and public communications", "description": "Where appropriate, notify service recipients without undue delay of significant incidents likely to adversely affect their services. Where applicable, promptly send potentially affected service recipients the measures or remedies they can take against a significant cyber threat; where appropriate, also explain the threat itself. Assess each trigger separately: protective advice can be needed before any incident occurs. These communications go to service recipients and do not replace CSIRT or competent-authority notification.", "evidence": "Incident or threat assessment identifying relevant recipients and applicable communication duties; sent incident notices or actionable protective advice, relevant threat explanations, recipient lists, dispatch times and justified non-applicability decisions.", "risk_text": "Service recipients lack timely information or practical guidance and suffer avoidable disruption or harm.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(1), service-recipient notification, and NIS2 Article 23(2), protective advice and information on significant cyber threats.", "ref": "Art. 23(1)"}'::jsonb),
  ('NIS2','C64.4','The Entity Publishes Incident Information When Required by the CSIRT or Competent Authority (Applies when the entity is required to inform the public.)','The Entity Publishes Incident Information When Required by the CSIRT or Competent Authority (Applies when the entity is required to inform the public.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-REP-RECIP · Service-recipient and public communications", "topic_label": "B-REP-RECIP · Service-recipient and public communications", "description": "If the CSIRT or competent authority requires the entity to inform the public about a significant incident under Article 23(7), issue the requested public communication in line with the applicable requirement. This concerns public awareness needed to prevent or address the incident, or disclosure otherwise in the public interest; it is not a routine publication duty for every incident. (Applies when the entity is required to inform the public.)", "evidence": "Authority or CSIRT requirement, consulted or agreed communication details and publication evidence.", "risk_text": "R1: Required public information is withheld and people cannot respond to the incident appropriately.<br>R2: A public incident notice unnecessarily exposes personal data or sensitive response details, causing further disclosure or helping attackers adapt.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 23(7).", "ref": "Art. 23(7)", "applicability": {"condition": "when the entity is required to inform the public", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C21.1','The Entity Notifies the NIS2 Authority When Joining or Leaving an Information-Sharing Arrangement (Applies only to essential and important entities joining or withdrawing from such arrangements.)','The Entity Notifies the NIS2 Authority When Joining or Leaving an Information-Sharing Arrangement (Applies only to essential and important entities joining or withdrawing from such arrangements.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-SHR · Voluntary information-sharing arrangements", "topic_label": "B-SHR · Voluntary information-sharing arrangements", "description": "Notify the competent NIS2 authority when the entity enters a cybersecurity information-sharing arrangement and, on withdrawal, when that withdrawal takes effect. This notification concerns participation in the arrangement, not an individual incident report. (Applies only to essential and important entities joining or withdrawing from such arrangements.)", "evidence": "Participation or withdrawal record, effective date and notification sent to the competent NIS2 authority.", "risk_text": "The competent authority acts on an inaccurate picture of the entity''s participation in an information-sharing arrangement, impairing required oversight and follow-up.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 29(4).", "ref": "Art. 29(4)", "applicability": {"condition": "only to essential and important entities joining or withdrawing from such arrangements", "condition_source": "control_name", "scope_group": "APP-SHARE", "presentation": "inline"}}'::jsonb),
  ('NIS2','C21.2','If the Entity Participates in an Information-Sharing Arrangement, It Shares Cybersecurity Information Securely','If the Entity Participates in an Information-Sharing Arrangement, It Shares Cybersecurity Information Securely','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T14", "subgroup": "B-SHR · Voluntary information-sharing arrangements", "topic_label": "B-SHR · Voluntary information-sharing arrangements", "description": "If the entity participates in a voluntary cybersecurity information-sharing arrangement, it follows the agreed handling rules, protects sensitive information and sends information only to authorised participants. Joining is voluntary. This control is not applicable without relevant participation; it concerns peer sharing, not statutory incident notification.", "evidence": "Arrangement rules, recipient permissions, handling restrictions and suitable examples of shared information.", "risk_text": "Voluntary sharing exposes sensitive information or distributes it beyond the permitted participants.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "H", "nis2_basis": "NIS2 Article 29(1)-(3), 2(14); supporting safe-sharing practice.", "ref": "Art. 29(1)", "applicability": {"condition": "Does your entity participate in, join or withdraw from a cybersecurity information-sharing arrangement?", "condition_source": "scope_group_question", "scope_group": "APP-SHARE", "presentation": "inline"}}'::jsonb),
  ('NIS2','BC-BIA','Business Impact Analysis (BIA) Is Conducted and Continuity Requirements Are Defined','Business Impact Analysis (BIA) Is Conducted and Continuity Requirements Are Defined','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "topic_label": "C-IMPACT · Assess business impact and define service recovery targets", "description": "Assess how disruption of relevant services and activities affects operations over time, including dependencies on systems, data, personnel and suppliers. Consider operational, financial, legal and safety consequences. Identify recovery priorities and the point at which disruption becomes unacceptable, expressed where useful as the Maximum Tolerable Period of Disruption (MTPD). Document the continuity requirements that follow. This assesses disruption consequences, not just the likelihood of threats.", "evidence": "Documented service/activity impact analysis with time horizons, dependencies and stakeholder input; justified intolerable-impact thresholds, recovery priorities and resulting continuity requirements.", "risk_text": "Critical dependencies and the consequences of prolonged disruption are misunderstood, so recovery priorities and continuity arrangements do not protect the services that matter most.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c); CIR Annex 4.1.3 explicitly requires BIA and resulting continuity requirements within CIR scope. ENISA guidance 4.1.3, p.53, supports impact-based objectives; named metrics and a specific template are not universally prescribed.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','BC-RTO','Recovery Time Objectives (RTO) Are Defined for Priority Services','Recovery Time Objectives (RTO) Are Defined for Priority Services','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "topic_label": "C-IMPACT · Assess business impact and define service recovery targets", "description": "Set the target time for restoring each priority service to a stated usable level, based on business-impact findings. Define when the clock starts and what counts as recovery; account for system and supplier dependencies. Set targets early enough to avoid unacceptable disruption, allowing for subsequent business recovery where needed. For example, an RTO of two hours requires the specified service capability within two hours. A backup job duration is not a service RTO.", "evidence": "Service-specific RTO register or equivalent plan entries; business-impact justification; defined start/end criteria and service level; dependency alignment and business-owner validation.", "risk_text": "Recovery teams work to arbitrary or inconsistent deadlines, allowing services to remain unavailable beyond business tolerances.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c); CIR Annex 4.1.2(f), 4.1.3 and recital 13. ENISA guidance 4.1.3, p.53: RTO is an impact-based recovery-objective method; CIR requires appropriate recovery objectives, not a fixed universal duration.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.1','Business Continuity Plans Are Defined','Business Continuity Plans Are Defined','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define how priority services will continue while normal systems or premises are unavailable, using the business-impact findings and recovery objectives. Specify activation conditions, workarounds, responsibilities and resources. State the minimum acceptable service level during temporary operation, using a Service Delivery Objective (SDO) where useful; for example, which essential transactions remain available. This is the operational continuity plan, not the BIA itself or a promise of uninterrupted service.", "evidence": "Current continuity plans linked to BIA priorities and recovery objectives; minimum temporary service levels, activation conditions, workarounds, owners and resource requirements.", "risk_text": "Priority services stop or operate below an acceptable level during disruption because planned continuity arrangements are not workable.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.1.1; CIR Annex 4.1.2(b); CIR Annex 4.1.2(d); CIR Annex 4.1.2(f); CIR Annex 4.1.2(g); CIR Annex 4.1.2(h); CIR Annex 4.1.3.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.3','Disaster Recovery Procedures Are Defined','Disaster Recovery Procedures Are Defined','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define the steps, recovery order and responsible teams for restoring disrupted systems and services. Address dependencies, access to recovery resources, validation of recovered systems and return from temporary to normal operations. Use the RTO and RPO values established under BC-RTO and BC-RPO to design the procedures; do not redefine conflicting targets here. Assess whether staff have executable instructions, not merely a statement that recovery will occur.", "evidence": "Current restoration instructions, dependency-based recovery sequence, responsible teams, resource/access arrangements and acceptance checks; traceability to defined RTO/RPO values.", "risk_text": "Recovery teams lack executable instructions or restore dependencies in the wrong order, preventing timely and reliable service recovery.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(c)", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.4','Crisis Plans Define When to Escalate and Who Decides','Crisis Plans Define When to Escalate and Who Decides','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define when a disruption requires crisis-level coordination beyond routine incident handling, who activates the crisis team and who can make urgent service and resource decisions. Set out internal and external communication arrangements, substitutes and how plans and contacts remain accessible if normal systems fail. Not every security incident needs crisis activation; statutory reporting is assessed in T14.", "evidence": "Crisis activation and stand-down criteria, decision authorities and substitutes, communication arrangements, accessible plan/contact copies and continuity-plan interfaces.", "risk_text": "A disruption exceeding routine incident capacity receives conflicting or delayed leadership decisions, extending service interruption and confusing stakeholders.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.3.1; CIR Annex 4.3.2(a); CIR Annex 4.3.2(b); CIR Annex 4.3.2(c).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.6','The Resources Required by Continuity Plans Are Available','The Resources Required by Continuity Plans Are Available','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-READY · Prepare alternative resources", "topic_label": "C-READY · Prepare alternative resources", "description": "Make the alternative systems, facilities, personnel and communication resources specified in the continuity and recovery plans available within the required time. Check their capacity, access arrangements and dependencies against the planned service level, including resources provided by suppliers. A supplier name or planned purchase alone does not demonstrate availability; not every service requires a second site.", "evidence": "Plan-to-resource mapping, capacity and access checks, staff cover, supplier commitments and evidence of resource availability within the required time.", "risk_text": "Documented workarounds or recovery steps cannot be carried out because replacement resources are unavailable, inaccessible or undersized.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.1.2(g); CIR Annex 4.2.1; CIR Annex 4.2.4; CIR Annex 4.2.5.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','BC-RPO','Recovery Point Objectives (RPO) Are Defined for Data Recovery','Recovery Point Objectives (RPO) Are Defined for Data Recovery','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Determine how far back in time data may be recovered without unacceptable loss, based on the business impact of losing records or transactions. Specify the acceptable data-loss window for relevant datasets and services, then use it to select backup frequency and other recovery arrangements. For example, an RPO of 15 minutes permits at most 15 minutes of lost updates. RPO is neither the time taken to restore data nor a backup retention period.", "evidence": "Documented RPO values for relevant data/services; business-owner justification of acceptable loss; mapping to backup or other recovery design; consistent assumptions about replication, timing and data dependencies.", "risk_text": "Recovery arrangements restore data that is too old, causing unacceptable loss of transactions or records even when the service is restored quickly.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c); CIR Annex 4.1.2(f), 4.1.3 and recital 13; backup implementation under 4.2. ENISA guidance 4.1.3 supports RPO-based backup design. NIST SP 800-34 Rev.1 defines RPO by the data recovery point, not restoration duration. The named method is not a universal fixed legal threshold.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.2','Backup Procedures Are Implemented and Tested','Backup Procedures Are Implemented and Tested','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Run backups for the data, software and configurations needed for recovery, including relevant cloud-hosted content, using defined schedules and retention periods. Test that the backup process includes the required sources, creates the intended copies and identifies failed or omitted jobs; correct failures and retest affected steps. This control assesses reliable backup creation, while C32.5 checks stored-copy integrity and C33.1 tests actual restoration. Replication or a cloud subscription alone is insufficient.", "evidence": "Backup scope and schedules linked to recovery needs; retention settings; job and exception records; documented tests of source coverage, copy creation and failure detection; corrected failures and retest results.", "risk_text": "The backup process silently omits required information or fails to create current recovery copies, leaving services without a viable recovery source.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.2.1; CIR Annex 4.2.2(b); CIR Annex 4.2.2(f); CIR Annex 7.1.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C33.2','Backups Are Protected from Production-System Compromise','Backups Are Protected from Production-System Compromise','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Protect backup copies and their administration against compromise of production systems, unauthorised access, alteration and deletion. Address shared dependencies and site-level damage. For CIR-covered entities, place copies outside the production system''s network and sufficiently far from the main site to escape the same disaster, with appropriate access controls. Online and offline copies are both possible; no universal offline-only design or particular product is prescribed.", "evidence": "Backup network and administration architecture, location and common-disaster assessment, access restrictions, deletion/alteration safeguards and tested compromise scenarios. For CIR scope, verify network and geographical separation rather than accepting an unexplained ''secure backup'' label.", "risk_text": "R1: A compromise or common failure destroys or corrupts production data and the recovery copies needed to restore them.<br>R2: An attacker obtains sensitive information from recovery copies that share the compromised production trust boundary.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c); CIR Annex 4.2.2(c)-(d).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.7','Security Controls Remain Effective During Emergency Operations','Security Controls Remain Effective During Emergency Operations','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-OPERATE · Maintain security during disruption and return to normal operations", "topic_label": "C-OPERATE · Maintain security during disruption and return to normal operations", "description": "Apply appropriate security when continuity arrangements use temporary systems, manual records, emergency access or alternative premises. Control who can access information, protect temporary records and reassess safeguards as conditions change. When normal operations resume, withdraw temporary access and handle temporary records securely; where no disruption occurred, assess prepared safeguards and exercise evidence.", "evidence": "Emergency-operation security arrangements, temporary-access and record-handling controls, incident or exercise evidence, risk decisions and return-to-normal checks.", "risk_text": "R1: Emergency workarounds expose information or permit unauthorised access during disrupted operation.<br>R2: Temporary emergency privileges or insecure configurations remain in place after recovery and are later misused.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.3.2(c); CIR Annex 1.2.2; CIR Annex 4.1.2(h); CIR Annex 11.2.1; CIR Annex 12.2.1.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','TRN-BCDR','Personnel Are Trained in Their Business Continuity and Disaster Recovery Duties','Personnel Are Trained in Their Business Continuity and Disaster Recovery Duties','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Train personnel for their assigned continuity and recovery duties: staff learn the relevant temporary working arrangements, recovery teams learn restoration procedures and crisis coordinators learn activation and communication duties. Refresh instruction when relevant duties or plans change and check that participants can apply it. A separate course or certificate is not required; an exercise can also provide training evidence if learning and understanding are demonstrated. T06 assesses the general training programme, not this topic-specific delivery.", "evidence": "Role-to-duty training coverage; current instructions and training records; practical demonstrations or knowledge checks; follow-up of identified learning gaps.", "risk_text": "Personnel do not know how to maintain priority services or perform assigned recovery tasks, so otherwise adequate plans fail during disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c), (g): role-relevant implementation. CIR Annex 8.2.1-8.2.5 within CIR scope; not a separately named mandatory BCDR course. ENISA technical implementation guidance 4.1.4, p.54; provided ISO checklist part3, A.6.3.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.5','Backup Copies Are Checked for Corruption and Incompleteness','Backup Copies Are Checked for Corruption and Incompleteness','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Regularly verify the integrity and completeness of stored backup copies using appropriate checks and investigate failures. Confirm that affected copies are repaired or replaced as needed. This checks the stored material; it does not replace a restoration test or prove that a service can run from the recovered data.", "evidence": "Integrity and completeness checks, identified failures, affected-copy records and evidence of successful correction or replacement.", "risk_text": "Corrupt or incomplete backup content is trusted as usable and fails to supply the data, configuration or metadata needed for recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.2.3; CIR Annex 4.2.2(b).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C33.1','Backup Restoration Is Tested Against Recovery Point Objectives (RPO)','Backup Restoration Is Tested Against Recovery Point Objectives (RPO)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "At planned, risk-appropriate intervals, restore selected data and systems from backups and verify usability, completeness and the recovered data point against the defined Recovery Point Objective (RPO). Record elapsed restoration time as an input to service-level RTO validation, together with failures and corrective actions. A successful backup job does not prove restoration, and an isolated restore test does not by itself demonstrate that the whole service meets its RTO.", "evidence": "Restore scenarios and acceptance criteria; recovered data-point timestamps and RPO comparisons; usability/completeness checks; measured restore durations; failures, corrective actions and retest results.", "risk_text": "A restore cannot reconstruct complete, usable data at the required recovery point, causing data loss beyond the agreed RPO.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.2.6; CIR Annex 4.2.2(e); CIR Annex 4.1.2(f).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C33.4','Failover Tests Confirm That Redundant Resources Can Take Over','Failover Tests Confirm That Redundant Resources Can Take Over','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Test the planned switch from primary resources to their redundant alternatives under realistic failure conditions. Check whether capacity, connectivity and dependent services remain sufficient, and record and correct failed transitions. This assesses taking over service delivery, not rebuilding a system from a backup. Apply it to the redundancy required by the continuity design.", "evidence": "Failover scenarios, transition records, service and dependency checks under the alternative resources, capacity results and correction of failures.", "risk_text": "Standby resources exist but fail to take over, or cannot support the service when primary resources are unavailable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.2.6; CIR Annex 4.2.4.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C33.3','Continuity and Recovery Exercises Test Service Recovery Objectives (RTO)','Continuity and Recovery Exercises Test Service Recovery Objectives (RTO)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Exercise a realistic disruption from continuity activation through restoration and return to normal operations. Verify the temporary service level and measure end-to-end service recovery against the defined Recovery Time Objective (RTO), including staff, supplier and system dependencies. Where restoration involves data loss, use the RPO verification evidence as well. Review plans at planned intervals and after significant incidents or relevant significant changes; incorporate lessons and verify corrective actions.", "evidence": "End-to-end exercise scenarios and participation; measured service recovery times compared with RTO; temporary service-level results; relevant RPO evidence; revised plans and verified corrective actions.", "risk_text": "End-to-end recovery exceeds the service RTO because dependencies, hand-offs or combined recovery steps fail despite individual component tests.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.1.4; CIR Annex 4.1.2(f).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C32.8','Crisis Exercises Test Leadership Decisions and Communication','Crisis Exercises Test Leadership Decisions and Communication','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Use realistic crisis scenarios to test activation, decision authority, coordination and communication when normal arrangements are under pressure. Review and update the crisis plan under the applicable regular or incident/change-triggered review requirements. Assess crisis leadership here, not duplicate technical recovery tests; a shared exercise may provide evidence for both distinct outcomes.", "evidence": "Crisis scenarios, leadership participation, decision and communication records, review results, updated arrangements and follow-up of weaknesses.", "risk_text": "Leaders cannot coordinate urgent decisions or communicate effectively during a major disruption despite having a written crisis plan.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(c) CIR-specific requirement within CIR scope: CIR Annex 4.3.4; CIR Annex 4.3.2(a); CIR Annex 4.3.2(b).", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','REC-METRIC','Actual Recovery Times Are Measured and Reviewed (MTTR)','Actual Recovery Times Are Measured and Reviewed (MTTR)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-MEASURE · Measure recovery performance and improve it", "topic_label": "C-MEASURE · Measure recovery performance and improve it", "description": "Record the time from service disruption to verified service restoration using consistent start and end rules. For comparable actual events, calculate Mean Time to Recovery (MTTR) as total recovery time divided by the number of recovered events; separate services and scenarios with materially different recovery expectations. Review each event against its RTO as well as reviewing the average, investigate overruns and track improvements. Keep exercise results separate from actual-event statistics. With no actual events, assess measurement readiness and test timings; do not require an invented average or report zero MTTR.", "evidence": "Defined timing boundaries and comparable-event scope; event timestamps and acceptance records; reproducible MTTR calculation with sample size; individual RTO comparisons; investigation and improvement records. Where no events occurred: prepared measurement method and separately identified exercise results.", "risk_text": "Recurring recovery delays or service-specific RTO breaches remain hidden by incomplete measurement or misleading averages, so improvement effort misses the real bottlenecks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(c), (f): supporting measurement of recovery effectiveness, not an expressly prescribed MTTR metric. NIST SP 800-55 and NIST CSRC glossary, mean time to recovery.", "ref": "Art. 21(2)(c)"}'::jsonb),
  ('NIS2','C51.5','The Entity Defines How Supplier Security Is Managed','The Entity Defines How Supplier Security Is Managed','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Define who is responsible for supplier security and how suppliers are assessed, contracted, monitored and offboarded. Apply these rules according to the risks of the products and services being supplied.", "evidence": "Supply-chain security policy, assigned owners and records showing the rules used in actual supplier relationships.", "risk_text": "Supplier security responsibilities fall between procurement, service owners and security teams, allowing material exposure to persist throughout the relationship.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["8.1", "A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR Annex 5.1.1.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C51.1','The Entity Keeps an Up-to-Date Supplier and Service Register','The Entity Keeps an Up-to-Date Supplier and Service Register','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "List relevant direct suppliers, their contacts and the ICT products, services or processes they provide. Identify which business services depend on each supplier and update the register when the relationship changes.", "evidence": "Supplier register with contacts, supplied products/services, business-service links and reconciliation against procurement records.", "risk_text": "An unrecorded supplier or service dependency is omitted from incident coordination and security oversight, delaying action when that supplier fails or is compromised.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR Annex 5.2.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','SUP-RESP','Security Responsibilities Are Agreed Between the Entity and the Supplier (Applies where security responsibilities are shared with a supplier.)','Security Responsibilities Are Agreed Between the Entity and the Supplier (Applies where security responsibilities are shared with a supplier.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "For services with shared security duties, agree which party performs each relevant task, such as patching, backups, access administration, logging and incident response. Define handovers and verify that no necessary task is left unassigned. (Applies where security responsibilities are shared with a supplier.)", "evidence": "Service-specific responsibility matrix or equivalent agreed allocation, supplier acknowledgement and records confirming responsibility at operational handovers.", "risk_text": "R1: Each party assumes the other performs a necessary security task, leaving systems unpatched, unmonitored or without usable backups.<br>R2: Unclear handovers delay containment or recovery while the entity and supplier dispute who must act.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(d), (3), implementation mapping; Grundschutz++ BES.1.7 and BES.7.4.6. Not a standalone responsibility-matrix duty expressly prescribed by the Directive.", "ref": "Art. 21(2)(d)", "applicability": {"condition": "where security responsibilities are shared with a supplier", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C51.2','The Entity Determines Which Suppliers Are Critical to Its Services','The Entity Determines Which Suppliers Are Critical to Its Services','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Assess what would happen to operations, information and recovery if each relevant supplier failed or was compromised. Use the result to decide how closely the supplier must be assessed and monitored.", "evidence": "Supplier criticality assessments showing service impact, recovery dependencies and resulting oversight requirements.", "risk_text": "Supplier failure or compromise affects a priority service more severely than anticipated because its business and recovery dependencies were underestimated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(d), (3)", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C51.3','The Entity Checks Which Systems and Data Suppliers Can Access','The Entity Checks Which Systems and Data Suppliers Can Access','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Identify supplier accounts, remote connections, privileges and accessible information. Compare the recorded access with actual permissions and refer unnecessary or unexplained access for correction through access management.", "evidence": "Supplier access records, actual account/connection listings and evidence that discrepancies were resolved.", "risk_text": "R1: Unknown or excessive supplier access is used to obtain organisational information.<br>R2: A compromised supplier account or connection enables unauthorised changes to internal systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR-specific requirement within CIR scope: CIR Annex 11.2.1; CIR Annex 11.2.2(d); CIR Annex 11.2.2(e); CIR Annex 11.2.3; CIR Annex 6.7.2(d).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C51.4','The Entity Assesses Dependence on Individual Suppliers and Shared Platforms','The Entity Assesses Dependence on Individual Suppliers and Shared Platforms','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Identify services that could fail together because they depend on one supplier or platform. Assess barriers to switching suppliers, such as incompatible data formats or unavailable expertise, and decide how to reduce unacceptable dependence.", "evidence": "Shared-dependency analysis, switching/exit constraints and documented treatment decisions; multiple suppliers are not automatically required.", "risk_text": "R1: One supplier or shared-platform failure interrupts several dependent services at once.<br>R2: Lock-in or loss of internal knowledge prevents timely replacement of the supplier, extending the disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR-specific requirement within CIR scope: CIR Annex 5.1.2(d); CIR Annex 2.1.2(d).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C49.4','The Entity Uses Security Criteria When Selecting Suppliers','The Entity Uses Security Criteria When Selecting Suppliers','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Compare prospective suppliers against defined security and resilience requirements before making the selection. Record why the chosen supplier is suitable and how any accepted gaps will be treated.", "evidence": "Security selection criteria, evaluated supplier offers, selection approval and justified treatment of gaps.", "risk_text": "A supplier unable to meet justified cybersecurity or resilience needs is selected, leaving the entity with avoidable exposure or a costly constrained replacement.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR-specific requirement within CIR scope: CIR Annex 5.1.2; CIR Annex 5.1.5.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C50.1','The Entity Uses Relevant EU Supply-Chain Risk Assessment Findings (Applies where a relevant assessment under NIS2 Article 22(1) exists.)','The Entity Uses Relevant EU Supply-Chain Risk Assessment Findings (Applies where a relevant assessment under NIS2 Article 22(1) exists.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Check whether coordinated EU assessments identify risks relevant to the entity''s suppliers, products or services. Incorporate applicable findings into supplier security decisions and document why findings do or do not apply. (Applies where a relevant assessment under NIS2 Article 22(1) exists.)", "evidence": "Relevance check, applicable EU assessment findings and evidence of resulting supplier/security decisions.", "risk_text": "A supplier decision relies on outdated assumptions and leaves a material supply-chain exposure untreated despite a relevant coordinated EU assessment identifying it.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(3), second sentence, read with Article 22(1); CIR Annex 5.1.3 within CIR scope. CIR-specific requirement within CIR scope: CIR Annex 5.1.3; CIR Annex 5.1.5.", "ref": "Art. 21(3)", "applicability": {"condition": "where a relevant assessment under NIS2 Article 22(1) exists", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C49.2','The Entity Assesses Supplier Security Practices and Product Reliability','The Entity Assesses Supplier Security Practices and Product Reliability','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Assess whether the supplier''s security practices and the quality and resilience of its products or services meet the entity''s needs. Where relevant, include how the supplier develops and maintains software securely; apply this also to purchased software, not only outsourced development projects.", "evidence": "Supplier assessment, relevant assurance and product/service evidence, and evaluation of secure-development practices where applicable.", "risk_text": "R1: A supplier product or operating practice exposes entrusted information to unauthorised access.<br>R2: An unsuitable supplier service fails to provide the availability or recoverability needed by the entity.<br>R3: Weak supplier development practices introduce exploitable defects or compromised components into acquired or maintained systems.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.19", "A.5.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(3); CIR Annex 5.1.2(a)-(c) within CIR scope.", "ref": "Art. 21(3)"}'::jsonb),
  ('NIS2','SUP-LOC','Supplier Locations Are Assessed for Security and Continuity Risks (Applies where supplier operating or information-processing locations can materially affect security or continuity.)','Supplier Locations Are Assessed for Security and Continuity Risks (Applies where supplier operating or information-processing locations can materially affect security or continuity.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Identify the countries or regions where relevant supplier services operate and the entity''s information is processed or stored, including recovery locations. Assess whether regional outages, disrupted connectivity, instability or shared location dependencies could interrupt the service or compromise information. Agree advance notification of material location changes so their effects can be assessed before the move. This is not a blanket requirement to keep information in the EU. (Applies where supplier operating or information-processing locations can materially affect security or continuity.)", "evidence": "Relevant service, processing, storage and recovery location records; assessment of location-specific and shared dependencies; agreed advance-notification terms; assessments of actual material location changes.", "risk_text": "R1: A regional power, communications or other disruption affects both the primary service and its recovery arrangements because their location dependency was not identified.<br>R2: A supplier relocates service delivery or information processing without prior assessment, invalidating security assumptions or making agreed recovery arrangements ineffective.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (c), (d), and (3), implementation mapping; ENISA Technical Implementation Guidance, June 2025, p.71, additional contractual guidance; Grundschutz++ BES.2.2. Not a standalone Directive data-localisation duty.", "ref": "Art. 21(2)", "applicability": {"condition": "where supplier operating or information-processing locations can materially affect security or continuity", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C49.1','The Entity Addresses Security Weaknesses Identified in Its Suppliers','The Entity Addresses Security Weaknesses Identified in Its Suppliers','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Assess how identified weaknesses in a supplier, its products or services could affect the entity. Decide and track necessary safeguards or corrective actions; for example, require stronger protection before allowing a remote-support provider privileged access. Technical patching remains part of vulnerability management.", "evidence": "Supplier-specific findings, impact assessment, required safeguards or contractual conditions, assigned actions and follow-up.", "risk_text": "An identified supplier-specific security weakness is left untreated in acceptance or corrective decisions and enables unauthorised access, changes to the entity''s systems or disruption of its services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(3)", "ref": "Art. 21(3)"}'::jsonb),
  ('NIS2','C52.1','Supplier Contracts Define Security, Incident Notification and Vulnerability Handling','Supplier Contracts Define Security, Incident Notification and Vulnerability Handling','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "The entity agrees enforceable, risk-appropriate security requirements with suppliers. Include notification to the entity without undue delay of incidents that threaten its systems, and responsibilities for handling relevant vulnerabilities. Specify contacts and necessary information; these arrangements support, but do not replace, the entity''s own response and statutory reporting duties.", "evidence": "Signed security clauses and service-level agreements identifying required safeguards, incident contacts/notification duties, and vulnerability-handling responsibilities and escalation arrangements.", "risk_text": "R1: A supplier disputes or omits necessary security work because binding responsibilities and service expectations are unclear, leaving the entity unable to obtain timely protection or correction.<br>R2: A supplier delays or withholds relevant incident information, delaying the entity''s response or causing it to miss an applicable statutory notification deadline.<br>R3: A vulnerability affecting the entity remains exploitable while supplier and customer dispute responsibility, notification or remediation expectations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.20", "A.8.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (e), (3); CIR Annex 5.1.4(a), (d), (f), subject to its scope and qualifiers.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C52.3','The Entity Secures Rights to Audit Suppliers or Obtain Audit Reports','The Entity Secures Rights to Audit Suppliers or Obtain Audit Reports','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Agree a practical way to obtain evidence about the security of the supplied service, through audit rights or relevant audit reports. An on-site audit of every supplier is not required; the agreed access must allow meaningful verification.", "evidence": "Contractual audit/report rights showing the covered service, permitted evidence and relevant access conditions.", "risk_text": "The entity cannot obtain scope-relevant assurance evidence, so material supplier weaknesses remain undetected or unresolved.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR Annex 5.1.4(e).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C52.7','The Entity Sets Security Conditions for Supplier Subcontracting','The Entity Sets Security Conditions for Supplier Subcontracting','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Define whether and under which conditions suppliers may subcontract the work. Where subcontracting is allowed, require relevant security obligations to apply to subcontractors and obtain evidence that these conditions are met.", "evidence": "Subcontracting permissions/restrictions, relevant subcontractor records and evidence of applicable security obligations.", "risk_text": "R1: A subcontractor obtains or handles organisational information without the safeguards expected of the direct supplier.<br>R2: An undisclosed or poorly controlled subcontractor dependency interrupts the contracted service.<br>R3: A subcontractor introduces malicious or compromised components into the supplied product or service, enabling compromise of the entity''s systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21", "A.5.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3) CIR Annex 5.1.4(g).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C52.5','The Entity Verifies Required Background Checks for Supplier Personnel (Applies where the role and applicable law justify background checks.)','The Entity Verifies Required Background Checks for Supplier Personnel (Applies where the role and applicable law justify background checks.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "For sensitive supplier roles, agree which lawful background checks are necessary and confirm their completion before assignment. Obtain proportionate confirmation rather than unnecessary personal records. (Applies where the role and applicable law justify background checks.)", "evidence": "Role-based screening requirements and lawful completion confirmations for personnel assigned to the relevant roles.", "risk_text": "R1: A person with relevant, lawfully discoverable trust concerns is assigned sensitive supplier duties and misuses the resulting access.<br>R2: Disproportionate screening collects or discloses unnecessary personal information about supplier personnel.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (i) CIR Annex 5.1.4(c).", "ref": "Art. 21(2)(d)", "applicability": {"condition": "where the role and applicable law justify background checks", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C52.4','The Entity Verifies Supplier Personnel Have the Required Security Skills','The Entity Verifies Supplier Personnel Have the Required Security Skills','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Define the security skills and role-specific training needed by supplier personnel working on the service. Obtain proportionate evidence that they meet those requirements; request certificates only where justified.", "evidence": "Agreed role/competence requirements and proportionate qualification or training evidence covering the assigned supplier personnel.", "risk_text": "Supplier personnel make security-relevant operational errors or fail to respond correctly because they lack the skills required for their assigned tasks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (g), (i) CIR Annex 5.1.4(b).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','SUP-AUTH','The Entity Verifies the Authenticity and Integrity of Critical ICT Deliveries','The Entity Verifies the Authenticity and Integrity of Critical ICT Deliveries','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-DELIVERY · Verify ICT deliveries before operational use", "topic_label": "D-DELIVERY · Verify ICT deliveries before operational use", "description": "Before using critical acquired hardware or software, verify that it comes from a trusted source and shows no evidence of substitution or tampering. Select checks according to product risk, such as authorised-source confirmation, manufacturer verification, digital signatures or physical delivery inspection. This checks the delivered product''s provenance and integrity, not whether its security functions work or whether later patches are authentic.", "evidence": "Risk-based acceptance criteria, trusted-source records and product-appropriate authenticity/integrity checks, with rejected or suspicious deliveries and their disposition recorded.", "risk_text": "R1: Counterfeit, substituted or maliciously modified hardware or software is accepted into operational systems, enabling unauthorised access or manipulation.<br>R2: An unreliable counterfeit component fails during operation and disrupts a critical service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(d), (e), and (3), implementation mapping; NIST SP 800-161 Rev.1 Update1, SR-9, SR-10 and SR-11.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','TRN-12','The Entity Ensures Relevant Suppliers Understand Its Security and Reporting Rules','The Entity Ensures Relevant Suppliers Understand Its Security and Reporting Rules','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Communicate the cybersecurity risks, cyber-hygiene practices and reporting routes relevant to the supplied service. Check that the supplier understands and applies them, and offer appropriate awareness activities where needed. This covers shared working rules, not specialist qualifications.", "evidence": "Supplier guidance and communication records, awareness participation where appropriate, and evidence of understanding and application.", "risk_text": "Supplier staff disregard the entity''s cyber-hygiene or reporting expectations, exposing shared information or delaying escalation of suspicious activity.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (g) CIR-specific requirement within CIR scope: CIR Annex 8.1.1; CIR Annex 8.1.2; CIR Annex 10.1.2(a); CIR Annex 3.3.2.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C53.1','The Entity Checks Supplier Certificates and Audit Reports Before Relying on Them','The Entity Checks Supplier Certificates and Audit Reports Before Relying on Them','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Verify that assurance evidence covers the actual supplier service and a relevant period. Review exclusions and unresolved findings, then decide whether further evidence or corrective action is necessary; a certificate alone is not sufficient.", "evidence": "Recorded checks of report/certificate scope, dates, findings and exclusions, with follow-up decisions.", "risk_text": "A certificate or report covering the wrong service, period or scope creates false assurance, allowing actual supplier weaknesses to remain accepted and untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.22"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(d), (3)", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','C53.2','The Entity Reassesses Suppliers When Security Performance or Conditions Change','The Entity Reassesses Suppliers When Security Performance or Conditions Change','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Review supplier security performance at planned, risk-appropriate intervals and after significant changes or relevant incidents. Where service-level agreements exist, examine their implementation reports and related incidents, not only current certificates. Record whether an unscheduled review is needed, assess changed risks and track necessary safeguards or corrective action.", "evidence": "Periodic and event-triggered reviews, service/security reports, change or incident notices and tracked corrective actions.", "risk_text": "Deteriorating supplier safeguards or changed service dependencies go unnoticed, extending exposure to compromise or interruption beyond the originally accepted conditions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["8.1", "A.5.22", "A.8.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (3); CIR Annex 5.1.6-5.1.7.", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','SUP-EXIT-TEST','The Entity Tests Whether Critical Outsourced Services Can Be Transferred (Applies to critical outsourced services where supplier exit requires service or information transfer.)','The Entity Tests Whether Critical Outsourced Services Can Be Transferred (Applies to critical outsourced services where supplier exit requires service or information transfer.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-EXIT · End the relationship securely", "topic_label": "D-EXIT · End the relationship securely", "description": "Before an exit becomes necessary, test the feasible transfer of a critical outsourced service to another provider or an internal environment. Use a risk-appropriate exercise or technical test to verify that required information, configurations and documentation can be obtained and used, and that essential operations can continue. Resolve material barriers and retest when justified by changes. An export button or an exit clause alone is not evidence that transfer works. (Applies to critical outsourced services where supplier exit requires service or information transfer.)", "evidence": "Exit test scope and scenario, usable data/configuration exports, alternative-environment import or processing results where relevant, continuity exercise results, identified barriers and corrective-action records.", "risk_text": "R1: Supplier failure or termination leaves the entity unable to use exported information or rebuild the service elsewhere because portability was never demonstrated.<br>R2: Unrecognised configuration, licence, expertise or integration dependencies prolong a supplier transition beyond the service''s tolerable interruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2)(c), (d), (f), implementation mapping; Grundschutz++ DLS.3.6 (optional portability testing) and DLS.4.1.1 (testing processing independence before decommissioning). Risk-based catalogue practice, not a universal statutory migration-test requirement.", "ref": "Art. 21(2)(c)", "applicability": {"condition": "to critical outsourced services where supplier exit requires service or information transfer", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C52.8','The Entity Retrieves Its Information and Ends Supplier Access When a Contract Ends','The Entity Retrieves Its Information and Ends Supplier Access When a Contract Ends','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-EXIT · End the relationship securely", "topic_label": "D-EXIT · End the relationship securely", "description": "Agree and verify the return or secure disposal of information held by the departing supplier, as appropriate to the contract and applicable requirements. Remove access no longer needed and confirm any service handover so that ending the relationship does not expose data or interrupt operations.", "evidence": "Exit terms, completed handover, information-return/deletion confirmations and verified removal of accounts, credentials and connections.", "risk_text": "R1: A former supplier retains usable access or information and later accesses, alters or discloses organisational data without authority.<br>R2: An incomplete service handover makes information or a dependent service unavailable during supplier exit.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.11", "A.5.20", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(d), (i) CIR Annex 5.1.4(h).", "ref": "Art. 21(2)(d)"}'::jsonb),
  ('NIS2','ENV-RISK','Physical and Environmental Risks Are Assessed','Physical and Environmental Risks Are Assessed','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-RISK · Physical and environmental risk assessment", "topic_label": "I-PHY-RISK · Physical and environmental risk assessment", "description": "Assess current and reasonably foreseeable physical and environmental threats to relevant ICT systems, their locations and supporting utilities. Determine whether climate change is relevant to information security and continuity, considering local flood exposure, extreme heat, storms and related power or cooling disruption. Use location-specific information and relevant interested-party requirements; record the reasoning if climate change is not relevant. Link identified risks to the existing risk register, protection and recovery decisions, and update the assessment when conditions materially change. This is not an emissions or general environmental-impact assessment.", "evidence": "Recorded climate-relevance conclusion; site-specific flood/hazard information and relevant projections, utility/cooling dependency assessment, risk-register links, interested-party requirements where relevant, and review/treatment decisions. Reuse the T03 assessment process rather than demand a separate report.", "risk_text": "R1: Changing flood, heat or storm exposure is overlooked and existing protection becomes inadequate, causing ICT damage, information loss or service interruption.<br>R2: Physical and environmental risks to supporting power, cooling or recovery locations are underestimated, causing simultaneous loss of primary and recovery capability.<br>R3: Physical access, theft or tampering exposure at an ICT location is overlooked, leaving sensitive information and equipment without appropriate protection against unauthorised intervention.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(1), 21(2) opening sentence, (a), (c); Recital 79. ISO/IEC 27001:2022/Amd 1:2024 clause 4.1 climate relevance determination and clause 4.2 interested-party note; Annex A.7.5. ENISA Technical Implementation Guidance, June 2025, 13.2 pp.159-160; CIR Annex 13.2.1 within scope. Specific climate assessment is an implementation mapping, not an expressly named standalone NIS2 duty. CIR-specific requirement within CIR scope: CIR Annex 2.1.2(d); CIR Annex 2.1.2(e); CIR Annex 13.2.1; CIR Annex 13.3.2(a).", "ref": "Art. 21(1)"}'::jsonb),
  ('NIS2','PHY-ZONE','Server and Network Rooms Have Protected Physical Boundaries (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','Server and Network Rooms Have Protected Physical Boundaries (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Define the boundary of each protected server or network area and inspect doors, walls, windows and accessible ceiling/floor routes for ways entry controls could be bypassed. Provide risk-appropriate separation from public, shared or delivery areas. This checks the physical boundary, not individual access permissions. (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)", "evidence": "Protected-area plan, boundary inspection and records of repaired bypass routes.", "risk_text": "R1: An intruder bypasses the controlled door through an inadequately protected boundary and accesses equipment or information.<br>R2: A shared or delivery area provides an uncontrolled route into critical equipment space.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence, (i); ISO/IEC 27001:2022 Annex A.7.1, A.7.3; CIR Annex 13.3.2(a),(c) supports the underlying perimeter duty within its scope. Room-specific techniques are implementation choices. CIR-specific requirement within CIR scope: CIR Annex 13.3.2(a); CIR Annex 13.3.2(b); CIR Annex 13.3.2(c).", "ref": "Art. 21(2)", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C46.1','Physical Access to Protected Areas Is Restricted','Physical Access to Protected Areas Is Restricted','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Allow entry to server rooms, network rooms and other protected areas only for an authorised purpose. Manage keys/cards, periodically review access rights and remove them when no longer needed. Authorise visitors and contractors and supervise them according to risk; prevent entry through unattended doors or uncontrolled delivery routes.", "evidence": "Access approvals and reviews, key/card register, visitor authorisations, observed door controls and records of revoked access. Entry/exit record completeness is assessed under PHY-ENTRY-LOG.", "risk_text": "R1: An unauthorised person enters a protected area and steals, observes or copies sensitive information.<br>R2: Physical tampering with systems or equipment interrupts services or changes their operation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.15", "A.7.1", "A.7.2", "A.7.3"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence; ISO/IEC 27001:2022 Annex A.7.2; CIR Annex 13.3.2(b)-(c), 13.3.3.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','PHY-ENTRY-LOG','Server-Room Access Is Logged and Supported by Video Where Justified (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','Server-Room Access Is Logged and Supported by Video Where Justified (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Record each person''s entry to and exit from protected equipment rooms, including visitors and contractors, with identity, room and sufficiently reliable times. Use individual credentials or an equivalent controlled register. Where camera surveillance is justified, provide usable coverage of relevant access points or equipment areas, check image quality and verify retrieval of recorded footage. Protect logs and footage against unauthorised access or alteration, define justified retention/deletion and investigate incomplete or unexplained records. Limit camera coverage to necessary areas. Entry logging remains applicable even where cameras are not justified; footage does not replace reliable person/room/time traceability or live intrusion response under C46.4. (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)", "evidence": "Person/room/time entry-exit and visitor records; timestamp/completeness checks; where cameras are justified, coverage rationale, image-quality and retrieval tests; protected access/export permissions, justified retention/deletion and investigated discrepancies.", "risk_text": "R1: Unauthorised or unexplained access cannot be attributed to an individual or time because server-room entry and exit records are missing, incomplete or based only on shared credentials.<br>R2: Altered, prematurely deleted or inaccessible access records prevent reliable investigation of physical interference and reconstruction of events.<br>R3: Blind spots, camera failure or unusable images prevent reconstruction of unauthorised access or physical interference where visual evidence is relied upon.<br>R4: Excessive camera coverage or unauthorised access to recordings exposes sensitive information or identifiable individuals unnecessarily.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.2", "A.7.4"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence, (i), implementation mapping; ISO/IEC 27001:2022 Annex A.7.2 and A.7.4; ENISA Technical Implementation Guidance, June 2025, 13.2 p.160 and 13.3 pp.162-163. CIR Annex 13.3 supports scope-dependent physical security and monitoring; universal CCTV and a fixed retention duration are not prescribed. CIR-specific requirement within CIR scope: CIR Annex 3.2.3(i); CIR Annex 3.2.5; CIR Annex 13.3.1; CIR Annex 13.3.2(d).", "ref": "Art. 21(2)", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C46.4','Premises Are Monitored for Unauthorised Physical Access','Premises Are Monitored for Unauthorised Physical Access','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Operate risk-appropriate physical intrusion monitoring for relevant premises, including server-room access points. Route detections to a responder and verify response arrangements, including outside working hours. Guards, intrusion alarms or other suitable arrangements may be used; cameras everywhere are not required.", "evidence": "Monitoring coverage, alarm routing and response records, access to monitoring systems and detection/response tests.", "risk_text": "An intruder remains undetected long enough to steal information or tamper with systems before responsible personnel can respond.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.4"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2) opening sentence, (i); ISO/IEC 27001:2022 Annex A.7.4; CIR Annex 13.3.2(d).", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','PHY-WORK','Secure Working Rules Are Defined and Followed in Server and Network Rooms (Applies where personnel or contractors work in protected equipment areas.)','Secure Working Rules Are Defined and Followed in Server and Network Rooms (Applies where personnel or contractors work in protected equipment areas.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Define and enforce rules for work inside protected equipment rooms: keep security doors closed, supervise contractors where required, restrict photography and recording to authorised purposes, prohibit food, drinks and unrelated storage, keep cooling and escape routes clear, and secure the room after work. These rules govern conduct inside the room; access authorisation and personnel training are assessed separately. (Applies where personnel or contractors work in protected equipment areas.)", "evidence": "Approved working instructions, contractor supervision records, room inspections and observed compliance.", "risk_text": "R1: An authorised worker exposes information or enables unauthorised entry by disregarding secure-area working rules.<br>R2: Unsafe work or materials left in the room obstruct cooling or damage live equipment and interrupt services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.6"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (i); ISO/IEC 27001:2022 Annex A.7.6; risk-based implementation, not a separately named Directive duty.", "ref": "Art. 21(2)", "applicability": {"condition": "where personnel or contractors work in protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','TRN-PHY','Relevant Personnel Receive Physical Security Training (Applies to personnel whose duties involve protected equipment areas.)','Relevant Personnel Receive Physical Security Training (Applies to personnel whose duties involve protected equipment areas.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Before relevant work, instruct staff and contractors on applicable access, working and emergency rules, including whom to alert about intrusion, smoke, leaks or failed cooling and what actions they are authorised to take. Refresh instruction when needed and verify understanding. General training governance stays in T06. (Applies to personnel whose duties involve protected equipment areas.)", "evidence": "Role-appropriate instructions, induction/refresher records and practical checks or exercises showing understood reporting and action boundaries.", "risk_text": "R1: Personnel fail to report a physical or environmental warning promptly, allowing damage or interruption to escalate.<br>R2: Untrained personnel respond outside their competence or bypass room safeguards, causing avoidable exposure or outage.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.7.6"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (g), (i); ISO/IEC 27001:2022 Annex A.6.3, A.7.6; topic-specific training implementation.", "ref": "Art. 21(2)", "applicability": {"condition": "to personnel whose duties involve protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','PHY-ACCESS-TEST','Physical Access Controls Are Tested for Effectiveness (Applies to physical entry controls operated by the entity.)','Physical Access Controls Are Tested for Effectiveness (Applies to physical entry controls operated by the entity.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Test physical entry controls at planned intervals and after relevant significant incidents or changes. Use authorised, risk-appropriate scenarios to verify that unauthorised or revoked credentials are rejected and that bypass routes or entry behind an authorised person are prevented or detected as intended. Record deficiencies and verify corrective action. Access-right reviews alone do not demonstrate that entry controls work. Coordinate tests to protect people and service availability; covert penetration testing is not universally required. (Applies to physical entry controls operated by the entity.)", "evidence": "Approved test scope and scenarios, denied-entry/bypass test results, identified defects, assigned corrective actions and retest evidence.", "risk_text": "R1: Defective entry controls allow an unauthorised person to reach protected systems despite apparently correct access permissions.<br>R2: Untested changes leave bypass routes undetected, exposing equipment or information to theft or interference.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.2"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence, (f), (i); CIR Annex 13.3.3 within scope; ENISA Technical Implementation Guidance, June 2025, 13.3.3 p.162; Grundschutz++ GEB.3.7; ISO/IEC 27001:2022 Annex A.7.2 implementation mapping.", "ref": "Art. 21(2)", "applicability": {"condition": "to physical entry controls operated by the entity", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','PHY-SITING','Servers and Network Equipment Are Securely Positioned and Protected (Applies where the entity controls the physical installation of ICT equipment.)','Servers and Network Equipment Are Securely Positioned and Protected (Applies where the entity controls the physical installation of ICT equipment.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-EQUIP · Equipment protection and tamper checks", "topic_label": "I-PHY-EQUIP · Equipment protection and tamper checks", "description": "Position and secure equipment and racks to prevent accidental damage, unauthorised handling and blocked airflow. Consider local leak sources, falling objects and access to consoles or removable components; protect shared racks where needed. This checks equipment placement and protection, not the room''s general fire or intrusion safeguards. (Applies where the entity controls the physical installation of ICT equipment.)", "evidence": "Equipment/rack layout, physical inspection, installation requirements and corrected placement/protection defects.", "risk_text": "R1: Poor equipment placement or obstructed airflow causes overheating, damage or a service outage.<br>R2: Exposed consoles, components or unsecured equipment allow unauthorised observation, removal or manipulation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.3", "A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (e), (i); ISO/IEC 27001:2022 Annex A.7.8; risk-based physical-environment implementation.", "ref": "Art. 21(2)", "applicability": {"condition": "where the entity controls the physical installation of ICT equipment", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','PHY-TAMPER-CHECK','Exposed ICT Equipment Is Checked for Physical Tampering (Applies where the entity controls equipment subject to material physical tampering risk.)','Exposed ICT Equipment Is Checked for Physical Tampering (Applies where the entity controls equipment subject to material physical tampering risk.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-EQUIP · Equipment protection and tamper checks", "topic_label": "I-PHY-EQUIP · Equipment protection and tamper checks", "description": "Identify equipment with material physical tampering exposure and define risk-based inspection intervals and triggers. Inspect relevant enclosures, components and connections for unexplained changes or signs of interference, using seals or recorded baselines where appropriate. Record results and route suspected tampering through incident response while preserving relevant evidence. This checks equipment during operation, not only after maintenance, and does not require routine inspection of every device. (Applies where the entity controls equipment subject to material physical tampering risk.)", "evidence": "Risk-based equipment scope, inspection intervals and triggers, baseline or seal records where used, completed inspection records and investigated discrepancies.", "risk_text": "R1: An unauthorised physical modification remains unnoticed and enables information theft or changes to system operation.<br>R2: Unexplained component or connection changes remain undetected until they disrupt a critical service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (b), (i), risk-based implementation; Grundschutz++ DET.4.9 and GEB.5.2 describe optional risk-dependent practices; ISO/IEC 27001:2022 Annex A.7.8 topic mapping. No universal inspection interval or device-sealing obligation is inferred.", "ref": "Art. 21(2)", "applicability": {"condition": "where the entity controls equipment subject to material physical tampering risk", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C46.2','Protective Measures Address Physical and Environmental Hazards','Protective Measures Address Physical and Environmental Hazards','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Use the documented physical and environmental risk assessment (ENV-RISK) to apply suitable protection to server and network rooms, such as fire detection and suitable suppression, leak protection and avoidance of hazardous storage where the assessment requires them. Normal temperature and humidity control is assessed under PHY-CLIMATE. No particular suppression technology or building design is universally prescribed. Review and test relevant measures regularly and after significant incidents or changes.", "evidence": "Site hazard assessment, implemented fire/water protection, inspection and test records and corrective actions.", "risk_text": "R1: Fire, water, heat or another material site-specific hazard damages equipment or media and interrupts the supported services.<br>R2: A site-specific hazard destroys or irreversibly damages stored information, leaving required records unavailable even after systems and premises are restored.<br>R3: Fire or extreme environmental conditions injure personnel or make the premises unsafe to occupy, preventing safe operation or incident response.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.3", "A.7.5", "A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence; ISO/IEC 27001:2022 Annex A.7.5; CIR Annex 13.2.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','C46.3','Supporting Utilities Meet Service Resilience Requirements','Supporting Utilities Meet Service Resilience Requirements','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Provide power and connectivity arrangements capable of meeting the required service resilience, and assess continuity arrangements for cooling. Actual temperature and humidity control is assessed under PHY-CLIMATE. Determine the need and capacity for uninterruptible power supplies (UPS), alternative power, cooling redundancy and emergency fuel or support from assessed interruption tolerances; no generator is required for every room.", "evidence": "Utility dependency and capacity assessment, installed safeguards and runtime calculations, emergency supply arrangements where needed.", "risk_text": "R1: Loss of power, cooling or communications disables dependent systems or premises for longer than the service can tolerate.<br>R2: An abrupt loss of power corrupts in-progress writes or loses uncommitted data, requiring data reconstruction even when service is restored quickly.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence; ISO/IEC 27001:2022 Annex A.7.11; CIR Annex 13.1.1-13.1.2.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','PHY-CLIMATE','Server and Network Rooms Maintain Suitable Temperature and Humidity (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)','Server and Network Rooms Maintain Suitable Temperature and Humidity (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Keep equipment within justified operating temperature and humidity ranges using appropriately sized cooling, ventilation or other suitable environmental controls. Account for heat load, airflow and foreseeable hot-weather conditions; verify actual conditions at representative equipment locations. Assess cooling failure and redundancy needs through utility resilience (C46.3); alarm escalation remains under C46.5 and maintenance under C46.6. A dedicated air-conditioning unit is not mandatory where another effective method maintains the required conditions. (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)", "evidence": "Equipment environmental requirements, justified operating ranges, heat-load/cooling capacity assessment and representative temperature/humidity readings demonstrating effective environmental control.", "risk_text": "R1: Inadequate cooling or airflow causes overheating, equipment throttling, damage or service shutdown.<br>R2: Unsuitable humidity permits condensation or electrostatic effects that damage equipment and impair reliable operation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5", "A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2), opening sentence, (c), (e), implementation mapping; ISO/IEC 27001:2022 Annex A.7.8 and A.7.11; ENISA Technical Implementation Guidance, June 2025, 13.1 p.158 and 13.2 p.160. CIR Annex 13.1.2(f), 13.2.2 provide relevant scope-dependent requirements; no universal temperature setpoint or cooling product is prescribed. CIR-specific requirement within CIR scope: CIR Annex 13.1.1; CIR Annex 13.1.2(f); CIR Annex 13.2.2(a); CIR Annex 13.2.2(b); CIR Annex 13.2.2(c).", "ref": "Art. 21(2)", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable equipment environments", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C46.7','Power and Telecommunications Infrastructure Is Protected','Power and Telecommunications Infrastructure Is Protected','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Protect relevant power and communications routes, distribution points and patch panels against damage or unauthorised interference. Address interception of communications and electrical interference through suitable routing, separation, enclosures and access restrictions; identify cables sufficiently for safe work.", "evidence": "Cable-route and distribution plans, inspections of protective measures, labelling and controlled access to distribution points.", "risk_text": "R1: Damage or tampering to power or telecommunications infrastructure interrupts dependent services.<br>R2: Interception of exposed telecommunications infrastructure discloses sensitive communications.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.12"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2) opening sentence, (i); ISO/IEC 27001:2022 Annex A.7.12; CIR Annex 13.1.2(c).", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','C46.6','Supporting Utilities and Emergency Supplies Are Maintained and Tested','Supporting Utilities and Emergency Supplies Are Maintained and Tested','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "Maintain and test the power, cooling, communications and emergency arrangements needed for the service. Check relevant UPS batteries, transfer arrangements and other installed safeguards under controlled conditions, and correct failures. Distinguish this supporting-infrastructure work from server and network hardware maintenance.", "evidence": "Maintenance schedules, service reports, controlled load/failover tests where appropriate and resolved defects.", "risk_text": "A degraded utility safeguard or emergency supply fails when demanded, causing an avoidable outage despite nominal backup capacity.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2) opening sentence, (c); ISO/IEC 27001:2022 Annex A.7.11; CIR Annex 13.1.2(f), 13.1.3.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','PHY-MAINT','Server and Network Hardware Is Maintained by Authorised Personnel','Server and Network Hardware Is Maintained by Authorised Personnel','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "Schedule and perform risk-appropriate hardware maintenance using manufacturer guidance and operational needs. Authorise technicians and record the work and defects. Apply existing change and access controls to disruptive or remote work. This covers hardware servicing, not software patching or maintenance of building utilities.", "evidence": "Hardware maintenance schedule, technician authorisations, service reports and defect follow-up linked to relevant assets.", "risk_text": "R1: Unmaintained hardware degrades or fails and interrupts the supported service.<br>R2: Unauthorised or uncontrolled servicing exposes information or alters critical equipment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (c), (e); ISO/IEC 27001:2022 Annex A.7.13; risk-based implementation.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','PHY-RETURN','Maintained or Repaired Equipment Is Checked Before Return to Service','Maintained or Repaired Equipment Is Checked Before Return to Service','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "After hardware maintenance or repair, verify correct operation and that relevant security settings and physical protections remain effective before releasing equipment for operational use. Check for unexpected changes and remove temporary service access where used. This checks the post-maintenance result, not the maintenance activity or initial procurement acceptance.", "evidence": "Post-maintenance checks, relevant setting/component comparison, temporary-access closure and release record.", "risk_text": "R1: Equipment returns to service with altered security settings or residual service access, enabling unauthorised use.<br>R2: An undetected repair defect causes renewed failure or unreliable operation after release.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.13"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H", "nis2_basis": "NIS2 Article 21(2), opening sentence, (e), (f); ISO/IEC 27001:2022 Annex A.7.13; risk-based implementation linked to maintenance and effectiveness.", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','C46.5','Environmental and Utility Deviations Trigger Alerts to Responsible Personnel','Environmental and Utility Deviations Trigger Alerts to Responsible Personnel','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ALERT · Environmental and utility alerting", "topic_label": "I-PHY-ALERT · Environmental and utility alerting", "description": "Define justified thresholds for relevant conditions such as temperature, humidity and power status. Monitor them and route deviations to personnel able to act, including outside working hours. Test that the alert reaches its recipient; a sensor display without effective escalation is insufficient.", "evidence": "Approved thresholds, sensor/alarm configuration, monitoring history and alert-delivery and response tests.", "risk_text": "An environmental or utility deviation goes unnoticed or reaches no responder, escalating into equipment damage or service interruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5", "A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2) opening sentence, (c); ISO/IEC 27001:2022 Annex A.7.5, A.7.11; CIR Annex 13.1.2(d), 13.2.2(b)-(c).", "ref": "Art. 21(2)"}'::jsonb),
  ('NIS2','C37.1','Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners','Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners. Specify which measures will be evaluated, how valid results will be obtained, when assessment and analysis occur, and who performs them. Base the programme on assessed risks and relevant incident experience, and record usable criteria for interpreting the results.", "evidence": "Examples: an assessment programme or equivalent records identifying measures in scope, methods for valid results, assessment/analysis timing, responsible persons and interpretation criteria, linked to assessed risks and relevant incident experience.", "risk_text": "Assessments measure activity rather than protective outcomes or use inconsistent criteria, producing false assurance and misdirected improvement priorities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R · CIR D", "nis2_basis": "NIS2 Article 21(2)(f); CIR Annex 7.1-7.3.", "ref": "Art. 21(2)(f)"}'::jsonb),
  ('NIS2','C37.5','Operational Systems Undergo Risk-Based Technical Security Testing','Operational Systems Undergo Risk-Based Technical Security Testing','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Operational Systems Undergo Risk-Based Technical Security Testing. Test the technical security of systems already in use, including acquired applications and infrastructure, against relevant attack paths such as unauthorised access, privilege escalation or movement between network segments. Define the scope, methods and frequency according to risk; authorise testing and protect service availability and data. Document findings and track remediation. This is distinct from pre-release development tests, monitoring-detection checks and physical entry tests; existing results may be reused where they demonstrate the required operational coverage.", "evidence": "Risk-based test scope and schedule; authorisation and operational safety arrangements; reports identifying tested systems, methods and findings; remediation records. Testing does not require uncontrolled exploitation of live systems or a specific commercial testing product.", "risk_text": "R1: Untested operational attack paths remain exploitable and are falsely assumed to be protected.<br>R2: Poorly controlled security tests disrupt operational services or damage data.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.34"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(e), (f) CIR-specific requirement within CIR scope: CIR Annex 6.5.1; CIR Annex 6.5.2(a); CIR Annex 6.5.2(b); CIR Annex 6.5.2(c); CIR Annex 6.5.2(d).", "ref": "Art. 21(2)(e)"}'::jsonb),
  ('NIS2','C37.2','Security Effectiveness Assessments Are Performed and Reviewed','Security Effectiveness Assessments Are Performed and Reviewed','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Carry out the planned effectiveness assessments and review the underlying results against the intended protective outcomes. A completed test record without examination and interpretation of its results does not establish that the organisation assessed whether the security measures actually work.", "evidence": "Examples: completed effectiveness assessments with underlying results and evidence of review and interpretation against the intended protective outcomes.", "risk_text": "Ineffective safeguards remain relied upon because their operation and results are not examined, allowing known types of incident to recur.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(2)(f)", "ref": "Art. 21(2)(f)"}'::jsonb),
  ('NIS2','C37.3','Security Compliance Is Monitored and Reported to Management','Security Compliance Is Monitored and Reported to Management','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Monitor actual compliance with applicable security policies, rules and standards, and report the findings and relevant deviations to the management body. Retain the link between monitoring results and the information reported; a management summary unsupported by monitoring, or findings never reported, does not demonstrate the complete process.", "evidence": "Examples: monitoring results against applicable internal security policies, rules and standards, with evidence that the findings and relevant deviations were reported to the management body.", "risk_text": "Routine departures from security rules persist without management visibility, leaving unsafe practices uncorrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 20(1); 21(2)(a), (f) CIR-specific requirement within CIR scope: CIR Annex 2.2.1; CIR Annex 2.2.2; CIR Annex 2.2.3.", "ref": "Art. 20(1)"}'::jsonb),
  ('NIS2','C37.4','Competent, Impartial Reviews Assess Security Management and Implementation','Competent, Impartial Reviews Assess Security Management and Implementation','false','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Competent, Impartial Reviews Assess Security Management and Its Implementation. Review people, processes and technology at planned intervals and after significant incidents or significant operational or risk changes where CIR applies. Ensure appropriate audit competence and independence from the area reviewed, or documented alternative safeguards for impartiality where size prevents separation. Report results to management and route findings to correction or authorised risk treatment.", "evidence": "Examples: completed reviews covering security-management people, processes and technology, with planned/event-driven timing, reviewer competence and independence or documented alternative impartiality safeguards where size prevents separation. Include management reporting and routing of findings to correction or authorised treatment, checking significant incident/change triggers where CIR applies.", "risk_text": "A biased or unqualified review overlooks weaknesses or reports an inaccurate security posture, leading to inappropriate corrective decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.2.1", "A.5.35"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "H · CIR D", "nis2_basis": "NIS2 Article 21(2)(a), (f); CIR Annex 2.3.1-2.3.4. ENISA''s annual review guidance is not presented as a universal statutory frequency.", "ref": "Art. 21(2)(a)"}'::jsonb),
  ('NIS2','C47.1','Security Measure Deficiencies Receive Corrective Action Without Undue Delay','Security Measure Deficiencies Receive Corrective Action Without Undue Delay','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-FIX · Corrective actions", "topic_label": "F-FIX · Corrective actions", "description": "Take appropriate corrective action on identified security-measure deficiencies without undue delay, with dates and progress traceable to the identified weakness. Examine actual action and the justification for any continuing delay in light of the risk; merely opening a ticket or listing a future action does not demonstrate timely correction.", "evidence": "Examples: identified measure deficiencies linked to correction decisions and actual actions, with dates, progress and delay explanations sufficient to assess whether appropriate correction occurred without undue delay.", "risk_text": "An identified protection weakness remains active while correction is delayed, allowing the same failure or attack path to recur.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["10.2", "A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(4)", "ref": "Art. 21(4)"}'::jsonb),
  ('NIS2','C47.2','Corrective-Action Completion and Effectiveness Are Verified','Corrective-Action Completion and Effectiveness Are Verified','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-FIX · Corrective actions", "topic_label": "F-FIX · Corrective actions", "description": "Before closing a corrective action, verify both that the agreed change was implemented and that it resolved the identified weakness; a completed task or ticket alone does not establish effectiveness.", "evidence": "Examples: verification of completed corrective actions and relevant follow-up results showing whether the identified weakness was resolved, with closure or further-action decisions where applicable.", "risk_text": "A corrective action is closed despite not removing the underlying weakness, creating false assurance and allowing recurrence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2", "A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "ISO27001", "nis2_binding": "R", "nis2_basis": "NIS2 Article 21(4)", "ref": "Art. 21(4)"}'::jsonb),
  ('NIS2','C28.2','Applicable European Cybersecurity Certification Requirements Are Met (Applies only where an operative legal requirement under NIS2 Article 24 requires such certification; it is not a universal ISO 27001 or generic NIS2-certificate requirement.)','Applicable European Cybersecurity Certification Requirements Are Met (Applies only where an operative legal requirement under NIS2 Article 24 requires such certification; it is not a universal ISO 27001 or generic NIS2-certificate requirement.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-CERT · Applicable certification requirements", "topic_label": "F-CERT · Applicable certification requirements", "description": "Applicable European Cybersecurity Certification Requirements Are Met. Verify the required scheme, certified scope, validity and assurance level for the relevant products, services, processes or entity. (Applies only where an operative legal requirement under NIS2 Article 24 requires such certification; it is not a universal ISO 27001 or generic NIS2-certificate requirement.)", "evidence": "Where an operative certification requirement applies, examples include the applicability decision and certification evidence showing the required European scheme, covered product/service/process/entity, validity and assurance level. If no operative requirement applies, substantiate that scope conclusion rather than demanding a certificate.", "risk_text": "A product, service, process or entity is relied upon without meeting an operative certification requirement, leading to compliance challenge and potentially disruptive replacement or restricted use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 24(1)-(2), conditional on an operative applicable certification requirement.", "ref": "Art. 24(1)", "applicability": {"condition": "only where an operative legal requirement under NIS2 Article 24 requires such certification; it is not a universal ISO 27001 or generic NIS2-certificate requirement", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C69.1','Required Implementation Evidence Is Provided Accurately to the Competent Authority','Required Implementation Evidence Is Provided Accurately to the Competent Authority','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "O-EVD · Evidence and supervisory cooperation", "topic_label": "O-EVD · Evidence and supervisory cooperation", "description": "Where the competent authority requests implementation evidence, provide an accurate and sufficient response for the requested scope, traceable to underlying records and actual transmission. An unsupported assertion of compliance is not a substitute for requested evidence. If no request occurred, record that context rather than inventing a submission. (Applies where such a request has been made.)", "evidence": "Where implementation evidence has been requested, examples include the competent authority''s request and the submitted response, mapped to source records and required scope to demonstrate accuracy and sufficiency, with transmission evidence. If no request occurred, record that context rather than inventing a submission.", "risk_text": "Incomplete or inaccurate evidence prevents the authority from assessing implementation reliably, leading to additional enquiries or corrective supervisory action.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 32(2)(g), 33(2)(f)", "ref": "Art. 32(2)(g)"}'::jsonb),
  ('NIS2','C69.2','Lawful Supervisory Inspections and Requests Are Supported (Applies where a competent authority conducts supervision or issues a lawful request.)','Lawful Supervisory Inspections and Requests Are Supported (Applies where a competent authority conducts supervision or issues a lawful request.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "O-EVD · Evidence and supervisory cooperation", "topic_label": "O-EVD · Evidence and supervisory cooperation", "description": "Provide the cooperation and access required for lawful supervisory inspections, audits, security scans and information or document requests, including cooperation with an appointed monitoring officer where applicable. Assess the request actually made and the entity''s response. Complete obstruction of requested lawful supervision supports the Absent Major default; an isolated administrative lapse with effective cooperation is not the same failure. No applicable supervisory action or request means not applicable, not an automatic pass. Unknown applicability requires scope review, not a Minor finding.", "evidence": "Where lawful supervision occurs, examples include the inspection, audit, scan or information/access request and coordination or access records showing that the entity supported the authorised activity within its scope. If none occurred, inspect relevant arrangements without claiming demonstrated cooperation with a nonexistent event.", "risk_text": "Obstructed lawful supervisory access delays identification or verification of weaknesses and exposes the entity to escalation of enforcement.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 32(2)(a)-(f), 32(4)(g), 33(2)(a)-(e); serious-infringement context: Article 32(7)(a)(iv), applied to important entities through Article 33(5). Cooperation with the monitoring officer is assessed here; compliance with corrective orders is assessed under C72.1.", "ref": "Art. 32(2)(a)", "applicability": {"condition": "where a competent authority conducts supervision or issues a lawful request", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C69.3','Targeted Security Audit Results Are Available to the Competent Authority (Applies where such a supervisory audit is conducted.)','Targeted Security Audit Results Are Available to the Competent Authority (Applies where such a supervisory audit is conducted.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "O-EVD · Evidence and supervisory cooperation", "topic_label": "O-EVD · Evidence and supervisory cooperation", "description": "Targeted Security Audit Results Are Made Available to the Competent Authority. Where a targeted security audit is conducted under NIS2 supervisory powers by the competent authority or an independent body, ensure that its results are made available to that authority. Such an audit focuses on risks identified through assessments by the authority or the entity, or other available risk information. This control checks availability of the audit results, not general cooperation with the audit or a routine internal audit. (Applies where such a supervisory audit is conducted.)", "evidence": "Documentation identifying the supervisory audit and its scope; the resulting audit report; transmission, acknowledgement or other evidence that the competent authority has access to the results. Where the authority conducts the audit itself, do not demand a redundant submission of a report it already holds.", "risk_text": "The authority cannot evaluate targeted-audit findings or follow up identified weaknesses because the audit results are not made available as required.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Articles 32(2)(b) and 33(2)(b), together with the final two subparagraphs of each paragraph on the risk basis and availability of targeted-audit results; Article 33(1) governs the trigger for supervision of important entities.", "ref": "Art. 32(2)(b)", "applicability": {"condition": "where such a supervisory audit is conducted", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C72.1','Binding Supervisory Instructions Are Fulfilled Within Their Scope and Deadlines (Applies where an operative binding instruction has been issued to the entity.)','Binding Supervisory Instructions Are Fulfilled Within Their Scope and Deadlines (Applies where an operative binding instruction has been issued to the entity.)','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "O-ORD · Binding supervisory instructions", "topic_label": "O-ORD · Binding supervisory instructions", "description": "Identify the operative instruction, required action, scope and deadline. Implement the required action and retain evidence of completion and any required communication to the competent authority. The Absent Major default concerns complete non-fulfilment of an applicable instruction when due. A minor administrative omission despite effective protective action is assessed by its actual extent; Partial may still warrant escalation. If no instruction exists, mark not applicable. Before a deadline expires, assess compliance with obligations already due rather than treating future completion as overdue. Article 32(5) enforcement is subject to its own conditions and is not an automatic consequence or an automatic ISO audit grade.", "evidence": "Where binding instructions exist, examples include the instruction and applicable scope/deadlines compared with dated implementation records and supporting outcomes. Where none exist, substantiate that context rather than inventing an order or treating it as proof of compliance with other controls.", "risk_text": "A binding supervisory instruction is not fulfilled in scope or on time, prolonging the identified infringement and triggering further enforcement consideration.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 32(4)(b)-(f), 32(5), 33(4)(b)-(f); serious-infringement context: Article 32(7)(a)(iii), applied to important entities through Article 33(5).", "ref": "Art. 32(4)(b)", "applicability": {"condition": "where an operative binding instruction has been issued to the entity", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('NIS2','C72.2','Ordered Public Disclosure of Infringements Follows the Specified Manner','Ordered Public Disclosure of Infringements Follows the Specified Manner','true','NIS2-268-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "O-ORD · Binding supervisory instructions", "topic_label": "O-ORD · Binding supervisory instructions", "description": "Where the competent authority has ordered public disclosure of an infringement, publish the required information in the manner and within any timing specified in that order; without such an order, this control does not require publication.", "evidence": "Where public disclosure has been ordered, examples include the order and a dated public publication or equivalent evidence showing the specified content, manner and applicable timing were followed. If no disclosure was ordered, establish that condition rather than demanding publication.", "risk_text": "Required public disclosure of an infringement is incomplete or delayed, leaving affected parties uninformed and prompting further supervisory follow-up.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": [], "source": "iso27001-nis2-v7", "nis2_binding": "R", "nis2_basis": "NIS2 Article 32(4)(h); 33(4)(g)", "ref": "Art. 32(4)(h)"}'::jsonb)
INSERT INTO public.controls (framework,id,req_de,req_en,muss,source,meta) VALUES
  ('ISO27001','ISO-CONTEXT','Internal and External Issues Affecting the ISMS Are Determined','Internal and External Issues Affecting the ISMS Are Determined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify the organisational, commercial, legal, technological and external conditions that can affect information security management. Keep the assessment useful when circumstances change; a named framework or separate SWOT document is not required.", "evidence": "Context assessment; relevant changes; links to scope and planning decisions.", "risk_text": "Material business or external conditions are overlooked, so the ISMS protects the wrong priorities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["4.1"], "source": "iso27001-nis2-v7", "annex": "4.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-PARTIES-ID','Relevant ISMS Interested Parties Are Identified','Relevant ISMS Interested Parties Are Identified','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify the parties whose needs or obligations can affect the ISMS, including relevant internal and external parties. Explain their relevance; deciding which requirements the ISMS addresses is assessed separately.", "evidence": "Interested-party record with relevance and scope; reconciliation with key business relationships and internal responsibilities.", "risk_text": "A relevant party is overlooked and its information security expectations never enter ISMS planning.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["4.2"], "source": "iso27001-nis2-v7", "annex": "4.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-PARTIES-REQUIREMENTS','Relevant Party Requirements Have an ISMS Treatment Decision','Relevant Party Requirements Have an ISMS Treatment Decision','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine relevant requirements of the identified parties and which the ISMS will address. Link mandatory legal and contractual obligations to the existing requirements register; do not treat all preferences as mandatory.", "evidence": "Party-to-requirement links and documented treatment decisions, including applicable obligations and the reasons for scope choices.", "risk_text": "Identified stakeholders remain a name list while binding or important requirements are omitted from the ISMS.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["4.2"], "source": "iso27001-nis2-v7", "annex": "4.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-CLIMATE','Climate Change Relevance to the ISMS Is Determined','Climate Change Relevance to the ISMS Is Determined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine whether climate change affects intended ISMS results and consider relevant interested-party requirements. Reuse site and supplier assessments, but also consider changes in operations, dependencies and contractual expectations. Record a reasoned conclusion, including non-relevance where justified; this is not a carbon-reduction programme.", "evidence": "Climate relevance conclusion and rationale; relevant interested-party requirements; links to ENV-RISK and supplier assessments.", "risk_text": "Climate-related changes invalidate security or continuity assumptions and relevant requirements are missed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["4.1", "4.2"], "source": "iso27001-nis2-v7", "annex": "4.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-SCOPE','The ISMS Scope and Its Boundaries Are Documented','The ISMS Scope and Its Boundaries Are Documented','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define the organisational units, activities, locations, information, interfaces and external dependencies within the ISMS. Consider context and interested-party requirements. Distinguish this scope from the legal NIS2 entity boundary and identify any difference explicitly.", "evidence": "Approved scope statement; interfaces and dependency records; reconciliation with the NIS2 scope where both frameworks apply.", "risk_text": "Relevant information or interfaces fall outside security management while a broader certification claim is made.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["4.3"], "source": "iso27001-nis2-v7", "annex": "4.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-LEGAL-REQUIREMENTS','Applicable Information Security Obligations Are Identified and Kept Current','Applicable Information Security Obligations Are Identified and Kept Current','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Maintain applicable legal, regulatory, statutory and contractual information security obligations with responsible owners and how they are met. Record relevant recipients and deadlines; reuse existing NIS2 controls instead of creating duplicate reporting duties.", "evidence": "Current requirements register with applicability, sources, owners, recipients/deadlines where relevant and links to controls.", "risk_text": "A binding or contractual obligation is missed, outdated or applied to the wrong scope.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.31"], "source": "iso27001-nis2-v7", "annex": "A.5.31", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-LEGAL-COMPLIANCE','Implementation of Applicable Security Obligations Is Checked','Implementation of Applicable Security Obligations Is Checked','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Check that the organisation actually meets the identified security obligations and address gaps. Reuse assessments of the underlying controls; this evaluates obligation coverage rather than requesting a second implementation answer.", "evidence": "Obligation-to-evidence review, identified gaps and corrective decisions using existing assessment results.", "risk_text": "A complete legal register creates false assurance although its obligations are not implemented.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.31", "A.5.36"], "source": "iso27001-nis2-v7", "annex": "A.5.31", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-AUTHORITY-CONTACTS','Relevant Authority Contacts and Contact Arrangements Are Maintained','Relevant Authority Contacts and Contact Arrangements Are Maintained','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T01", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Maintain the relevant authority contacts and circumstances for contact, including security incidents and other applicable obligations. Reuse the NIS2 notification route where appropriate; this control does not impose routine intelligence sharing or contact with every authority.", "evidence": "Contact directory; contact responsibilities and triggers; currency checks and applicable communication records.", "risk_text": "The organisation cannot obtain authority assistance or reach the proper recipient when required.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.5"], "source": "iso27001-nis2-v7", "annex": "A.5.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-PROCESS-DESIGN','ISMS Processes and Their Operating Criteria Are Defined','ISMS Processes and Their Operating Criteria Are Defined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define the interacting ISMS processes, owners, interfaces and criteria needed to deliver planned security outcomes. Include how relevant externally provided processes are controlled, using existing supplier records.", "evidence": "Process descriptions or equivalent workflow definitions, interfaces, owners and operating criteria; links to supplier controls.", "risk_text": "ISMS activities lack agreed operating criteria and responsibilities fail at process interfaces.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["4.4", "8.1"], "source": "iso27001-nis2-v7", "annex": "4.4", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-PROCESS-OPERATION','ISMS Processes Operate as Planned within Business Activities','ISMS Processes Operate as Planned within Business Activities','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Demonstrate actual operation of the defined ISMS processes in relevant business activities. Retain enough records to establish planned execution and control of relevant externally provided processes; reuse supplier reviews rather than repeat them.", "evidence": "Recent process execution records and business decisions compared with the defined criteria; existing outsourcing oversight records.", "risk_text": "The ISMS has documented procedures but they are bypassed in actual business operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["4.4", "5.1", "8.1"], "source": "iso27001-nis2-v7", "annex": "4.4", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-LEADERSHIP-ALIGNMENT','Top Management Aligns Security Policy and Objectives with Strategy','Top Management Aligns Security Policy and Objectives with Strategy','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Top management ensures the security policy and objectives are compatible with organisational strategic direction. Reuse policy and objective records; this tests strategic alignment, not a second policy approval.", "evidence": "Management decisions linking strategy, policy and security objectives, including resolution of conflicting priorities.", "risk_text": "Security objectives conflict with business strategy and are bypassed in material decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.1"], "source": "iso27001-nis2-v7", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-LEADERSHIP-SUPPORT','Top Management Communicates and Supports Effective ISMS Operation','Top Management Communicates and Supports Effective ISMS Operation','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Top management communicates the importance of effective information security and meeting ISMS requirements and supports people and relevant managers in contributing to intended results and improvement. Resource sufficiency remains C22.2.", "evidence": "Leadership communications and demonstrable support for accountable managers, barriers and improvement decisions.", "risk_text": "Formal roles exist but people cannot implement the ISMS without active management support.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.1"], "source": "iso27001-nis2-v7", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C22.1','Management Approves Current Cybersecurity Risk-Management Measures','Management Approves Current Cybersecurity Risk-Management Measures','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "The management body''s approval identifies the cybersecurity risk-management measures currently in force, so an auditor can distinguish an authorised version or scope from a draft or an operational team''s unapproved proposal.", "evidence": "Examples: the current cybersecurity risk-management measures linked to a dated management approval identifying the approved version or scope, whether recorded in a decision, workflow or equivalent record.", "risk_text": "Security measures are contested or bypassed because management has not endorsed their priorities and authority, delaying implementation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "5.2", "A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C22.2','Security Responsibilities Have Sufficient Staff, Funding and Tools','Security Responsibilities Have Sufficient Staff, Funding and Tools','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Compare assigned security work with the staff time, funding and usable tools available to perform it; an approved responsibility is not adequately resourced if essential tasks cannot be carried out.", "evidence": "Examples: assigned security work compared with available staff time, funding and usable tools, supported by allocations and operating records. Include identified resource shortfalls and their handling where relevant.", "risk_text": "Approved measures do not operate because people, time, funding or tools are missing, leaving risks untreated.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "7.1", "A.5.4"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-OBJECTIVES-DEFINED','Information Security Objectives Are Defined and Communicated','Information Security Objectives Are Defined and Communicated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Establish documented information security objectives at relevant functions and levels, consistent with the policy and relevant requirements and risk results. Make them measurable where practicable and communicate them to those who must act.", "evidence": "Current objectives, their policy/risk links and measurement rationale, with relevant communication records.", "risk_text": "The organisation lacks a clear and shared definition of the security results it intends to achieve.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.2"], "source": "iso27001-nis2-v7", "annex": "6.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-OBJECTIVE-PLANS','Security Objectives Have Resourced Delivery Plans','Security Objectives Have Resourced Delivery Plans','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "For each objective, determine actions, required resources, responsible owners, completion timing and how results will be evaluated. Reuse existing delivery plans where these elements are identifiable.", "evidence": "Objective-to-action plans with resources, owners, dates and evaluation arrangements.", "risk_text": "Security objectives remain aspirations because nobody has an executable plan for achieving them.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.2"], "source": "iso27001-nis2-v7", "annex": "6.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-OBJECTIVE-REVIEW','Security Objectives Are Monitored and Updated','Security Objectives Are Monitored and Updated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Monitor progress and results against the objectives and update them when appropriate. This tests objective-level performance, not whether individual technical safeguards pass their tests.", "evidence": "Objective progress/results, evaluation against the intended outcome and justified update decisions.", "risk_text": "Missed or obsolete objectives continue to drive decisions without management recognising the gap.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.2", "9.1"], "source": "iso27001-nis2-v7", "annex": "6.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C27.3','Conflicting Duties Are Segregated Where Applicable','Conflicting Duties Are Segregated Where Applicable','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Identify conflicting duties and compare their assigned responsibilities with actual permissions and operations to verify applicable segregation. A written separation rule is insufficient if one person can still initiate, approve and conceal the same action. Any alternative arrangement must be justified against the applicable requirement; independent oversight is not an automatic waiver of required segregation.", "evidence": "Examples: identified conflicting duties compared with actual responsibilities, permissions and sampled transactions showing applicable separation. Where an alternative arrangement is relied on, examine its justification and effective independent scrutiny against the applicable requirement.", "risk_text": "A person can initiate, approve and conceal an improper action without effective independent scrutiny.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C27.2','Security Reporting Reaches the Management Body Effectively (For CIR-covered entities, at least one person reports directly to the management body.)','Security Reporting Reaches the Management Body Effectively (For CIR-covered entities, at least one person reports directly to the management body.)','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Security findings, resource needs and decisions requiring oversight reach the management body through an operating reporting route; for CIR-covered entities, at least one person reports directly to that body.", "evidence": "Examples: reporting responsibilities and recent communications demonstrating that security reporting reaches the management body. For CIR-covered entities, identify at least one person with a direct reporting route and evidence that the route operates.", "risk_text": "Material security issues are filtered or delayed before reaching management, so decisions and corrective action occur too late.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-COMMUNICATION','Internal and External ISMS Communications Are Defined','Internal and External ISMS Communications Are Defined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine what ISMS information must be communicated, when, to whom and how. Allocate responsibility through existing roles. Link to incident and authority communication arrangements rather than creating parallel reporting channels.", "evidence": "Communication arrangements; audiences, timing and methods; sample communications and accountable roles.", "risk_text": "Security decisions, obligations or changes do not reach the people who must act.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.4"], "source": "iso27001-nis2-v7", "annex": "7.4", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C23.1','Management Receives Sufficient Implementation and Risk Information for Oversight','Management Receives Sufficient Implementation and Risk Information for Oversight','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Provide the management body with current implementation status and material-risk information, including significant deficiencies and delays, so it can exercise oversight. Compare the information actually received with known material issues; preparing a report that never reaches management, or omits those issues, is not sufficient.", "evidence": "Examples: implementation-status and material-risk information provided to the management body, with evidence of receipt and comparison against known material issues and current implementation status.", "risk_text": "Management relies on incomplete or outdated information and overlooks serious deficiencies or delayed measures.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C23.2','Management Oversees Implementation of Cybersecurity Measures','Management Oversees Implementation of Cybersecurity Measures','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Management actually exercises oversight of implementation.", "evidence": "Examples: management review discussions, decisions, interventions or follow-up records linked to implementation status, material issues and the progress of actions it requested.", "risk_text": "Known deficiencies persist because management does not decide, intervene or follow up; oversight becomes a reporting formality.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.1", "A.5.4"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C27.4','Security Roles and Personnel Assignments Are Reviewed','Security Roles and Personnel Assignments Are Reviewed','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T02", "subgroup": "A-GOV · Management governance", "topic_label": "A-GOV · Management governance", "description": "Security Roles and Personnel Assignments Are Reviewed. Check that assigned responsibilities, decision authority and available personnel still meet current security needs. Record decisions and update assignments when necessary. For CIR-covered entities, review roles at planned intervals and after significant incidents or changes, and review personnel assignments and staffing at least annually.", "evidence": "Examples: dated reviews of responsibilities, decision authority and staffing, with changed assignments or justified no-change decisions. For CIR-covered entities, compare role reviews with planned intervals and significant incident/change triggers, and personnel-assignment and staffing reviews with the at-least-annual requirement.", "risk_text": "Security tasks are missed or delayed after organisational changes because responsibilities and available personnel no longer match operational needs.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.3", "A.5.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ROLES','Responsibility for ISMS Conformity and Performance Reporting Is Assigned','Responsibility for ISMS Conformity and Performance Reporting Is Assigned','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Assign and communicate responsibility and authority for ISMS conformity and reporting ISMS performance to top management. Reuse existing security roles where they cover these duties; a new job title or a separate organisation chart is not required.", "evidence": "Role assignments and authority; communication records; ISMS performance reports.", "risk_text": "ISMS requirements and performance gaps remain unowned or are not escalated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.3", "A.5.2"], "source": "iso27001-nis2-v7", "annex": "5.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-CHANGE-PLAN','Changes to the ISMS Are Planned before Implementation','Changes to the ISMS Are Planned before Implementation','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Plan changes to ISMS scope, responsibilities, methods or processes before implementing them. Determine implications and delivery arrangements; technical system changes remain in the existing change controls.", "evidence": "ISMS change decisions, impact considerations and transition arrangements with owners and approval.", "risk_text": "A governance or scope change creates unassigned responsibilities or inconsistent ISMS processes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.3", "8.1"], "source": "iso27001-nis2-v7", "annex": "6.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-UNINTENDED-CHANGE','Unintended ISMS Changes Are Reviewed and Harmful Effects Addressed','Unintended ISMS Changes Are Reviewed and Harmful Effects Addressed','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T02", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Review unintended changes affecting ISMS operation and take action to mitigate adverse effects where necessary. Use actual change records or a proportionate scenario where no such change occurred.", "evidence": "Unintended-change review and mitigation decisions, linked to affected ISMS processes and follow-up.", "risk_text": "Unexpected organisational changes undermine the ISMS without their consequences being addressed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["8.1"], "source": "iso27001-nis2-v7", "annex": "8.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-RISKS-OPPORTUNITIES','Risks and Opportunities Affecting ISMS Results Are Determined','Risks and Opportunities Affecting ISMS Results Are Determined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Use organisational context and interested-party requirements to determine risks and opportunities affecting intended ISMS results. Address management-system issues, not a second copy of the technical risk register.", "evidence": "ISMS planning assessment linking context and requirements to risks, opportunities and intended results.", "risk_text": "Management-system weaknesses or improvement opportunities are missed despite technical risk assessments.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.1"], "source": "iso27001-nis2-v7", "annex": "6.1.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-ACTIONS','Actions for ISMS Risks and Opportunities Are Planned and Integrated','Actions for ISMS Risks and Opportunities Are Planned and Integrated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Plan actions for the identified ISMS risks and opportunities and integrate them into the processes that will implement them. Identify accountable delivery arrangements; this does not duplicate individual technical risk-treatment actions.", "evidence": "Action decisions, responsible process owners and integration into operating plans or workflows.", "risk_text": "Known ISMS weaknesses remain unactioned because planning decisions never enter operational work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.1"], "source": "iso27001-nis2-v7", "annex": "6.1.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-ACTION-EFFECTIVENESS','Actions for ISMS Risks and Opportunities Are Evaluated','Actions for ISMS Risks and Opportunities Are Evaluated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Evaluate whether the actions taken for ISMS risks and opportunities achieved their intended effect. Use existing performance or review evidence and respond where an action did not work.", "evidence": "Action-specific evaluation criteria, results and follow-up decisions linked to the original planning issue.", "risk_text": "Completed planning actions are assumed effective while the original management-system weakness persists.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.1"], "source": "iso27001-nis2-v7", "annex": "6.1.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C29.2','Information Security Policy Defines the Security Approach and Responsibilities','Information Security Policy Defines the Security Approach and Responsibilities','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "The Information Security Policy Defines the Security Approach and Responsibilities. Set security objectives, accountable roles, implementation resources and monitoring arrangements, and identify the supporting topic-specific policies. Management approval and operational implementation must be evidenced; separate documents are not required for every topic if the requirements remain identifiable.", "evidence": "Examples: the current information-security policy identifying objectives, responsibilities, resources, monitoring arrangements and supporting topic requirements, linked to management approval and samples of operational application. These elements may be held in one document or an identifiable set of existing records.", "risk_text": "Teams make incompatible security decisions or routinely bypass agreed safeguards, leaving information and services exposed at organisational boundaries.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.2", "A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-POLICY-COMMITMENTS','The Security Policy Includes the Required ISMS Commitments','The Security Policy Includes the Required ISMS Commitments','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Check that the policy is appropriate to the organisation, supports setting information security objectives, and commits to applicable information security requirements and continual ISMS improvement. Use the existing policy, approval and communication records rather than issue a second policy.", "evidence": "The current policy with identifiable commitments and objective-setting provisions, reconciled with organisational purpose and applicable obligations; existing approval and distribution records.", "risk_text": "The policy omits the commitments needed to guide compliance and improvement, allowing security decisions to be made without a clear management mandate.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["5.2"], "source": "iso27001-nis2-v7", "annex": "5.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C29.5','Security Documents and Records Are Current, Assigned and Retrievable','Security Documents and Records Are Current, Assigned and Retrievable','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Required security documents and records have identifiable current versions, assigned responsible persons and defined retention periods, and can be retrieved when needed.", "evidence": "Examples: document metadata or equivalent records identifying current versions, responsible persons and retention periods, with retrieval of sampled current instructions and retained security records.", "risk_text": "R1: Obsolete instructions are used in operations, causing incorrect security actions.<br>R2: Lost or untraceable records prevent reconstruction and substantiation of security decisions or implementation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.5.1", "7.5.2", "7.5.3", "A.5.33"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-DOCUMENT-NEEDS','Necessary ISMS Documented Information Is Identified','Necessary ISMS Documented Information Is Identified','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify the documented information required by the standard and that the organisation needs for an effective ISMS. Use existing documents and records; do not mandate a separate policy or template for every requirement.", "evidence": "Documented-information inventory or equivalent coverage record, linked to ISMS requirements and operating needs.", "risk_text": "Essential instructions or evidence are absent because documentation needs were never determined.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.5.1"], "source": "iso27001-nis2-v7", "annex": "7.5.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-DOCUMENT-RELEASE','ISMS Documents Are Suitably Identified, Reviewed and Approved','ISMS Documents Are Suitably Identified, Reviewed and Approved','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "When creating or updating ISMS documents, use appropriate identification and format and review and approve suitability before release. C29.5 continues to cover shared document administration and version control.", "evidence": "Released document samples with suitable identification, format, review and approval, including changed versions.", "risk_text": "Unsuitable or unapproved documents are issued as authoritative instructions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.5.2"], "source": "iso27001-nis2-v7", "annex": "7.5.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-EXTERNAL-DOCUMENTS','Necessary External Documents Are Identified and Controlled','Necessary External Documents Are Identified and Controlled','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify external documents necessary for ISMS planning and operation, such as contractual requirements, standards and supplier instructions. Control currency and access so that superseded or unavailable external instructions do not drive decisions.", "evidence": "External-document register or equivalent references; version checks; controlled access and update ownership.", "risk_text": "Obsolete external requirements or instructions cause incorrect security or conformity decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.5.3"], "source": "iso27001-nis2-v7", "annex": "7.5.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C29.3','Relevant Personnel and External Parties Receive and Follow Security Instructions','Relevant Personnel and External Parties Receive and Follow Security Instructions','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Relevant employees and external parties receive the security policies or instructions applicable to their work and follow them. Receipt and acknowledgement are evidenced where required.", "evidence": "Examples: distribution or access records for relevant employees and external parties, receipt and acknowledgement where required, and work samples or observation demonstrating compliance with the applicable instructions.", "risk_text": "Personnel or external parties mishandle information or bypass required safeguards because the instructions relevant to their work are not understood or followed.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["5.2", "7.3", "A.5.1", "A.5.4", "A.5.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "5.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C29.4','Security Policies and Procedures Follow Their Applicable Review Schedules','Security Policies and Procedures Follow Their Applicable Review Schedules','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-POL · Security policies and documents", "topic_label": "A-POL · Security policies and documents", "description": "Security Policies and Procedures Are Reviewed on Their Applicable Schedules. Maintain an identifiable review schedule for the overarching policy and the relevant topic-specific policies and procedures, with owners and applicable incident/change triggers. Record the review and resulting updates or justified no-change decision. For CIR-covered entities, management reviews the overarching policy at least annually; apply each topic''s own review provision rather than inventing one annual interval for everything.", "evidence": "Examples: an identifiable schedule linking each relevant policy or procedure to its owner, interval and incident/change triggers, with dated reviews and updates or justified no-change decisions. For CIR-covered entities, include at least annual management review of the overarching policy while retaining each topic''s applicable schedule.", "risk_text": "Staff follow obsolete rules that no longer protect changed systems or working practices, allowing previously addressed exposures to recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C29.1','Risk-Analysis Policy Guides Actual Cybersecurity Risk Assessments','Risk-Analysis Policy Guides Actual Cybersecurity Risk Assessments','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Define how cybersecurity risks are identified, analysed and assessed, and use that approach in completed assessments. Compare the policy with the methods and assumptions actually applied; a policy document alone is insufficient where operational assessments follow an unexplained, inconsistent approach.", "evidence": "Examples: the risk-analysis policy or equivalent identifiable policy content defining identification, analysis and assessment, with completed assessments showing that the stated approach is applied.", "risk_text": "Assessments omit relevant threats or apply incompatible assumptions, so treatment decisions leave material exposures unaddressed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.4','Risk-Assessment Methods and Acceptance Criteria Are Applied Consistently','Risk-Assessment Methods and Acceptance Criteria Are Applied Consistently','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "A defined risk-assessment method and risk-acceptance criteria are applied consistently when rating risks and deciding whether they can be accepted.", "evidence": "Examples: the defined assessment method and acceptance criteria compared with sampled risk ratings and acceptance decisions, including explanations for materially different treatment of comparable risks.", "risk_text": "Risk ratings depend on individual judgement without a common basis, distorting priorities and acceptance decisions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.1','Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies','Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Cybersecurity Risks Are Assessed Across Services, Systems and Dependencies. Use current information on threats, vulnerabilities, likelihood and impact, including third-party dependencies and single points of failure. Address confidentiality, integrity, authenticity and availability through an all-hazards approach, including relevant physical events. Consider effects on service recipients and other services, not only the entity''s own financial loss.", "evidence": "Examples: current assessments linking services, systems and third-party dependencies to threats, vulnerabilities, likelihood and impact, including single points of failure and relevant physical hazards. Check confidentiality, integrity, authenticity and availability impacts and consequences for recipients and other services.", "risk_text": "Significant risks are missed or rated incorrectly, leading to unsuitable priorities and measures.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.2", "8.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-RISK-PRIORITY','Evaluated Risks Have Justified Treatment Priorities','Evaluated Risks Have Justified Treatment Priorities','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Use the risk evaluations already assessed under C30.4 to determine the relative priorities for treating risks. Record why particular risks must be treated before others and explain justified exceptions. Reuse the risk register; do not repeat the risk-scoring or acceptance test, or the action ownership and dates assessed under C30.5.", "evidence": "Risk-treatment priorities linked to evaluated risks and their significance, with the reasoning for exceptions; the existing risk register or treatment plan is sufficient.", "risk_text": "High-impact risks are deferred while lower-priority actions consume resources because risk scores were not turned into consistent treatment priorities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "annex": "6.1.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-RISK-OWNER','Information Security Risks Have Accountable Owners','Information Security Risks Have Accountable Owners','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Assign each assessed information security risk to a person with authority to manage that risk. Distinguish ownership of the risk from ownership of an asset or responsibility for completing one treatment action.", "evidence": "Risk register with named or unambiguously assigned risk owners; ownership acceptance and escalation routes.", "risk_text": "No accountable owner decides how a material risk should be treated or accepted.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.2"], "source": "iso27001-nis2-v7", "annex": "6.1.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.2','Risk-Treatment Decisions Are Justified and Linked to Assessed Risks','Risk-Treatment Decisions Are Justified and Linked to Assessed Risks','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risk-Treatment Decisions Are Justified and Linked to the Assessed Risks. Record selected safeguards and reasons, considering exposure, entity size, likelihood and severity, societal and economic consequences, the state of the art and implementation cost. Use relevant effectiveness findings, asset protection needs and continuity requirements. Risk acceptance does not waive an applicable legal duty.", "evidence": "Examples: treatment decisions linked to assessed risks and chosen safeguards, explaining proportionality using exposure, size, likelihood, severity, societal/economic effects, state of the art and cost. Relevant effectiveness results, asset protection needs, continuity requirements and applicable duties should be traceable in the decision basis.", "risk_text": "Treatment choices cannot be traced to the risks and assumptions they address, leading to unsuitable safeguards or untreated exposure when decisions are revisited.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3", "8.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ANNEX-COMPARISON','Necessary Controls Are Compared with All Annex A Controls','Necessary Controls Are Compared with All Annex A Controls','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Compare the controls determined through risk treatment with all 93 Annex A reference controls to check for omissions. Include necessary organisation-specific controls; Annex A is a completeness reference, not a universal product checklist.", "evidence": "Complete Annex A comparison, identified omissions and resulting control-selection decisions linked to risk treatment.", "risk_text": "A necessary safeguard is omitted because selection was never checked against the full reference set.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-SOA-INCLUSIONS','The SoA Identifies Necessary Controls and Reasons for Inclusion','The SoA Identifies Necessary Controls and Reasons for Inclusion','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Maintain a Statement of Applicability (SoA) identifying the necessary controls and why each is included. Link to risks or other applicable requirements and include necessary controls outside Annex A.", "evidence": "SoA entries with necessary control IDs and inclusion rationales, reconciled with risk treatment and applicable obligations.", "risk_text": "The organisation cannot justify its selected safeguards or demonstrate that necessary non-Annex controls were considered.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-SOA-EXCLUSIONS','Excluded Annex A Controls Have Defensible Justifications','Excluded Annex A Controls Have Defensible Justifications','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Justify each excluded Annex A control against the assessed ISMS scope, risks and applicable obligations. Do not exclude clauses 4-10 through the SoA or equate lack of implementation with non-applicability.", "evidence": "Exclusion decisions supported by scope and risk evidence; checks for contradictory applicable obligations.", "risk_text": "Necessary controls are hidden behind unsupported non-applicability decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-SOA-STATUS','The SoA Implementation Status Matches the Control Records','The SoA Implementation Status Matches the Control Records','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Record whether necessary controls are implemented and reconcile the SoA with current implementation evidence. Link to the shared control records rather than maintain a second implementation answer.", "evidence": "SoA status linked to current assessment records, with investigated and corrected discrepancies.", "risk_text": "Management or auditors rely on a SoA claiming implementation that the underlying evidence does not support.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.5','Risk-Treatment Measures Have Owners, Target Dates and Tracked Progress','Risk-Treatment Measures Have Owners, Target Dates and Tracked Progress','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Each risk-treatment measure has an assigned responsible person and a planned implementation date. Progress, delays and completion are tracked.", "evidence": "Examples: treatment actions in existing plans or work-tracking records identifying the responsible person, planned date, progress, delays and evidence of implemented completion.", "risk_text": "Treatment stalls, actions become ownerless or unresolved risks persist behind nominal completion claims.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3", "8.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.3','Residual Risks Are Evaluated and Accepted by Accountable Decision-Makers','Residual Risks Are Evaluated and Accepted by Accountable Decision-Makers','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risks remaining after treatment are evaluated and accepted by the management body or, where applicable, an authorised, accountable risk owner, with adequate reporting to the management body.", "evidence": "Examples: post-treatment residual-risk evaluations linked to acceptance by the management body or an authorised accountable risk owner, with evidence of adequate reporting to the management body where acceptance is delegated.", "risk_text": "Unresolved exposure is accepted without authority or understanding, or acceptance is wrongly used to excuse non-compliance.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-TREATMENT-PLAN-APPROVAL','Risk Owners Approve the Risk Treatment Plan','Risk Owners Approve the Risk Treatment Plan','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Obtain the relevant risk owners'' approval of the treatment plan and its selected actions. Identify the approved version; this decision is distinct from accepting the risks remaining after treatment.", "evidence": "Treatment plan and approval by the identified risk owners, linked to the agreed version and treatment decisions.", "risk_text": "Treatment proceeds without the accountable risk owner agreeing to the planned response.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-RESIDUAL-ACCEPTANCE','Risk Owners Accept the Residual Information Security Risks','Risk Owners Accept the Residual Information Security Risks','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T03", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Obtain acceptance of the identified residual risks from their risk owners. Reuse C30.3 where the accepting management member is also the risk owner; a generic management sign-off does not automatically establish this authority.", "evidence": "Residual-risk decisions identifying the risk, treatment assumptions and accepting risk owner; the existing combined approval record may suffice.", "risk_text": "Remaining exposure is accepted by someone who does not own the risk or is not informed of the residual exposure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["6.1.3"], "source": "iso27001-nis2-v7", "annex": "6.1.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C30.6','Risk Assessments and Treatment Plans Are Reviewed and Updated','Risk Assessments and Treatment Plans Are Reviewed and Updated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T03", "subgroup": "A-RSK · Risk assessment and treatment", "topic_label": "A-RSK · Risk assessment and treatment", "description": "Risk Assessments and Treatment Plans Are Reviewed and Updated. Review at planned intervals and after significant incidents or significant operational or risk changes. For CIR-covered entities, the periodic review is at least annual. Record the outcome and update assessment results, treatment priorities and plans where needed.", "evidence": "Examples: dated reviews and resulting updates or confirmed assessments and treatment plans, compared with planned intervals and significant incident, operational-change and risk-change triggers. For CIR-covered entities, check that periodic review is at least annual.", "risk_text": "Changes in systems, threats or incidents invalidate treatment assumptions, leaving new or increased exposures untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["8.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "8.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C42.1','Asset Inventory Identifies Services and Their Supporting Assets','Asset Inventory Identifies Services and Their Supporting Assets','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "The Asset Inventory Identifies Services and Their Supporting Assets. Maintain a complete, accurate and consistent inventory for the assessed scope, covering operations and services, their descriptions, supporting network and information systems and associated assets. Include relevant cloud, operational-technology and outsourced dependencies rather than limiting the inventory to owned hardware. Record changes traceably; C42.4 assesses periodic reconciliation and review.", "evidence": "Examples: the current inventory identifying in-scope operations, services, descriptions and supporting systems/assets, including relevant cloud, OT and outsourced dependencies, with traceable changes. Compare representative entries with actual operations to assess completeness and accuracy.", "risk_text": "Unrecorded assets escape patching, access control or incident scoping, allowing compromise to persist outside operational oversight.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.9", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-INFORMATION-INVENTORY','The Inventory Identifies Information and Non-ICT Associated Assets','The Inventory Identifies Information and Non-ICT Associated Assets','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify the information sets and relevant non-ICT assets within the ISMS scope, with accountable owners, and maintain their inventory when they change. Reuse the service and system inventory; add only information or assets not represented there, such as a paper archive or a business information set spanning several systems.", "evidence": "Information-set and associated-asset inventory entries with ownership and updates; reconciliation with service/system records and sampled business activities or physical holdings.", "risk_text": "Business information or non-ICT assets remain outside protection decisions because the inventory lists only services, systems and equipment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.9"], "source": "iso27001-nis2-v7", "annex": "A.5.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.3','In-Scope Assets Have Accountable Owners','In-Scope Assets Have Accountable Owners','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Each asset within scope has an identifiable person or role accountable for its management and protection decisions; technical custody alone does not establish that accountability.", "evidence": "Examples: asset or service records, responsibility assignments or equivalent information identifying an accountable owner for each in-scope asset, corroborated by the relevant owners.", "risk_text": "Asset protection or maintenance actions are left undone because teams assume another owner will act, prolonging known exposure or service faults.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.9"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.2','Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability','Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Asset Protection Levels Reflect Confidentiality, Integrity, Authenticity and Availability Needs. Assign systems and supporting assets protection levels based on sensitivity, criticality, risks and service dependencies. Align availability needs with continuity and recovery objectives. INFO-CLASS separately assesses information confidentiality labels; it does not replace the other protection dimensions.", "evidence": "Examples: assigned asset and system protection levels linked to sensitivity, criticality, risk and service dependencies across confidentiality, integrity, authenticity and availability. Compare availability levels with continuity and recovery objectives.", "risk_text": "R1: Protection effort is misallocated because the service impact and dependencies of assets are underestimated, leaving priority operations vulnerable to disruption.<br>R2: Underestimated integrity requirements allow critical data or system configurations to be altered without adequate safeguards, causing incorrect business decisions or unsafe operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.12", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.4','Asset Reviews and Material-Change Updates Are Performed','Asset Reviews and Material-Change Updates Are Performed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Carry out the planned asset reviews and update inventory records for material changes. Retain review results and traceable updates or a justified conclusion that no update was needed; an unchanged inventory by itself does not demonstrate that a review occurred.", "evidence": "Examples: completed asset reviews, comparisons identifying missing or obsolete entries and traceable inventory updates after material changes, or review outcomes confirming that no update was needed.", "risk_text": "Outdated asset details cause new or changed systems to be omitted from security operations and misdirect incident or recovery work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.9"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','INFO-CLASS','Data and Information Are Classified by Confidentiality Level','Data and Information Are Classified by Confidentiality Level','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Assign data and information a confidentiality level using the organisation''s classification scheme and the consequences of unauthorised disclosure; a device inventory alone does not show that its information has been classified.", "evidence": "Examples: the confidentiality classification scheme and representative information classified under it, with explanations supporting the assigned levels. Redacted samples or supervised inspection can demonstrate classification without disclosing sensitive contents.", "risk_text": "Sensitive information is treated as public or internal, allowing unauthorised access or disclosure.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.12", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-INFORMATION-IA','Information Classification Includes Integrity and Availability Needs','Information Classification Includes Integrity and Availability Needs','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Alongside the confidentiality classification already assessed under INFO-CLASS, determine the information-level consequences of unauthorised alteration and unavailability, considering relevant interested-party requirements. Reuse asset protection levels only where they explicitly cover the information concerned; do not create a second confidentiality classification.", "evidence": "Information classification records with integrity and availability needs and their rationale, linked to relevant requirements and existing confidentiality or asset-protection records.", "risk_text": "R1: Information is protected against disclosure but can be altered without adequate safeguards.<br>R2: Information needed for a critical decision is unavailable because its availability needs were never classified.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "annex": "A.5.12", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','INFO-LABEL','Information Labels Reflect the Assigned Confidentiality Class','Information Labels Reflect the Assigned Confidentiality Class','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Apply the organisation''s labelling rules so that users can recognise the confidentiality class assigned to relevant information or media; a visible marking or associated metadata may be used without prescribing one universal format.", "evidence": "Examples: representative documents, files or media showing labels consistent with their assigned confidentiality classes and applicable labelling rules. Use redacted samples or observation; no particular label format is required.", "risk_text": "R1: Users or automated handling rules disclose confidential information because the visible label indicates a lower protection class.<br>R2: Labels or asset markings themselves reveal sensitive personnel, location or network information to unauthorised people, supporting reconnaissance or targeted deception.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','INFO-CLASS-REV','Information Confidentiality Classifications Are Reviewed and Updated','Information Confidentiality Classifications Are Reviewed and Updated','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST · Asset inventory, ownership and information classification", "topic_label": "I-AST · Asset inventory, ownership and information classification", "description": "Reassess assigned confidentiality levels periodically and following relevant changes, retaining or correcting each level according to current sensitivity; CIR expressly requires periodic review, while the change trigger is a supporting practice in this catalogue.", "evidence": "Examples: dated reviews of information confidentiality classifications and resulting corrections or confirmed classifications, including reassessment following relevant changes.", "risk_text": "Outdated confidentiality levels leave sensitive information exposed or impose unnecessary restrictions after its sensitivity has changed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.12"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.12", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-PRIVACY-IMPLEMENTATION','Applicable Privacy Safeguards Cover Processing throughout the ISMS','Applicable Privacy Safeguards Cover Processing throughout the ISMS','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Implement the applicable privacy and personally identifiable information requirements across processing within the ISMS scope. Reuse the legal register and shared safeguards; C45.1/C45.2 cover NIS2-purpose processing, not all employment or customer processing.", "evidence": "Processing scope and applicable privacy obligations linked to implemented safeguards, including logging and audit records where relevant.", "risk_text": "Personal information outside the NIS2 security-processing context is handled contrary to applicable privacy requirements.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.34"], "source": "iso27001-nis2-v7", "annex": "A.5.34", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-PRIVACY-RESPONSIBILITIES','Relevant Parties Know Their Privacy Responsibilities','Relevant Parties Know Their Privacy Responsibilities','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Communicate applicable privacy responsibilities to the parties involved in the relevant processing. Reuse contractual duties and training records; this is not a new requirement to notify every stakeholder of every processing operation.", "evidence": "Responsibility assignments and communication to relevant staff or providers, supported by evidence that the instructions are understood.", "risk_text": "Privacy safeguards are defined but the parties performing the processing do not know their responsibilities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.34"], "source": "iso27001-nis2-v7", "annex": "A.5.34", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.5','Asset Handling Rules Are Established and Applied','Asset Handling Rules Are Established and Applied','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Define and communicate how the relevant asset and information types may be used, stored and otherwise handled, and check that operating practice follows those rules; practical employee instruction is assessed separately under TRN-DATA.", "evidence": "Examples: applicable handling rules by asset or information type, evidence that relevant users receive them, and observed handling or operational samples showing that they are applied.", "risk_text": "R1: Improper handling damages or loses equipment and media, interrupting work or making needed information unavailable.<br>R2: Handling that ignores sensitivity exposes information to unauthorised people.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.10", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.6','Asset and Information Transfers Are Protected According to Type and Classification','Asset and Information Transfers Are Protected According to Type and Classification','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Match safeguards for electronic, physical and, where relevant, verbal transfers to the information''s classification and the asset type, so the chosen transfer method protects the material throughout the exchange.", "evidence": "Examples: transfer arrangements and representative transfers showing safeguards matched to asset/information type and classification, covering electronic, physical or verbal exchange where relevant. Existing channel settings, observed practices or transfer records may demonstrate protection.", "risk_text": "R1: Information is intercepted or delivered to an unintended recipient during transfer.<br>R2: Transferred data are altered or become incomplete, causing the recipient to act on incorrect information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.14"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','DATA-OUTFLOW','Unauthorised Transfers of Sensitive Data Are Prevented or Detected','Unauthorised Transfers of Sensitive Data Are Prevented or Detected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Identify sensitive-data transfer paths and apply risk-based safeguards that prevent or detect unauthorised disclosure; assess the protection achieved rather than the purchase of a particular data loss prevention product.", "evidence": "Examples: risk-based selection of safeguards for relevant sensitive-data transfer paths, operating configurations or procedures, and detection/prevention records or safe checks showing unauthorised transfers are prevented or detected.", "risk_text": "Sensitive information is exfiltrated through an authorised account or unapproved transfer channel, and delayed detection allows further disclosure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.8.12"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','DATA-MASK','Sensitive Data Is Masked Where Full Visibility Is Unnecessary (Applies where access needs can be met with a limited view of sensitive data.)','Sensitive Data Is Masked Where Full Visibility Is Unnecessary (Applies where access needs can be met with a limited view of sensitive data.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where a limited view meets the access need, conceal sensitive values from users who do not need the full content and check that the assessed access paths do not expose the unmasked values; this is not a requirement to mask every field.", "evidence": "Where limited views can meet access needs, examples include visibility decisions, masking settings and safe tests using synthetic or redacted data showing that restricted users cannot obtain the full sensitive values through the assessed access paths.", "risk_text": "People who need only limited information obtain full sensitive values through displays, exports or unrestricted reidentification.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.11", "annex_kind": "annex", "applicability": {"condition": "where access needs can be met with a limited view of sensitive data", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','MEDIA-UNATTENDED','Sensitive Papers and Media Are Secured When Unattended (Applies where sensitive physical information or removable media is handled.)','Sensitive Papers and Media Are Secured When Unattended (Applies where sensitive physical information or removable media is handled.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where sensitive papers or removable media are handled, place them in protected storage or apply equivalent safeguards when left unattended, so people without permission cannot read or remove them.", "evidence": "Where sensitive papers or removable media are handled, examples include applicable storage arrangements and observation that unattended materials are secured, supported by relevant checks or corrected exposures where available.", "risk_text": "Visitors or unauthorised personnel read, photograph or take sensitive material left unattended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.7"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.7", "annex_kind": "annex", "applicability": {"condition": "where sensitive physical information or removable media is handled", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-DISPLAY-CLEARING','Sensitive Information Is Cleared from Shared Physical Displays','Sensitive Information Is Cleared from Shared Physical Displays','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Clear or securely conceal sensitive information on shared whiteboards and other non-device displays when no longer needed or when unauthorised people could see it. Reuse MEDIA-UNATTENDED for papers/media and DEVICE-LOCK for electronic devices; this control addresses the remaining display exposure.", "evidence": "Applicable display-clearing rules and observations after meetings or work activities, with staff explanation of how information is concealed or removed.", "risk_text": "Sensitive meeting or operational information remains visible to visitors or later room users after the authorised activity has ended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.7"], "source": "iso27001-nis2-v7", "annex": "A.7.7", "annex_kind": "annex", "applicability": {"condition": "Shared physical displays are used for sensitive information", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ASSET-OFFSITE','Assets Used Outside the Organisation Are Protected (Applies only where work assets are used outside organisational premises.)','Assets Used Outside the Organisation Are Protected (Applies only where work assets are used outside organisational premises.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Where work assets leave organisational premises, apply handling and protection measures suited to their information, location and exposure to loss, theft or unauthorised use; location tracking and remote erasure are possible safeguards, not universal requirements.", "evidence": "Where work assets are used off-site, examples include applicable handling arrangements and representative assets or operating records showing protections suited to the location and exposure. Examine selected safeguards and relevant loss-handling records where available; tracking and remote erasure are not universally required.", "risk_text": "R1: Loss, theft or observation of an off-site asset exposes organisational information.<br>R2: Damage or loss of an off-site asset interrupts work or makes locally held data unavailable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.9", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.7", "annex_kind": "annex", "applicability": {"condition": "only where work assets are used outside organisational premises", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C42.7','Removable Media Connections Are Blocked Unless Organisationally Authorised','Removable Media Connections Are Blocked Unless Organisationally Authorised','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Connection of removable media is technically prohibited unless an organisational reason authorises it.", "evidence": "Examples: enforced removable-media connection restrictions, organisational reasons and authorisation for exceptions, and safe allowed/blocked connection checks on representative systems.", "risk_text": "R1: Unauthorised removable media introduce malicious code into connected systems.<br>R2: Users copy sensitive information to unapproved media and remove it from organisational control.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.10", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.8','Removable Media Are Scanned Before Use and Do Not Auto-Execute','Removable Media Are Scanned Before Use and Do Not Auto-Execute','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Removable media do not auto-execute and are scanned for malicious code before use.", "evidence": "Examples: representative configuration checks and safe demonstrations showing that removable media cannot auto-execute and are scanned for malicious code before use. Existing scan records may corroborate operation.", "risk_text": "R1: Malicious code executes from removable media, stealing information or credentials.<br>R2: Media-borne malware corrupts data, disrupts systems or spreads to connected services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.10", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.10", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C42.9','Portable Storage Is Protected in Transit and Storage','Portable Storage Is Protected in Transit and Storage','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "topic_label": "I-INFO-SAFE · Information handling safeguards", "description": "Apply appropriate handling and storage protections to portable media containing organisational data while stored and transported, using cryptography where appropriate. Check the actual protections, not only issue or custody records; recording who holds a device does not establish that its data or the medium are protected.", "evidence": "Examples: observed portable-storage handling and storage/transport protections, with cryptographic settings and safe checks where encryption is appropriate. Custody information or transfer records may support the assessment where relevant.", "risk_text": "R1: Lost or stolen portable media disclose readable sensitive information.<br>R2: Loss or damage to portable media makes required information unavailable where no usable copy exists.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-DATA','Employees Are Trained in Secure Data and Removable Media Handling','Employees Are Trained in Secure Data and Removable Media Handling','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-DATA-TRN · Data and removable media training", "topic_label": "I-DATA-TRN · Data and removable media training", "description": "Employees handling data or removable media receive practical instruction in the applicable classification, transfer, storage and disposal rules, so they can carry out those tasks securely; existing training can cover this without a separate course.", "evidence": "Examples: relevant data and removable-media handling instruction and participation records, supported by staff explanation or practical checks of the applicable handling rules. Existing onboarding or other training may supply this evidence without a separate course or certificate.", "risk_text": "R1: Employees mishandle or disclose sensitive work information or fail to escalate its loss promptly.<br>R2: Employees introduce malicious code by using removable media unsafely.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.7.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-RECORD-RETENTION','Business Record Retention and Preservation Requirements Are Defined','Business Record Retention and Preservation Requirements Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine retention and preservation requirements for relevant business record categories, including applicable legal or contractual needs. Reuse defined security-document and log periods; do not invent a universal retention period.", "evidence": "Record-category retention and preservation rules with their reasons and responsible owners.", "risk_text": "Required business records are destroyed too early or retained without a justified need.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.33"], "source": "iso27001-nis2-v7", "annex": "A.5.33", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-RECORD-SAFEGUARDS','Business Records Are Protected throughout Their Required Retention','Business Records Are Protected throughout Their Required Retention','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Protect retained business records against loss, destruction, falsification and unauthorised disclosure. Reuse existing access and storage safeguards, testing only record populations not already evidenced by them.", "evidence": "Record protection arrangements and observed access/integrity/recovery safeguards, linked to existing shared control evidence.", "risk_text": "Records exist for the required period but are altered, lost or exposed and cannot serve their intended purpose.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.33", "7.5.3"], "source": "iso27001-nis2-v7", "annex": "A.5.33", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-RECORD-READABILITY','Retained Business Records Remain Readable through Technology Changes','Retained Business Records Remain Readable through Technology Changes','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Preserve readable and retrievable records over the required period, including when formats, software or storage platforms change. Verify retrieval after relevant migrations; retaining a file alone does not establish readability.", "evidence": "Retrieval/readability checks, relevant migration arrangements and results for retained formats and record categories.", "risk_text": "Retained records become unusable because the software or format needed to read them is no longer available.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.33", "7.5.3"], "source": "iso27001-nis2-v7", "annex": "A.5.33", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','DATA-DELETE','Data No Longer Required Is Securely Deleted','Data No Longer Required Is Securely Deleted','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Apply the relevant retention and deletion criteria to securely remove information that is no longer needed, taking account of valid retention requirements and relevant copies; this concerns the data lifecycle, not only disposal of equipment.", "evidence": "Examples: applicable retention/deletion criteria and representative deletion outcomes showing that data no longer required are securely removed, with checks of relevant copies under the applicable disposal arrangements. Use metadata or controlled demonstrations rather than copying the deleted sensitive content.", "risk_text": "R1: Obsolete sensitive data are exposed during later access, disclosure or restoration, extending the population and period affected by a breach.<br>R2: Deletion is applied before required retention or preservation needs end, destroying records needed for operations, investigations or substantiating decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.33", "A.8.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.33", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.12','Personnel Assets Are Returned, Deposited or Deleted and Residual Access Removed on Termination','Personnel Assets Are Returned, Deposited or Deleted and Residual Access Removed on Termination','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Reconcile termination actions with the assets held by the person and verify their return, deposit or appropriate deletion, together with removal of residual access. Collecting a laptop alone is insufficient if organisational information or usable accounts, tokens or remote-access paths remain outside authorised control; remote erasure is not required in every case.", "evidence": "Examples: termination records reconciled with assets held by the person, showing return, deposit or appropriate deletion and removal of residual access. Receipts, system records or supervised checks may demonstrate the outcome without requiring remote erasure in every case.", "risk_text": "R1: Former personnel retain and disclose organisational information after their authority ends.<br>R2: Unreturned equipment or retained access enables unauthorised use of organisational resources.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.11", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-ASSET-CHANGE','Assets No Longer Authorised After a Role or Contract Change Are Returned','Assets No Longer Authorised After a Role or Contract Change Are Returned','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "When employment, a role, a contract or an agreement changes without ending, reconcile the assets and information held against the new authorised need. Recover items no longer authorised and record any justified continuing assignment. Reuse the same inventory and access-change records; termination recovery remains under C40.12 and C52.8. A role change does not require surrendering equipment still properly assigned for the new work.", "evidence": "Change records matched to assigned physical and information assets, confirmed returns or transfers of custody, and documented continuing assignments. Link access changes without assessing them twice. If no relevant change occurred in the period, assess the defined reconciliation and return arrangements, assigned responsibilities and a proportionate walkthrough or safe scenario using the existing asset records. Record the absence of an execution sample; do not invent a change or require return of assets still properly assigned.", "risk_text": "A reassigned person or changed service provider retains information or equipment no longer needed and can use or disclose it outside the new authorised role.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.11"], "source": "iso27001-nis2-v7", "annex": "A.5.11", "annex_kind": "annex", "applicability": {"condition": "Employment, roles, contracts or agreements change within the ISMS scope; assess arrangements if no such event occurred", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C40.4','Information Is Securely Erased on Reuse and Disposal','Information Is Securely Erased on Reuse and Disposal','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T04", "subgroup": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "topic_label": "I-AST-EXIT · Asset return, information deletion and equipment disposal", "description": "Before equipment or media are reused or disposed of, remove the information they hold using erasure or destruction appropriate to the medium and sensitivity, and verify the outcome; merely deleting a file reference is not evidence of secure removal.", "evidence": "Examples: reuse or disposal records linked to the relevant equipment/media, identifying the erasure or destruction method and checks showing that information was securely removed before reuse or release.", "risk_text": "A recipient of reused, sold or discarded equipment recovers residual sensitive information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.10", "A.7.14", "A.8.10"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.10", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-IP-ENTITLEMENTS','Rights to Use Software and Protected Material Are Established','Rights to Use Software and Protected Material Are Established','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Establish the applicable intellectual-property and licence conditions for acquired software and other protected material, including ownership and usage limits where relevant. Reuse contract and acquisition evidence.", "evidence": "Licence entitlements, protected-material rights and relevant acquisition/ownership terms.", "risk_text": "The organisation relies on software or material without a valid right to use it.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.32"], "source": "iso27001-nis2-v7", "annex": "A.5.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-IP-USAGE','Actual Software and Material Use Complies with Granted Rights','Actual Software and Material Use Complies with Granted Rights','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Check actual installations, use and copying against established rights and limits and resolve unauthorised use. Malware approval and an entitlement record do not prove that actual usage is licensed.", "evidence": "Usage or installation reconciliation with entitlements, exceptions and remediation records.", "risk_text": "Actual use exceeds licence rights and creates legal exposure or loss of access to critical software.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.32"], "source": "iso27001-nis2-v7", "annex": "A.5.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-IP-DISPOSAL','Licensed Software Is Removed before Equipment Disposal or Reuse','Licensed Software Is Removed before Equipment Disposal or Reuse','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T04", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Before relevant equipment is disposed of or reused, verify removal or secure overwriting of licensed software. Reuse the disposal record; C40.4 continues to assess sensitive-data removal.", "evidence": "Disposal/reuse records establishing licensed-software removal or overwrite, linked to existing sanitisation evidence.", "risk_text": "Equipment leaves authorised use with licensed software still installed, permitting unauthorised use or transfer.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.14"], "source": "iso27001-nis2-v7", "annex": "A.7.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-SCREENING-ENTRY','Proportionate Entry Screening Covers the Relevant Personnel Population','Proportionate Entry Screening Covers the Relevant Personnel Population','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine and perform lawful, ethical background verification before relevant personnel join. Reuse C40.7 for sensitive roles and address the remaining population proportionately to business needs, information classification and risk; criminal or credit checks are not required for every person.", "evidence": "Coverage and proportionate screening criteria with protected completion records; links to existing sensitive-role checks.", "risk_text": "Relevant personnel enter trusted work without the background verification justified for their role.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.1"], "source": "iso27001-nis2-v7", "annex": "A.6.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-SCREENING-ONGOING','Ongoing Screening Responds to Relevant Trust and Role Changes','Ongoing Screening Responds to Relevant Trust and Role Changes','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine and perform justified ongoing background verification as employment, access or relevant circumstances change. Record lawful reasons to recheck or not recheck; initial recruitment screening alone does not address continuing trust requirements.", "evidence": "Ongoing screening criteria and triggers, proportionate review decisions and restricted records of justified checks.", "risk_text": "Changes affecting trust remain unexamined after initial screening.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.1"], "source": "iso27001-nis2-v7", "annex": "A.6.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.7','Necessary Background Checks Precede Assignment to Sensitive Roles','Necessary Background Checks Precede Assignment to Sensitive Roles','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Before assigning sensitive duties, complete the background checks justified by the role and permitted by applicable law, using only the personal information necessary to establish the result.", "evidence": "Examples: necessary, lawful screening criteria for sensitive roles and protected outcome/date records showing completion before assignment. Inspect only the information needed to substantiate the check, not unrestricted background reports.", "risk_text": "A person with relevant, lawfully discoverable trust concerns gains sensitive access and misuses it to obtain information or manipulate systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.6','Security-Relevant Personnel Are Qualified for Their Roles','Security-Relevant Personnel Are Qualified for Their Roles','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Match the security skills and expertise needed for assigned duties with the person''s qualifications, experience or demonstrated capability, and address relevant gaps; a particular certificate is not automatically required.", "evidence": "Examples: role-specific competence needs compared with relevant qualifications, experience or demonstrated capability of assigned personnel, including how any identified capability gaps are addressed.", "risk_text": "Personnel make security-relevant configuration or response errors because their assigned tasks exceed their skills, exposing information or prolonging service faults.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["7.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-COMPETENCE-ACTIONS','Non-Training Competence Actions Have Demonstrated Effectiveness','Non-Training Competence Actions Have Demonstrated Effectiveness','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Where competence gaps are addressed through mentoring, reassignment, recruitment or other non-training action, evaluate whether the required capability was obtained and retain evidence. C40.6 retains the qualification/gap check and TRN-05 retains training-effectiveness assessment.", "evidence": "Non-training competence-gap decisions and mentoring, reassignment or recruitment records, with demonstrated capability after the action and retained qualification or experience evidence. Reuse C40.6 for the underlying competence assessment and TRN-05 for training effectiveness.", "risk_text": "A competence gap remains after mentoring, reassignment or recruitment because completion of the action is mistaken for demonstrated capability.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2"], "source": "iso27001-nis2-v7", "annex": "7.2", "annex_kind": "clause", "applicability": {"condition": "A non-training action is needed or used to close a competence gap within the ISMS scope; record a justified non-applicability decision if no such action is needed", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C40.1','Personnel Accept Security and Confidentiality Duties Before Access','Personnel Accept Security and Confidentiality Duties Before Access','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Before relevant access is granted, personnel understand and accept the security and confidentiality responsibilities attached to their work; accepted contractual terms or an equivalent recorded commitment can suffice without a duplicate agreement.", "evidence": "Examples: accepted employment terms or equivalent recorded commitments covering security and confidentiality duties, with acceptance dates compared with the granting of relevant access.", "risk_text": "Personnel disclose or misuse information after receiving access without understanding and accepting their security and confidentiality responsibilities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.2", "A.6.6"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.2", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-EMPLOYER-DUTIES','Employment Terms State the Organisation''s Security Responsibilities','Employment Terms State the Organisation''s Security Responsibilities','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Check that applicable employment agreements state the organisation''s information security responsibilities as well as the personnel duties already assessed under C40.1. Existing contractual terms can fulfil both controls; this adds the employer side of the agreement, not a second employee acknowledgement.", "evidence": "Applicable employment terms or incorporated contractual provisions showing organisational and personnel responsibilities; checks across relevant employment categories without copying unnecessary personal details.", "risk_text": "Security expectations are imposed on personnel without defining the organisation''s own responsibilities, creating ambiguity in employment-related security decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.2"], "source": "iso27001-nis2-v7", "annex": "A.6.2", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-NDA-TERMS','Confidentiality Terms Match the Information and Relationship','Confidentiality Terms Match the Information and Relationship','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine and review confidentiality terms appropriate to the protected information and the relationship, including duration and return or destruction obligations where needed. Existing employment or supplier clauses may suffice.", "evidence": "Confidentiality requirements, current terms and review decisions when information or relationships change.", "risk_text": "Signed agreements fail to protect the actual information or continue with unsuitable terms.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.6"], "source": "iso27001-nis2-v7", "annex": "A.6.6", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-NDA-COVERAGE','Required Confidentiality Agreements Cover the Relevant Parties','Required Confidentiality Agreements Cover the Relevant Parties','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T05", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Verify that the required confidentiality agreements or incorporated terms are documented and signed for relevant parties. Reuse C40.1 and supplier-contract results for populations already covered; assess only remaining coverage gaps.", "evidence": "Relevant-party coverage reconciliation to signed agreements or accepted contractual terms, with links to existing personnel/supplier evidence.", "risk_text": "Suitable confidentiality terms exist but a party receiving protected information is not bound by them.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.6"], "source": "iso27001-nis2-v7", "annex": "A.6.6", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.9','A Lawful, Communicated Disciplinary Process Addresses Security-Policy Violations','A Lawful, Communicated Disciplinary Process Addresses Security-Policy Violations','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Personnel are informed how security-policy violations are handled through a lawful disciplinary process, and actual cases follow that process; an organisation does not need to invent a disciplinary case to demonstrate readiness.", "evidence": "Examples: the lawful disciplinary process and evidence of communication to relevant personnel, with anonymised handling records if security-policy violations have occurred. Absence of a disciplinary case does not itself indicate failure.", "risk_text": "Violations are ignored or handled inconsistently, allowing repeated unsafe behaviour or unfair treatment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.4"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.4", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.8','Continuing Security Duties Are Defined and Enforced After Employment Changes or Termination','Continuing Security Duties Are Defined and Enforced After Employment Changes or Termination','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T05", "subgroup": "I-HR · Personnel security", "topic_label": "I-HR · Personnel security", "description": "Specify the security duties that continue after a role change or termination in the applicable employment terms or agreements, communicate them to the person concerned and enforce them where applicable. A generic contract template alone does not demonstrate that the relevant continuing duties were agreed, communicated and enforced.", "evidence": "Examples: defined continuing security duties in employment terms or equivalent arrangements, their communication at role change or termination, and relevant records showing enforcement where those duties apply.", "risk_text": "Former or reassigned personnel disclose or misuse information because continuing duties are unclear.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-07','Security Training Needs Are Defined by Role','Security Training Needs Are Defined by Role','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Security training needs are defined by role, based on security responsibilities, systems used and exposure. Roles with the same training needs may be grouped; a separate training plan for every job title is not required.", "evidence": "Examples: training-needs records linking roles or justified role groups to security responsibilities, systems used, exposure and required learning.", "risk_text": "Role-specific security tasks are performed incorrectly because generic training does not address the actual tools, privileges or exposure of the role.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','TRN-04','Cybersecurity Awareness Guidance Is Clear and Accessible to Employees','Cybersecurity Awareness Guidance Is Clear and Accessible to Employees','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Clear cybersecurity awareness guidance is prepared and accessible to employees. It covers the organisation''s security policies and procedures, relevant threats, safeguards in use, safe working practices, and contact points for advice and reporting concerns. Any accessible format may be used, including intranet content, training materials, videos or short instructions; a separate booklet is not required.", "evidence": "Examples: accessible awareness guidance covering current policies, procedures, relevant threats, safeguards, safe practices and advice/reporting contacts, with checks that employees can reach it.", "risk_text": "Employees improvise unsafe information handling or delay reporting concerns because usable guidance and contact information cannot be found.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.3", "A.6.3", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','TRN-02','New Employees Receive Cybersecurity Awareness Within a Risk-Appropriate Onboarding Timeframe','New Employees Receive Cybersecurity Awareness Within a Risk-Appropriate Onboarding Timeframe','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Deliver onboarding cybersecurity awareness within the organisation''s defined, risk-appropriate timeframe. Compare starter dates with completion records and follow up late or missed participation; assigning a course without its completion does not demonstrate that a new employee received the required awareness in time.", "evidence": "Examples: the organisation''s risk-appropriate onboarding timeframe, starter dates and awareness-completion records, with handling of missed or late completion.", "risk_text": "New starters expose information or follow fraudulent instructions before they have learned the essential security practices for their work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.3", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','TRN-03','Planned Awareness and Role-Based Security Training Are Delivered Regularly','Planned Awareness and Role-Based Security Training Are Delivered Regularly','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Planned Awareness and Role-Based Security Training Are Delivered Regularly. Repeat awareness activities and deliver the security training identified through TRN-07 at planned intervals. Check delivery and participation records, address missed training, and reuse evidence from the relevant operational topics rather than requiring duplicate courses.", "evidence": "Examples: planned awareness and role-based training intervals compared with actual delivery, participation and missed-training follow-up, linked to the needs identified under TRN-07. Reuse relevant operational-topic training records without requiring duplicate courses.", "risk_text": "Personnel repeat unsafe practices or cannot perform assigned security tasks because planned awareness and role-based training are not delivered or refreshed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "7.3", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','TRN-09','Transferred Employees Receive Training for New Security Skill Requirements (Applies to transfers into roles requiring security-relevant skills and expertise.)','Transferred Employees Receive Training for New Security Skill Requirements (Applies to transfers into roles requiring security-relevant skills and expertise.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Identify the new security-relevant skill requirements introduced by a role transfer and provide training that addresses them. Compare the changed duties with training content and completion; prior general awareness or training for the previous role is not sufficient evidence of coverage of the new needs. (Applies to transfers into roles requiring security-relevant skills and expertise.)", "evidence": "Where a transfer introduces new security-relevant skill needs, examples include transfer/role information, the changed needs and completion of training addressing them.", "risk_text": "Transferred personnel make security-relevant mistakes while performing unfamiliar duties, exposing information or interrupting the affected operation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex", "applicability": {"condition": "to transfers into roles requiring security-relevant skills and expertise", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','TRN-05','Training Effectiveness Is Assessed Beyond Attendance','Training Effectiveness Is Assessed Beyond Attendance','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Training Effectiveness Is Assessed, Not Inferred from Attendance. Check whether participants can apply the security knowledge and skills required for their work. For CIR-covered entities, assess the effectiveness of training for roles requiring security expertise; testing of the general awareness programme is required where appropriate. Use proportionate practical checks, exercises or other suitable assessments and address ineffective learning.", "evidence": "Examples: proportionate practical checks, exercises or other assessments showing whether participants can apply required security skills, evaluated results and responses to ineffective learning. For CIR-covered entities, include effectiveness assessment for security-expertise roles; assess general awareness where appropriate.", "risk_text": "Personnel remain unable to recognise threats or perform assigned security tasks because attendance is mistaken for effective learning and deficiencies are not corrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-AWARENESS','Personnel Understand Their Contribution to the ISMS','Personnel Understand Their Contribution to the ISMS','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T06", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "People working under the organisation''s control understand the information security policy, how their work contributes to ISMS effectiveness and improved security performance, and the implications of not meeting ISMS requirements. Reuse general and role-specific awareness activities; this is an understanding check, not an extra mandatory course.", "evidence": "Existing awareness material covering these points, with proportionate interviews or practical examples showing personnel understanding; link existing participation and evaluation records.", "risk_text": "Personnel know individual technical rules but disregard the wider security responsibilities or consequences that make the management system work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.3"], "source": "iso27001-nis2-v7", "annex": "7.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','TRN-06','Awareness and Security Training Programmes Are Kept Current','Awareness and Security Training Programmes Are Kept Current','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T06", "subgroup": "G-AWR · Awareness and staff training", "topic_label": "G-AWR · Awareness and staff training", "description": "Awareness and Security Training Programmes Are Kept Current. Review their content and delivery arrangements at planned intervals against current policies, responsibilities, technologies and relevant threats. Update the programme and associated role-based needs where these change. Topic-specific courses stay in their operational topics; this control assesses programme maintenance.", "evidence": "Examples: dated reviews of programme content and delivery at planned intervals against current policies, responsibilities, technologies and threats, with resulting updates to materials and role-based needs where necessary.", "risk_text": "Employees follow outdated cyber-hygiene advice and mishandle current threats or changed working practices.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.2','Access Rules Define Who May Use Which Resources','Access Rules Define Who May Use Which Resources','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Set access rules linking users or roles to the resources and permitted actions they need, taking business and protection needs into account; these rules provide the basis for individual access decisions.", "evidence": "Examples: access-control rules identifying which users or roles may use which resources, compared with representative permissions and the business/protection needs supporting them.", "risk_text": "Users are granted access beyond legitimate business need, allowing unauthorised disclosure, modification or deletion of information and disruption of the affected service.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["7.5.3", "A.5.15", "A.8.1", "A.8.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "7.5.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ACCESS-COORDINATION','Relevant Access-Control Arrangements Are Coordinated','Relevant Access-Control Arrangements Are Coordinated','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T07", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify security-relevant dependencies between the physical-entry, system-access and information-permission arrangements that exist within the assessed scope. Define responsibilities and decision or communication interfaces so that the related access rules and changes support business and information security requirements without unintended gaps or conflicting decisions. Verify representative cases across the relevant interfaces, including role or supplier-access changes where applicable, and resolve unjustified inconsistencies. Different permissions can be intentional and justified; coordination does not require identical rights, simultaneous removal of unrelated rights or one combined policy. Reuse C40.2, C40.3, C46.1, ACCESS-RECERT and ISMS process evidence where it already establishes the same coordination outcome; assess only the remaining gap.", "evidence": "Linked access rules, workflow definitions or equivalent records identifying the relevant dependencies, responsibilities and justified differences. Representative cases trace the intended access decision or change through the relevant interfaces to actual permissions, with records of identified inconsistencies and their resolution. Reuse existing approvals, rights reviews and process records for the same scope and period. Where no relevant change occurred, inspect the implemented arrangements and use a safe scenario rather than inventing an event. No single matrix format, combined document or additional copy of existing evidence is required.", "risk_text": "R1: A security-relevant access change is not communicated or applied at a dependent interface, leaving an unintended route to protected information or assets.<br>R2: Conflicting access decisions across relevant arrangements permit unjustified access or incorrectly prevent authorised work.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.15"], "source": "iso27001-nis2-v7", "annex": "A.5.15", "annex_kind": "annex", "applicability": {"condition": "In-scope access arrangements with security-relevant dependencies between physical entry, system access or information permissions, including dependencies involving third parties where present. Assess the interfaces that actually exist; the absence of one layer does not exclude relevant dependencies between the others. Where no security-relevant dependency exists, record a justified scope decision. Apply risk-based ISO control selection", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C40.10','User and System Identities Are Managed Throughout Their Lifecycle','User and System Identities Are Managed Throughout Their Lifecycle','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Create, maintain and retire identities for people and systems so their assignment and ownership remain clear and unnecessary identities are deactivated; the identity record is distinct from the permissions attached to it.", "evidence": "Examples: user and system identity records showing identifiable ownership and correct assignment through creation, change and retirement, compared with representative active and retired accounts.", "risk_text": "R1: Orphaned user or system accounts are used for unauthorised access, and unclear ownership delays containment.<br>R2: An account is assigned to the wrong person or technical identity, giving the wrong party access and misattributing subsequent actions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.3','Access Rights Are Approved, Updated and Removed','Access Rights Are Approved, Updated and Removed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Implement authorised access grants, changes and removals when responsibilities or access needs change, and verify the resulting permissions; planned reviews of existing rights are assessed separately under ACCESS-RECERT.", "evidence": "Examples: access decisions and their authorisation linked to implemented grants, updates and removals, compared with actual rights and current need on representative resources.", "risk_text": "R1: Unapproved or obsolete permissions are used to view or alter information after the business need has ended.<br>R2: Incorrect access updates or premature revocation prevent authorised personnel or service accounts from performing necessary tasks, interrupting legitimate operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.3", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.18", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ACCESS-RECERT','Existing Access Rights Are Reviewed Against Current Need','Existing Access Rights Are Reviewed Against Current Need','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Review the access rights of users and service accounts at planned intervals against their current business need. Modify rights following relevant organisational changes. Record the review results and required corrections, then verify that rejected or excessive rights were removed or changed. Account existence alone does not justify every assigned permission. Reuse the privileged-account review under C43.1 where it covers the same rights; do not record the same deficiency twice.", "evidence": "Dated rights listings for the reviewed users and service accounts; planned review intervals and responsible reviewers; recorded decisions on continued need; resulting changes or revocations and verification that they took effect.", "risk_text": "R1: Permissions accumulated through earlier roles or projects remain active and enable unauthorised access to or modification of information.<br>R2: A review is marked complete while permissions it rejected remain usable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.18", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C40.11','Shared Accounts Are Justified and Approved Exceptions','Shared Accounts Are Justified and Approved Exceptions','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Where an account must be shared, retain its specific justification and approval and apply safeguards for accountable use; convenience alone does not demonstrate that shared access is a justified exception.", "evidence": "Examples: identified shared accounts with specific justifications and approvals, compared with actual shared-account use and applicable accountability safeguards. Existing account metadata or decisions may suffice without a separate exception register.", "risk_text": "R1: Shared access conceals who performed an action and makes misuse harder to investigate.<br>R2: A former or reassigned user retains a shared credential and continues to access resources after their individual authorisation has ended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C43.2','Administration Uses Separate, Individually Assigned Accounts','Administration Uses Separate, Individually Assigned Accounts','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Give administrators individually assigned administrative accounts separate from their ordinary-use accounts, and use those identities for administrative work so elevated actions can be attributed to the responsible person.", "evidence": "Examples: individually assigned administrative accounts linked to their users and separate ordinary-use accounts, with safe account/usage checks demonstrating that administration uses the separate identities.", "risk_text": "R1: Compromise of a routine-use account enables privileged changes or access to protected data.<br>R2: Administrative actions cannot be reliably attributed to an individual, impairing investigation and accountability.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.2", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C43.3','Administration Systems Are Separated and Protected','Administration Systems Are Separated and Protected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Separate and protect the systems used for administration so ordinary user activity or unauthorised connections do not provide a route into the management environment; separate account names alone do not establish system separation.", "evidence": "Examples: administration-system design and operating configurations showing separation and protection, corroborated by representative access, isolation and hardening checks.", "risk_text": "Malware on an administration workstation captures privileged sessions or credentials and uses them to compromise managed systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.2", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C43.1','Privileged Access Is Regularly Checked Against Current Need','Privileged Access Is Regularly Checked Against Current Need','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "At planned intervals and following organisational changes, check whether administrators still need their privileged permissions and implement the resulting changes; reuse this evidence in ACCESS-RECERT rather than duplicating the same finding.", "evidence": "Examples: dated reviews of the privileged-account and permission population against current responsibilities, with retained decisions and implemented removal or adjustment of unnecessary rights.", "risk_text": "Obsolete or excessive administrator rights are misused to access sensitive information or alter systems beyond the holder''s current responsibilities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.18", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-EMERGENCY-AUTHORISATION','Exceptional Privileged Access Has Authorised Scope and Expiry','Exceptional Privileged Access Has Authorised Scope and Expiry','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T07", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Where exceptional privileged access is needed, define and apply the authorisation route, allowed scope and expiry. Reuse existing access provisioning and removal controls; this tests the exceptional-access decision, not a required break-glass product.", "evidence": "Exceptional-access procedure and case approvals specifying scope, authority and expiry, linked to access records. Where exceptional access is needed but has not been used, assess the defined authorisation route, authorised scope and expiry arrangements through a proportionate walkthrough or safe test. Record that there is no actual-use sample; do not require a fabricated emergency or a particular product.", "risk_text": "Emergency privilege becomes an unrestricted route to sensitive systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2", "A.5.18"], "source": "iso27001-nis2-v7", "annex": "A.8.2", "annex_kind": "annex", "applicability": {"condition": "Exceptional privileged access is used or needed; selected through risk treatment", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-EMERGENCY-REVIEW','Exceptional Privileged Sessions Receive Post-Use Review','Exceptional Privileged Sessions Receive Post-Use Review','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T07", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Review exceptional privileged use after the event against its approved purpose and resolve unauthorised activity or access left open. Reuse LOG-PRIV for the underlying activity records and C40.3 for removing access. Where exceptional access is needed but has not been used, assess post-use review readiness without representing a scenario as an actual session review.", "evidence": "Post-use review of exceptional sessions, linked activity records, exceptions and confirmed closure of temporary access. For needed but unused exceptional access, inspect the defined reviewer, review criteria, availability of suitable activity records and temporary-access closure arrangements through a proportionate walkthrough or safe test. Distinguish this readiness evidence from review of real use.", "risk_text": "Misuse during exceptional access is not detected because authorisation is mistaken for assurance of proper use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2"], "source": "iso27001-nis2-v7", "annex": "A.8.2", "annex_kind": "annex", "applicability": {"condition": "Exceptional privileged access is used or needed; selected through risk treatment", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C40.5','Remote Access Uses Approved, Encrypted Connections','Remote Access Uses Approved, Encrypted Connections','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-ACC · Identity and access control", "topic_label": "I-ACC · Identity and access control", "description": "Use organisation-approved remote-access methods that protect connections with encryption and restrict them to authorised access; assess actual connection settings, not simply whether a remote-access product is installed.", "evidence": "Examples: approved remote-access methods compared with deployed encryption, access scope and representative connection checks showing that actual remote access follows those methods.", "risk_text": "R1: Remote-access traffic or credentials are intercepted, or commands and data are altered in transit, compromising confidentiality or the integrity of remote operations.<br>R2: Unapproved or overbroad remote connections give an attacker access to internal systems.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','SUP-ACCESS-WINDOW','Service-Provider Connections Are Approved and Time-Limited (Applies where service providers connect to the entity''s network and information systems.)','Service-Provider Connections Are Approved and Time-Limited (Applies where service providers connect to the entity''s network and information systems.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-SUP-ACCESS · Time-limited service-provider connections", "topic_label": "I-SUP-ACCESS · Time-limited service-provider connections", "description": "Require an authorisation request before enabling a service-provider connection. Record the approved purpose, systems or resources and permitted time period. Close or disable the connection when that period ends, and approve any justified extension. Verify that access duration is controlled in operation; encrypted transport alone does not demonstrate this. C40.5 assesses the secure remote-access method and C51.3 assesses supplier-access visibility; reuse their records without duplicating findings. The express CIR requirement applies only within CIR scope.", "evidence": "Provider connection requests and approvals identifying resources and permitted duration; connection settings and redacted session records; expiry/closure records or safe tests; justified extension approvals. A named remote-access product is not required.", "risk_text": "R1: A supplier connection remains usable after the approved support period and provides an unnecessary path for an attacker.<br>R2: Provider access extends to systems or activities outside the approved scope and enables unauthorised disclosure or changes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.18", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.18", "annex_kind": "annex", "applicability": {"condition": "where service providers connect to the entity''s network and information systems", "condition_source": "control_name", "scope_group": "APP-SUP-ACCESS", "presentation": "inline"}}'::jsonb),
  ('ISO27001','C43.4','Privileged Utility Programs Are Restricted and Monitored','Privileged Utility Programs Are Restricted and Monitored','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "I-UTIL · Privileged utility programs", "topic_label": "I-UTIL · Privileged utility programs", "description": "Limit tools capable of bypassing normal application or system controls to authorised uses and monitor their execution, so powerful maintenance or diagnostic utilities do not become an uncontrolled route to data or settings.", "evidence": "Examples: identified privileged utilities, their access/execution restrictions and representative usage or monitoring records showing that use is limited to authorised purposes and monitored.", "risk_text": "R1: Privileged utilities bypass application safeguards to expose or modify protected data.<br>R2: Misuse of privileged utilities cannot be reconstructed, delaying attribution and containment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.2", "A.8.18"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.2", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.1','Authentication Uses Risk-Appropriate Strength','Authentication Uses Risk-Appropriate Strength','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Authentication Uses Risk-Appropriate Strength, Including Multi-Factor or Continuous Authentication. Select and enforce authentication according to the resource''s classification and access risk. Use multi-factor authentication (MFA) or continuous authentication where appropriate, explicitly assessing privileged and remote access. Where passwords are used, enforce suitable strength and reject commonly used or known-compromised passwords. A policy statement alone is not proof that the login paths enforce the selected protections.", "evidence": "Examples: authentication choices tied to resource classification and access risk, explicitly addressing privileged and remote access, with enforced settings and safe tests across relevant login paths. Where applicable, verify MFA or continuous authentication and rejection of weak, common or known-compromised passwords using non-production test credentials, not live secrets.", "risk_text": "Weak authentication allows attackers to access sensitive systems using stolen credentials.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-LOGIN-ATTEMPTS','Repeated Failed Login Attempts Are Limited','Repeated Failed Login Attempts Are Limited','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T07", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define and enforce risk-appropriate limits or other effective safeguards against repeated unsuccessful authentication attempts on relevant login paths. Verify the configured response, such as throttling, temporary blocking or additional verification, through safe tests. A universal failed-attempt count or automatic credential reset is not prescribed here. C41.8 retains the distinct CIR blocking-and-reset outcome. Reuse its evidence where the same scope and period demonstrate this protection; assess any remaining ISO login paths separately.", "evidence": "Documented login-abuse safeguards and their risk rationale; relevant identity-provider and application settings; safe test-account results showing the response to repeated failed attempts; linked records of detected abuse where available. Do not collect live passwords. Reuse C41.8 test evidence where it establishes this outcome.", "risk_text": "R1: An attacker repeatedly guesses or reuses leaked credentials without an effective restriction, obtaining unauthorised access.<br>R2: Poorly chosen blocking behaviour lets an attacker deny legitimate users access by deliberately triggering lockouts.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.5"], "source": "iso27001-nis2-v7", "annex": "A.8.5", "annex_kind": "annex", "applicability": {"condition": "In-scope login paths requiring protection against repeated unsuccessful authentication. Apply risk-based ISO control selection; do not turn CIR-specific reset behaviour into a universal ISO prescription", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C41.11','Account Setup and Recovery Do Not Bypass Authentication Security','Account Setup and Recovery Do Not Bypass Authentication Security','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Account enrolment, initial credential delivery and recovery verify the user''s entitlement and preserve the required authentication protection, so an attacker cannot gain access through a weaker setup or reset route.", "evidence": "Examples: account-enrolment, initial-delivery and recovery arrangements with redacted case records or controlled test-account demonstrations showing that identity checks and recovery paths do not bypass the required authentication protection.", "risk_text": "An attacker obtains account access through weak enrolment, initial credential delivery or recovery checks, bypassing otherwise strong login protection.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.6','Passwords and Other Authentication Secrets Are Protected','Passwords and Other Authentication Secrets Are Protected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Protect authentication secrets during allocation, storage and transmission, and conceal password entry by default with any reveal requiring deliberate user action; display masking alone does not protect stored or transmitted secrets.", "evidence": "Examples: redacted storage, transmission and access settings demonstrating protection of authentication secrets, together with synthetic-input checks showing password-entry concealment by default and reveal only through deliberate user action. Do not collect live passwords, tokens or other authentication secrets.", "risk_text": "Exposed authentication secrets, including passwords observed during entry, allow unauthorised access.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','DEVICE-LOCK','Unattended Devices Lock and Require Reauthentication','Unattended Devices Lock and Require Reauthentication','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "An unattended device prevents continued use until the user authenticates again, using the applicable locking arrangements; a device lock is distinct from terminating the application''s underlying session.", "evidence": "Examples: applicable device-lock settings and safe observation on representative devices showing locking when unattended and reauthentication before access resumes.", "risk_text": "An unauthorised person uses an unattended, unlocked device to view information or perform actions in the legitimate user''s account.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.7", "A.7.7", "A.8.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.9','Inactive Sessions End Automatically','Inactive Sessions End Automatically','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Configure a predefined inactivity period after which the authenticated session terminates and no longer authorises access; hiding the screen without ending the session does not satisfy this control.", "evidence": "Examples: inactivity termination settings and safe session tests on relevant applications showing that expired sessions no longer grant authenticated access.", "risk_text": "Another person reuses an inactive authenticated session to read information or perform actions as the legitimate user.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.7", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.7','Credentials Are Replaced or Revoked on Suspected or Confirmed Compromise','Credentials Are Replaced or Revoked on Suspected or Confirmed Compromise','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "Compromised Authentication Credentials Are Replaced or Revoked. Act on suspected or confirmed compromise by changing affected passwords and replacing or revoking other affected credentials, such as tokens or authentication certificates. Ensure the exposed credential no longer grants access and assess affected sessions through incident response.", "evidence": "Examples: redacted suspected/confirmed compromise cases or controlled exercises showing replacement or revocation of affected credentials, invalidation of their access and assessment of affected sessions through incident response. Use test credentials or metadata and do not collect exposed live secrets.", "risk_text": "An attacker continues to authenticate with an exposed password, token or other credential after the organisation becomes aware of the compromise.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.10','Authentication Methods Are Reviewed Regularly','Authentication Methods Are Reviewed Regularly','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH · Authentication", "topic_label": "J-AUTH · Authentication", "description": "At planned intervals, assess whether the authentication procedures and technologies remain appropriate for current risks and access needs, then update them or substantiate continued use; this is not a periodic credential-change check.", "evidence": "Examples: dated reviews of authentication methods against current threats, resource/access needs and relevant changes, with conclusions and implemented updates or justified continued use. Review timing and coverage should demonstrate that the methods are reviewed regularly.", "risk_text": "Authentication weaknesses become exploitable as threats or access needs change, while the organisation continues to trust outdated methods.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.12','Confidential Information Is Hidden Until Authentication Succeeds','Confidential Information Is Hidden Until Authentication Succeeds','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Prevent unauthenticated access to confidential content through the application''s relevant access paths, including direct requests where applicable; displaying a login page is insufficient if protected information remains accessible behind it.", "evidence": "Examples: unauthenticated tests using synthetic protected content across relevant pages, direct URLs, APIs and other access paths, showing that confidential information is unavailable until authentication succeeds. Corroborate with access-enforcement settings; a login screen alone is insufficient.", "risk_text": "An unauthenticated person reads protected information by bypassing the normal login screen.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.3", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.13','Initial, Default and Temporary Credentials Are Changed Before Normal Use','Initial, Default and Temporary Credentials Are Changed Before Normal Use','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Initial, Default and Temporary Credentials Are Changed Before Normal Use. Replace or change initial and temporary passwords and supplier-provided default authentication secrets through a controlled setup process. Verify that defaults no longer permit access. For credential types that are individually generated rather than shared defaults, document the applicable secure provisioning method.", "evidence": "Examples: secure setup/provisioning arrangements and redacted activation records or test-account checks showing initial, temporary and supplier-default secrets are changed before normal use and defaults no longer permit access. For individually generated credential types, inspect the documented secure provisioning method; do not collect live secrets.", "risk_text": "A person who knows an initial, temporary or supplier-default secret accesses the account or system after deployment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.8.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.14','An Approved Password Manager Is Used for Work Passwords','An Approved Password Manager Is Used for Work Passwords','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-GUARD · Login disclosure and password safeguards", "topic_label": "J-GUARD · Login disclosure and password safeguards", "description": "Use an organisation-approved password manager for work passwords and protect access to its vault and recovery process; the control assesses safe, actual use without prescribing a vendor or requiring disclosure of stored passwords.", "evidence": "Examples: the approved password-manager choice, evidence of actual use for work passwords and safe checks of vault access protections and authorised recovery arrangements. Use non-secret configuration or demonstrations, never vault exports, recovery secrets or work passwords.", "risk_text": "R1: Exposed or reused work passwords enable account compromise.<br>R2: Weak protection or recovery of a password vault exposes credentials for multiple work accounts at once.<br>R3: Loss of access to the password vault, without a usable authorised recovery route, prevents staff from retrieving credentials needed for critical work or recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-AUTH','Employees Are Trained in Password and Sign-In Security','Employees Are Trained in Password and Sign-In Security','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH-TRN · Password and remote-access training", "topic_label": "J-AUTH-TRN · Password and remote-access training", "description": "Employees receive practical instruction in protecting authentication secrets, recognising suspicious sign-in activity and following the organisation''s response rules, using examples relevant to the authentication methods they use.", "evidence": "Examples: password and sign-in instruction, relevant participation records and staff explanations or safe exercises addressing secret handling, sign-in checks and response to suspicious authentication activity.", "risk_text": "An employee discloses credentials or approves an attacker''s sign-in, defeating otherwise effective technical protection.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.17", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-REMOTE','Employees Are Trained in Secure Remote Access','Employees Are Trained in Secure Remote Access','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T07", "subgroup": "J-AUTH-TRN · Password and remote-access training", "topic_label": "J-AUTH-TRN · Password and remote-access training", "description": "Employees who use remote access are instructed in the organisation''s approved connection methods and the precautions needed when working away from its premises; the instruction follows the actual remote-access arrangements rather than prescribing a particular technology.", "evidence": "Examples: instruction in the organisation''s approved remote-access methods and precautions, relevant participation records and staff explanations or practical checks of secure connection use.", "risk_text": "Employees bypass the protected connection, trust a false connection or expose internal resources through an unauthorised access route.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.6.7", "A.7.9"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-OPERATING-PROCEDURES','Necessary Operating Procedures Are Documented and Accessible','Necessary Operating Procedures Are Documented and Accessible','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Provide usable instructions for information-processing operations where consistent execution is necessary. Cover relevant routine tasks, dependencies, exception handling and escalation. Reuse existing backup, incident, change and other runbooks; do not create one additional document per system by default.", "evidence": "Relevant operating instructions; current ownership and access; operational samples showing staff can use them.", "risk_text": "Routine operations depend on individual memory and inconsistent execution damages information or interrupts services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.37"], "source": "iso27001-nis2-v7", "annex": "A.5.37", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-NETWORK-SERVICE-REQUIREMENTS','Network Service Security and Service-Level Requirements Are Defined','Network Service Security and Service-Level Requirements Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define the security mechanisms, service levels and management requirements for in-scope network services, including internally operated services. Reuse supplier agreements where they already establish the requirements.", "evidence": "Network-service requirements and accountable owners, with applicable agreements or internal service specifications.", "risk_text": "Dependent systems rely on network-service protections or support levels that were never agreed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.21"], "source": "iso27001-nis2-v7", "annex": "A.8.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-NETWORK-SERVICE-ASSURANCE','Network Services Meet Their Defined Security Requirements','Network Services Meet Their Defined Security Requirements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Verify and monitor fulfilment of the defined network-service security arrangements. Reuse supplier reviews, network tests and capacity evidence; assess the internal-service or requirement coverage not already established there.", "evidence": "Requirement-to-evidence review of actual network service delivery, tests or service results and corrective decisions.", "risk_text": "A network service has agreed protections on paper but does not deliver them in operation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.21"], "source": "iso27001-nis2-v7", "annex": "A.8.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.5','Network Architecture Documentation Is Accurate and Current','Network Architecture Documentation Is Accurate and Current','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Maintain architecture records showing the relevant systems, zones, connections and dependencies actually deployed. Compare them with current configurations or controlled observation and trace relevant changes; a dated diagram does not establish accuracy if the running network has changed without corresponding documentation updates.", "evidence": "Examples: current network diagrams or equivalent architecture records showing relevant systems, zones, connections and dependencies, compared with deployed configurations or controlled observation. Dated revisions or change links should substantiate accuracy and currency.", "risk_text": "Responders or administrators act on an incorrect network map, overlooking an attack path or disrupting a dependency during containment or change.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.3','Secure Configurations Are Applied and Deviations Are Managed','Secure Configurations Are Applied and Deviations Are Managed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Secure configurations are applied and deviations are managed. Compare actual settings with approved security configurations throughout operation, identify deviations, and correct them or record a justified, authorised exception with appropriate safeguards.", "evidence": "Examples: approved secure configuration baselines compared with actual settings during operation, and records of deviations showing correction or justified authorised exceptions with operating safeguards.", "risk_text": "R1: Configuration drift exposes unnecessary services or weak permissions that attackers use to access systems.<br>R2: Uncontrolled configuration deviations cause service malfunction or incompatible operation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.1", "A.8.9", "A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.4','Networks Are Segmented by Risk and Protection Needs','Networks Are Segmented by Risk and Protection Needs','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Networks Are Segmented by Risk and Protection Needs. Place systems and services in defined security zones according to their function, criticality and trust level, separating critical and third-party environments where required. This control assesses the overall segmentation design and implementation; dedicated controls assess wireless separation and inbound/outbound filtering.", "evidence": "Examples: defined security zones and placement decisions based on function, criticality and trust, with configurations and safe cross-zone checks showing the intended segmentation, including critical and third-party environments where required.", "risk_text": "R1: An attacker moves from a lower-trust or third-party zone into sensitive systems and discloses or alters information.<br>R2: An infection or disruptive event propagates across insufficiently separated zones and affects otherwise unrelated services.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.22", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.12','A Demilitarised Zone Protects Incoming and Outgoing Network Communication','A Demilitarised Zone Protects Incoming and Outgoing Network Communication','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "A demilitarised zone protects communication originating from or destined to the entity''s networks.", "evidence": "Examples: DMZ architecture and deployed boundary/service configurations, corroborated by safe connection checks showing how traffic to or from the entity''s networks is protected through the intended separation.", "risk_text": "Compromise of an externally reachable service provides a direct path into internal systems, extending the breach beyond the exposed service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.22", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.10','Administration Networks and Channels Are Separated from Other Traffic','Administration Networks and Channels Are Separated from Other Traffic','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Separate administration networks and channels from operational and other traffic and verify that the intended separation is enforced by actual access and routing configurations. A separately named management VLAN alone is insufficient if ordinary traffic can bypass the intended boundary and reach administrative interfaces; assess any controlled access paths against the separation design.", "evidence": "Examples: administration-network/channel design and actual access/routing configurations, with safe checks showing separation of management traffic from operational and other traffic.", "risk_text": "An attacker on an operational or lower-trust network reaches management interfaces and makes unauthorised administrative changes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.22", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.11','Production Systems and Backups Are Separated from Development and Testing','Production Systems and Backups Are Separated from Development and Testing','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Use environment and access separation to prevent development or testing activity from compromising production systems or their backups; different environment names alone do not demonstrate an effective boundary.", "evidence": "Examples: environment and connectivity records with access/configuration checks showing that production systems and their backups are separated from development and test systems.", "risk_text": "R1: Compromise or unsafe activity in development or testing reaches production systems or recovery copies and exposes production information.<br>R2: Test activity damages production data or backups, interrupting live services or impairing recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.22", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.22", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.6','Network Access Is Restricted to Authorised Devices Where Appropriate','Network Access Is Restricted to Authorised Devices Where Appropriate','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Determine where restricting network admission to authorised devices is appropriate and enforce that restriction within the selected scope. Check that permitted devices can connect and unauthorised devices are rejected; a device list or an admission rule that is not enforced does not demonstrate restricted access.", "evidence": "Examples: the decision on where device-admission restriction is appropriate, and, for that scope, authorised-device information and safe checks showing that admission controls accept permitted devices and reject others.", "risk_text": "An unauthorised or compromised device joins the network and accesses internal resources or introduces malicious traffic.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.9','DNS and Internet Routing Follow Applicable Security Practices','DNS and Internet Routing Follow Applicable Security Practices','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Apply the DNS and Internet-routing security practices relevant to the entity''s network role and services, and check their operational configuration; do not assume that every entity operates its own DNS or routing infrastructure.", "evidence": "Examples: identification of applicable DNS and Internet-routing security practices, corresponding service/router configurations and operational checks showing those practices are applied to the entity''s role.", "risk_text": "R1: Manipulated name resolution or routing sends users and systems to an attacker-controlled destination, exposing credentials or exchanged data.<br>R2: Routing or DNS failures make legitimate services unreachable or divert their traffic.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C28.1','Protection Against Malicious and Unauthorised Software Operates','Protection Against Malicious and Unauthorised Software Operates','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-HYG · Configuration, network hygiene and malware defence", "topic_label": "G-HYG · Configuration, network hygiene and malware defence", "description": "Protection against malicious and unauthorised software operates. Prevent or detect unapproved software installation and execution on relevant systems, keep protective measures current, and investigate detections through the established security process.", "evidence": "Examples: operating controls against malicious and unapproved software, current protection status and representative installation/execution detections or safe tests. Include handling of actual detections through the established security process where they occurred.", "risk_text": "R1: Malicious or unauthorised software steals information, captures credentials or enables remote control.<br>R2: Malicious software corrupts or encrypts data and interrupts affected services.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.1", "A.8.7", "A.8.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.1", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-MALWARE-COVERAGE','Malware Protection Covers Relevant Entry Points and Channels','Malware Protection Covers Relevant Entry Points and Channels','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Identify how malicious code could enter or move through in-scope systems, including relevant email, web, removable-media, file-sharing and system-transfer paths. Confirm that each path has risk-appropriate protection. Define how encrypted traffic and archives are handled, using inspection or justified alternative safeguards where inspection is unsuitable. Assess coverage gaps rather than rescoring the operation of protection already assessed under C28.1. No particular product, number of security products or universal traffic-decryption requirement is imposed.", "evidence": "An entry-point and channel inventory linked to protective measures; representative configuration and safe test results showing covered paths; documented handling of encrypted content and archives; justified alternatives and recorded treatment of coverage gaps. Reuse existing malware, web-filter and removable-media evidence by reference.", "risk_text": "R1: Malicious code enters through an unprotected file share, transfer path or removable medium despite protection operating elsewhere.<br>R2: Encrypted or archived content bypasses the selected safeguards because neither suitable inspection nor an effective alternative has been implemented.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.7"], "source": "iso27001-nis2-v7", "annex": "A.8.7", "annex_kind": "annex", "applicability": {"condition": "In-scope systems and transfer paths for which malware protection is a necessary selected control. Assess the additional coverage outcome, not a prescribed product architecture", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','NET-FILTER','Inbound and Outbound Network Traffic Is Restricted','Inbound and Outbound Network Traffic Is Restricted','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-FLT · Network boundary filtering", "topic_label": "G-FLT · Network boundary filtering", "description": "Inbound and Outbound Network Traffic Is Restricted. Permit only justified incoming and outgoing connections through enforced rules for relevant sources, destinations, services and protocols. Block unneeded communication and verify allowed and denied paths in both directions. A named firewall product alone is not evidence that restrictions work.", "evidence": "Examples: justified rules for relevant sources, destinations, services and protocols compared with enforced configurations, plus safe allowed/denied path tests in both incoming and outgoing directions.", "risk_text": "R1: Unnecessary inbound connections expose internal services to unauthorised access.<br>R2: Unrestricted outbound paths enable data exfiltration or attacker command-and-control traffic.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-WEB-RULES','Web Access Restrictions Are Defined from Security Risk','Web Access Restrictions Are Defined from Security Risk','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine web-access restrictions needed to reduce exposure to malicious content, with justified exceptions. Select rules or categories suited to the organisation; a universal allow-list or inspection of every encrypted session is not prescribed.", "evidence": "Web-access risk rationale, defined restrictions/categories and exception authorisation arrangements.", "risk_text": "Web protection rules are arbitrary or omit the exposure that the organisation needs to reduce.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.23"], "source": "iso27001-nis2-v7", "annex": "A.8.23", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-WEB-ENFORCEMENT','Web Access Protections Enforce the Defined Restrictions','Web Access Protections Enforce the Defined Restrictions','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T08", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Implement and verify the defined protections against malicious web content. Check relevant block/allow behaviour and approved exceptions safely; the rule document alone does not demonstrate enforcement.", "evidence": "Enforced web-access settings, safe functional checks and correction of bypasses or unintended exceptions.", "risk_text": "Users reach malicious content despite documented web restrictions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.23"], "source": "iso27001-nis2-v7", "annex": "A.8.23", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','WIFI-SEG','Wi-Fi Networks Are Segregated According to Their Trust Level (Applies only where the entity operates or provides wireless networks, including managed networks.)','Wi-Fi Networks Are Segregated According to Their Trust Level (Applies only where the entity operates or provides wireless networks, including managed networks.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-WLAN · Wireless network protection", "topic_label": "G-WLAN · Wireless network protection", "description": "Wi-Fi Networks Are Segregated According to Their Trust Level. Isolate guest and other untrusted wireless access from internal organisational systems. Restrict corporate wireless access to the zones and resources justified by its security requirements. Verify the separation through connection tests; different network names alone do not demonstrate isolation. (Applies only where the entity operates or provides wireless networks, including managed networks.)", "evidence": "For operated or provided wireless networks, examples include guest/untrusted and corporate zone configurations and connection tests showing guest isolation and only justified corporate access to internal resources.", "risk_text": "A guest or compromised low-trust wireless device reaches corporate resources and accesses data or spreads an attack.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.22", "annex_kind": "annex", "applicability": {"condition": "only where the entity operates or provides wireless networks, including managed networks", "condition_source": "control_name", "scope_group": "APP-WIFI", "presentation": "inline"}}'::jsonb),
  ('ISO27001','WIFI-AUTH','Wireless Access Uses Secure Authentication and Encryption (Applies only where the entity operates or provides wireless networks, including managed networks.)','Wireless Access Uses Secure Authentication and Encryption (Applies only where the entity operates or provides wireless networks, including managed networks.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-WLAN · Wireless network protection", "topic_label": "G-WLAN · Wireless network protection", "description": "Wireless Access Uses Secure Authentication and Encryption. Protect wireless connections with authentication and encryption appropriate to their purpose and risk. Require authorised user or device authentication for corporate wireless access, disable insecure connection modes, and verify that unauthorised access is rejected. Keep guest access outside corporate access privileges. (Applies only where the entity operates or provides wireless networks, including managed networks.)", "evidence": "For operated or provided wireless networks, examples include risk-appropriate authentication/encryption settings and safe checks of corporate user/device authorisation, rejection of unauthorised access and disabled insecure modes. Check that guest access does not receive corporate privileges, without collecting wireless passwords or keys.", "risk_text": "R1: An unauthorised user or device obtains corporate wireless access through weak authentication.<br>R2: An attacker intercepts or manipulates inadequately protected wireless traffic, obtaining sensitive information or causing systems to accept altered data.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.20", "annex_kind": "annex", "applicability": {"condition": "only where the entity operates or provides wireless networks, including managed networks", "condition_source": "control_name", "scope_group": "APP-WIFI", "presentation": "inline"}}'::jsonb),
  ('ISO27001','SYS-CAP','System and Network Capacity Meets Service Needs','System and Network Capacity Meets Service Needs','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-CAP · System and network capacity", "topic_label": "G-CAP · System and network capacity", "description": "System and network capacity meets service needs. Assess current and expected processing, memory, storage and network demand against available capacity. Define thresholds, identify impending shortfalls and implement timely adjustments to avoid service disruption.", "evidence": "Examples: current and forecast processing, memory, storage and network demand compared with available capacity and defined thresholds, with records of identified shortfalls and timely implemented adjustments where needed.", "risk_text": "Demand exceeds processing, storage or network capacity, degrading or stopping services and potentially dropping queued work or records.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.6"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.6", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C38.13','Network Protections and Segmentation Are Reviewed at Planned Intervals and After Relevant Events','Network Protections and Segmentation Are Reviewed at Planned Intervals and After Relevant Events','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T08", "subgroup": "G-REVIEW · Network protection review", "topic_label": "G-REVIEW · Network protection review", "description": "Review the deployed network safeguards and segmentation at planned intervals and after significant incidents or relevant changes to operations or risks, recording necessary corrections or a supported decision that the protections remain appropriate.", "evidence": "Examples: planned review intervals and relevant-event triggers, completed reviews of network protections and segmentation, and resulting corrections or justified no-change decisions supported by relevant technical checks.", "risk_text": "R1: Changes leave obsolete network rules or ineffective zone boundaries in place, allowing unauthorised paths to persist unnoticed.<br>R2: Network changes leave legitimate service dependencies blocked by outdated filtering or segmentation rules, interrupting operations until the rules are corrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C39.1','An Applied Cryptography Policy Defines Appropriate Use','An Applied Cryptography Policy Defines Appropriate Use','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY · Cryptography policy", "topic_label": "H-CRY · Cryptography policy", "description": "The cryptography policy specifies when and how cryptographic protection is to be used and guides actual implementation choices; a policy that is published but not followed does not demonstrate this outcome.", "evidence": "Examples: the operative cryptography policy defining appropriate use in the assessed scope, compared with relevant implementation decisions and practice demonstrating its application.", "risk_text": "Inconsistent cryptographic choices leave sensitive information unprotected or falsely assumed to be protected across systems and exchanges.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','CRYPTO-INV','Cryptographic Keys and Certificates Are Inventoried','Cryptographic Keys and Certificates Are Inventoried','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-INV · Cryptographic inventory", "topic_label": "H-INV · Cryptographic inventory", "description": "Cryptographic Keys and Certificates Are Inventoried. Maintain identifiable records of relevant keys and digital certificates, their systems, purpose, responsible owners, approved storage locations, validity or usage periods and renewal responsibility. Reconcile records with actual use. Record references to securely held keys, not secret key material in the inventory. This control establishes what must be managed; C39.3 assesses the lifecycle actions.", "evidence": "Inventory or equivalent system records; owner and service mappings; expiry or usage-period tracking; reconciliation against deployed certificates and key-management systems. Do not extract private keys or other secret key material as audit evidence.", "risk_text": "R1: Unrecorded certificates expire without an identified renewal owner, interrupting dependent services.<br>R2: Compromised or obsolete keys remain in use because their locations and dependent systems cannot be identified for replacement or revocation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C39.2','Required Cryptographic Protections Are Implemented','Required Cryptographic Protections Are Implemented','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Check that the cryptographic safeguards selected for relevant information and communications are enabled and operate as intended; listing a requirement or deploying a product without the required configuration is insufficient.", "evidence": "Examples: the required cryptographic protections compared with deployed settings and safe checks demonstrating their operation on relevant data and communications. Use non-secret metadata or test data, not keys or sensitive plaintext.", "risk_text": "R1: An unauthorised party reads sensitive stored or transmitted information where required encryption is absent or ineffective.<br>R2: Altered communications or data are accepted as genuine where required integrity and authenticity protections do not operate.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C39.3','Cryptographic Keys Are Managed Throughout Their Lifecycle','Cryptographic Keys Are Managed Throughout Their Lifecycle','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Cryptographic Keys Are Managed Throughout Their Lifecycle. Protect key generation, distribution, storage and access. Set and enforce appropriate usage periods, change keys when due, and revoke or replace compromised keys. Provide secure backup and recovery where needed, renew or revoke certificates as appropriate, and securely retire and destroy keys. Verify that the lifecycle actions actually occur; identifying keys and certificates is assessed separately under CRYPTO-INV. Log significant key-management actions and audit those records as appropriate to the key-management policy.", "evidence": "Examples: redacted records and configurations covering key generation, distribution, storage/access, usage periods and due changes, compromise revocation/replacement, certificate renewal/revocation, needed backup/recovery and secure retirement/destruction. Include significant key-management action logs and their audit as appropriate to the policy; do not extract private keys or other secret key material.", "risk_text": "R1: Exposed, weak or unrevoked keys allow an attacker to decrypt information or impersonate a trusted party.<br>R2: Lost or prematurely destroyed keys, expired certificates or erroneous revocation make protected data or dependent services unavailable.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.23", "A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.23", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C39.4','Cryptographic Policies and Procedures Track the State of the Art','Cryptographic Policies and Procedures Track the State of the Art','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "topic_label": "H-CRY-IMPL · Cryptographic implementation and key lifecycle", "description": "Review cryptographic policies and procedures against relevant technical developments and current guidance, updating obsolete choices or substantiating why existing arrangements remain appropriate.", "evidence": "Examples: dated cryptographic policy/procedure reviews considering relevant current technical guidance and developments, with resulting updates or substantiated decisions that existing arrangements remain appropriate.", "risk_text": "Obsolete cryptographic algorithms or practices permit protected information to be decrypted or trusted communications to be forged.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.2','Required Routine Voice, Video and Text Communications Are Secured','Required Routine Voice, Video and Text Communications Are Secured','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "Where appropriate, use secured voice, video and text services for routine communications, with safeguards matched to their assessed protection needs; the control does not prescribe the same solution for every communication channel.", "evidence": "Examples: identified protection needs for routine voice, video and text services, compared with actual service settings and safe demonstrations showing that the required communications are secured.", "risk_text": "R1: Unauthorised parties overhear or read routine voice, video or text communications containing sensitive information.<br>R2: A forged or manipulated communication is trusted and causes an incorrect business or security action.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.14"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.5','System-to-System Channels Authenticate Endpoints and Protect Data','System-to-System Channels Authenticate Endpoints and Protect Data','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "System-to-system communication uses trusted channels with authenticated endpoints and protected data. Within CIR scope, verify that the trusted channels are isolated from other communication channels using logical, cryptographic or physical separation. This isolation requirement is additional to endpoint identification and protection against data modification or disclosure.", "evidence": "Examples: system-to-system endpoint-authentication and trusted-channel settings, with safe connection/message checks demonstrating peer authentication and required data protection, including rejection of untrusted peers where relevant. Within CIR scope, include configurations or safe checks demonstrating logical, cryptographic or physical separation of the trusted channels from other communication channels.", "risk_text": "R1: A system connects to an impersonated endpoint and discloses data or credentials.<br>R2: Messages between systems are altered or replayed, causing unauthorised transactions or incorrect processing.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.14", "A.8.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C41.3','Secure Emergency Communications Remain Usable When Needed','Secure Emergency Communications Remain Usable When Needed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T09", "subgroup": "J-COM · Secure routine and emergency communications", "topic_label": "J-COM · Secure routine and emergency communications", "description": "Where appropriate, provide secure emergency communications that remain usable during the relevant disruption scenarios, including loss of normal channels; having contact details alone does not establish an available communication route.", "evidence": "Examples: secured emergency communication arrangements and controlled exercises or actual-use records demonstrating availability when needed, including relevant disruption of normal channels.", "risk_text": "R1: Failure of emergency communication channels delays coordination and protective decisions during an incident.<br>R2: Responders fall back to untrusted channels and expose sensitive incident information or act on impersonated instructions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.29", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-PROJECT-RISKS','Non-Development Projects Assess Information Security Risks through Delivery','Non-Development Projects Assess Information Security Risks through Delivery','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T10", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Assess and revisit information security risks in relevant business or organisational projects from initiation through delivery. Apply this only to the project population not already assessed by the shared development/acquisition controls.", "evidence": "Relevant project inventory, lifecycle risk assessments and treatment decisions linked to business-project changes.", "risk_text": "A business project introduces unassessed information exposure because security reviews focus only on IT development.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.8"], "source": "iso27001-nis2-v7", "annex": "A.5.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-PROJECT-REQUIREMENTS','Non-Development Projects Implement Their Security Requirements','Non-Development Projects Implement Their Security Requirements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T10", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "For those business or organisational projects, identify applicable security requirements, assign delivery responsibility and verify fulfilment before the relevant acceptance decision. Reuse the legal register and underlying safeguard evidence.", "evidence": "Project requirements, responsible owners and security acceptance evidence linked to the identified risks and obligations.", "risk_text": "Project risks are assessed but the required protections are not delivered before business change takes effect.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.8"], "source": "iso27001-nis2-v7", "annex": "A.5.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-01','Required Security Features Are Defined Before Acquisition or Development','Required Security Features Are Defined Before Acquisition or Development','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Required Security Features Are Defined Before Buying or Developing a System. State what the system must protect and which security functions it must provide, based on its intended use, data, interfaces and risks. Put these requirements into the purchasing or development specifications and applicable supplier requirements. For example, specify who may access patient records and which access events must be logged.", "evidence": "Examples: dated purchasing/development specifications or equivalent requirement records defining protection needs and security functions from intended use, data, interfaces and risks, with applicable requirements communicated to suppliers before acquisition or development.", "risk_text": "An acquired system cannot provide the protections required for its intended data and service context, exposing information or forcing costly changes before safe use.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.8", "A.8.26"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-02','Proposed System Designs Are Checked Against Security Requirements','Proposed System Designs Are Checked Against Security Requirements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "The Proposed System Design Is Checked Against the Security Requirements. Before accepting the proposed design, check whether its architecture, integrations and planned configuration can meet the requirements defined under D04-01. For example, check that the proposed access model restricts patient records to authorised users and that the design provides the required logging. Resolve material gaps or document justified treatment decisions. For a ready-made product, assess the available solution and deployment design; this does not require unrestricted access to the supplier''s internal design.", "evidence": "Examples: a design-stage comparison against D04-01 requirements covering architecture, integrations and planned configuration, with decisions resolving material gaps or justifying treatment before design acceptance. For ready-made products, available solution and deployment-design information may suffice.", "risk_text": "A design with unsafe trust boundaries or incompatible integrations is accepted, embedding an access or resilience weakness that is expensive to correct after delivery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.26", "A.8.27"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.26", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-10','Component Information Identifies Products and Dependencies in Security-Relevant Acquisitions','Component Information Identifies Products and Dependencies in Security-Relevant Acquisitions','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "For security-relevant acquisitions, the entity obtains and maintains sufficient information about the hardware and software components to identify affected products and dependencies when security issues arise.", "evidence": "For security-relevant acquisitions, examples include maintained component/version and dependency information sufficient to identify affected products when security issues arise, compared with representative deployed acquisitions.", "risk_text": "A vulnerable component or dependency cannot be matched to the acquired product, delaying identification and treatment of affected systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-11','Security-Relevant Acquisitions Include Usable Security and Configuration Information','Security-Relevant Acquisitions Include Usable Security and Configuration Information','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "For security-relevant acquisitions, the entity obtains usable information about security functions and the configuration required to operate the product or service securely.", "evidence": "For security-relevant acquisitions, examples include usable supplier documentation or equivalent information describing security functions and the configuration needed for secure operation, matched to the acquired product/service.", "risk_text": "Operators deploy or run a product with insecure settings because its security functions and configuration needs are not understood.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.37"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.37", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-12','Security-Update Support Commitments and End Dates Are Tracked','Security-Update Support Commitments and End Dates Are Tracked','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Security-update support commitments and support end dates are known and tracked for relevant products and services, so that gaps in supported operation are identified in time.", "evidence": "Examples: relevant supplier security-update commitments and support end dates in agreements, service records or equivalent tracking information, with checks identifying approaching or existing support gaps.", "risk_text": "Security support ends unnoticed, leaving deployed products exposed to vulnerabilities for which updates are no longer available.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-03','Security Acceptance Confirms Delivered Systems Meet Requirements','Security Acceptance Confirms Delivered Systems Meet Requirements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Security Acceptance Confirms That the Delivered System Meets the Requirements. Before the system or release goes live, review test results and other suitable evidence showing that the required protections actually work. For example, verify that an unauthorised test account cannot open a patient record and that the required log is produced. Record the acceptance decision, treatment of material findings and any unresolved conditions. This is the decision to accept the delivered system, not the earlier review of its proposed design.", "evidence": "Examples: the pre-go-live acceptance decision linked to the delivered system/release, defined requirements and tests or other evidence that the required protections work, including material-finding treatment and unresolved conditions.", "risk_text": "A delivered system goes live with ineffective required safeguards because acceptance relies on promises rather than working evidence, exposing live data or services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.8", "A.8.26", "A.8.29"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-13','Products Near or Beyond Support End Have Implemented Lifecycle Decisions','Products Near or Beyond Support End Have Implemented Lifecycle Decisions','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-ACQ · Acquisition and lifecycle", "topic_label": "E-ACQ · Acquisition and lifecycle", "description": "Products approaching or reaching the end of security support have an implemented lifecycle decision, with a responsible owner, a replacement or migration schedule and justified interim safeguards where needed.", "evidence": "Examples: identified products approaching or beyond security-support end, with implemented lifecycle decisions, responsible owners, replacement/migration schedules and evidence of justified interim safeguards where needed.", "risk_text": "R1: Unsupported systems remain in use without effective interim protection or a feasible migration path, extending exposure to exploitable vulnerabilities.<br>R2: A rushed replacement of unsupported technology disrupts dependent services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-04','Relevant Secure-Development Rules Are Established Before Development and Applied (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Relevant Secure-Development Rules Are Established Before Development and Applied (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Secure-development rules are established before development starts, cover the relevant lifecycle stages and responsible roles, and are used in both internal and outsourced development projects.", "evidence": "Where development is in scope, examples include secure-development rules established before work starts, covering relevant lifecycle stages and roles, with project records showing application to internal and outsourced development as applicable.", "risk_text": "Development teams omit security activities or apply inconsistent practices, allowing recurring design or implementation weaknesses into releases.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.25"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.25", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-23','Outsourced Development Follows Acquisition and Supply-Chain Security Processes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Outsourced Development Follows Acquisition and Supply-Chain Security Processes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Outsourced development is included in the entity''s acquisition and supply-chain security processes, with applicable requirements and responsibilities communicated to and agreed with the development provider.", "evidence": "Where development is outsourced, examples include agreed security requirements and responsibilities in contracts or equivalent arrangements, with evidence of their communication and inclusion in acquisition and supply-chain processes.", "risk_text": "An external developer omits required safeguards or leaves responsibilities unresolved, delivering software with unaddressed weaknesses or exposing entrusted information.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.30", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-14','System Architecture Prevents Unauthorised Access and Limits Attacks (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','System Architecture Prevents Unauthorised Access and Limits Attacks (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "System Architecture Is Designed to Prevent Unauthorised Access and Limit Attacks. Apply secure-engineering principles when deciding how components connect, where sensitive data are held and how access crosses system boundaries. For example, a patient-record database is reachable only through authorised application paths, not directly from the Internet. Record design decisions and assess and address material departures from the principles. This control assesses the security of the architecture, not the way individual code functions are written.", "evidence": "Where development is in scope, examples include architecture decisions showing secure component connections, sensitive-data placement and controlled trust-boundary access, with assessment and treatment of material departures from secure-engineering principles.", "risk_text": "An unsafe system architecture exposes sensitive components or permits an attacker to cross trust boundaries and compromise additional functions.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.27"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.27", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-16','Development Repository Changes Are Authorised, Traceable and Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Development Repository Changes Are Authorised, Traceable and Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Access and change permissions to development repositories restrict code modification to authorised persons and processes, with traceable changes and appropriate protection of release-relevant branches.", "evidence": "Where development is in scope, examples include repository permissions, change histories and protection of release-relevant branches, with checks that only authorised persons/processes can modify code.", "risk_text": "Unauthorised changes to source code or release branches enter a trusted release, introducing malicious behaviour or disabling safeguards.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.4", "A.8.31"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.4", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-SOURCE-READ','Read Access to Source Code and Development Resources Is Restricted','Read Access to Source Code and Development Resources Is Restricted','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T10", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Restrict reading and extraction of source code, libraries and development resources to authorised needs. Review relevant access and external sharing. Reuse D04-16 for modification and release-branch protection; write protection alone does not protect confidential source code.", "evidence": "Repository and development-tool read permissions; external sharing settings; owner approvals and review records.", "risk_text": "Unauthorised readers obtain confidential code or development knowledge even though they cannot modify it.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.4"], "source": "iso27001-nis2-v7", "annex": "A.8.4", "annex_kind": "annex", "applicability": {"condition": "The organisation holds or controls access to source code or development resources", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-18','Development, Build and Deployment Secrets Are Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Development, Build and Deployment Secrets Are Protected (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Credentials, tokens and signing secrets used for development, build or deployment are stored and exposed only to authorised users and processes, with appropriate handling when they are no longer valid or are suspected to be compromised.", "evidence": "Where development is in scope, examples include redacted secret-storage, access and exposure settings for development/build/deployment, plus metadata showing appropriate handling of invalid or suspected-compromised secrets. Use synthetic demonstrations where useful; never collect live credentials, tokens or signing secrets.", "risk_text": "Exposed development, deployment or signing secrets let an attacker impersonate trusted automation, access systems or distribute apparently authentic malicious releases.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.4", "A.8.28"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.4", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-15','Software Is Written Using Secure Coding Practices (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Software Is Written Using Secure Coding Practices (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Software Is Written Using Secure Coding Practices. Apply coding rules that prevent relevant vulnerabilities, such as checking access rights for each requested patient record and using parameterised database queries to prevent SQL injection. Use code review or analysis to identify violations and correct material weaknesses before release, with any unresolved findings subject to a justified treatment and release decision. This control assesses how software functions are implemented, not the overall system architecture.", "evidence": "Where development is in scope, examples include applicable coding rules, representative code-review or analysis results and corrected material weaknesses before release, with justified treatment/release decisions for unresolved findings.", "risk_text": "R1: An attacker exploits coding flaws to read or modify data without authorisation.<br>R2: Software defects cause incorrect processing or service failure even without an attack.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.28"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.28", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-17','Build and Deployment Processes Prevent Unauthorised Changes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Build and Deployment Processes Prevent Unauthorised Changes (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Build and deployment processes prevent unauthorised changes to pipeline configuration, build inputs and release actions, with permissions and execution records appropriate to the development risks.", "evidence": "Where development is in scope, examples include pipeline and build-input permissions, change protections and execution records showing that configuration changes and release actions are authorised, proportionate to development risks.", "risk_text": "An attacker alters build inputs, pipeline configuration or deployment actions to distribute a compromised release or change production without authorisation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.25"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.25", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-20','Test Data Selection Reflects Purpose, Sensitivity and Necessity (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Test Data Selection Reflects Purpose, Sensitivity and Necessity (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test datasets are selected for the testing purpose and assessed for sensitivity and necessity before use, avoiding unnecessary use of live sensitive information.", "evidence": "Where development is in scope, examples include test-dataset selection decisions made before use, linking purpose to sensitivity and necessity and showing why any live sensitive information is needed. Inspect descriptions or protected samples rather than exporting live datasets.", "risk_text": "R1: Unnecessary live sensitive data are copied into testing, exposing more people and records if the test environment is accessed or shared improperly.<br>R2: Unrepresentative test data omit relevant formats, relationships or boundary conditions, allowing defects that affect real operations to pass testing.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.33", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-TEST-SELECTION','Non-Development Test Information Is Selected and Authorised for Its Purpose','Non-Development Test Information Is Selected and Authorised for Its Purpose','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T10", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "For testing outside in-house or commissioned development, select information suited to the test purpose and assess its sensitivity and necessity before use. Obtain appropriate authorisation for using live or sensitive information and prefer suitable synthetic or sanitised data when they meet the need. Examples include testing an acquired application, a configuration change or a recovery procedure. D04-20 remains the assessment for development test-data selection; do not ask for a second answer for that population.", "evidence": "Non-development test plans, dataset-selection and sensitivity decisions, authorisation for live data where needed, and traceability to the tested system and purpose. Use descriptions or protected demonstrations rather than copying live datasets.", "risk_text": "R1: Sensitive production information is unnecessarily exposed in operational testing.<br>R2: Unsuitable test information fails to represent important operational conditions, allowing a defective change or recovery procedure to appear successful.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "annex": "A.8.33", "annex_kind": "annex", "applicability": {"condition": "Test information is used outside the development population already covered by D04-20", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-22','Risk-Justified Test Data Sanitisation and Anonymisation Are Verified Before Use (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Risk-Justified Test Data Sanitisation and Anonymisation Are Verified Before Use (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test data undergo the sanitisation and anonymisation justified by the risk assessment, and the resulting data are checked to confirm the claimed protection before use.", "evidence": "Where development is in scope, examples include the risk-based sanitisation/anonymisation choice and pre-use validation results demonstrating the claimed protection of the resulting test data. Use controlled samples and do not infer anonymity from pseudonymisation alone.", "risk_text": "Data claimed to be sanitised or anonymised still contain identifiable or recoverable sensitive values, leading to disclosure when treated as safe test data.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.11", "A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.11", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-21','Test Data Are Protected Throughout Their Lifecycle (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Test Data Are Protected Throughout Their Lifecycle (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Test data are protected throughout storage, access, transfer and disposal, with access limited to the relevant test participants and retention appropriate to the testing need.", "evidence": "Where development is in scope, examples include test-data access, storage, transfer and disposal safeguards compared with actual participant permissions and the testing need, with representative records or checks of retention and disposal.", "risk_text": "Unauthorised test participants or later recipients obtain sensitive test data during storage, transfer or after the testing need ends.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.33", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-TEST-PROTECTION','Non-Development Test Information Is Protected Until Secure Removal','Non-Development Test Information Is Protected Until Secure Removal','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T10", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Protect information used in non-development tests during copying, storage, access, transfer and disposal. Apply and check the sanitisation or masking justified for the dataset, restrict use to authorised test participants and remove unnecessary copies after the approved need ends. Reuse existing access, masking and deletion evidence. Identical test and production permissions are not required. Development datasets remain under D04-21 and D04-22.", "evidence": "Non-development dataset access and storage safeguards, checks of selected masking or sanitisation, approved retention and removal records, and evidence covering transferred copies. Use synthetic or redacted samples.", "risk_text": "Unauthorised people obtain sensitive test information through excessive access, ineffective sanitisation or retained copies after an operational test ends.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.33"], "source": "iso27001-nis2-v7", "annex": "A.8.33", "annex_kind": "annex", "applicability": {"condition": "Test information is used outside the development population already covered by D04-21 and D04-22", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-19','Risk-Appropriate Security Tests Are Performed During Development and Before Release Acceptance (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','Risk-Appropriate Security Tests Are Performed During Development and Before Release Acceptance (Applies only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-DEV · Internal and commissioned development", "topic_label": "E-DEV · Internal and commissioned development", "description": "Relevant security tests are performed during development and before release acceptance using a scope and method appropriate to the system''s risks, and their results identify the tested version and findings.", "evidence": "Where development is in scope, examples include risk-appropriate security test scope/methods and retained results from development and before release acceptance, identifying the tested version and findings.", "risk_text": "Security defects remain undetected until after release because tests do not cover relevant attack paths or the findings refer to a different version.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.29", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.29", "annex_kind": "annex", "applicability": {"condition": "only to relevant in-house or commissioned development activities; buying and using an unchanged ready-made product alone does not activate this group", "condition_source": "control_name", "scope_group": "APP-DEV", "presentation": "inline"}}'::jsonb),
  ('ISO27001','D04-06','Planned Changes Undergo Security and Service Impact Assessment Before Implementation','Planned Changes Undergo Security and Service Impact Assessment Before Implementation','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Before a planned change is implemented, its potential security and service impacts are assessed using the relevant dependencies and risks, and the required safeguards are identified.", "evidence": "Examples: assessments completed before planned changes, identifying affected dependencies, potential security/service impacts, relevant risks and required safeguards, linked to the proposed change.", "risk_text": "A change unexpectedly weakens a security boundary or breaks a dependent service because its effects were not assessed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','CHG-ROLLBACK','Failed Changes Have a Defined Rollback or Recovery Method','Failed Changes Have a Defined Rollback or Recovery Method','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Failed Changes Have a Defined Rollback or Recovery Method. Before implementing a change, determine how safe operation will be restored if it fails. Identify the required previous configurations, backups or other recovery resources, responsible people and conditions for starting recovery. Confirm that the necessary resources are usable and that the method is appropriate to the change''s risk. Where reversal is impossible, define an alternative recovery method rather than assuming that every change can be undone.", "evidence": "Change-specific rollback or alternative recovery instructions; responsibility and activation criteria; usable configuration copies or backups; relevant validation or test results proportionate to the risk.", "risk_text": "A failed change cannot be reversed or otherwise recovered safely, extending service interruption or leaving damaged data and configuration in use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-07','Planned Operational Changes Undergo Risk-Appropriate Testing Before Implementation','Planned Operational Changes Undergo Risk-Appropriate Testing Before Implementation','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Planned operational changes are tested before implementation to an extent justified by their risks, and the recorded results support the decision to proceed or revise the change.", "evidence": "Examples: pre-implementation test scope justified by the planned change''s risks, recorded results and the resulting decision to proceed or revise the change.", "risk_text": "A defective or incompatible operational change reaches production and disrupts services or disables a required safeguard.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','CHG-AUTH','Changes Are Authorised Before Implementation','Changes Are Authorised Before Implementation','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Changes Are Authorised Before Implementation. Obtain approval from an authorised person before implementing a planned operational change. The approval identifies the change, its permitted scope and the decision-maker, taking account of the impact assessment and relevant test results. Where an emergency prevents the normal route, use the defined emergency authorisation process and record any exceptional departure and subsequent review.", "evidence": "Change request; named approval authority; approval time preceding planned implementation; approved scope matched to execution records; emergency authorisation or exception and review records where applicable.", "risk_text": "An unauthorised change bypasses accountable risk decisions and introduces an unsafe or disruptive production state.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.19", "A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-05','Security-Relevant Changes and Their Outcomes Are Recorded','Security-Relevant Changes and Their Outcomes Are Recorded','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "Security-relevant software, hardware and configuration changes are recorded with their scope, responsible person, timing and implementation outcome so that the changed state can be reconstructed.", "evidence": "Examples: software, hardware and configuration change histories identifying scope, responsible person, timing and implementation outcome, sufficient to reconstruct the changed state.", "risk_text": "Investigators or operators cannot reconstruct a changed system state, delaying fault diagnosis, incident scoping or recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.9", "A.8.19", "A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.9", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-24','Emergency Change Records Explain Actions, Outcomes and Procedural Departures','Emergency Change Records Explain Actions, Outcomes and Procedural Departures','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T10", "subgroup": "E-CHG · Operational changes", "topic_label": "E-CHG · Operational changes", "description": "When an emergency prevents the normal change procedure from being followed, the change record documents what was done, its result and why the normal steps could not be followed.", "evidence": "Where an emergency prevents normal change steps, examples include the change record showing what was done, its result and why the normal steps could not be followed.", "risk_text": "An emergency change leaves an undocumented unsafe state that later operators cannot assess or reverse reliably.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.32"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.32", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-08','Vulnerability Reports and Advisories Are Tracked and Disclosure Coordinated Where Needed','Vulnerability Reports and Advisories Are Tracked and Disclosure Coordinated Where Needed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability Reports and Advisories Are Tracked and Disclosure Is Coordinated Where Needed. Provide a usable contact for reports about vulnerabilities in the organisation''s systems or products. Actively follow relevant supplier, authority and Computer Security Incident Response Team (CSIRT) information channels, and review whether those sources remain relevant. Record received reports and actionable threat or vulnerability advisories, and route them to a responsible assessment or response handler. Where coordinated disclosure is relevant, coordinate handling and the timing and content of disclosure with affected suppliers, reporters and other appropriate parties through a defined procedure consistent with applicable coordinated-disclosure policies. Receiving reports alone does not satisfy active advisory monitoring; not every vulnerability requires public disclosure.", "evidence": "Working reporting contact; received reports and handler assignments; relevant advisory sources and their periodic relevance checks; evidence of active monitoring and actionable advisories routed to assessment or response; correspondence and decisions on coordinated handling and disclosure where relevant. A lack of public disclosure alone is not a failure where disclosure is not relevant.", "risk_text": "R1: Actionable reports or advisories fail to reach assessment, allowing a known vulnerability to be exploited before treatment.<br>R2: Poorly coordinated disclosure exposes affected users before protective action is ready or delays information they need to protect themselves.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.7", "A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-SECURITY-FORUMS','Relevant Security Forums and Specialist Contacts Are Maintained','Relevant Security Forums and Specialist Contacts Are Maintained','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T11", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Maintain useful contact with relevant specialist security groups, forums or professional associations. Select channels suited to the organisation; paid membership or joining a statutory voluntary sharing arrangement is not universally required.", "evidence": "Selected contacts or channels; responsible participants; examples of relevant information received or exchanged.", "risk_text": "Relevant expertise and security developments are missed, delaying informed security decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.6"], "source": "iso27001-nis2-v7", "annex": "A.5.6", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-THREAT-SOURCES','Threat Intelligence Sources Are Selected for Organisational Relevance','Threat Intelligence Sources Are Selected for Organisational Relevance','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T11", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Select and review internal and external sources relevant to the organisation''s threats and operations, including wider attacker activity where relevant. Reuse vulnerability advisory feeds; this tests source suitability, not subscription volume.", "evidence": "Source-selection rationale, collection responsibilities and reviews of source relevance and reliability.", "risk_text": "Threat analysis relies on irrelevant or unreliable sources and misses the threats affecting the organisation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.7"], "source": "iso27001-nis2-v7", "annex": "A.5.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-THREAT-ANALYSIS','Threat Information Is Analysed and Delivered as Actionable Intelligence','Threat Information Is Analysed and Delivered as Actionable Intelligence','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T11", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Analyse collected threat information in the organisation''s context and deliver actionable conclusions to appropriate risk, monitoring or response owners. A feed subscription or forwarded advisory alone is not analysis.", "evidence": "Dated threat assessments tied to operations and assets, delivered conclusions and resulting decisions or justified no-action outcomes.", "risk_text": "Relevant threat information is collected but never informs protective or response decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.7"], "source": "iso27001-nis2-v7", "annex": "A.5.7", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-25','Vulnerability Scans and Reviews Are Risk-Appropriate and Operationally Safe','Vulnerability Scans and Reviews Are Risk-Appropriate and Operationally Safe','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability identification uses risk-appropriate scans or reviews over the required system scope, with planned intervals where applicable and retained results; methods are safe for operational, OT and clinical systems.", "evidence": "Examples: risk-appropriate vulnerability scan/review scope, planned intervals where applicable and retained results demonstrating required system coverage, with methods and precautions suitable for operational, OT or clinical systems where present.", "risk_text": "R1: Undetected vulnerabilities remain exploitable on systems omitted from or inadequately covered by scanning and review.<br>R2: An unsafe vulnerability-identification activity disrupts a sensitive operational, clinical or OT system.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-26','Vulnerabilities Are Matched to Actual Products, Configurations and Exposure','Vulnerabilities Are Matched to Actual Products, Configurations and Exposure','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Identified or reported vulnerabilities are matched to the entity''s actual products, versions, configurations and exposure so that affected and unaffected systems are distinguished with reasons.", "evidence": "Examples: vulnerability assessments linked to actual products, versions, configurations and exposure, with affected/unaffected decisions and supporting reasons for representative systems.", "risk_text": "R1: An affected system is incorrectly considered unaffected, leaving an exploitable vulnerability untreated.<br>R2: An unaffected system receives unnecessary disruptive remediation because product, version or exposure information is misinterpreted.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-27','Vulnerability Treatment Priorities Reflect Operational Impact, Exposure and Existing Protections','Vulnerability Treatment Priorities Reflect Operational Impact, Exposure and Existing Protections','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability treatment priorities reflect the entity''s operational impact, exposure and existing protections, and identify vulnerabilities critical to operations for action without undue delay where CIR applies.", "evidence": "Examples: treatment priorities linked to operational impact, exposure and existing protections, identifying operationally critical vulnerabilities and their routing for action without undue delay where CIR applies.", "risk_text": "Resources are directed to less consequential vulnerabilities while exposed, operationally important weaknesses remain available to attackers.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-28','Vulnerabilities Are Remediated Within Appropriate Timeframes','Vulnerabilities Are Remediated Within Appropriate Timeframes','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerabilities Are Remediated Within Appropriate Timeframes. Assign a responsible person and a risk-based target date for each required remediation. Apply patches or other treatments through the defined change process, and record the affected systems and implementation outcome. Implement treatment according to the justified priority and timing, including impact-justified mitigation plans and applicable CIR requirements for prompt critical treatment and timely patching. An internal target date does not override an applicable legal timing requirement.", "evidence": "Examples: required remediation actions with responsible persons and justified risk-based target dates, linked to change records, affected systems and actual implementation outcomes. Compare priority and elapsed time with applicable prompt-treatment/patching requirements, including impact-justified mitigation plans where relevant and handling of delays.", "risk_text": "Attackers exploit a known vulnerability while required remediation is delayed, abandoned or only recorded as complete without being implemented.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-31','Compensating Controls Protect Systems with Unpatched Vulnerabilities','Compensating Controls Protect Systems with Unpatched Vulnerabilities','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Compensating Controls Protect Systems with Unpatched Vulnerabilities. When a patch is unavailable or not applied, implement and maintain alternative safeguards appropriate to the vulnerability, such as restricting access, isolating the affected system or disabling the vulnerable function. Base residual-risk decisions on the safeguards actually operating, not merely on planned actions; these controls do not waive applicable remediation obligations.", "evidence": "For unpatched vulnerabilities, examples include implemented alternative safeguards mapped to the affected attack paths, with current configuration/operational checks and residual-risk decisions based on those operating protections.", "risk_text": "An attacker reaches and exploits an unpatched vulnerable function because assumed compensating safeguards do not actually restrict the attack path.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-30','Decisions Not to Remediate Vulnerabilities Are Justified and Assigned to Accountable Owners','Decisions Not to Remediate Vulnerabilities Are Justified and Assigned to Accountable Owners','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Decisions not to remediate or patch a vulnerability are substantively justified, assigned to an accountable owner and supported by authorised residual-risk acceptance where required; acceptance does not override a binding duty.", "evidence": "Examples: substantive decisions not to patch or otherwise remediate, identifying affected vulnerabilities, reasons and accountable owners, with authorised residual-risk acceptance where required and consideration of applicable binding duties.", "risk_text": "A vulnerability is left exposed on the basis of an uninformed or unauthorised exception, and treatment is deferred beyond what accountable owners intended.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-32','Vulnerability Exceptions Are Reassessed When Due or Conditions Change','Vulnerability Exceptions Are Reassessed When Due or Conditions Change','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-VUL · Vulnerability management", "topic_label": "E-VUL · Vulnerability management", "description": "Vulnerability exceptions have a justified expiry or review date and are reassessed when due or when relevant conditions change, including patch availability, exposure or the effectiveness of interim safeguards.", "evidence": "Examples: vulnerability exceptions with justified expiry or review dates and completed reassessments when due or when relevant conditions change, covering patch availability, exposure and interim-safeguard effectiveness.", "risk_text": "An exception outlives its justification after exposure, patch availability or safeguards change, leaving an increasingly exploitable system untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-35','Security Patches Come from Verified or Trusted Sources','Security Patches Come from Verified or Trusted Sources','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patches are obtained through verified supplier or otherwise trusted distribution channels, with the package''s origin traceable before installation.", "evidence": "Examples: verified supplier or other trusted distribution-channel information and patch retrieval/provenance records showing the package''s origin was traceable before installation.", "risk_text": "A counterfeit update obtained from an untrusted source installs malicious code with the privileges of the update process.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-36','Security Patch Integrity Is Verified Before Installation','Security Patch Integrity Is Verified Before Installation','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patch integrity is verified before installation using a trusted verification mechanism, and failed or unverifiable packages are not accepted as validated updates.", "evidence": "Examples: trusted signature, hash or equivalent integrity-verification results before installation, together with records or safe tests showing failed/unverifiable packages are not accepted as validated updates.", "risk_text": "A modified or corrupted update package is installed as legitimate, introducing malicious changes or breaking the target system.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D04-34','Security Patches Are Tested Before Production Deployment','Security Patches Are Tested Before Production Deployment','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T11", "subgroup": "E-PAT · Security patches", "topic_label": "E-PAT · Security patches", "description": "Security patches are tested before production application using a method appropriate to the affected system, and the recorded results support the deployment decision.", "evidence": "Examples: pre-production patch-test methods appropriate to the affected systems, retained results and their linkage to the deployment decision.", "risk_text": "An incompatible or faulty security patch interrupts production or breaks a required security function.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','MON-RISK','Monitoring Needs Are Determined Through Risk Assessment','Monitoring Needs Are Determined Through Risk Assessment','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Monitoring Needs Are Determined Through Risk Assessment. Assess the systems, services, relevant threats, exposure and potential service impact to determine what security monitoring is needed. Record which systems and events require monitoring, the necessary detection coverage, monitoring frequency and degree of automation, and the capabilities needed from tools or services. Existing risk-assessment records may be used if they explicitly support these monitoring decisions; a separate risk report is not required. This control assesses the justified monitoring requirements, not their implementation.", "evidence": "Risk assessment identifying relevant threats and service impact; a traceable mapping to monitored systems/events, detection needs, monitoring frequency and automation/tool capability decisions. Existing risk records are acceptable if this link is explicit.", "risk_text": "Monitoring requirements overlook a relevant system or attack path, allowing compromise to persist in an unobserved area.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','MON-BASE','Normal System Behaviour and Alert Thresholds Are Defined','Normal System Behaviour and Alert Thresholds Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Normal System Behaviour and Alert Thresholds Are Defined. Establish relevant normal operating patterns and justified alert criteria for monitored systems, based on their purpose and assessed risks. Configure suitable thresholds or other detection conditions, allowing for legitimate variations and changes. Record why a deviation warrants investigation; a statistical baseline or numerical threshold is not necessary for every detection rule. This control assesses the reference patterns and alarm criteria, not the risk assessment or testing of detection effectiveness.", "evidence": "Documented normal operating patterns and justified alarm conditions; configured thresholds or rules, legitimate exceptions and relevant change records.", "risk_text": "R1: Detection criteria treat malicious deviations as normal, delaying investigation.<br>R2: Excessive or misleading alerts consume analyst attention and obscure significant events.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-01','Monitoring Is Implemented According to the Risk Assessment','Monitoring Is Implemented According to the Risk Assessment','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET · Operational monitoring and detection checks", "topic_label": "B-DET · Operational monitoring and detection checks", "description": "Monitoring Is Implemented According to the Risk Assessment. Configure and operate monitoring to meet the requirements established under MON-RISK, covering the selected systems, events, detection needs and frequency. Demonstrate that the chosen tools or services produce usable information for detecting and investigating suspected incidents. Record and address gaps between assessed needs and actual coverage. No particular SIEM or other named product is universally required; applicable CIR duties, including automation to the extent feasible, still apply. This control assesses actual operation, not the existence of a risk assessment alone.", "evidence": "Operational configurations, coverage records and monitoring outputs demonstrating that the assessed requirements are implemented; recorded coverage gaps and actions. A purchased licence or approved plan alone does not demonstrate operation.", "risk_text": "An attack remains undetected because the required monitoring coverage is not operating or does not produce usable information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.6','System Clocks Are Synchronised to Approved Time Sources','System Clocks Are Synchronised to Approved Time Sources','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "System Clocks Are Synchronised to Approved Time Sources. Use suitable approved time sources for relevant systems, check for clock drift and correct deviations that could impair event correlation. Restrict changes to time settings and monitor relevant time-source configuration changes. Demonstrate consistent event timestamps across systems; no particular time protocol or in-house server is universally required.", "evidence": "Approved time sources, synchronisation settings, clock-drift checks, protected configuration and change records, and correlated timestamps from relevant systems.", "risk_text": "R1: Inconsistent or manipulated timestamps produce an incorrect incident sequence, weakening correlation, attribution and the reliability of evidence.<br>R2: Clock drift causes time-dependent authentication or certificate checks to reject valid access, interrupting services that depend on those checks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.17"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.17", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','LOG-RET-DEF','Security Log Retention Periods Are Defined and Justified','Security Log Retention Periods Are Defined and Justified','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Security Log Retention Periods Are Defined and Justified. Determine and document how long each relevant category of security logs must be retained, based on investigation needs, assessed risks and applicable requirements. Identify any different periods for readily searchable and archived records, where used, and the responsible owner. Explain the chosen periods rather than adopting an arbitrary universal duration. This control assesses the retention decision, not storage configuration or actual retained records.", "evidence": "Documented retention periods by relevant log category; rationale linked to investigation needs, risks and applicable requirements; responsible owner and any searchable/archive distinctions.", "risk_text": "R1: A retention decision is too short for investigation needs, causing relevant evidence to disappear before an incident is discovered.<br>R2: Excessive retention exposes unnecessary personal or sensitive records and creates unjustified data-processing exposure.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.1','Required Security Log Sources Deliver Usable Records','Required Security Log Sources Deliver Usable Records','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Required security-log sources actually deliver usable records. Verify coverage and record quality for the required sources; privileged-activity coverage and its review are assessed separately under LOG-PRIV.", "evidence": "Required source list, actual incoming log samples, completeness and usability checks, and collection-gap follow-up.", "risk_text": "Missing or unusable event records conceal relevant activity and prevent reconstruction of an incident on the affected source systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.2','Security Logs Are Protected Against Unauthorised Access and Alteration','Security Logs Are Protected Against Unauthorised Access and Alteration','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Restrict who can read or change security logs and protect them against unauthorised alteration during storage and transfer, so investigators can rely on the retained records.", "evidence": "Log access permissions, protected storage and transfer settings, alteration safeguards and access or integrity checks.", "risk_text": "R1: An attacker alters or deletes logs to conceal activity and mislead investigators.<br>R2: Unauthorised access to logs exposes personal data, internal infrastructure details or other sensitive operational information.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.3','Security Logs Are Retained for the Defined Periods','Security Logs Are Retained for the Defined Periods','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Security Logs Are Retained for the Defined Periods. Configure log storage, rotation, archiving, backup and deletion to implement the periods established under LOG-RET-DEF. Back up logs and verify that backup records can be retrieved; redundant logging alone does not demonstrate a recoverable backup. Check actual retained records and retrieval, and address premature loss or retention inconsistent with the defined periods and applicable requirements. A documented period alone does not demonstrate implementation.", "evidence": "Effective storage, rotation, archive, backup and deletion settings; dated records demonstrating the defined periods; retrieval checks including backed-up logs and records of retention failures or corrections.", "risk_text": "R1: Rotation, deletion or storage failures remove required logs before the approved retention period ends, preventing investigation or recovery of evidence.<br>R2: Logs remain accessible beyond their justified retention period, unnecessarily exposing personal or sensitive information.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.4','Logs Can Be Retrieved and Correlated for Investigations','Logs Can Be Retrieved and Correlated for Investigations','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Retrieve records from the relevant systems and periods and combine them into a usable event timeline; storing logs is not enough if they cannot be located, interpreted or correlated during an investigation.", "evidence": "Retrieval and correlation checks using records from relevant systems and periods; case timelines demonstrating usable correlation.", "risk_text": "Investigators cannot retrieve or connect relevant records across systems, delaying incident scoping and leaving affected assets or actions unidentified.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','LOG-PRIV','Privileged Activities Are Logged and Reviewed','Privileged Activities Are Logged and Reviewed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Privileged Activities Are Logged and Reviewed. Record privileged access and relevant administrative actions with enough information to identify the account, time, affected system and action. Review these records for misuse or suspicious activity and document investigation and follow-up. Cover administrative activity beyond the use of privileged utility programs; automated review may support the process but alerts must receive an appropriate response.", "evidence": "Administrative access and action logs showing account, time, target and action; review records, investigated exceptions and documented follow-up. Check privileged coverage separately from generic log collection.", "risk_text": "Misuse of administrative privileges remains unnoticed and cannot be reliably attributed, allowing unauthorised changes or data access to continue.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.15", "A.8.18"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.5','Logs Are Reviewed Regularly and Alarms Receive Timely, Qualified Responses','Logs Are Reviewed Regularly and Alarms Receive Timely, Qualified Responses','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Logs are regularly reviewed for unusual trends and alarms receive a timely, qualified response. Assess the general review and response process here; assess privileged-activity review under LOG-PRIV and avoid duplicating the same finding.", "evidence": "Review schedules, analysed trends, alert tickets, qualified response assignments and response timestamps; avoid duplicating LOG-PRIV review findings.", "risk_text": "Significant alerts or unusual patterns are not investigated promptly, allowing unauthorised activity or service damage to continue.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.15", "A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.7','Monitoring and Logging Systems Are Redundant','Monitoring and Logging Systems Are Redundant','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Provide redundant monitoring and logging components or arrangements so that failure of a relevant component does not remove the required monitoring and recording capability; a single untested backup copy does not demonstrate operational redundancy.", "evidence": "Redundant monitoring and logging architecture, configuration and failover test results covering relevant failure scenarios.", "risk_text": "A monitoring or logging component failure creates a visibility gap and loses event records while the monitored services remain in use.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.14", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C44.8','Monitoring and Logging Availability Is Monitored Independently','Monitoring and Logging Availability Is Monitored Independently','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-LOG · Logging and monitoring", "topic_label": "B-LOG · Logging and monitoring", "description": "Check the availability of monitoring and logging services independently of the systems whose activities they monitor. Examine dependencies and test outage detection; normal log arrival alone does not establish that failure of the monitoring or logging service will be detected and notified reliably.", "evidence": "Independent availability checks, dependency review, outage notifications and tests showing detection when the monitored service fails.", "risk_text": "Failure of the monitoring or logging service goes unnoticed, allowing an extended period without detection or reliable event evidence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-02','Detection Checks Identify Missed Events and Misleading Alerts','Detection Checks Identify Missed Events and Misleading Alerts','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T12", "subgroup": "B-DET-TEST · Detection effectiveness testing", "topic_label": "B-DET-TEST · Detection effectiveness testing", "description": "Detection arrangements are checked against relevant known-event scenarios and benign activity. Missed detections and misleading alerts are investigated, and necessary adjustments are verified by a repeat check.", "evidence": "Known-event and benign-activity test cases, detection outputs, missed or misleading alerts and repeat-test results after correction.", "risk_text": "Unrecognised detection blind spots or misleading rules persist because known-event checks do not reveal and verify corrections, creating false confidence in monitoring.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.16"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.16", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-12','Incident Handling Is Defined and Approved','Incident Handling Is Defined and Approved','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "An approved incident-handling policy defines the response lifecycle, accountable roles, classification and escalation arrangements, communications, and the records and working documents to be used. It is consistent with the entity''s business continuity and recovery arrangements.", "evidence": "Approved incident-handling policy, responsibilities, escalation and communication arrangements, working templates and consistency with continuity plans.", "risk_text": "Responders make conflicting or delayed decisions under pressure, allowing the incident to worsen or causing unnecessary operational disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','IR-TIME','Incident Response Time Targets Are Defined','Incident Response Time Targets Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Define and document risk-appropriate time targets for initial assessment, starting a response and escalation where needed, according to incident priority and potential impact. Specify what starts each target period and the responsible response function. These are internal action targets, not authority-notification deadlines or guaranteed incident-resolution times; they do not permit delaying urgent action or overriding applicable legal duties.", "evidence": "Documented targets by priority and response stage, risk-based rationale, defined start points and responsible functions, and evidence that targets are available to responders.", "risk_text": "Urgent incident work waits too long for assessment, escalation or containment, increasing avoidable exposure or disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-05','Incident Communication Channels Are Established','Incident Communication Channels Are Established','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Establish usable communication channels for incident escalation and coordination with the responsible responders and relevant internal and external stakeholders. Identify current contacts and a fallback route when the normal channel or primary contact is unavailable.", "evidence": "Defined communication channels, current contact and alternate-contact details, and a test or incident record showing that the appropriate responders and stakeholders can be reached.", "risk_text": "Incident information does not reach those who must act, delaying or misdirecting the response.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-13','Suspicious Events Can Be Reported Easily','Suspicious Events Can Be Reported Easily','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Employees, suppliers and customers have a simple, usable way to report suspicious events. A submitted report reaches the responsible handling function and can be traced into the assessment process.", "evidence": "Accessible reporting channels for employees, suppliers and customers; submitted test or real reports traceable to the handling function.", "risk_text": "Observed suspicious activity does not reach the response team, delaying recognition and containment of a real incident.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.8", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-14','Personnel Are Trained in Incident Reporting and Response','Personnel Are Trained in Incident Reporting and Response','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Train employees to recognise and report suspicious events through the available channel and to follow safe initial actions without exceeding their authority. Train designated responders in the incident-handling tasks assigned to them. Keep instruction current through regular, role-appropriate training; inform suppliers and customers of the reporting mechanism where appropriate. General programme methodology is assessed in T06, and operational response exercises are assessed under D02-18.", "evidence": "Role-matched incident training content and completion records; reporting and safe-action knowledge checks; responder instruction records and accessible reporting information for relevant suppliers and customers.", "risk_text": "R1: Personnel fail to report or escalate a real incident promptly.<br>R2: Unprepared responders take unsafe actions that worsen disruption or destroy evidence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.6.3", "A.6.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-03','Suspicious Events Are Assessed','Suspicious Events Are Assessed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Suspicious events are assessed using the relevant facts, logs and correlated information to determine whether an incident has occurred. The decision, including a decision to dismiss an event, is recorded with its supporting reasons.", "evidence": "Assessment records with supporting logs, event facts, decision, rationale and reviewer; include dismissed events.", "risk_text": "R1: Real incidents are dismissed or remain unrecognised, delaying response.<br>R2: Benign activity is wrongly confirmed as an incident, triggering unnecessary isolation or account suspension that disrupts legitimate operations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.25", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-04','Incidents Are Classified and Prioritised','Incidents Are Classified and Prioritised','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Confirmed incidents are classified by their nature and severity using predefined criteria and the observed or credible service impact. The resulting priority guides how urgently containment and threat removal are undertaken.", "evidence": "Severity criteria and incident records showing type, assessed impact, priority and response urgency.", "risk_text": "A high-impact incident is treated as low priority, delaying containment while response resources are used on less urgent events.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.25", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-15','Incident Assessments Are Updated When Facts Change','Incident Assessments Are Updated When Facts Change','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "When new information becomes available or existing information is reanalysed, the event assessment and classification are revisited and changed where warranted. The revised decision is recorded and passed to the response and reporting functions that need to act on it.", "evidence": "Versioned assessment and classification decisions, reasons for changes and evidence that response and reporting functions received updates.", "risk_text": "Outdated assessments cause inappropriate response or missed reporting obligations.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.25"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.25", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-16','Incident Actions and Decisions Are Recorded','Incident Actions and Decisions Are Recorded','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Incident records show who performed each material response action, when it occurred, what was done and the outcome. The records are maintained during handling so that the sequence of decisions and actions can be reconstructed reliably.", "evidence": "Incident timeline or case record showing who acted, when, what was done and the outcome; contemporaneous entries.", "risk_text": "Actions cannot be reconstructed and responders repeat or contradict earlier decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.26", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-17','Incident Evidence Is Traceable and Protected','Incident Evidence Is Traceable and Protected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Evidence collected for an incident retains an identifiable source and collection context, and is protected against unauthorised access or alteration. Relevant transfers and transformations are recorded so that the material used for decisions can be traced back to what was collected.", "evidence": "Collection records identifying source, time and context; access restrictions, integrity checks where appropriate and transfer or transformation history.", "risk_text": "R1: Evidence is altered, lost or cannot be traced to its source, undermining investigation and defensibility.<br>R2: Unauthorised disclosure of incident evidence exposes personal information, credentials or sensitive details of the affected environment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.28"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.28", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-07','Incidents Are Contained','Incidents Are Contained','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Documented containment procedures are used to limit an incident''s spread and impact through authorised, timely actions. The selected actions take account of critical service dependencies and safety constraints.", "evidence": "Containment procedures, authorisation and action records; evidence of isolation or access restriction and consideration of safety and service dependencies.", "risk_text": "R1: An incident spreads to additional systems or continues to expose information before it is contained.<br>R2: Poorly chosen containment actions interrupt necessary services or destroy volatile evidence.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.26", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-08','Incident Threats Are Removed','Incident Threats Are Removed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Documented eradication procedures guide the removal or neutralisation of the mechanisms that allow the incident to continue or recur. The results are checked rather than treating containment alone as removal of the threat.", "evidence": "Eradication procedures, records of removed persistence or compromised access, and checks demonstrating that the identified threat mechanisms were neutralised.", "risk_text": "Attackers retain access or the incident recurs despite apparent containment.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26", "A.8.7"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.26", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-09','Services Return to Operation Securely','Services Return to Operation Securely','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Where recovery is needed, documented procedures define and verify the incident-specific security conditions for returning affected services to operation. An authorised decision records why recovery or reconnection can proceed and any remaining safeguards.", "evidence": "Incident-specific recovery criteria, security validation results, authorised restoration or reconnection decision and remaining safeguards.", "risk_text": "Services are restored with unresolved compromise and immediately become affected again.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.26"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.26", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-10','Incidents Are Reviewed for Lessons Learned','Incidents Are Reviewed for Lessons Learned','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "After recovery, incidents are reviewed where appropriate to establish what happened, identify root causes where possible and record practical lessons. Periodic checks confirm that incidents warranting review have not been overlooked.", "evidence": "Review criteria and completed post-incident reviews covering timeline, root causes where possible and lessons; checks for omitted reviews.", "risk_text": "Unrecognised root causes or response weaknesses recur in later incidents, causing avoidable repeat disruption or compromise.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.27", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-11','Incident Improvements Are Implemented','Incident Improvements Are Implemented','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Agreed improvements from incident reviews and exercises have responsible owners and target dates, and are implemented in the affected risk treatment, detection or response arrangements. Closure is supported by evidence that the intended correction works.", "evidence": "Action register linked to reviews or exercises, owners, target dates, implemented changes and evidence-based closure checks.", "risk_text": "Identified weaknesses remain unresolved and the same failures recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.27", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-18','Incident Response Is Tested Through Exercises','Incident Response Is Tested Through Exercises','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Incident-response procedures and the relevant roles are tested through planned exercises covering credible scenarios and the necessary hand-offs. Further tests address significant incidents or significant operational or risk changes where the applicable requirements call for them; observed results and failures are recorded.", "evidence": "Exercise plan, credible scenarios, participant and hand-off records, observed outcomes and identified failures; applicable change-triggered tests.", "risk_text": "Untested response procedures fail during a real incident and hand-offs break down.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','D02-19','Incident Response Procedures Are Kept Current','Incident Response Procedures Are Kept Current','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T13", "subgroup": "B-IR · Incident response", "topic_label": "B-IR · Incident response", "description": "Review operational incident-response procedures, playbooks and contact or escalation arrangements at planned intervals and after significant incidents or significant changes to operations or risks. Update and distribute them where needed, recording a justified no-change outcome where appropriate. This control assesses current operational instructions, not policy approval or general role assignments. It remains relevant even when no incident has occurred.", "evidence": "Dated scheduled and event-triggered reviews of operational procedures, playbooks and contact arrangements; version changes or justified no-change decisions; evidence that current instructions reach users. Do not duplicate policy or general role-assignment findings.", "risk_text": "Responders follow obsolete instructions or contact the wrong people, delaying or misdirecting incident handling.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.24", "A.5.27"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.24", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','BC-BIA','Business Impact Analysis (BIA) Is Conducted and Continuity Requirements Are Defined','Business Impact Analysis (BIA) Is Conducted and Continuity Requirements Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "topic_label": "C-IMPACT · Assess business impact and define service recovery targets", "description": "Assess how disruption of relevant services and activities affects operations over time, including dependencies on systems, data, personnel and suppliers. Consider operational, financial, legal and safety consequences. Identify recovery priorities and the point at which disruption becomes unacceptable, expressed where useful as the Maximum Tolerable Period of Disruption (MTPD). Document the continuity requirements that follow. This assesses disruption consequences, not just the likelihood of threats.", "evidence": "Documented service/activity impact analysis with time horizons, dependencies and stakeholder input; justified intolerable-impact thresholds, recovery priorities and resulting continuity requirements.", "risk_text": "Critical dependencies and the consequences of prolonged disruption are misunderstood, so recovery priorities and continuity arrangements do not protect the services that matter most.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','BC-RTO','Recovery Time Objectives (RTO) Are Defined for Priority Services','Recovery Time Objectives (RTO) Are Defined for Priority Services','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "topic_label": "C-IMPACT · Assess business impact and define service recovery targets", "description": "Set the target time for restoring each priority service to a stated usable level, based on business-impact findings. Define when the clock starts and what counts as recovery; account for system and supplier dependencies. Set targets early enough to avoid unacceptable disruption, allowing for subsequent business recovery where needed. For example, an RTO of two hours requires the specified service capability within two hours. A backup job duration is not a service RTO.", "evidence": "Service-specific RTO register or equivalent plan entries; business-impact justification; defined start/end criteria and service level; dependency alignment and business-owner validation.", "risk_text": "Recovery teams work to arbitrary or inconsistent deadlines, allowing services to remain unavailable beyond business tolerances.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.1','Business Continuity Plans Are Defined','Business Continuity Plans Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define how priority services will continue while normal systems or premises are unavailable, using the business-impact findings and recovery objectives. Specify activation conditions, workarounds, responsibilities and resources. State the minimum acceptable service level during temporary operation, using a Service Delivery Objective (SDO) where useful; for example, which essential transactions remain available. This is the operational continuity plan, not the BIA itself or a promise of uninterrupted service.", "evidence": "Current continuity plans linked to BIA priorities and recovery objectives; minimum temporary service levels, activation conditions, workarounds, owners and resource requirements.", "risk_text": "Priority services stop or operate below an acceptable level during disruption because planned continuity arrangements are not workable.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.3','Disaster Recovery Procedures Are Defined','Disaster Recovery Procedures Are Defined','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define the steps, recovery order and responsible teams for restoring disrupted systems and services. Address dependencies, access to recovery resources, validation of recovered systems and return from temporary to normal operations. Use the RTO and RPO values established under BC-RTO and BC-RPO to design the procedures; do not redefine conflicting targets here. Assess whether staff have executable instructions, not merely a statement that recovery will occur.", "evidence": "Current restoration instructions, dependency-based recovery sequence, responsible teams, resource/access arrangements and acceptance checks; traceability to defined RTO/RPO values.", "risk_text": "Recovery teams lack executable instructions or restore dependencies in the wrong order, preventing timely and reliable service recovery.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.4','Crisis Plans Define When to Escalate and Who Decides','Crisis Plans Define When to Escalate and Who Decides','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-PREP · Define continuity, recovery and crisis arrangements", "topic_label": "C-PREP · Define continuity, recovery and crisis arrangements", "description": "Define when a disruption requires crisis-level coordination beyond routine incident handling, who activates the crisis team and who can make urgent service and resource decisions. Set out internal and external communication arrangements, substitutes and how plans and contacts remain accessible if normal systems fail. Not every security incident needs crisis activation; statutory reporting is assessed in T14.", "evidence": "Crisis activation and stand-down criteria, decision authorities and substitutes, communication arrangements, accessible plan/contact copies and continuity-plan interfaces.", "risk_text": "A disruption exceeding routine incident capacity receives conflicting or delayed leadership decisions, extending service interruption and confusing stakeholders.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.29", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.6','The Resources Required by Continuity Plans Are Available','The Resources Required by Continuity Plans Are Available','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-READY · Prepare alternative resources", "topic_label": "C-READY · Prepare alternative resources", "description": "Make the alternative systems, facilities, personnel and communication resources specified in the continuity and recovery plans available within the required time. Check their capacity, access arrangements and dependencies against the planned service level, including resources provided by suppliers. A supplier name or planned purchase alone does not demonstrate availability; not every service requires a second site.", "evidence": "Plan-to-resource mapping, capacity and access checks, staff cover, supplier commitments and evidence of resource availability within the required time.", "risk_text": "Documented workarounds or recovery steps cannot be carried out because replacement resources are unavailable, inaccessible or undersized.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','BC-RPO','Recovery Point Objectives (RPO) Are Defined for Data Recovery','Recovery Point Objectives (RPO) Are Defined for Data Recovery','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Determine how far back in time data may be recovered without unacceptable loss, based on the business impact of losing records or transactions. Specify the acceptable data-loss window for relevant datasets and services, then use it to select backup frequency and other recovery arrangements. For example, an RPO of 15 minutes permits at most 15 minutes of lost updates. RPO is neither the time taken to restore data nor a backup retention period.", "evidence": "Documented RPO values for relevant data/services; business-owner justification of acceptable loss; mapping to backup or other recovery design; consistent assumptions about replication, timing and data dependencies.", "risk_text": "Recovery arrangements restore data that is too old, causing unacceptable loss of transactions or records even when the service is restored quickly.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.2','Backup Procedures Are Implemented and Tested','Backup Procedures Are Implemented and Tested','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Run backups for the data, software and configurations needed for recovery, including relevant cloud-hosted content, using defined schedules and retention periods. Test that the backup process includes the required sources, creates the intended copies and identifies failed or omitted jobs; correct failures and retest affected steps. This control assesses reliable backup creation, while C32.5 checks stored-copy integrity and C33.1 tests actual restoration. Replication or a cloud subscription alone is insufficient.", "evidence": "Backup scope and schedules linked to recovery needs; retention settings; job and exception records; documented tests of source coverage, copy creation and failure detection; corrected failures and retest results.", "risk_text": "The backup process silently omits required information or fails to create current recovery copies, leaving services without a viable recovery source.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C33.2','Backups Are Protected from Production-System Compromise','Backups Are Protected from Production-System Compromise','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "topic_label": "C-BACKUP · Define data recovery targets and implement protected backups", "description": "Protect backup copies and their administration against compromise of production systems, unauthorised access, alteration and deletion. Address shared dependencies and site-level damage. For CIR-covered entities, place copies outside the production system''s network and sufficiently far from the main site to escape the same disaster, with appropriate access controls. Online and offline copies are both possible; no universal offline-only design or particular product is prescribed.", "evidence": "Backup network and administration architecture, location and common-disaster assessment, access restrictions, deletion/alteration safeguards and tested compromise scenarios. For CIR scope, verify network and geographical separation rather than accepting an unexplained ''secure backup'' label.", "risk_text": "R1: A compromise or common failure destroys or corrupts production data and the recovery copies needed to restore them.<br>R2: An attacker obtains sensitive information from recovery copies that share the compromised production trust boundary.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.7','Security Controls Remain Effective During Emergency Operations','Security Controls Remain Effective During Emergency Operations','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-OPERATE · Maintain security during disruption and return to normal operations", "topic_label": "C-OPERATE · Maintain security during disruption and return to normal operations", "description": "Apply appropriate security when continuity arrangements use temporary systems, manual records, emergency access or alternative premises. Control who can access information, protect temporary records and reassess safeguards as conditions change. When normal operations resume, withdraw temporary access and handle temporary records securely; where no disruption occurred, assess prepared safeguards and exercise evidence.", "evidence": "Emergency-operation security arrangements, temporary-access and record-handling controls, incident or exercise evidence, risk decisions and return-to-normal checks.", "risk_text": "R1: Emergency workarounds expose information or permit unauthorised access during disrupted operation.<br>R2: Temporary emergency privileges or insecure configurations remain in place after recovery and are later misused.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.29"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.29", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-BCDR','Personnel Are Trained in Their Business Continuity and Disaster Recovery Duties','Personnel Are Trained in Their Business Continuity and Disaster Recovery Duties','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Train personnel for their assigned continuity and recovery duties: staff learn the relevant temporary working arrangements, recovery teams learn restoration procedures and crisis coordinators learn activation and communication duties. Refresh instruction when relevant duties or plans change and check that participants can apply it. A separate course or certificate is not required; an exercise can also provide training evidence if learning and understanding are demonstrated. T06 assesses the general training programme, not this topic-specific delivery.", "evidence": "Role-to-duty training coverage; current instructions and training records; practical demonstrations or knowledge checks; follow-up of identified learning gaps.", "risk_text": "Personnel do not know how to maintain priority services or perform assigned recovery tasks, so otherwise adequate plans fail during disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.5','Backup Copies Are Checked for Corruption and Incompleteness','Backup Copies Are Checked for Corruption and Incompleteness','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Regularly verify the integrity and completeness of stored backup copies using appropriate checks and investigate failures. Confirm that affected copies are repaired or replaced as needed. This checks the stored material; it does not replace a restoration test or prove that a service can run from the recovered data.", "evidence": "Integrity and completeness checks, identified failures, affected-copy records and evidence of successful correction or replacement.", "risk_text": "Corrupt or incomplete backup content is trusted as usable and fails to supply the data, configuration or metadata needed for recovery.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C33.1','Backup Restoration Is Tested Against Recovery Point Objectives (RPO)','Backup Restoration Is Tested Against Recovery Point Objectives (RPO)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "At planned, risk-appropriate intervals, restore selected data and systems from backups and verify usability, completeness and the recovered data point against the defined Recovery Point Objective (RPO). Record elapsed restoration time as an input to service-level RTO validation, together with failures and corrective actions. A successful backup job does not prove restoration, and an isolated restore test does not by itself demonstrate that the whole service meets its RTO.", "evidence": "Restore scenarios and acceptance criteria; recovered data-point timestamps and RPO comparisons; usability/completeness checks; measured restore durations; failures, corrective actions and retest results.", "risk_text": "A restore cannot reconstruct complete, usable data at the required recovery point, causing data loss beyond the agreed RPO.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C33.4','Failover Tests Confirm That Redundant Resources Can Take Over','Failover Tests Confirm That Redundant Resources Can Take Over','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Test the planned switch from primary resources to their redundant alternatives under realistic failure conditions. Check whether capacity, connectivity and dependent services remain sufficient, and record and correct failed transitions. This assesses taking over service delivery, not rebuilding a system from a backup. Apply it to the redundancy required by the continuity design.", "evidence": "Failover scenarios, transition records, service and dependency checks under the alternative resources, capacity results and correction of failures.", "risk_text": "Standby resources exist but fail to take over, or cannot support the service when primary resources are unavailable.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30", "A.8.14"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C33.3','Continuity and Recovery Exercises Test Service Recovery Objectives (RTO)','Continuity and Recovery Exercises Test Service Recovery Objectives (RTO)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Exercise a realistic disruption from continuity activation through restoration and return to normal operations. Verify the temporary service level and measure end-to-end service recovery against the defined Recovery Time Objective (RTO), including staff, supplier and system dependencies. Where restoration involves data loss, use the RPO verification evidence as well. Review plans at planned intervals and after significant incidents or relevant significant changes; incorporate lessons and verify corrective actions.", "evidence": "End-to-end exercise scenarios and participation; measured service recovery times compared with RTO; temporary service-level results; relevant RPO evidence; revised plans and verified corrective actions.", "risk_text": "End-to-end recovery exceeds the service RTO because dependencies, hand-offs or combined recovery steps fail despite individual component tests.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C32.8','Crisis Exercises Test Leadership Decisions and Communication','Crisis Exercises Test Leadership Decisions and Communication','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "topic_label": "C-VERIFY · Verify recovery capability, train personnel and exercise the plans", "description": "Use realistic crisis scenarios to test activation, decision authority, coordination and communication when normal arrangements are under pressure. Review and update the crisis plan under the applicable regular or incident/change-triggered review requirements. Assess crisis leadership here, not duplicate technical recovery tests; a shared exercise may provide evidence for both distinct outcomes.", "evidence": "Crisis scenarios, leadership participation, decision and communication records, review results, updated arrangements and follow-up of weaknesses.", "risk_text": "Leaders cannot coordinate urgent decisions or communicate effectively during a major disruption despite having a written crisis plan.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.30", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','REC-METRIC','Actual Recovery Times Are Measured and Reviewed (MTTR)','Actual Recovery Times Are Measured and Reviewed (MTTR)','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T15", "subgroup": "C-MEASURE · Measure recovery performance and improve it", "topic_label": "C-MEASURE · Measure recovery performance and improve it", "description": "Record the time from service disruption to verified service restoration using consistent start and end rules. For comparable actual events, calculate Mean Time to Recovery (MTTR) as total recovery time divided by the number of recovered events; separate services and scenarios with materially different recovery expectations. Review each event against its RTO as well as reviewing the average, investigate overruns and track improvements. Keep exercise results separate from actual-event statistics. With no actual events, assess measurement readiness and test timings; do not require an invented average or report zero MTTR.", "evidence": "Defined timing boundaries and comparable-event scope; event timestamps and acceptance records; reproducible MTTR calculation with sample size; individual RTO comparisons; investigation and improvement records. Where no events occurred: prepared measurement method and separately identified exercise results.", "risk_text": "Recurring recovery delays or service-specific RTO breaches remain hidden by incomplete measurement or misleading averages, so improvement effort misses the real bottlenecks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "9.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C51.5','The Entity Defines How Supplier Security Is Managed','The Entity Defines How Supplier Security Is Managed','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Define who is responsible for supplier security and how suppliers are assessed, contracted, monitored and offboarded. Apply these rules according to the risks of the products and services being supplied.", "evidence": "Supply-chain security policy, assigned owners and records showing the rules used in actual supplier relationships.", "risk_text": "Supplier security responsibilities fall between procurement, service owners and security teams, allowing material exposure to persist throughout the relationship.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["8.1", "A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "8.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-CLOUD-LIFECYCLE','Cloud Use Follows Defined Security Governance Arrangements','Cloud Use Follows Defined Security Governance Arrangements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T16", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define and apply cloud-use governance covering adoption, permitted use, management and exit decisions. Link existing supplier assurance, responsibility and exit controls; do not reassess them here. This applies to cloud customers, including SaaS users, not just providers.", "evidence": "Cloud-use arrangements; approved service and tenant inventory; shared-responsibility decisions; adoption, change and exit records linked to existing supplier controls.", "risk_text": "The customer assumes the provider protects an unassigned responsibility, or loses secure access and data portability when the cloud service changes or ends.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.23"], "source": "iso27001-nis2-v7", "annex": "A.5.23", "annex_kind": "annex", "applicability": {"condition": "Cloud services are used within the ISMS scope", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C51.1','The Entity Keeps an Up-to-Date Supplier and Service Register','The Entity Keeps an Up-to-Date Supplier and Service Register','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "List relevant direct suppliers, their contacts and the ICT products, services or processes they provide. Identify which business services depend on each supplier and update the register when the relationship changes.", "evidence": "Supplier register with contacts, supplied products/services, business-service links and reconciliation against procurement records.", "risk_text": "An unrecorded supplier or service dependency is omitted from incident coordination and security oversight, delaying action when that supplier fails or is compromised.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','SUP-RESP','Security Responsibilities Are Agreed Between the Entity and the Supplier (Applies where security responsibilities are shared with a supplier.)','Security Responsibilities Are Agreed Between the Entity and the Supplier (Applies where security responsibilities are shared with a supplier.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "For services with shared security duties, agree which party performs each relevant task, such as patching, backups, access administration, logging and incident response. Define handovers and verify that no necessary task is left unassigned. (Applies where security responsibilities are shared with a supplier.)", "evidence": "Service-specific responsibility matrix or equivalent agreed allocation, supplier acknowledgement and records confirming responsibility at operational handovers.", "risk_text": "R1: Each party assumes the other performs a necessary security task, leaving systems unpatched, unmonitored or without usable backups.<br>R2: Unclear handovers delay containment or recovery while the entity and supplier dispute who must act.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.20", "annex_kind": "annex", "applicability": {"condition": "where security responsibilities are shared with a supplier", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C51.2','The Entity Determines Which Suppliers Are Critical to Its Services','The Entity Determines Which Suppliers Are Critical to Its Services','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Assess what would happen to operations, information and recovery if each relevant supplier failed or was compromised. Use the result to decide how closely the supplier must be assessed and monitored.", "evidence": "Supplier criticality assessments showing service impact, recovery dependencies and resulting oversight requirements.", "risk_text": "Supplier failure or compromise affects a priority service more severely than anticipated because its business and recovery dependencies were underestimated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C51.3','The Entity Checks Which Systems and Data Suppliers Can Access','The Entity Checks Which Systems and Data Suppliers Can Access','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Identify supplier accounts, remote connections, privileges and accessible information. Compare the recorded access with actual permissions and refer unnecessary or unexplained access for correction through access management.", "evidence": "Supplier access records, actual account/connection listings and evidence that discrepancies were resolved.", "risk_text": "R1: Unknown or excessive supplier access is used to obtain organisational information.<br>R2: A compromised supplier account or connection enables unauthorised changes to internal systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C51.4','The Entity Assesses Dependence on Individual Suppliers and Shared Platforms','The Entity Assesses Dependence on Individual Suppliers and Shared Platforms','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-REL · Identify suppliers, responsibilities and dependencies", "topic_label": "D-REL · Identify suppliers, responsibilities and dependencies", "description": "Identify services that could fail together because they depend on one supplier or platform. Assess barriers to switching suppliers, such as incompatible data formats or unavailable expertise, and decide how to reduce unacceptable dependence.", "evidence": "Shared-dependency analysis, switching/exit constraints and documented treatment decisions; multiple suppliers are not automatically required.", "risk_text": "R1: One supplier or shared-platform failure interrupts several dependent services at once.<br>R2: Lock-in or loss of internal knowledge prevents timely replacement of the supplier, extending the disruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C49.4','The Entity Uses Security Criteria When Selecting Suppliers','The Entity Uses Security Criteria When Selecting Suppliers','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Compare prospective suppliers against defined security and resilience requirements before making the selection. Record why the chosen supplier is suitable and how any accepted gaps will be treated.", "evidence": "Security selection criteria, evaluated supplier offers, selection approval and justified treatment of gaps.", "risk_text": "A supplier unable to meet justified cybersecurity or resilience needs is selected, leaving the entity with avoidable exposure or a costly constrained replacement.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C49.2','The Entity Assesses Supplier Security Practices and Product Reliability','The Entity Assesses Supplier Security Practices and Product Reliability','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Assess whether the supplier''s security practices and the quality and resilience of its products or services meet the entity''s needs. Where relevant, include how the supplier develops and maintains software securely; apply this also to purchased software, not only outsourced development projects.", "evidence": "Supplier assessment, relevant assurance and product/service evidence, and evaluation of secure-development practices where applicable.", "risk_text": "R1: A supplier product or operating practice exposes entrusted information to unauthorised access.<br>R2: An unsuitable supplier service fails to provide the availability or recoverability needed by the entity.<br>R3: Weak supplier development practices introduce exploitable defects or compromised components into acquired or maintained systems.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.19", "A.5.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','SUP-LOC','Supplier Locations Are Assessed for Security and Continuity Risks (Applies where supplier operating or information-processing locations can materially affect security or continuity.)','Supplier Locations Are Assessed for Security and Continuity Risks (Applies where supplier operating or information-processing locations can materially affect security or continuity.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Identify the countries or regions where relevant supplier services operate and the entity''s information is processed or stored, including recovery locations. Assess whether regional outages, disrupted connectivity, instability or shared location dependencies could interrupt the service or compromise information. Agree advance notification of material location changes so their effects can be assessed before the move. This is not a blanket requirement to keep information in the EU. (Applies where supplier operating or information-processing locations can materially affect security or continuity.)", "evidence": "Relevant service, processing, storage and recovery location records; assessment of location-specific and shared dependencies; agreed advance-notification terms; assessments of actual material location changes.", "risk_text": "R1: A regional power, communications or other disruption affects both the primary service and its recovery arrangements because their location dependency was not identified.<br>R2: A supplier relocates service delivery or information processing without prior assessment, invalidating security assumptions or making agreed recovery arrangements ineffective.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex", "applicability": {"condition": "where supplier operating or information-processing locations can materially affect security or continuity", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C49.1','The Entity Addresses Security Weaknesses Identified in Its Suppliers','The Entity Addresses Security Weaknesses Identified in Its Suppliers','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-ASSESS · Assess suppliers and select suitable services", "topic_label": "D-ASSESS · Assess suppliers and select suitable services", "description": "Assess how identified weaknesses in a supplier, its products or services could affect the entity. Decide and track necessary safeguards or corrective actions; for example, require stronger protection before allowing a remote-support provider privileged access. Technical patching remains part of vulnerability management.", "evidence": "Supplier-specific findings, impact assessment, required safeguards or contractual conditions, assigned actions and follow-up.", "risk_text": "An identified supplier-specific security weakness is left untreated in acceptance or corrective decisions and enables unauthorised access, changes to the entity''s systems or disruption of its services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C52.1','Supplier Contracts Define Security, Incident Notification and Vulnerability Handling','Supplier Contracts Define Security, Incident Notification and Vulnerability Handling','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "The entity agrees enforceable, risk-appropriate security requirements with suppliers. Include notification to the entity without undue delay of incidents that threaten its systems, and responsibilities for handling relevant vulnerabilities. Specify contacts and necessary information; these arrangements support, but do not replace, the entity''s own response and statutory reporting duties.", "evidence": "Signed security clauses and service-level agreements identifying required safeguards, incident contacts/notification duties, and vulnerability-handling responsibilities and escalation arrangements.", "risk_text": "R1: A supplier disputes or omits necessary security work because binding responsibilities and service expectations are unclear, leaving the entity unable to obtain timely protection or correction.<br>R2: A supplier delays or withholds relevant incident information, delaying the entity''s response or causing it to miss an applicable statutory notification deadline.<br>R3: A vulnerability affecting the entity remains exploitable while supplier and customer dispute responsibility, notification or remediation expectations.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.20", "A.8.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C52.3','The Entity Secures Rights to Audit Suppliers or Obtain Audit Reports','The Entity Secures Rights to Audit Suppliers or Obtain Audit Reports','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Agree a practical way to obtain evidence about the security of the supplied service, through audit rights or relevant audit reports. An on-site audit of every supplier is not required; the agreed access must allow meaningful verification.", "evidence": "Contractual audit/report rights showing the covered service, permitted evidence and relevant access conditions.", "risk_text": "The entity cannot obtain scope-relevant assurance evidence, so material supplier weaknesses remain undetected or unresolved.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.20", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C52.7','The Entity Sets Security Conditions for Supplier Subcontracting','The Entity Sets Security Conditions for Supplier Subcontracting','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Define whether and under which conditions suppliers may subcontract the work. Where subcontracting is allowed, require relevant security obligations to apply to subcontractors and obtain evidence that these conditions are met.", "evidence": "Subcontracting permissions/restrictions, relevant subcontractor records and evidence of applicable security obligations.", "risk_text": "R1: A subcontractor obtains or handles organisational information without the safeguards expected of the direct supplier.<br>R2: An undisclosed or poorly controlled subcontractor dependency interrupts the contracted service.<br>R3: A subcontractor introduces malicious or compromised components into the supplied product or service, enabling compromise of the entity''s systems.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21", "A.5.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C52.5','The Entity Verifies Required Background Checks for Supplier Personnel (Applies where the role and applicable law justify background checks.)','The Entity Verifies Required Background Checks for Supplier Personnel (Applies where the role and applicable law justify background checks.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "For sensitive supplier roles, agree which lawful background checks are necessary and confirm their completion before assignment. Obtain proportionate confirmation rather than unnecessary personal records. (Applies where the role and applicable law justify background checks.)", "evidence": "Role-based screening requirements and lawful completion confirmations for personnel assigned to the relevant roles.", "risk_text": "R1: A person with relevant, lawfully discoverable trust concerns is assigned sensitive supplier duties and misuses the resulting access.<br>R2: Disproportionate screening collects or discloses unnecessary personal information about supplier personnel.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.20"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.20", "annex_kind": "annex", "applicability": {"condition": "where the role and applicable law justify background checks", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C52.4','The Entity Verifies Supplier Personnel Have the Required Security Skills','The Entity Verifies Supplier Personnel Have the Required Security Skills','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-CON · Agree and verify supplier security obligations", "topic_label": "D-CON · Agree and verify supplier security obligations", "description": "Define the security skills and role-specific training needed by supplier personnel working on the service. Obtain proportionate evidence that they meet those requirements; request certificates only where justified.", "evidence": "Agreed role/competence requirements and proportionate qualification or training evidence covering the assigned supplier personnel.", "risk_text": "Supplier personnel make security-relevant operational errors or fail to respond correctly because they lack the skills required for their assigned tasks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.19"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.19", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','SUP-AUTH','The Entity Verifies the Authenticity and Integrity of Critical ICT Deliveries','The Entity Verifies the Authenticity and Integrity of Critical ICT Deliveries','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-DELIVERY · Verify ICT deliveries before operational use", "topic_label": "D-DELIVERY · Verify ICT deliveries before operational use", "description": "Before using critical acquired hardware or software, verify that it comes from a trusted source and shows no evidence of substitution or tampering. Select checks according to product risk, such as authorised-source confirmation, manufacturer verification, digital signatures or physical delivery inspection. This checks the delivered product''s provenance and integrity, not whether its security functions work or whether later patches are authentic.", "evidence": "Risk-based acceptance criteria, trusted-source records and product-appropriate authenticity/integrity checks, with rejected or suspicious deliveries and their disposition recorded.", "risk_text": "R1: Counterfeit, substituted or maliciously modified hardware or software is accepted into operational systems, enabling unauthorised access or manipulation.<br>R2: An unreliable counterfeit component fails during operation and disrupts a critical service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.21"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.21", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','TRN-12','The Entity Ensures Relevant Suppliers Understand Its Security and Reporting Rules','The Entity Ensures Relevant Suppliers Understand Its Security and Reporting Rules','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Communicate the cybersecurity risks, cyber-hygiene practices and reporting routes relevant to the supplied service. Check that the supplier understands and applies them, and offer appropriate awareness activities where needed. This covers shared working rules, not specialist qualifications.", "evidence": "Supplier guidance and communication records, awareness participation where appropriate, and evidence of understanding and application.", "risk_text": "Supplier staff disregard the entity''s cyber-hygiene or reporting expectations, exposing shared information or delaying escalation of suspicious activity.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C53.1','The Entity Checks Supplier Certificates and Audit Reports Before Relying on Them','The Entity Checks Supplier Certificates and Audit Reports Before Relying on Them','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Verify that assurance evidence covers the actual supplier service and a relevant period. Review exclusions and unresolved findings, then decide whether further evidence or corrective action is necessary; a certificate alone is not sufficient.", "evidence": "Recorded checks of report/certificate scope, dates, findings and exclusions, with follow-up decisions.", "risk_text": "A certificate or report covering the wrong service, period or scope creates false assurance, allowing actual supplier weaknesses to remain accepted and untreated.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.22"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.22", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C53.2','The Entity Reassesses Suppliers When Security Performance or Conditions Change','The Entity Reassesses Suppliers When Security Performance or Conditions Change','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-MON · Communicate rules and monitor the relationship", "topic_label": "D-MON · Communicate rules and monitor the relationship", "description": "Review supplier security performance at planned, risk-appropriate intervals and after significant changes or relevant incidents. Where service-level agreements exist, examine their implementation reports and related incidents, not only current certificates. Record whether an unscheduled review is needed, assess changed risks and track necessary safeguards or corrective action.", "evidence": "Periodic and event-triggered reviews, service/security reports, change or incident notices and tracked corrective actions.", "risk_text": "Deteriorating supplier safeguards or changed service dependencies go unnoticed, extending exposure to compromise or interruption beyond the originally accepted conditions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["8.1", "A.5.22", "A.8.21", "A.8.30"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "8.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','SUP-EXIT-TEST','The Entity Tests Whether Critical Outsourced Services Can Be Transferred (Applies to critical outsourced services where supplier exit requires service or information transfer.)','The Entity Tests Whether Critical Outsourced Services Can Be Transferred (Applies to critical outsourced services where supplier exit requires service or information transfer.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-EXIT · End the relationship securely", "topic_label": "D-EXIT · End the relationship securely", "description": "Before an exit becomes necessary, test the feasible transfer of a critical outsourced service to another provider or an internal environment. Use a risk-appropriate exercise or technical test to verify that required information, configurations and documentation can be obtained and used, and that essential operations can continue. Resolve material barriers and retest when justified by changes. An export button or an exit clause alone is not evidence that transfer works. (Applies to critical outsourced services where supplier exit requires service or information transfer.)", "evidence": "Exit test scope and scenario, usable data/configuration exports, alternative-environment import or processing results where relevant, continuity exercise results, identified barriers and corrective-action records.", "risk_text": "R1: Supplier failure or termination leaves the entity unable to use exported information or rebuild the service elsewhere because portability was never demonstrated.<br>R2: Unrecognised configuration, licence, expertise or integration dependencies prolong a supplier transition beyond the service''s tolerable interruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.23", "annex_kind": "annex", "applicability": {"condition": "to critical outsourced services where supplier exit requires service or information transfer", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C52.8','The Entity Retrieves Its Information and Ends Supplier Access When a Contract Ends','The Entity Retrieves Its Information and Ends Supplier Access When a Contract Ends','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T16", "subgroup": "D-EXIT · End the relationship securely", "topic_label": "D-EXIT · End the relationship securely", "description": "Agree and verify the return or secure disposal of information held by the departing supplier, as appropriate to the contract and applicable requirements. Remove access no longer needed and confirm any service handover so that ending the relationship does not expose data or interrupt operations.", "evidence": "Exit terms, completed handover, information-return/deletion confirmations and verified removal of accounts, credentials and connections.", "risk_text": "R1: A former supplier retains usable access or information and later accesses, alters or discloses organisational data without authority.<br>R2: An incomplete service handover makes information or a dependent service unavailable during supplier exit.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.11", "A.5.20", "A.5.23"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.11", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ENV-RISK','Physical and Environmental Risks Are Assessed','Physical and Environmental Risks Are Assessed','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-RISK · Physical and environmental risk assessment", "topic_label": "I-PHY-RISK · Physical and environmental risk assessment", "description": "Assess current and reasonably foreseeable physical and environmental threats to relevant ICT systems, their locations and supporting utilities. Determine whether climate change is relevant to information security and continuity, considering local flood exposure, extreme heat, storms and related power or cooling disruption. Use location-specific information and relevant interested-party requirements; record the reasoning if climate change is not relevant. Link identified risks to the existing risk register, protection and recovery decisions, and update the assessment when conditions materially change. This is not an emissions or general environmental-impact assessment.", "evidence": "Recorded climate-relevance conclusion; site-specific flood/hazard information and relevant projections, utility/cooling dependency assessment, risk-register links, interested-party requirements where relevant, and review/treatment decisions. Reuse the T03 assessment process rather than demand a separate report.", "risk_text": "R1: Changing flood, heat or storm exposure is overlooked and existing protection becomes inadequate, causing ICT damage, information loss or service interruption.<br>R2: Physical and environmental risks to supporting power, cooling or recovery locations are underestimated, causing simultaneous loss of primary and recovery capability.<br>R3: Physical access, theft or tampering exposure at an ICT location is overlooked, leaving sensitive information and equipment without appropriate protection against unauthorised intervention.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-ZONE','Server and Network Rooms Have Protected Physical Boundaries (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','Server and Network Rooms Have Protected Physical Boundaries (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Define the boundary of each protected server or network area and inspect doors, walls, windows and accessible ceiling/floor routes for ways entry controls could be bypassed. Provide risk-appropriate separation from public, shared or delivery areas. This checks the physical boundary, not individual access permissions. (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)", "evidence": "Protected-area plan, boundary inspection and records of repaired bypass routes.", "risk_text": "R1: An intruder bypasses the controlled door through an inadequately protected boundary and accesses equipment or information.<br>R2: A shared or delivery area provides an uncontrolled route into critical equipment space.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.1", "annex_kind": "annex", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-OTHER-AREA-PERIMETERS','Other Sensitive Areas Have Defined and Effective Security Boundaries','Other Sensitive Areas Have Defined and Effective Security Boundaries','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T17", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define and implement boundaries for sensitive areas outside the equipment rooms assessed under PHY-ZONE, such as archives or confidential work areas. Check that public or shared-space routes cannot bypass the selected perimeter; individual entry permissions remain under C46.1.", "evidence": "Plans identifying the additional sensitive areas, selected boundaries and observed bypass checks, with corrections where gaps were found; link shared building controls rather than duplicate inspections.", "risk_text": "People reach sensitive information through an unprotected office or archive boundary despite effective server-room protection.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.1"], "source": "iso27001-nis2-v7", "annex": "A.7.1", "annex_kind": "annex", "applicability": {"condition": "Sensitive ISMS areas exist outside the protected equipment areas already assessed under PHY-ZONE", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C46.1','Physical Access to Protected Areas Is Restricted','Physical Access to Protected Areas Is Restricted','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Allow entry to server rooms, network rooms and other protected areas only for an authorised purpose. Manage keys/cards, periodically review access rights and remove them when no longer needed. Authorise visitors and contractors and supervise them according to risk; prevent entry through unattended doors or uncontrolled delivery routes.", "evidence": "Access approvals and reviews, key/card register, visitor authorisations, observed door controls and records of revoked access. Entry/exit record completeness is assessed under PHY-ENTRY-LOG.", "risk_text": "R1: An unauthorised person enters a protected area and steals, observes or copies sensitive information.<br>R2: Physical tampering with systems or equipment interrupts services or changes their operation.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.5.15", "A.7.1", "A.7.2", "A.7.3"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.15", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-ENTRY-LOG','Server-Room Access Is Logged and Supported by Video Where Justified (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','Server-Room Access Is Logged and Supported by Video Where Justified (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Record each person''s entry to and exit from protected equipment rooms, including visitors and contractors, with identity, room and sufficiently reliable times. Use individual credentials or an equivalent controlled register. Where camera surveillance is justified, provide usable coverage of relevant access points or equipment areas, check image quality and verify retrieval of recorded footage. Protect logs and footage against unauthorised access or alteration, define justified retention/deletion and investigate incomplete or unexplained records. Limit camera coverage to necessary areas. Entry logging remains applicable even where cameras are not justified; footage does not replace reliable person/room/time traceability or live intrusion response under C46.4. (Applies where the entity operates server rooms, network rooms or comparable protected equipment areas.)", "evidence": "Person/room/time entry-exit and visitor records; timestamp/completeness checks; where cameras are justified, coverage rationale, image-quality and retrieval tests; protected access/export permissions, justified retention/deletion and investigated discrepancies.", "risk_text": "R1: Unauthorised or unexplained access cannot be attributed to an individual or time because server-room entry and exit records are missing, incomplete or based only on shared credentials.<br>R2: Altered, prematurely deleted or inaccessible access records prevent reliable investigation of physical interference and reconstruction of events.<br>R3: Blind spots, camera failure or unusable images prevent reconstruction of unauthorised access or physical interference where visual evidence is relied upon.<br>R4: Excessive camera coverage or unauthorised access to recordings exposes sensitive information or identifiable individuals unnecessarily.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.2", "A.7.4"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.2", "annex_kind": "annex", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C46.4','Premises Are Monitored for Unauthorised Physical Access','Premises Are Monitored for Unauthorised Physical Access','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Operate risk-appropriate physical intrusion monitoring for relevant premises, including server-room access points. Route detections to a responder and verify response arrangements, including outside working hours. Guards, intrusion alarms or other suitable arrangements may be used; cameras everywhere are not required.", "evidence": "Monitoring coverage, alarm routing and response records, access to monitoring systems and detection/response tests.", "risk_text": "An intruder remains undetected long enough to steal information or tamper with systems before responsible personnel can respond.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.4"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.4", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-WORK','Secure Working Rules Are Defined and Followed in Server and Network Rooms (Applies where personnel or contractors work in protected equipment areas.)','Secure Working Rules Are Defined and Followed in Server and Network Rooms (Applies where personnel or contractors work in protected equipment areas.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Define and enforce rules for work inside protected equipment rooms: keep security doors closed, supervise contractors where required, restrict photography and recording to authorised purposes, prohibit food, drinks and unrelated storage, keep cooling and escape routes clear, and secure the room after work. These rules govern conduct inside the room; access authorisation and personnel training are assessed separately. (Applies where personnel or contractors work in protected equipment areas.)", "evidence": "Approved working instructions, contractor supervision records, room inspections and observed compliance.", "risk_text": "R1: An authorised worker exposes information or enables unauthorised entry by disregarding secure-area working rules.<br>R2: Unsafe work or materials left in the room obstruct cooling or damage live equipment and interrupt services.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.6"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.6", "annex_kind": "annex", "applicability": {"condition": "where personnel or contractors work in protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-OTHER-SECURE-AREA-WORK','Work in Other Secure Areas Follows Defined Protection Rules','Work in Other Secure Areas Follows Defined Protection Rules','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T17", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Define and apply working rules for secure areas outside the equipment rooms covered by PHY-WORK. Address who may conduct activities, supervision where needed and unauthorised recording or removal of information. Tailor rules to the actual area instead of copying server-room housekeeping requirements.", "evidence": "Rules for the additional secure areas, communication to relevant workers or contractors, and observations or work records demonstrating their use.", "risk_text": "Authorised entry is mistaken for permission to record, expose or interfere with protected information while working inside a secure area.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.6"], "source": "iso27001-nis2-v7", "annex": "A.7.6", "annex_kind": "annex", "applicability": {"condition": "Work takes place in secure areas outside the equipment areas already assessed under PHY-WORK", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','TRN-PHY','Relevant Personnel Receive Physical Security Training (Applies to personnel whose duties involve protected equipment areas.)','Relevant Personnel Receive Physical Security Training (Applies to personnel whose duties involve protected equipment areas.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Before relevant work, instruct staff and contractors on applicable access, working and emergency rules, including whom to alert about intrusion, smoke, leaks or failed cooling and what actions they are authorised to take. Refresh instruction when needed and verify understanding. General training governance stays in T06. (Applies to personnel whose duties involve protected equipment areas.)", "evidence": "Role-appropriate instructions, induction/refresher records and practical checks or exercises showing understood reporting and action boundaries.", "risk_text": "R1: Personnel fail to report a physical or environmental warning promptly, allowing damage or interruption to escalate.<br>R2: Untrained personnel respond outside their competence or bypass room safeguards, causing avoidable exposure or outage.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.6.3", "A.7.6"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.6.3", "annex_kind": "annex", "applicability": {"condition": "to personnel whose duties involve protected equipment areas", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','PHY-ACCESS-TEST','Physical Access Controls Are Tested for Effectiveness (Applies to physical entry controls operated by the entity.)','Physical Access Controls Are Tested for Effectiveness (Applies to physical entry controls operated by the entity.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-AREA · Protected areas, access and secure working", "topic_label": "I-PHY-AREA · Protected areas, access and secure working", "description": "Test physical entry controls at planned intervals and after relevant significant incidents or changes. Use authorised, risk-appropriate scenarios to verify that unauthorised or revoked credentials are rejected and that bypass routes or entry behind an authorised person are prevented or detected as intended. Record deficiencies and verify corrective action. Access-right reviews alone do not demonstrate that entry controls work. Coordinate tests to protect people and service availability; covert penetration testing is not universally required. (Applies to physical entry controls operated by the entity.)", "evidence": "Approved test scope and scenarios, denied-entry/bypass test results, identified defects, assigned corrective actions and retest evidence.", "risk_text": "R1: Defective entry controls allow an unauthorised person to reach protected systems despite apparently correct access permissions.<br>R2: Untested changes leave bypass routes undetected, exposing equipment or information to theft or interference.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.2"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.2", "annex_kind": "annex", "applicability": {"condition": "to physical entry controls operated by the entity", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','PHY-SITING','Servers and Network Equipment Are Securely Positioned and Protected (Applies where the entity controls the physical installation of ICT equipment.)','Servers and Network Equipment Are Securely Positioned and Protected (Applies where the entity controls the physical installation of ICT equipment.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-EQUIP · Equipment protection and tamper checks", "topic_label": "I-PHY-EQUIP · Equipment protection and tamper checks", "description": "Position and secure equipment and racks to prevent accidental damage, unauthorised handling and blocked airflow. Consider local leak sources, falling objects and access to consoles or removable components; protect shared racks where needed. This checks equipment placement and protection, not the room''s general fire or intrusion safeguards. (Applies where the entity controls the physical installation of ICT equipment.)", "evidence": "Equipment/rack layout, physical inspection, installation requirements and corrected placement/protection defects.", "risk_text": "R1: Poor equipment placement or obstructed airflow causes overheating, damage or a service outage.<br>R2: Exposed consoles, components or unsecured equipment allow unauthorised observation, removal or manipulation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.3", "A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.3", "annex_kind": "annex", "applicability": {"condition": "where the entity controls the physical installation of ICT equipment", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-OTHER-EQUIPMENT-PROTECTION','Other Information-Related Equipment Is Safely Positioned and Protected','Other Information-Related Equipment Is Safely Positioned and Protected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T17", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Assess relevant information-related equipment not covered by PHY-SITING, including associated non-ICT equipment where present. Position and protect it against damage, unauthorised handling and exposure of information during use; reuse safeguards already demonstrated for the same equipment.", "evidence": "Identification of additional equipment, siting and protection decisions, and physical inspection showing protection from relevant damage or information exposure.", "risk_text": "Equipment outside the ICT installation scope is damaged or exposes information because its position and protection were not assessed.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.8"], "source": "iso27001-nis2-v7", "annex": "A.7.8", "annex_kind": "annex", "applicability": {"condition": "Information-related equipment exists outside the scope already assessed under PHY-SITING", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','PHY-TAMPER-CHECK','Exposed ICT Equipment Is Checked for Physical Tampering (Applies where the entity controls equipment subject to material physical tampering risk.)','Exposed ICT Equipment Is Checked for Physical Tampering (Applies where the entity controls equipment subject to material physical tampering risk.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-EQUIP · Equipment protection and tamper checks", "topic_label": "I-PHY-EQUIP · Equipment protection and tamper checks", "description": "Identify equipment with material physical tampering exposure and define risk-based inspection intervals and triggers. Inspect relevant enclosures, components and connections for unexplained changes or signs of interference, using seals or recorded baselines where appropriate. Record results and route suspected tampering through incident response while preserving relevant evidence. This checks equipment during operation, not only after maintenance, and does not require routine inspection of every device. (Applies where the entity controls equipment subject to material physical tampering risk.)", "evidence": "Risk-based equipment scope, inspection intervals and triggers, baseline or seal records where used, completed inspection records and investigated discrepancies.", "risk_text": "R1: An unauthorised physical modification remains unnoticed and enables information theft or changes to system operation.<br>R2: Unexplained component or connection changes remain undetected until they disrupt a critical service.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.8", "annex_kind": "annex", "applicability": {"condition": "where the entity controls equipment subject to material physical tampering risk", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C46.2','Protective Measures Address Physical and Environmental Hazards','Protective Measures Address Physical and Environmental Hazards','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Use the documented physical and environmental risk assessment (ENV-RISK) to apply suitable protection to server and network rooms, such as fire detection and suitable suppression, leak protection and avoidance of hazardous storage where the assessment requires them. Normal temperature and humidity control is assessed under PHY-CLIMATE. No particular suppression technology or building design is universally prescribed. Review and test relevant measures regularly and after significant incidents or changes.", "evidence": "Site hazard assessment, implemented fire/water protection, inspection and test records and corrective actions.", "risk_text": "R1: Fire, water, heat or another material site-specific hazard damages equipment or media and interrupts the supported services.<br>R2: A site-specific hazard destroys or irreversibly damages stored information, leaving required records unavailable even after systems and premises are restored.<br>R3: Fire or extreme environmental conditions injure personnel or make the premises unsafe to occupy, preventing safe operation or incident response.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.3", "A.7.5", "A.7.8"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.3", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','ISO-OTHER-FACILITY-EXPOSURE','Confidential Work in Other Facilities Is Protected from Outside Observation','Confidential Work in Other Facilities Is Protected from Outside Observation','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T17", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "For relevant non-equipment offices or facilities, prevent unauthorised visual or audible observation of confidential work. Reuse building entry and boundary controls; this tests exposure during authorised work, not access permission.", "evidence": "Facility layout and observation checks demonstrating protection against relevant outside sight or hearing.", "risk_text": "Confidential information is overheard or observed without anyone entering the protected room.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.3"], "source": "iso27001-nis2-v7", "annex": "A.7.3", "annex_kind": "annex", "applicability": {"condition": "Relevant offices or facilities exist beyond the equipment-room scope already assessed", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-OTHER-FACILITY-HAZARDS','Other ISMS Facilities Are Protected against Assessed Physical Hazards','Other ISMS Facilities Are Protected against Assessed Physical Hazards','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T17", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Apply suitable safeguards to relevant offices, archives and other non-equipment facilities against assessed physical or environmental damage. Reuse ENV-RISK and existing fire/water safeguards; supplement only the area population not covered by C46.2.", "evidence": "Additional facility coverage, risk-linked safeguards and inspection or test results for selected protections.", "risk_text": "Information in offices or archives is damaged while protection concentrates only on equipment rooms.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.3", "A.7.5"], "source": "iso27001-nis2-v7", "annex": "A.7.3", "annex_kind": "annex", "applicability": {"condition": "Relevant offices or facilities exist beyond the equipment-room scope already assessed", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C46.3','Supporting Utilities Meet Service Resilience Requirements','Supporting Utilities Meet Service Resilience Requirements','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Provide power and connectivity arrangements capable of meeting the required service resilience, and assess continuity arrangements for cooling. Actual temperature and humidity control is assessed under PHY-CLIMATE. Determine the need and capacity for uninterruptible power supplies (UPS), alternative power, cooling redundancy and emergency fuel or support from assessed interruption tolerances; no generator is required for every room.", "evidence": "Utility dependency and capacity assessment, installed safeguards and runtime calculations, emergency supply arrangements where needed.", "risk_text": "R1: Loss of power, cooling or communications disables dependent systems or premises for longer than the service can tolerate.<br>R2: An abrupt loss of power corrupts in-progress writes or loses uncommitted data, requiring data reconstruction even when service is restored quickly.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.11", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-CLIMATE','Server and Network Rooms Maintain Suitable Temperature and Humidity (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)','Server and Network Rooms Maintain Suitable Temperature and Humidity (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Keep equipment within justified operating temperature and humidity ranges using appropriately sized cooling, ventilation or other suitable environmental controls. Account for heat load, airflow and foreseeable hot-weather conditions; verify actual conditions at representative equipment locations. Assess cooling failure and redundancy needs through utility resilience (C46.3); alarm escalation remains under C46.5 and maintenance under C46.6. A dedicated air-conditioning unit is not mandatory where another effective method maintains the required conditions. (Applies where the entity operates server rooms, network rooms or comparable equipment environments.)", "evidence": "Equipment environmental requirements, justified operating ranges, heat-load/cooling capacity assessment and representative temperature/humidity readings demonstrating effective environmental control.", "risk_text": "R1: Inadequate cooling or airflow causes overheating, equipment throttling, damage or service shutdown.<br>R2: Unsuitable humidity permits condensation or electrostatic effects that damage equipment and impair reliable operation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5", "A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.5", "annex_kind": "annex", "applicability": {"condition": "where the entity operates server rooms, network rooms or comparable equipment environments", "condition_source": "control_name", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C46.7','Power and Telecommunications Infrastructure Is Protected','Power and Telecommunications Infrastructure Is Protected','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ENV · Hazard protection and supporting infrastructure", "topic_label": "I-PHY-ENV · Hazard protection and supporting infrastructure", "description": "Protect relevant power and communications routes, distribution points and patch panels against damage or unauthorised interference. Address interception of communications and electrical interference through suitable routing, separation, enclosures and access restrictions; identify cables sufficiently for safe work.", "evidence": "Cable-route and distribution plans, inspections of protective measures, labelling and controlled access to distribution points.", "risk_text": "R1: Damage or tampering to power or telecommunications infrastructure interrupts dependent services.<br>R2: Interception of exposed telecommunications infrastructure discloses sensitive communications.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.12"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.12", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C46.6','Supporting Utilities and Emergency Supplies Are Maintained and Tested','Supporting Utilities and Emergency Supplies Are Maintained and Tested','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "Maintain and test the power, cooling, communications and emergency arrangements needed for the service. Check relevant UPS batteries, transfer arrangements and other installed safeguards under controlled conditions, and correct failures. Distinguish this supporting-infrastructure work from server and network hardware maintenance.", "evidence": "Maintenance schedules, service reports, controlled load/failover tests where appropriate and resolved defects.", "risk_text": "A degraded utility safeguard or emergency supply fails when demanded, causing an avoidable outage despite nominal backup capacity.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.11", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-MAINT','Server and Network Hardware Is Maintained by Authorised Personnel','Server and Network Hardware Is Maintained by Authorised Personnel','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "Schedule and perform risk-appropriate hardware maintenance using manufacturer guidance and operational needs. Authorise technicians and record the work and defects. Apply existing change and access controls to disruptive or remote work. This covers hardware servicing, not software patching or maintenance of building utilities.", "evidence": "Hardware maintenance schedule, technician authorisations, service reports and defect follow-up linked to relevant assets.", "risk_text": "R1: Unmaintained hardware degrades or fails and interrupts the supported service.<br>R2: Unauthorised or uncontrolled servicing exposes information or alters critical equipment.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','PHY-RETURN','Maintained or Repaired Equipment Is Checked Before Return to Service','Maintained or Repaired Equipment Is Checked Before Return to Service','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-MAINT · Maintenance and return to service", "topic_label": "I-PHY-MAINT · Maintenance and return to service", "description": "After hardware maintenance or repair, verify correct operation and that relevant security settings and physical protections remain effective before releasing equipment for operational use. Check for unexpected changes and remove temporary service access where used. This checks the post-maintenance result, not the maintenance activity or initial procurement acceptance.", "evidence": "Post-maintenance checks, relevant setting/component comparison, temporary-access closure and release record.", "risk_text": "R1: Equipment returns to service with altered security settings or residual service access, enabling unauthorised use.<br>R2: An undetected repair defect causes renewed failure or unreliable operation after release.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.13"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.13", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C46.5','Environmental and Utility Deviations Trigger Alerts to Responsible Personnel','Environmental and Utility Deviations Trigger Alerts to Responsible Personnel','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T17", "subgroup": "I-PHY-ALERT · Environmental and utility alerting", "topic_label": "I-PHY-ALERT · Environmental and utility alerting", "description": "Define justified thresholds for relevant conditions such as temperature, humidity and power status. Monitor them and route deviations to personnel able to act, including outside working hours. Test that the alert reaches its recipient; a sensor display without effective escalation is insufficient.", "evidence": "Approved thresholds, sensor/alarm configuration, monitoring history and alert-delivery and response tests.", "risk_text": "An environmental or utility deviation goes unnoticed or reaches no responder, escalating into equipment damage or service interruption.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.7.5", "A.7.11"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.7.5", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C37.1','Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners','Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Effectiveness Assessments Have Defined Scope, Methods, Timing and Owners. Specify which measures will be evaluated, how valid results will be obtained, when assessment and analysis occur, and who performs them. Base the programme on assessed risks and relevant incident experience, and record usable criteria for interpreting the results.", "evidence": "Examples: an assessment programme or equivalent records identifying measures in scope, methods for valid results, assessment/analysis timing, responsible persons and interpretation criteria, linked to assessed risks and relevant incident experience.", "risk_text": "Assessments measure activity rather than protective outcomes or use inconsistent criteria, producing false assurance and misdirected improvement priorities.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "9.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-MEASUREMENT-DESIGN','ISMS Process Measurements Have Defined Methods, Timing and Responsibilities','ISMS Process Measurements Have Defined Methods, Timing and Responsibilities','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine which ISMS processes and performance results need monitoring or measurement, the methods for valid results, when monitoring and analysis occur and who performs each. Define usable evaluation criteria and retain the arrangements. Reuse C37.1 for security-measure assessment design; add only the management-system process coverage not already defined there. No fixed dashboard, numerical target for every process or universal metric set is required.", "evidence": "Process-level measurement and evaluation arrangements with scope, methods, monitoring and analysis timing, responsible roles and criteria, linked to the existing security-measure assessment programme.", "risk_text": "The organisation judges its ISMS from technical test results while unmeasured governance or operating-process failures prevent intended outcomes.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "annex": "9.1", "annex_kind": "clause", "applicability": {"condition": "ISMS processes and whole-system performance within the documented scope; clauses 4-10 are not excluded through the SoA", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C37.5','Operational Systems Undergo Risk-Based Technical Security Testing','Operational Systems Undergo Risk-Based Technical Security Testing','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Operational Systems Undergo Risk-Based Technical Security Testing. Test the technical security of systems already in use, including acquired applications and infrastructure, against relevant attack paths such as unauthorised access, privilege escalation or movement between network segments. Define the scope, methods and frequency according to risk; authorise testing and protect service availability and data. Document findings and track remediation. This is distinct from pre-release development tests, monitoring-detection checks and physical entry tests; existing results may be reused where they demonstrate the required operational coverage.", "evidence": "Risk-based test scope and schedule; authorisation and operational safety arrangements; reports identifying tested systems, methods and findings; remediation records. Testing does not require uncontrolled exploitation of live systems or a specific commercial testing product.", "risk_text": "R1: Untested operational attack paths remain exploitable and are falsely assumed to be protected.<br>R2: Poorly controlled security tests disrupt operational services or damage data.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.8.34"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.8.34", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C37.2','Security Effectiveness Assessments Are Performed and Reviewed','Security Effectiveness Assessments Are Performed and Reviewed','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Carry out the planned effectiveness assessments and review the underlying results against the intended protective outcomes. A completed test record without examination and interpretation of its results does not establish that the organisation assessed whether the security measures actually work.", "evidence": "Examples: completed effectiveness assessments with underlying results and evidence of review and interpretation against the intended protective outcomes.", "risk_text": "Ineffective safeguards remain relied upon because their operation and results are not examined, allowing known types of incident to recur.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "9.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-ISMS-PERFORMANCE','Information Security Performance and ISMS Effectiveness Are Evaluated','Information Security Performance and ISMS Effectiveness Are Evaluated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Use the methods, timing, responsibilities and criteria established under ISO-ISMS-MEASUREMENT-DESIGN and C37.1 to evaluate information security performance and the ISMS as a whole. Retain analysis and conclusions about intended results; individual technical test results alone are insufficient.", "evidence": "Performance analysis covering ISMS processes and objectives, underlying measurement results and recorded conclusions; links to the existing assessment programme and management review.", "risk_text": "Individual safeguards appear effective while management-system failures prevent the organisation from achieving its security objectives.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.1"], "source": "iso27001-nis2-v7", "annex": "9.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C37.3','Security Compliance Is Monitored and Reported to Management','Security Compliance Is Monitored and Reported to Management','false','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Monitor actual compliance with applicable security policies, rules and standards, and report the findings and relevant deviations to the management body. Retain the link between monitoring results and the information reported; a management summary unsupported by monitoring, or findings never reported, does not demonstrate the complete process.", "evidence": "Examples: monitoring results against applicable internal security policies, rules and standards, with evidence that the findings and relevant deviations were reported to the management body.", "risk_text": "Routine departures from security rules persist without management visibility, leaving unsafe practices uncorrected.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "A.5.36", "annex_kind": "annex"}'::jsonb),
  ('ISO27001','C37.4','Competent, Impartial Reviews Assess Security Management and Implementation','Competent, Impartial Reviews Assess Security Management and Implementation','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-ASSESS · Effectiveness and assurance", "topic_label": "F-ASSESS · Effectiveness and assurance", "description": "Competent, Impartial Reviews Assess Security Management and Its Implementation. Review people, processes and technology at planned intervals and after significant incidents or significant operational or risk changes where CIR applies. Ensure appropriate audit competence and independence from the area reviewed, or documented alternative safeguards for impartiality where size prevents separation. Report results to management and route findings to correction or authorised risk treatment.", "evidence": "Examples: completed reviews covering security-management people, processes and technology, with planned/event-driven timing, reviewer competence and independence or documented alternative impartiality safeguards where size prevents separation. Include management reporting and routing of findings to correction or authorised treatment, checking significant incident/change triggers where CIR applies.", "risk_text": "A biased or unqualified review overlooks weaknesses or reports an inaccurate security posture, leading to inappropriate corrective decisions.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.2.1", "A.5.35"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "9.2.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-REVIEW-CHANGE','Significant Changes Receive an Independent Security Review','Significant Changes Receive an Independent Security Review','false','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "When significant changes occur, obtain an independent review of the affected information-security approach and its implementation. Match the review scope to the change and retain conclusions and follow-up. Reuse C37.4 reviews and internal audit evidence when they already cover the event; an unchanged annual review date alone does not demonstrate that the changed arrangements were reviewed. This applies through ISO control selection, not only through CIR scope.", "evidence": "Significant-change records linked to independent review scope, reviewer impartiality, conclusions and follow-up. Where C37.4 already covers the same change, reference its assessment and evidence rather than repeat the review. If no significant change occurred, assess the defined review triggers, responsibility for recognising and referring changes, and arrangements for an impartial review through a proportionate walkthrough or safe scenario. This demonstrates readiness, not a completed event-specific review.", "risk_text": "A significant change invalidates security arrangements while independent review still assesses the previous operating model.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["A.5.35"], "source": "iso27001-nis2-v7", "annex": "A.5.35", "annex_kind": "annex", "applicability": {"condition": "A significant change affects selected information-security arrangements; assess trigger readiness when no event occurred", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-AUDIT-PLAN','An Internal ISMS Audit Programme Defines Coverage and Priorities','An Internal ISMS Audit Programme Defines Coverage and Priorities','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Plan internal audits of the organisation''s ISMS requirements and ISO 27001. Define frequency, methods, responsibilities, criteria and scope, considering process importance and previous audit results; no arbitrary annual frequency is imposed.", "evidence": "Audit programme, risk/importance rationale, schedule and defined audit criteria and scopes.", "risk_text": "Important ISMS processes or requirements are systematically omitted from internal audit coverage.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.2.1", "9.2.2"], "source": "iso27001-nis2-v7", "annex": "9.2.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-AUDITOR-SELECTION','Internal ISMS Auditors Are Competent and Impartial','Internal ISMS Auditors Are Competent and Impartial','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Select auditors with the competence needed for their assignments and ensure the objectivity and impartiality of the audit process. Reuse competence records; evaluate conflicts for the actual assignments.", "evidence": "Auditor competence evidence, assignment decisions and independence/conflict safeguards.", "risk_text": "Audit findings are unreliable because auditors lack competence or assess work without adequate impartiality.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["7.2", "9.2.2"], "source": "iso27001-nis2-v7", "annex": "7.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-AUDIT-EXECUTION','Planned Internal ISMS Audits Are Carried Out','Planned Internal ISMS Audits Are Carried Out','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Conduct the planned audits to determine ISMS conformity and effective implementation and maintenance. Reuse existing independent reviews only where the required ISMS audit scope and criteria are demonstrably covered.", "evidence": "Completed audit records tied to the programme, examined evidence and conclusions against the stated criteria.", "risk_text": "The audit programme exists on paper but significant ISMS failures are never examined.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.2.1", "9.2.2"], "source": "iso27001-nis2-v7", "annex": "9.2.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-AUDIT-REPORTING','Internal ISMS Audit Results Are Reported and Retained','Internal ISMS Audit Results Are Reported and Retained','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Report audit results to relevant management and retain evidence of the programme and results. Record enough detail to support findings and follow-up; generic technical-test output alone is insufficient.", "evidence": "Audit reports, recipients or management acknowledgement, retained programme records and traceable findings.", "risk_text": "Management cannot act on audit findings or substantiate what was actually audited.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.2.2"], "source": "iso27001-nis2-v7", "annex": "9.2.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-MR-CONDUCT','Top Management Reviews the ISMS at Planned Intervals','Top Management Reviews the ISMS at Planned Intervals','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Top management reviews the ISMS at planned intervals to determine continuing suitability, adequacy and effectiveness. Existing governance meetings may serve this purpose if the ISMS review is identifiable.", "evidence": "Review timing, top-management participation and an identifiable review of the ISMS; required inputs and outputs are assessed in separate controls.", "risk_text": "Top management does not periodically examine whether the management system remains fit for purpose.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["9.3.1"], "source": "iso27001-nis2-v7", "annex": "9.3.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-MR-INPUTS','Management Review Considers the Required ISMS Inputs','Management Review Considers the Required ISMS Inputs','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Consider previous review actions; changes in context and relevant party needs; security performance trends including nonconformities, corrective actions, measurements, audits and objective achievement; party feedback; risk assessment and treatment status; and improvement opportunities.", "evidence": "Review input pack and discussion record demonstrating consideration of each relevant input, including prior actions and current risk and performance information.", "risk_text": "Management reaches an apparently informed conclusion while omitting material changes, performance failures or unresolved risks.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.3.2"], "source": "iso27001-nis2-v7", "annex": "9.3.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-MR-DECISIONS','Management Review Records Decisions on Improvements and ISMS Changes','Management Review Records Decisions on Improvements and ISMS Changes','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Retain documented review results including decisions on improvement opportunities and any need to change the ISMS. Record justified decisions to retain the current approach where appropriate; a meeting date or slide pack alone is not an outcome.", "evidence": "Recorded review conclusions and decisions, including needed improvements or changes and sufficient traceability to the reviewed issues.", "risk_text": "Management review produces discussion but no retained direction for improvement or necessary change.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["9.3.3"], "source": "iso27001-nis2-v7", "annex": "9.3.3", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-MR-FOLLOW-UP','Management Review Actions Are Communicated and Followed Through','Management Review Actions Are Communicated and Followed Through','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Communicate agreed review actions to responsible owners and track implementation or a justified revised decision. Reuse existing change and improvement records; do not duplicate action tickets.", "evidence": "Review-action owners, communication, progress and closure evidence, with outstanding status available to the next review.", "risk_text": "Decisions remain in minutes and known ISMS weaknesses persist despite management approval.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.1", "6.3", "9.3.2"], "source": "iso27001-nis2-v7", "annex": "10.1", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','C47.1','Security Measure Deficiencies Receive Corrective Action Without Undue Delay','Security Measure Deficiencies Receive Corrective Action Without Undue Delay','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-FIX · Corrective actions", "topic_label": "F-FIX · Corrective actions", "description": "Take appropriate corrective action on identified security-measure deficiencies without undue delay, with dates and progress traceable to the identified weakness. Examine actual action and the justification for any continuing delay in light of the risk; merely opening a ticket or listing a future action does not demonstrate timely correction.", "evidence": "Examples: identified measure deficiencies linked to correction decisions and actual actions, with dates, progress and delay explanations sufficient to assess whether appropriate correction occurred without undue delay.", "risk_text": "An identified protection weakness remains active while correction is delayed, allowing the same failure or attack path to recur.", "default_absent": "Major", "default_partial": "Minor", "iso_refs": ["10.2", "A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "10.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-NC-CORRECTION','ISMS Process Nonconformities Are Controlled and Their Consequences Addressed','ISMS Process Nonconformities Are Controlled and Their Consequences Addressed','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "React to management-system nonconformities by controlling and correcting them as applicable and dealing with their consequences. Record the failure and actual response; opening a task is not correction. This covers process failures such as an omitted management review or uncontrolled required records, beyond security-measure deficiencies already assessed under C47.1. Cause elimination remains under ISO-NC-RECURRENCE.", "evidence": "ISMS process nonconformity records identifying the requirement, observed failure, containment or correction, consequences and actual response. Link existing corrective-action records for any shared deficiency. If no relevant process nonconformity occurred, assess response readiness through the defined responsibilities and arrangements for control, correction and consequence handling, using a proportionate walkthrough or safe scenario. Do not fabricate a failure; keep clause 10.2 coverage under review.", "risk_text": "A management-system failure remains active or its consequences persist while the organisation records only a future corrective-action intention.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2"], "source": "iso27001-nis2-v7", "annex": "10.2", "annex_kind": "clause", "applicability": {"condition": "Management-system nonconformities beyond the security-measure deficiency population assessed under C47.1; review readiness if no case occurred", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','ISO-NC-CAUSE','Causes of ISMS Nonconformities Are Determined','Causes of ISMS Nonconformities Are Determined','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Review each nonconformity and determine its causes to support proportionate recurrence-prevention decisions. Record the nature and cause; no particular root-cause technique is compulsory. Incident root-cause analysis remains in incident response.", "evidence": "Nonconformity records showing the failure, cause analysis and the evidence supporting the causal conclusion.", "risk_text": "The visible defect is corrected without identifying why it happened, so the same failure recurs.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2"], "source": "iso27001-nis2-v7", "annex": "10.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-NC-EXTENT','Similar or Potential ISMS Nonconformities Are Evaluated','Similar or Potential ISMS Nonconformities Are Evaluated','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Determine whether the identified nonconformity also exists or could occur elsewhere and record the resulting need for action. Reuse the same nonconformity record. For correction and effectiveness, use C47.1/C47.2 for the security-measure deficiency population and ISO-NC-CORRECTION/ISO-NC-EFFECTIVENESS for other ISMS process cases; reuse an existing assessment where it already demonstrates the same outcome, scope and period.", "evidence": "Extent-of-condition evaluation across relevant processes, systems or locations and linked recurrence-prevention actions.", "risk_text": "A defect is fixed locally while the same underlying failure remains in other parts of the organisation.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2"], "source": "iso27001-nis2-v7", "annex": "10.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-NC-RECURRENCE','Identified ISMS Causes Receive Proportionate Recurrence-Prevention Action','Identified ISMS Causes Receive Proportionate Recurrence-Prevention Action','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Implement the action determined necessary to eliminate the cause and prevent recurrence, including needed ISMS changes. Reuse C47.1 for actions already covering security-measure deficiencies; this adds management-system cause treatment beyond immediate correction. ISO-NC-CORRECTION covers the immediate response; C47.2 and ISO-NC-EFFECTIVENESS provide effectiveness checks for their respective populations.", "evidence": "Cause-to-action decisions, completed management-system changes and retained results, linked to existing corrective-action and effectiveness records.", "risk_text": "The cause is documented but only the immediate defect is corrected, allowing the same ISMS failure to recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2"], "source": "iso27001-nis2-v7", "annex": "10.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-NC-EFFECTIVENESS','ISMS Process Corrective Actions Are Verified for Effectiveness','ISMS Process Corrective Actions Are Verified for Effectiveness','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "For corrective actions on management-system process nonconformities, verify implementation and evaluate whether the action removed the cause or prevented the intended recurrence. Retain results and reopen ineffective actions. Assess after an appropriate opportunity to observe the result; a closed task or absence of a repeat before the process ran again is not sufficient evidence. Reuse C47.2 where it already tests the same action and scope.", "evidence": "Cause-linked effectiveness criteria, implementation evidence, follow-up process records and documented closure or further-action decisions. No fabricated cases or universal waiting period are required. Where no relevant action exists, review the arrangements for determining and evaluating effectiveness and record that no actual effectiveness result is available. Where an action exists but there has not yet been an appropriate observation opportunity, retain the planned review and its status as pending; do not treat it as verified effective or exclude clause 10.2.", "risk_text": "A management-system corrective action is declared successful without testing its effect, allowing the same process failure to recur.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2"], "source": "iso27001-nis2-v7", "annex": "10.2", "annex_kind": "clause", "applicability": {"condition": "Management-system corrective actions beyond the weakness-remediation population already assessed under C47.2", "condition_source": "applicability_field", "scope_group": null, "presentation": "inline"}}'::jsonb),
  ('ISO27001','C47.2','Corrective-Action Completion and Effectiveness Are Verified','Corrective-Action Completion and Effectiveness Are Verified','true','ISO27001-318-v7','{"coverage": "voll", "origin": "shared_nis2", "topic": "T18", "subgroup": "F-FIX · Corrective actions", "topic_label": "F-FIX · Corrective actions", "description": "Before closing a corrective action, verify both that the agreed change was implemented and that it resolved the identified weakness; a completed task or ticket alone does not establish effectiveness.", "evidence": "Examples: verification of completed corrective actions and relevant follow-up results showing whether the identified weakness was resolved, with closure or further-action decisions where applicable.", "risk_text": "A corrective action is closed despite not removing the underlying weakness, creating false assurance and allowing recurrence.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.2", "A.5.36"], "source": "iso27001-nis2-v7", "shared_with": "NIS2", "annex": "10.2", "annex_kind": "clause"}'::jsonb),
  ('ISO27001','ISO-CONTINUAL-IMPROVEMENT','The ISMS Is Continually Improved Beyond Individual Defect Correction','The ISMS Is Continually Improved Beyond Individual Defect Correction','true','ISO27001-318-v7','{"coverage": "voll", "origin": "iso_delta", "topic": "T18", "subgroup": "ISO-specific outcome", "topic_label": "ISO-specific outcome", "description": "Use performance, risk, review and operational information to improve ISMS suitability, adequacy and effectiveness. Demonstrate implemented improvements; do not require an arbitrary annual number of improvement projects.", "evidence": "Improvement decisions and implemented changes; evidence of resulting benefit or evaluation.", "risk_text": "The ISMS remains static and becomes ineffective as operations and threats change.", "default_absent": "Minor", "default_partial": "Minor", "iso_refs": ["10.1"], "source": "iso27001-nis2-v7", "annex": "10.1", "annex_kind": "clause"}'::jsonb)
