INSERT INTO public.risks (risk_id,quelle,iso_anchor,text_de,text_en,status,primary_control_framework,primary_control_id,meta) VALUES
  ('R6-ACCESS-RECERT','Unified Catalogue v6',ARRAY['A.5.18']::text[],'R1: Permissions accumulated through earlier roles or projects remain active and enable unauthorised access to or modification of information.<br>R2: A review is marked complete while permissions it rejected remain usable.','R1: Permissions accumulated through earlier roles or projects remain active and enable unauthorised access to or modification of information.<br>R2: A review is marked complete while permissions it rejected remain usable.','active','ISO27001','ACCESS-RECERT','{"topic": "T07", "subgroup": "I-ACC · Identity and access control", "language": "en"}'::jsonb),
  ('R6-ASSET-OFFSITE','Unified Catalogue v6',ARRAY['A.6.7','A.7.9','A.8.1']::text[],'R1: Loss, theft or observation of an off-site asset exposes organisational information.<br>R2: Damage or loss of an off-site asset interrupts work or makes locally held data unavailable.','R1: Loss, theft or observation of an off-site asset exposes organisational information.<br>R2: Damage or loss of an off-site asset interrupts work or makes locally held data unavailable.','active','ISO27001','ASSET-OFFSITE','{"topic": "T04", "subgroup": "I-INFO-SAFE · Information handling safeguards", "language": "en"}'::jsonb),
  ('R6-AUTH-INTERVAL','Unified Catalogue v6','{}'::text[],'A credential exposed without detection remains usable beyond its defined change interval, allowing continued unauthorised access.','A credential exposed without detection remains usable beyond its defined change interval, allowing continued unauthorised access.','active','NIS2','AUTH-INTERVAL','{"topic": "T07", "subgroup": "J-CIR-INTERVAL · Credential change intervals within CIR scope", "language": "en"}'::jsonb),
  ('R6-BC-BIA','Unified Catalogue v6',ARRAY['A.5.30']::text[],'Critical dependencies and the consequences of prolonged disruption are misunderstood, so recovery priorities and continuity arrangements do not protect the services that matter most.','Critical dependencies and the consequences of prolonged disruption are misunderstood, so recovery priorities and continuity arrangements do not protect the services that matter most.','active','ISO27001','BC-BIA','{"topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "language": "en"}'::jsonb),
  ('R6-BC-RPO','Unified Catalogue v6',ARRAY['A.8.13']::text[],'Recovery arrangements restore data that is too old, causing unacceptable loss of transactions or records even when the service is restored quickly.','Recovery arrangements restore data that is too old, causing unacceptable loss of transactions or records even when the service is restored quickly.','active','ISO27001','BC-RPO','{"topic": "T15", "subgroup": "C-BACKUP · Define data recovery targets and implement protected backups", "language": "en"}'::jsonb),
  ('R6-BC-RTO','Unified Catalogue v6',ARRAY['A.5.30']::text[],'Recovery teams work to arbitrary or inconsistent deadlines, allowing services to remain unavailable beyond business tolerances.','Recovery teams work to arbitrary or inconsistent deadlines, allowing services to remain unavailable beyond business tolerances.','active','ISO27001','BC-RTO','{"topic": "T15", "subgroup": "C-IMPACT · Assess business impact and define service recovery targets", "language": "en"}'::jsonb),
  ('R6-C11.1','Unified Catalogue v6','{}'::text[],'Authority communications or required follow-up are delayed because no authorised EU representative can act for the provider.','Authority communications or required follow-up are delayed because no authorised EU representative can act for the provider.','active','NIS2','C11.1','{"topic": "T01", "subgroup": "S-SCP · Scope and EU representation", "language": "en"}'::jsonb),
  ('R6-C12.1','Unified Catalogue v6','{}'::text[],'A change in scope, classification or jurisdiction goes unnoticed, causing missed obligations or reliance on the wrong competent authority.','A change in scope, classification or jurisdiction goes unnoticed, causing missed obligations or reliance on the wrong competent authority.','active','NIS2','C12.1','{"topic": "T01", "subgroup": "S-SCP · Scope and EU representation", "language": "en"}'::jsonb),
  ('R6-C14.1','Unified Catalogue v6','{}'::text[],'Incomplete or inaccurate data prevent correct identification, scope tracking or contact by the competent authority.','Incomplete or inaccurate data prevent correct identification, scope tracking or contact by the competent authority.','active','NIS2','C14.1','{"topic": "T01", "subgroup": "S-REG · Registration and changes", "language": "en"}'::jsonb),
  ('R6-C14.2','Unified Catalogue v6','{}'::text[],'The competent authority cannot reliably include or contact the entity through the required registration process, triggering corrective follow-up for an omitted or late submission.','The competent authority cannot reliably include or contact the entity through the required registration process, triggering corrective follow-up for an omitted or late submission.','active','NIS2','C14.2','{"topic": "T01", "subgroup": "S-REG · Registration and changes", "language": "en"}'::jsonb),
  ('R6-C15.2','Unified Catalogue v6','{}'::text[],'Authority records remain outdated, regulatory contact is impaired and the change-notification duty is not met.','Authority records remain outdated, regulatory contact is impaired and the change-notification duty is not met.','active','NIS2','C15.2','{"topic": "T01", "subgroup": "S-REG · Registration and changes", "language": "en"}'::jsonb),
  ('R6-C19.1','Unified Catalogue v6','{}'::text[],'Incorrect domain-holder records delay identification and contact during abuse investigations or incident response.','Incorrect domain-holder records delay identification and contact during abuse investigations or incident response.','active','NIS2','C19.1','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.2','Unified Catalogue v6','{}'::text[],'False or unreachable registrant details are accepted as genuine, allowing abusive registrations to evade reliable attribution and follow-up.','False or unreachable registrant details are accepted as genuine, allowing abusive registrations to evade reliable attribution and follow-up.','active','NIS2','C19.2','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.3','Unified Catalogue v6','{}'::text[],'Registrants and other users cannot understand or challenge how registration data are verified, leading to inconsistent submissions and avoidable disputes.','Registrants and other users cannot understand or challenge how registration data are verified, leading to inconsistent submissions and avoidable disputes.','active','NIS2','C19.3','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.4','Unified Catalogue v6','{}'::text[],'R1: Investigators and other users cannot obtain required non-personal domain information promptly, delaying abuse identification and follow-up.<br>R2: Publication that fails to distinguish personal from non-personal fields discloses registrants'' personal information to the public.','R1: Investigators and other users cannot obtain required non-personal domain information promptly, delaying abuse identification and follow-up.<br>R2: Publication that fails to distinguish personal from non-personal fields discloses registrants'' personal information to the public.','active','NIS2','C19.4','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.5','Unified Catalogue v6','{}'::text[],'R1: Unsubstantiated or excessive disclosures expose non-public registration data to unauthorised requesters.<br>R2: Lawful, substantiated requests are wrongly rejected, obstructing legitimate abuse investigations.','R1: Unsubstantiated or excessive disclosures expose non-public registration data to unauthorised requesters.<br>R2: Lawful, substantiated requests are wrongly rejected, obstructing legitimate abuse investigations.','active','NIS2','C19.5','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.6','Unified Catalogue v6','{}'::text[],'Responses are delayed, investigations are hindered and the access-request response deadline is missed.','Responses are delayed, investigations are hindered and the access-request response deadline is missed.','active','NIS2','C19.6','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
  ('R6-C19.8','Unified Catalogue v6','{}'::text[],'Legitimate requesters cannot identify the application route or requirements, and requests are misdirected or delayed.','Legitimate requesters cannot identify the application route or requirements, and requests are misdirected or delayed.','active','NIS2','C19.8','{"topic": "T01", "subgroup": "S-DOM · TLD registries and domain registration", "language": "en"}'::jsonb),
